export const contextWindowDefaults = {"width":360,"padding":16,"rowRadius":6,"narrowWidth":286,"cells":216,"columns":36,"narrowColumns":24,"warnAt":0.8,"fullAt":0.95,"duration":260,"countDuration":450,"swapEnter":320,"swapExit":220,"swapBlur":2,"shimmer":540,"compactDuration":1200,"compactShare":0.28,"ease":"cubic-bezier(0.22, 1, 0.36, 1)"} as const;
