  padding: 12px var(--kpr-inset) 6px;
  border-block: 0.5px solid var(--kpr-edge);
  background: var(--kpr-surface);
}
.kalos-permission-request .kalos-permission-preview-title {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 4px;
  color: var(--kpr-muted);
  font-size: 12px;
  line-height: 18px;
  font-weight: 400;
  overflow-wrap: anywhere;
}
.kalos-permission-count {
  flex: none;
  min-width: 17px;
  border-radius: 4px;
  box-shadow: inset 0 0 0 0.5px var(--kpr-edge);
  padding-inline: 3px;
  text-align: center;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.kalos-permission-list { display: flex; flex-direction: column; margin: 0; padding: 0; list-style: none; }
.kalos-permission-item {
  display: flex;
  min-height: 30px;
  align-items: center;
  gap: 10px;
  animation: kalos-permission-row var(--kpr-row-duration) var(--kpr-ease) calc(var(--kpr-order) * var(--kpr-row-stagger)) both;
}
.kalos-permission-item-icon { display: inline-flex; flex: none; color: var(--kpr-preview-icon); }
.kalos-permission-item-icon svg { width: 16px; height: 16px; }
.kalos-permission-meta {
  display: inline-flex;
  gap: 4px;
  margin-inline-start: auto;
  color: var(--kpr-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.kalos-permission-meta-add { color: var(--kpr-success); }
.kalos-permission-meta-remove { color: var(--kpr-danger); }
.kalos-permission-preview .kalos-permission-more { margin-block-start: 2px; margin-inline-start: 22px; padding-inline: 4px; color: var(--kpr-muted); }
.kalos-permission-scope-field { display: flex; flex-direction: column; gap: 6px; }
.kalos-permission-scope-note { color: var(--kpr-muted); font-size: 12px; line-height: 18px; }
.kalos-permission-scopes .kalos-segment__scroller { margin: -2px; }
.kalos-permission-request .kalos-permission-scopes[data-variant="buttons"] .kalos-segment__option { box-shadow: none; }
.kalos-permission-request .kalos-permission-scopes[data-variant="buttons"] .kalos-segment__option:not([data-active]):not(:hover) { background: var(--k-fill); }
.kalos-permission-request .kalos-permission-scopes .kalos-segment__indicator { background: var(--kpr-surface); box-shadow: var(--k-card-shadow); }
.kalos-permission-actions { display: flex; justify-content: flex-end; gap: 8px; }
.kalos-permission-actions > button { min-width: 0; gap: 8px; padding-inline: 12px 8px; }
.kalos-permission-request :is(.kalos-permission-actions, .kalos-permission-preview, .kalos-permission-summary) > button:focus-visible {
  outline: 2px solid var(--kpr-focus);
  outline-offset: 2px;
}
.kalos-permission-key {
  display: inline-grid;
  min-width: 18px;
  height: 18px;
  flex: none;
  place-items: center;
  border-radius: 4px;
  background: color-mix(in srgb, currentColor 13%, transparent);
  padding: 0 4px;
  font: inherit;
  font-size: 10px;
  line-height: 14px;
}
.kalos-permission-actions > button:first-child .kalos-permission-key { color: var(--kpr-preview-icon); background: var(--kpr-soft); }
.kalos-permission-actions > button:last-child .kalos-permission-key { color: color-mix(in srgb, currentColor 72%, transparent); }
.kalos-permission-label { position: relative; display: grid; justify-items: center; }
.kalos-permission-label > [aria-hidden="true"] { position: absolute; inset: 0; }
.kalos-permission-summary {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  min-height: 60px;
  padding: 8px var(--kpr-padding);
}
.kalos-permission-status-icon {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px currentColor;
  color: var(--kpr-success);
}
.kalos-permission-status-icon[data-status="denied"] { color: var(--kpr-danger); }
.kalos-permission-status-icon[data-status="expired"] { color: var(--kpr-muted); }
.kalos-permission-status-icon svg { width: 11px; height: 11px; }
.kalos-permission-status { display: flex; gap: 5px; }
.kalos-permission-status strong { flex: none; font-weight: 500; }
.kalos-permission-status-action { color: var(--kpr-muted); }
.kalos-permission-detail { font-variant-numeric: tabular-nums; }
.kalos-permission-progress { position: absolute; inset: auto 0 0; height: 2px; background: var(--kpr-soft); }
.kalos-permission-progress > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--kpr-success);
  transform-origin: left;
  transition: transform 1s linear;
}
.kalos-permission-progress:dir(rtl) > span { transform-origin: right; }

@keyframes kalos-permission-row {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
@container kalos-permission (width < 340px) {
  .kalos-permission-pending { --kpr-inset: var(--kpr-compact-padding); }
  .kalos-permission-request .kalos-permission-reason { grid-column: 1 / -1; }
  .kalos-permission-actions > button { flex: 1; }
  .kalos-permission-key { display: none; }
  .kalos-permission-summary { gap: 7px; padding-inline: var(--kpr-compact-padding); }
}
@media (pointer: coarse) {
  .kalos-permission-key { display: none; }
  .kalos-permission-actions > button,
  .kalos-permission-summary > button,
  .kalos-permission-preview .kalos-permission-more { min-height: 36px; }
}
