import {
  createContext, useContext, useEffect, useId, useLayoutEffect, useRef, useState,
  type ComponentProps, type ReactNode,
} from "react";
import { Radio } from "@base-ui/react/radio";
import { ArrowLeft, ArrowRight, Check, X } from "lucide-react";
