.kalos-dropzone-progress[data-visible] { height: 2px; margin-top: 5px; opacity: 1; }
.kalos-dropzone-row[data-status="done"] .kalos-dropzone-progress { transition-delay: 170ms, 170ms, 160ms; }
.kalos-dropzone-track {
