export type KalosNoticePattern = "orbit" | "grid" | "rays";
export type KalosNotificationPosition = "top-right" | "bottom-right" | "top-left" | "bottom-left";
export type KalosNotice = {
  id: string;
  badge?: string;
  title: string;
  text?: string;
  icon?: ReactNode;
