export function AccessiblePlot({ label, values, children }: {
  label: string;
  values: string[];
  children: ReactNode;
}) {
  const [index, setIndex] = useState<number | null>(null);
  const active = index === null ? undefined : values[index];
  return (
    <figure
      aria-label={label}
      aria-description="使用左右方向键浏览图表数据"
      tabIndex={0}
      className="relative h-full min-w-0 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-(--chart-1)"
      onFocus={(event) => {
        if (event.target === event.currentTarget && event.currentTarget.matches(":focus-visible")) setIndex(0);
      }}
      onPointerDown={() => setIndex(null)}
      onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setIndex(null); }}
      onKeyDown={(event) => {
        if (event.key === "Escape") setIndex(null);
        if (values.length && (event.key === "ArrowLeft" || event.key === "ArrowRight")) {
          event.preventDefault();
          const step = event.key === "ArrowLeft" ? -1 : 1;
          setIndex(current => ((current ?? 0) + step + values.length) % values.length);
        }
      }}
    >
      <figcaption className="sr-only">{values.join("；")}</figcaption>
      {children}
      {active && (
        <div role="tooltip" aria-live="polite" className="pointer-events-none absolute top-2 left-2 rounded-lg border bg-popover px-3 py-2 text-xs text-popover-foreground shadow-sm">
          {active}
        </div>
      )}
    </figure>
  );
}

import type { Transition } from "motion/react";

/** Default clip-reveal easing for cartesian charts. */
export const DEFAULT_ANIMATION_EASING = "cubic-bezier(0.85, 0, 0.15, 1)";

export const DEFAULT_ANIMATION_DURATION_MS = 1100;

/** Default enter transition — matches the original line chart reveal. */
export const DEFAULT_CHART_ENTER_TRANSITION: Transition = {
  type: "tween",
  duration: DEFAULT_ANIMATION_DURATION_MS / 1000,
  ease: [0.85, 0, 0.15, 1],
};

/**
 * Clip-path width reveal must use tween — spring does not reliably animate SVG width.
 */
export function clipRevealTransition(enterTransition?: Transition): Transition {
  if (enterTransition?.type === "tween") {
    return {
      ...enterTransition,
      ease: enterTransition.ease ?? DEFAULT_CHART_ENTER_TRANSITION.ease,
    };
  }

  const duration =
    typeof enterTransition?.duration === "number"
      ? enterTransition.duration
      : DEFAULT_ANIMATION_DURATION_MS / 1000;

  return {
    type: "tween",
    duration,
    ease: DEFAULT_CHART_ENTER_TRANSITION.ease,
  };
}

/*
 * Polar grid enter — the radar chart standard (RadarGrid / RadarAxis /
 * RadarLabels), shared by the radial and ring charts so every circular grid
 * draws in the same way: rings grow out of the center one after another,
 * spokes extend outward, then labels fade in.
 */

/** Delay between concentric grid rings, seconds. */
export const GRID_RING_STAGGER_S = 0.08;
/** Grid rings scale (and fade) in from the center. */
export const GRID_RING_SPRING: Transition = {
  type: "spring",
  stiffness: 100,
  damping: 15,
  mass: 1,
};
/** Delay between spokes, seconds. */
export const GRID_SPOKE_STAGGER_S = 0.05;
/** Spokes extend from their inner end outward. */
export const GRID_SPOKE_SPRING: Transition = {
  type: "spring",
  stiffness: 80,
  damping: 15,
  mass: 1,
};
/** Delay between value (level) labels, seconds. */
export const GRID_VALUE_LABEL_STAGGER_S = 0.06;
/** Delay between angle (category) labels, seconds. */
export const GRID_ANGLE_LABEL_STAGGER_S = 0.08;
/** Angle label fade duration, seconds. */
export const GRID_ANGLE_LABEL_FADE_S = 0.5;

/** Labels start once half of the `ringCount` grid rings have started. */
export function gridLabelDelay(
  ringCount: number,
  ringStagger: number = GRID_RING_STAGGER_S
): number {
  return ringCount * ringStagger * 0.5;
}

import { arc } from "d3-shape";

interface ArcDatum {
  innerRadius: number;
  outerRadius: number;
  startAngle: number;
  endAngle: number;
  cornerRadius: number;
  padAngle: number;
}

// One shared generator whose accessors read from the datum, so per-frame
// calls (enter animations, hover grow) allocate a single small object instead
// of a generator plus seven constant closures. Output is identical to building
// a fresh `arc()` with constant values: d3 evaluates the same numbers either way.
const generator = arc<ArcDatum>()
  .innerRadius((d) => d.innerRadius)
  .outerRadius((d) => d.outerRadius)
  .startAngle((d) => d.startAngle)
  .endAngle((d) => d.endAngle)
  .cornerRadius((d) => d.cornerRadius)
  .padAngle((d) => d.padAngle);

/**
 * SVG path `d` for an annular sector centred on the origin (d3 `arc`
 * convention: radians, 0 at 12 o'clock, clockwise). `padRadius` keeps the d3
 * default, sqrt(inner² + outer²). Returns "" when d3 produces no path.
 */
export function arcPath(
  innerRadius: number,
  outerRadius: number,
  startAngle: number,
  endAngle: number,
  cornerRadius = 0,
  padAngle = 0
): string {
  return (
    generator({
      innerRadius,
      outerRadius,
      startAngle,
      endAngle,
      cornerRadius,
      padAngle,
    }) || ""
  );
}

