}

function fadeMaskStops(lengthPercent: number): Array<{
  offset: string;
  opacity: number;
}> {
  const edge = clampFadeLength(lengthPercent);
  return [
    { offset: "0%", opacity: 0 },
    { offset: `${edge}%`, opacity: 1 },
    { offset: `${100 - edge}%`, opacity: 1 },
    { offset: "100%", opacity: 0 },
  ];
}

/** Plot-area pattern fill for charts without a grid. Renders behind series layers. */
export function Background(props: BackgroundProps) {
  const { innerWidth, innerHeight, isLoaded, enterTransition } =
    useChartStable();
  return (
    <BackgroundPatternLayer
      {...props}
      enterTransition={enterTransition}
      height={innerHeight}
      isLoaded={isLoaded}
      width={innerWidth}
    />
  );
}

Background.displayName = "Background";

export interface BackgroundPatternLayerProps extends BackgroundProps {
  width: number;
  height: number;
  isLoaded: boolean;
  enterTransition?: Transition;
}

/**
 * Context-free pattern fill with edge fades — `Background` reads its size from
 * the cartesian chart context; other charts (choropleth) pass it explicitly.
 */
export function BackgroundPatternLayer({
  pattern = "diagonal-up",
  color = "var(--chart-grid)",
  scale = 1,
  strokeWidth,
  radius,
  complement,
  fill,
  dotFill,
  tileBackground,
  showFill = true,
  opacity = 1,
  fadeHorizontal = true,
  fadeVertical = true,
  fadeHorizontalLength = 10,
  fadeVerticalLength = 10,
  width: innerWidth,
  height: innerHeight,
  isLoaded,
  enterTransition,
}: BackgroundPatternLayerProps) {
  const uniqueId = useId();
  const patternId = `chart-background-${uniqueId.replace(/:/g, "")}`;

  const hStops = useMemo(
    () => fadeMaskStops(fadeHorizontalLength),
    [fadeHorizontalLength]
  );
  const vStops = useMemo(
    () => fadeMaskStops(fadeVerticalLength),
    [fadeVerticalLength]
  );

  if (pattern === "none" || !showFill || innerWidth <= 0 || innerHeight <= 0) {
    return null;
  }

  const patternNode = renderPatternPreset(pattern, patternId, {
    color,
    scale,
    strokeWidth,
    radius,
    complement,
    fill,
    dotFill,
    tileBackground,
  });
  if (!patternNode) {
    return null;
  }

  const fadeMask = fadeHorizontal || fadeVertical;
  const hMaskId = `chart-background-fade-h-${uniqueId.replace(/:/g, "")}`;
  const hGradientId = `${hMaskId}-gradient`;
  const vMaskId = `chart-background-fade-v-${uniqueId.replace(/:/g, "")}`;
  const vGradientId = `${vMaskId}-gradient`;
  const combinedMaskId = `chart-background-fade-${uniqueId.replace(/:/g, "")}`;

  let maskRef: string | undefined;
  if (fadeHorizontal && fadeVertical) {
    maskRef = `url(#${combinedMaskId})`;
  } else if (fadeHorizontal) {
    maskRef = `url(#${hMaskId})`;
  } else if (fadeVertical) {
    maskRef = `url(#${vMaskId})`;
  }

  const targetOpacity = opacity;
  const revealOpacity = isLoaded ? targetOpacity : 0;
  const enterFade =
    enterTransition && typeof enterTransition === "object"
      ? enterTransition
      : { duration: BACKGROUND_ENTER_FADE_MS / 1000, ease: "easeOut" as const };

  return (
    // biome-ignore lint/a11y/noAriaHiddenOnFocusable: decorative plot-area pattern layer
    <g aria-hidden="true" className="chart-background">
      {fadeMask ? (
        <defs>
          {fadeHorizontal ? (
            <>
              <linearGradient
                id={hGradientId}
                x1="0%"
                x2="100%"
                y1="0%"
                y2="0%"
              >
                {hStops.map((stop) => (
                  <stop
                    key={stop.offset}
                    offset={stop.offset}
                    style={{ stopColor: "white", stopOpacity: stop.opacity }}
                  />
                ))}
              </linearGradient>
              <mask id={hMaskId}>
                <rect
                  fill={`url(#${hGradientId})`}
                  height={innerHeight}
                  width={innerWidth}
                  x={0}
                  y={0}
                />
              </mask>
            </>
          ) : null}
          {fadeVertical ? (
            <>
              <linearGradient
                id={vGradientId}
                x1="0%"
                x2="0%"
                y1="0%"
                y2="100%"
              >
                {vStops.map((stop) => (
                  <stop
                    key={stop.offset}
                    offset={stop.offset}
                    style={{ stopColor: "white", stopOpacity: stop.opacity }}
                  />
                ))}
              </linearGradient>
              <mask id={vMaskId}>
                <rect
                  fill={`url(#${vGradientId})`}
                  height={innerHeight}
                  width={innerWidth}
                  x={0}
                  y={0}
                />
              </mask>
            </>
          ) : null}
          {fadeHorizontal && fadeVertical ? (
            <mask id={combinedMaskId}>
              <g mask={`url(#${hMaskId})`}>
                <rect
                  fill={`url(#${vGradientId})`}
                  height={innerHeight}
                  width={innerWidth}
                  x={0}
                  y={0}
                />
              </g>
            </mask>
          ) : null}
        </defs>
      ) : null}
      <defs>{patternNode}</defs>
      <m.rect
        animate={{ opacity: revealOpacity }}
        fill={`url(#${patternId})`}
        height={innerHeight}
        initial={{ opacity: 0 }}
        mask={maskRef}
        transition={isLoaded ? enterFade : { duration: 0 }}
        width={innerWidth}
        x={0}
        y={0}
      />
    </g>
  );
}

export default Background;

import {
  Children,
  Fragment,
  isValidElement,
  type ReactElement,
  type ReactNode,
} from "react";
import { isChartClipPassthrough } from "./chart-child-passthrough";
import type { BandConfig } from "./chart-context";
import { normalizeYAxisId } from "./y-axis-scales";

export type { BandConfig } from "./chart-context";

/** Default `<Band>` colour (kept in sync with `Band`'s `fill` default). */
const DEFAULT_BAND_FILL = "var(--chart-line-primary)";

interface BandConfigProps {
  upperKey?: unknown;
  lowerKey?: unknown;
  yAxisId?: string | number;
  fill?: unknown;
  label?: unknown;
  showInTooltip?: unknown;
}

/** Default tooltip label: the key for a single-key band, else `lower – upper`. */
export function defaultBandLabel(upperKey: string, lowerKey: string): string {
  return upperKey === lowerKey ? upperKey : `${lowerKey} – ${upperKey}`;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function bandConfigFromProps(
  props: BandConfigProps | undefined
): BandConfig | null {
  if (!(nonEmptyString(props?.upperKey) && nonEmptyString(props.lowerKey))) {
    return null;
  }
  return {
    yAxisId: normalizeYAxisId(props.yAxisId),
    upperKey: props.upperKey,
    lowerKey: props.lowerKey,
    color: nonEmptyString(props.fill) ? props.fill : DEFAULT_BAND_FILL,
    label: nonEmptyString(props.label)
      ? props.label
      : defaultBandLabel(props.upperKey, props.lowerKey),
    showInTooltip: props.showInTooltip !== false,
  };
}

function getChildComponentName(child: ReactElement) {
  const childType = child.type as { displayName?: string; name?: string };
  return typeof child.type === "function"
    ? childType.displayName || childType.name || ""
    : "";
}

/** Collect `<Band>` props from chart children so band edges extend the y-domain. */
export function extractBandConfigs(children: ReactNode): BandConfig[] {
  const configs: BandConfig[] = [];

  const visit = (node: ReactNode) => {
    Children.forEach(node, (child) => {
      if (!isValidElement(child)) {
        return;
      }

      if (child.type === Fragment) {
        visit((child.props as { children?: ReactNode }).children);
        return;
      }

      if (getChildComponentName(child) === "Band") {
        const config = bandConfigFromProps(
          child.props as BandConfigProps | undefined
        );
        if (config) {
          configs.push(config);
        }
        return;
      }

      if (isChartClipPassthrough(child.type)) {
        visit((child.props as { children?: ReactNode }).children);
        return;
      }

      const childProps = child.props as { children?: ReactNode } | undefined;
      if (childProps?.children) {
        visit(childProps.children);
      }
    });
  };

  visit(children);
  return configs;
}

/** Band edge keys grouped by y-axis id (deduplicated, insertion order). */
export function bandKeysByAxis(
  configs: Pick<BandConfig, "yAxisId" | "upperKey" | "lowerKey">[]
): Record<string, string[]> {
  const byAxis: Record<string, string[]> = {};
  for (const config of configs) {
    const keys = byAxis[config.yAxisId] ?? [];
    for (const key of [config.upperKey, config.lowerKey]) {
      if (!keys.includes(key)) {
        keys.push(key);
      }
    }
    byAxis[config.yAxisId] = keys;
  }
  return byAxis;
}

