/**
 * Shared 3D bar-depth geometry — the single source of truth for the
 * perspective math used by BOTH `<Bar perspective>` (which shrinks a
 * bar's front-face top) AND the bar-depth surfaces (`<BarDepthBack>`'s side +
 * lid). Keeping the formula here means the front face and the 3D lid can never
 * drift out of alignment.
 */

/** Hard ceiling on side-face thickness in px. Capped further by the column gap
 * so depth never bleeds past the next bar's leading edge. */
export const BAR_DEPTH_MAX_PX = 7;
/** The side parallelogram's back edge lifts by `depth * this ratio`, giving a
 * subtle head-on perspective slope. */
export const BAR_DEPTH_PERSPECTIVE_RATIO = 0.45;

/**
 * Maximum side-face depth in px for a chart, clamped so depth never spills past
 * the gap between bars. `stepWidth` is d3-scaleBand's `step()` (bandwidth +
 * gap); `bandWidth` is a single bar's width. Returns 0 for gapless/dense charts.
 */
export function barDepthMaxDepth(stepWidth: number, bandWidth: number): number {
  const gap = Math.max(0, stepWidth - bandWidth);
  return Math.min(bandWidth * 0.22, Math.max(0, gap - 1), BAR_DEPTH_MAX_PX);
}

/**
 * Per-bar side-face depth + perspective rise.
 *
 * - `absOffset` ∈ [0, 1]: the bar's normalized distance from the chart's
 *   horizontal center. 0 = dead center (no depth); 1 = chart edge (full depth).
 * - `naturalHeight`: the bar's pixel height. Depth is capped by it so a short
 *   bar's side never reads wider than the bar is tall.
 * - `maxDepth`: from `barDepthMaxDepth`.
 */
export function barDepthAndRise(
  absOffset: number,
  naturalHeight: number,
  maxDepth: number
): { depth: number; perspectiveRise: number } {
  const offset = Math.min(1, Math.max(0, absOffset));
  const cappedMaxDepth = Math.min(maxDepth, Math.max(0, naturalHeight));
  const depth = offset * cappedMaxDepth;
  return { depth, perspectiveRise: depth * BAR_DEPTH_PERSPECTIVE_RATIO };
}

export interface SquareColumnLayout {
  /** Number of squares in the column */
  count: number;
  /** Top-left Y of each square, bottom square first (relative to bar top at 0) */
  positions: number[];
  /** Quantized column height in pixels */
  columnHeight: number;
  squareSize: number;
  /** Effective gap between squares (may differ when fit mode redistributes) */
  gap: number;
}

export interface SquareColumnInput {
  /** Raw bar length in pixels (baseline − value) */
  barLengthPx: number;
  /** Square width/height — typically equals bar width */
  squareSize: number;
  /** Gap between stacked squares in pixels */
  gap: number;
  /** When true, redistribute gap so column height matches barLengthPx exactly */
  fit?: boolean;
}

/** Quantize bar length into a stack of square cells. */
export function computeSquareColumn({
  barLengthPx,
  squareSize,
  gap,
  fit = false,
}: SquareColumnInput): SquareColumnLayout {
  if (barLengthPx <= 0 || squareSize <= 0) {
    return { count: 0, positions: [], columnHeight: 0, squareSize, gap };
  }

  if (fit) {
    const count = Math.max(
      1,
      Math.floor((barLengthPx + gap) / (squareSize + gap))
    );
    const effectiveGap =
      count > 1
        ? Math.max(0, (barLengthPx - count * squareSize) / (count - 1))
        : 0;
    const step = squareSize + effectiveGap;
    const columnHeight = barLengthPx;
    const positions: number[] = [];

    for (let i = 0; i < count; i++) {
      positions.push(columnHeight - squareSize - i * step);
    }

    return {
      count,
      positions,
      columnHeight,
      squareSize,
      gap: effectiveGap,
    };
  }

  const step = squareSize + gap;
  const count = Math.max(1, Math.round(barLengthPx / step));
  const columnHeight = count * squareSize + Math.max(0, count - 1) * gap;

  const positions: number[] = [];
  for (let i = 0; i < count; i++) {
    const offsetFromBottom = i * step;
    positions.push(columnHeight - squareSize - offsetFromBottom);
  }

  return { count, positions, columnHeight, squareSize, gap };
}

/** Y center of the topmost square in a vertical column. */
export function topSquareCenterY({
  baselineY,
  barLengthPx,
  squareSize,
  gap,
  fit = false,
}: SquareColumnInput & { baselineY: number }): number {
  const {
    count,
    squareSize: size,
    columnHeight,
  } = computeSquareColumn({
    barLengthPx,
    squareSize,
    gap,
    fit,
  });

  if (count === 0) {
    return baselineY;
  }

  const topY = baselineY - columnHeight;
  return topY + size / 2;
}

export type BarValueLabelOrientation = "auto" | "horizontal" | "vertical";
export type BarValueLabelPosition = "top" | "center" | "bottom";

/** Approximate rendered height of a 12px label. */
const LABEL_LINE_HEIGHT = 12;
/** Distance between a top/bottom-aligned label and the bar edge. */
const LABEL_INSET = 6;
/** Smallest bar thickness (across the text) that still fits a 12px label. */
const MIN_CROSS_SIZE = LABEL_LINE_HEIGHT + 6;

export function getBarValueLabelLayout({
  x,
  y,
  width,
  height,
  labelWidth,
  isHorizontal,
  orientation,
  position,
}: {
  x: number;
  y: number;
  width: number;
  height: number;
  labelWidth: number;
  isHorizontal: boolean;
  orientation: BarValueLabelOrientation;
  position: BarValueLabelPosition;
}) {
  const normalFits = width >= labelWidth + 10 && height >= MIN_CROSS_SIZE;
  const rotatedFits = height >= labelWidth + 10 && width >= MIN_CROSS_SIZE;
  let fits = normalFits || rotatedFits;
  if (orientation === "horizontal") {
    fits = normalFits;
  } else if (orientation === "vertical") {
    fits = rotatedFits;
  }

  const rotated =
    fits &&
    (orientation === "vertical" || (orientation === "auto" && !normalFits));
  // Footprint of the (possibly rotated) label, so top/bottom placement keeps
  // the whole label inside the bar instead of just its centre point.
  const extentX = rotated ? LABEL_LINE_HEIGHT : labelWidth;
  const extentY = rotated ? labelWidth : LABEL_LINE_HEIGHT;

  let labelX = x + width / 2;
  let labelY = y + height / 2;
  if (isHorizontal) {
    // Horizontal bars: "top" is the value end (right), "bottom" the base (left).
    if (position === "top") {
      labelX = x + width - LABEL_INSET - extentX / 2;
    } else if (position === "bottom") {
      labelX = x + LABEL_INSET + extentX / 2;
    }
  } else if (position === "top") {
    labelY = y + LABEL_INSET + extentY / 2;
  } else if (position === "bottom") {
    labelY = y + height - LABEL_INSET - extentY / 2;
  }

  return { fits, rotated, x: labelX, y: labelY };
}

