type ScaleBand<Domain extends { toString(): string }> = D3ScaleBand<Domain>;

export type BarLineCap = "round" | "butt" | number;
export type BarAnimationType = "grow" | "fade";

// ── Bar-depth perspective trim ───────────────────────────────────────────
// Uses the SHARED geometry (`bar-depth-geometry.ts`) so a
// `<Bar perspective>` front face lines up exactly with
// `<BarDepthBack>`'s lid — the formula lives in one place for both.

/** perspectiveRise for a positive bar whose visual top sits at `topY`.
 * Returns 0 for a dead-center bar or a dense chart (degenerate depth). */
function barDepthPerspectiveRise(
  barScale: ScaleBand<string>,
  bandWidth: number,
  barXAccessor: (d: Record<string, unknown>) => string,
  innerWidth: number,
  datum: Record<string, unknown>,
  topY: number,
  baselineY: number
): number {
  const centerX = innerWidth / 2;
  if (centerX <= 0) {
    return 0;
  }
  const step =
    (barScale as unknown as { step?: () => number }).step?.() ?? bandWidth;
  const maxDepth = barDepthMaxDepth(step, bandWidth);
  const bandX = barScale(barXAccessor(datum)) ?? 0;
  const cx = bandX + bandWidth / 2;
  const absOffset = Math.min(1, Math.abs((cx - centerX) / centerX));
  const naturalHeight = Math.abs(baselineY - topY);
  return barDepthAndRise(absOffset, naturalHeight, maxDepth).perspectiveRise;
}

export interface BarProps {
  /** Key in data to use for y values */
  dataKey: string;
  /** Y-scale group id for vertical bars (Recharts `yAxisId`). Default: `"left"`. */
  yAxisId?: string | number;
  /** Fill color for the bar. Can be a color, gradient url, or pattern url. Default: var(--chart-line-primary) */
  fill?: string;
  /** Color for tooltip dot. Use when fill is a gradient/pattern. Default: uses fill value */
  stroke?: string;
  /** Line cap style for bar ends: "round", "butt", or a number for custom radius. Default: "round" */
  lineCap?: BarLineCap;
  /** Whether to animate the bars. Default: true */
  animate?: boolean;
  /** Animation type: "grow" (height) or "fade" (opacity + blur). Default: "grow" */
  animationType?: BarAnimationType;
  /** Opacity when not hovered (when another bar is hovered). Default: 0.3 */
  fadedOpacity?: number;
  /** Stagger delay between bars in seconds. Auto-calculated if not provided. */
  staggerDelay?: number;
  /** Gap between stacked bars in pixels. Default: 0 */
  stackGap?: number;
  /** Gap between grouped bars in pixels. Default: 4 */
  groupGap?: number;
  /** Shrink each positive bar's top by its perspective rise so the front face
   * lines up with `<BarDepthBack>`'s lid (instead of the lid sitting above the
   * front face). Pass `true` whenever the chart also renders the bar-depth 3D
   * surfaces. Default: false */
  perspective?: boolean;
  /** Minimum rendered bar height in px (non-stacked, vertical). Floors short or
   * zero-value bars so they stay visible. Pair with the same value on
   * `<BarDepthProvider minBarHeight>` when using the 3D surfaces. Default: 0 */
  minBarHeight?: number;
  /** Show the formatted value inside each bar when it fits. Default: false. */
  showValue?: boolean;
  /** Format values displayed inside bars. Defaults to English integers. */
  valueLabelFormatter?: (value: number) => string;
  /** Text color for values displayed inside bars. Default: white. */
  valueLabelColor?: string;
  /** Label text direction. `auto` uses horizontal text, then rotates if needed. */
  valueLabelOrientation?: BarValueLabelOrientation;
  /** Position of the label inside the bar. On horizontal bars `"top"` is the
   * value end (right) and `"bottom"` the base (left). Default: center. */
  valueLabelPosition?: BarValueLabelPosition;
  /** Optional class for value labels. */
  valueLabelClassName?: string;
}

interface BarInnerProps extends BarProps {
  barScale: ScaleBand<string>;
  bandWidth: number;
  barXAccessor: (d: Record<string, unknown>) => string;
}

interface AnimatedBarProps {
  x: number;
  y: number;
  width: number;
  height: number;
  fill: string;
  rx: number;
  ry: number;
  index: number;
  isFaded: boolean;
  animationType: BarAnimationType;
  fadedOpacity: number;
  staggerDelay: number;
  enterTransition?: Transition;
  revealEpoch: number;
  isHorizontal: boolean;
  /** Value-axis position the grow animation starts from (the zero line for
   * non-stacked bars, the segment start for horizontal stacked bars). */
  growOrigin: number;
  valueLabel?: string;
  valueLabelColor: string;
  labelX: number;
  labelY: number;
  labelTransform?: string;
  valueLabelClassName?: string;
}

function AnimatedBar({
  x,
  y,
  width,
  height,
  fill,
  rx,
  ry,
  index,
  isFaded,
  animationType,
  fadedOpacity,
  staggerDelay,
  enterTransition,
  revealEpoch,
  isHorizontal,
  growOrigin,
  valueLabel,
  valueLabelColor,
  labelX,
  labelY,
  labelTransform,
  valueLabelClassName,
}: AnimatedBarProps) {
  const enterAnim = transitionWithDelay(enterTransition, index * staggerDelay);
  const label = valueLabel ? (
    <m.text
      animate={{ opacity: isFaded ? fadedOpacity : 1 }}
      className={valueLabelClassName}
      dominantBaseline="middle"
      fill={valueLabelColor}
      fontSize={12}
      fontWeight={600}
      initial={{ opacity: 0 }}
      textAnchor="middle"
      transform={labelTransform}
      transition={enterAnim}
      x={labelX}
      y={labelY}
    >
      {valueLabel}
    </m.text>
  ) : null;

  if (animationType === "fade") {
    return (
      <g>
        <m.rect
          animate={{
            opacity: isFaded ? fadedOpacity : 1,
            filter: "blur(0px)",
          }}
          fill={fill}
          height={height}
          initial={{ opacity: 0, filter: "blur(2px)" }}
          key={`fade-${index}-${revealEpoch}`}
          rx={rx}
          ry={ry}
          transition={enterAnim}
          width={width}
          x={x}
          y={y}
        />
        {label}
      </g>
    );
  }

  const initial = isHorizontal
    ? { width: 0, height, x: growOrigin, y }
    : { width, height: 0, x, y: growOrigin };
  const target = isHorizontal
    ? { width, height, x, y }
    : { width, height, x, y };

  return (
    <g
      opacity={isFaded ? fadedOpacity : 1}
      style={{ transition: "opacity 0.15s ease-in-out" }}
    >
      <m.rect
        animate={target}
        fill={fill}
        initial={initial}
        key={`grow-${index}-${revealEpoch}`}
        rx={rx}
        ry={ry}
        transition={enterAnim}
      />
      {label}
    </g>
  );
}

/** Geometry for one bar — independent of hover, so it is memoized once. */
interface BarGeometry {
  key: string;
  index: number;
  x: number;
  y: number;
  width: number;
  height: number;
  rx: number;
  growOrigin: number;
  valueLabel?: string;
  labelX: number;
  labelY: number;
  labelTransform?: string;
}

const STATIC_BAR_STYLE = {
  cursor: "default",
  transition: "opacity 0.15s ease-in-out",
} as const;
const STATIC_LABEL_STYLE = { transition: "opacity 0.15s ease-in-out" } as const;

interface StaticBarProps {
  geometry: BarGeometry;
  fill: string;
  opacity: number;
  valueLabelColor: string;
  valueLabelClassName?: string;
}

/**
 * Bar after the enter animation (or with animation off). Memoized on its
 * geometry object + opacity, so a hover only re-renders the bars whose fade
 * state changed instead of every bar in the series.
 */
const StaticBar = memo(function StaticBar({
  geometry,
  fill,
  opacity,
  valueLabelColor,
  valueLabelClassName,
}: StaticBarProps) {
  return (
    <g>
      <rect
        fill={fill}
        height={geometry.height}
        opacity={opacity}
        rx={geometry.rx}
        ry={geometry.rx}
        style={STATIC_BAR_STYLE}
        width={geometry.width}
        x={geometry.x}
        y={geometry.y}
      />
      {geometry.valueLabel ? (
        <text
          className={valueLabelClassName}
          dominantBaseline="middle"
          fill={valueLabelColor}
          fontSize={12}
          fontWeight={600}
          opacity={opacity}
          style={STATIC_LABEL_STYLE}
          textAnchor="middle"
          transform={geometry.labelTransform}
          x={geometry.labelX}
          y={geometry.labelY}
        >
          {geometry.valueLabel}
        </text>
      ) : null}
    </g>
  );
});

const BarInner = memo(function BarInner({
  dataKey,
  yAxisId,
  fill = chartCssVars.linePrimary,
  lineCap = "round",
  animate = true,
  animationType = "grow",
  fadedOpacity = 0.3,
  staggerDelay,
  stackGap = 0,
  groupGap = 4,
  perspective = false,
  minBarHeight = 0,
  showValue = false,
  valueLabelFormatter = valueLabelFmt,
  valueLabelColor = "white",
  valueLabelOrientation = "auto",
  valueLabelPosition = "center",
  valueLabelClassName,
  barScale,
  bandWidth,
  barXAccessor,
}: BarInnerProps) {
  const {
    data,
    yScale: chartYScale,
    innerHeight,
    innerWidth,
    isLoaded,
    lines,
    orientation,
    stacked,
    stackOffsets,
    animationDuration,
    enterTransition,
    revealEpoch = 0,
  } = useChartStable();
  const { hoveredBarIndex = null } = useChartHover();

  // Calculate stagger delay automatically if not provided
  // Total animation duration is ~1200ms, with 40% for stagger spread and 60% for bar animation
  const totalAnimDuration = animationDuration || 1100;
  const staggerSpread = totalAnimDuration * 0.4; // 40% of time for stagger spread
  const calculatedStaggerDelay =
    staggerDelay ?? (data.length > 1 ? staggerSpread / 1000 / data.length : 0);
  const uniqueId = useId();

  const isHorizontal = orientation === "horizontal";

  // Find the index of this bar series among all bar series
  const { hoveredIndex: legendHoveredIndex } = useChartLegendHover();

  const seriesIndex = useMemo(() => {
    const idx = lines.findIndex((l) => l.dataKey === dataKey);
    return idx >= 0 ? idx : 0;
  }, [lines, dataKey]);

  const seriesConfig = lines[seriesIndex];
  const valueScale = useYScale(yAxisId ?? seriesConfig?.yAxisId);

  const isLegendDimmed =
    legendHoveredIndex !== null && legendHoveredIndex !== seriesIndex;

  const seriesCount = lines.length;
  const isLastSeries = seriesIndex === seriesCount - 1;

  // Calculate the width for each bar within a group (for non-stacked)
  const barWidth = useMemo(() => {
    if (!bandWidth || seriesCount === 0) {
      return 0;
    }
    if (stacked) {
      // Stacked bars use full band width
      return bandWidth;
    }
    // Leave a gap between grouped bars (controlled by groupGap prop)
    const effectiveGroupGap = seriesCount > 1 ? groupGap : 0;
    return (bandWidth - effectiveGroupGap * (seriesCount - 1)) / seriesCount;
  }, [bandWidth, seriesCount, stacked, groupGap]);

  // Calculate corner radius based on lineCap. Perspective bars force a flat
  // top (radius 0) so the 3D lid from `<BarDepthBack>` meets the bar with no
  // gap — rounded corners would leave a wedge, so `perspective` overrides it.
  const cornerRadius = useMemo(() => {
    if (perspective) {
      return 0;
    }
    if (typeof lineCap === "number") {
      return lineCap;
    }
    if (lineCap === "round" && barWidth) {
      return Math.min(barWidth / 2, 8);
    }
    return 0;
  }, [lineCap, barWidth, perspective]);

  // Hover-independent geometry: recomputed on data / layout changes only.
  const geometries = useMemo(() => {
    const result: BarGeometry[] = [];
    const scale = isHorizontal ? chartYScale : valueScale;
    const zeroX = isHorizontal ? (scale(0) ?? 0) : 0;
    const zeroY = isHorizontal ? 0 : (scale(0) ?? innerHeight);
    const effectiveGroupGap = seriesCount > 1 ? groupGap : 0;
    // Apply rounded corners:
    // - For non-stacked: always apply
    // - For stacked with gap: apply to all bars
    // - For stacked without gap: only apply to the last series
    const applyRounding = !stacked || stackGap > 0 || isLastSeries;
    const effectiveRx = applyRounding ? cornerRadius : 0;

    for (let i = 0; i < data.length; i++) {
      const d = data[i] as Record<string, unknown>;
      const value = d[dataKey];
      if (typeof value !== "number") {
        continue;
      }

      const categoryValue = barXAccessor(d);
      const bandPos = barScale(categoryValue) ?? 0;

      let x = 0;
      let y = 0;
      let barHeight: number;
      let barW: number;

      if (isHorizontal) {
        // Horizontal bars: category on y-axis, value on x-axis
        const valuePos = scale(value) ?? 0;
        barW = valuePos; // Width is the value position (grows from left)
        barHeight = barWidth;

        if (stacked && stackOffsets) {
          const offset = stackOffsets.get(i)?.get(dataKey) ?? 0;
          x = scale(offset) ?? 0;
          // Segment spans [offset, offset + value]; `valuePos` is the
          // position of `value` alone, so it is not this segment's end.
          barW = (scale(offset + value) ?? 0) - x;
          // Apply stack gap for horizontal: shift right and reduce width
          const gapOffset = seriesIndex * stackGap;
          x += gapOffset;
          if (!isLastSeries && stackGap > 0) {
            barW = Math.max(0, barW - stackGap);
          }
        } else {
          // Grow from the zero line in either direction (zeroX is 0 for
          // non-negative data).
          x = Math.min(valuePos, zeroX);
          barW = Math.abs(valuePos - zeroX);
        }
        y = stacked
          ? bandPos
          : bandPos + seriesIndex * (barWidth + effectiveGroupGap);
      } else {
        // Vertical bars: category on x-axis, value on y-axis
        // Measure from the zero line (not the plot floor) so negative
        // values grow downward. For non-negative data zeroY === innerHeight.
        const valuePos = scale(value) ?? 0;
        barHeight = Math.abs(zeroY - valuePos);
        barW = barWidth;

        if (stacked && stackOffsets) {
          const offset = stackOffsets.get(i)?.get(dataKey) ?? 0;
          const offsetY = scale(offset) ?? innerHeight;
          // Apply stack gap: shift up and reduce height
          const gapOffset = seriesIndex * stackGap;
          y = offsetY - barHeight - gapOffset;
          // Reduce height slightly for non-last bars to create visual gap
          if (!isLastSeries && stackGap > 0) {
            barHeight = Math.max(0, barHeight - stackGap);
          }
        } else {
          y = Math.min(valuePos, zeroY);
        }
        x = stacked
          ? bandPos
          : bandPos + seriesIndex * (barWidth + effectiveGroupGap);

        // Minimum visible height — floor short/zero non-stacked bars so a
        // zero-value data point still reads as a tiny bar instead of
        // vanishing. Grows up from the zero line. Non-negative only, to
        // match bar-depth's floor. Floored bars skip the perspective trim
        // (sub-pixel on a 3px bar; keeps the front aligned with bar-depth,
        // which also skips trim for floored bars).
        let isFloored = false;
        if (
          !stacked &&
          minBarHeight > 0 &&
          value >= 0 &&
          barHeight < minBarHeight
        ) {
          barHeight = minBarHeight;
          y = zeroY - minBarHeight;
          isFloored = true;
        }

        // Perspective trim — shrink the topmost positive bar's front-face
        // top down by its perspective rise so it meets `<BarDepthBack>`'s
        // lid back edge. Stacked: only the last (topmost) series; grouped or
        // single: every positive bar. Clamped to `barHeight - 1` so very
        // short bars keep a positive height (matches bar-depth's clamp).
        if (
          perspective &&
          value > 0 &&
          !isFloored &&
          (!stacked || isLastSeries)
        ) {
          const rise = barDepthPerspectiveRise(
            barScale,
            bandWidth,
            barXAccessor,
            innerWidth,
            d,
            y,
            zeroY
          );
          const trim = Math.min(rise, Math.max(0, barHeight - 1));
          y += trim;
          barHeight -= trim;
        }
      }

      let labelX = 0;
      let labelY = 0;
      let labelTransform: string | undefined;
      let valueLabel: string | undefined;
      if (showValue) {
        const text = valueLabelFormatter(value);
        const labelLayout = getBarValueLabelLayout({
          x,
          y,
          width: barW,
          height: barHeight,
          labelWidth: text.length * 7.2,
          isHorizontal,
          orientation: valueLabelOrientation,
          position: valueLabelPosition,
        });
        labelX = labelLayout.x;
        labelY = labelLayout.y;
        labelTransform = labelLayout.rotated
          ? `rotate(-90 ${labelLayout.x} ${labelLayout.y})`
          : undefined;
        valueLabel = labelLayout.fits ? text : undefined;
      }

      let growOrigin = zeroY;
      if (isHorizontal) {
        growOrigin = stacked ? x : zeroX;
      }

      result.push({
        // Use categoryValue as key since it's the unique identifier from data
        key: `bar-${dataKey}-${categoryValue}`,
        index: i,
        x,
        y,
        width: barW,
        height: barHeight,
        rx: effectiveRx,
        growOrigin,
        valueLabel,
        labelX,
        labelY,
        labelTransform,
      });
    }
    return result;
  }, [
    bandWidth,
    barScale,
    barWidth,
    barXAccessor,
    chartYScale,
    cornerRadius,
    data,
    dataKey,
    groupGap,
    innerHeight,
    innerWidth,
    isHorizontal,
    isLastSeries,
    minBarHeight,
    perspective,
    seriesCount,
    seriesIndex,
    showValue,
    stackGap,
    stackOffsets,
    stacked,
    valueLabelFormatter,
    valueLabelOrientation,
    valueLabelPosition,
    valueScale,
  ]);

  const animating = animate && !isLoaded;

  return (
    <g className={`bar-series-${uniqueId}`}>
      {geometries.map((bar) => {
        const isFaded =
          (hoveredBarIndex !== null && hoveredBarIndex !== bar.index) ||
          isLegendDimmed;

        if (animating) {
          return (
            <AnimatedBar
              animationType={animationType}
              enterTransition={enterTransition}
              fadedOpacity={fadedOpacity}
              fill={fill}
              growOrigin={bar.growOrigin}
              height={bar.height}
              index={bar.index}
              isFaded={isFaded}
              isHorizontal={isHorizontal}
              key={bar.key}
              labelTransform={bar.labelTransform}
              labelX={bar.labelX}
              labelY={bar.labelY}
              revealEpoch={revealEpoch}
              rx={bar.rx}
              ry={bar.rx}
              staggerDelay={calculatedStaggerDelay}
              valueLabel={bar.valueLabel}
              valueLabelClassName={valueLabelClassName}
              valueLabelColor={valueLabelColor}
              width={bar.width}
              x={bar.x}
              y={bar.y}
            />
          );
        }

        // Static bar after animation completes
        return (
          <StaticBar
            fill={fill}
            geometry={bar}
            key={bar.key}
            opacity={isFaded ? fadedOpacity : 1}
            valueLabelClassName={valueLabelClassName}
            valueLabelColor={valueLabelColor}
          />
        );
      })}
    </g>
  );
});

export function Bar(props: BarProps) {
  const { barScale, bandWidth, barXAccessor } = useChartStable();

  if (!(barScale && bandWidth && barXAccessor)) {
    console.warn("Bar component must be used within a BarChart");
    return null;
  }

  return (
    <BarInner
      {...props}
      bandWidth={bandWidth}
      barScale={barScale}
      barXAccessor={barXAccessor}
    />
  );
}

Bar.displayName = "Bar";

export default Bar;

"use client";

import { bisector } from "d3-array";
import { scaleLinear, scaleTime } from "d3-scale";
import type { Transition } from "motion/react";
import { domAnimation, LazyMotion } from "motion/react";
import {
  Children,
  isValidElement,
  memo,
  type ReactElement,
  type ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { cn } from "@/lib/utils";
import {
  isClipExcludedComponent,
  isPostOverlayComponent,
  isUnderlayComponent,
  renderableChartChild,
  resolveChartChildElement,
} from "./chart-child-passthrough";
import { ChartProvider, type LineConfig, type Margin } from "./chart-context";
import { shortDateFmt } from "./chart-formatters";
import { ParentSize } from "./chart-parent-size";
import { DEFAULT_CHART_LIFECYCLE } from "./chart-phase";
import {
  decimateOhlcData,
  maxRenderPointsForWidth,
} from "./decimate-time-series";
import { extractReferenceAreaConfigs } from "./reference-area-config";
import { useChartInteraction } from "./use-chart-interaction";
import { wrapSingleYScale } from "./y-axis-scales";

export interface OHLCDataPoint {
  date: Date;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface CandlestickChartProps {
  /** OHLC data array */
  data: OHLCDataPoint[];
  /** Key in data for the x-axis (date). Default: "date" */
  xDataKey?: string;
  /** Chart margins */
  margin?: Partial<Margin>;
  /** Animation duration in milliseconds. Default: 1500 */
  animationDuration?: number;
  /** Motion enter transition (spring or cubic-bezier tween). */
  enterTransition?: Transition;
  /** Signature of motion URL state — triggers enter replay when it changes. */
  revealSignature?: string;
  /** Aspect ratio as "width / height". Default: "2 / 1" */
  aspectRatio?: string;
  /** Additional class name for the container */
  className?: string;
  /** Inline styles for the container (e.g. { height: 320 }) */
  style?: React.CSSProperties;
  /** Gap between candles as fraction of slot width (0–1). Default: 0.2. Ignored when candleWidth is set. */
  candleGap?: number;
  /** Fixed candle body width in pixels. If set, overrides candleGap. */
  candleWidth?: number;
  /** When set, xScale uses this domain instead of deriving from data. Use with brush so main chart and strip share the same scale. */
  xDomain?: [Date, Date];
  /** When xDomain is set, use this as the number of slots for scale padding (e.g. full data length). */
  xDomainSlotCount?: number;
  /** Child components (Candlestick, Grid, XAxis, YAxis, ChartTooltip, etc.) */
  children: ReactNode;
}

const DEFAULT_MARGIN: Margin = { top: 40, right: 40, bottom: 40, left: 40 };

interface ChartInnerProps {
  width: number;
  height: number;
  data: Record<string, unknown>[];
  xDataKey: string;
  margin: Margin;
  animationDuration: number;
  enterTransition?: Transition;
  revealSignature?: string;
  candleGap: number;
  candleWidthProp?: number;
  xDomain?: [Date, Date];
  xDomainSlotCount?: number;
  children: ReactNode;
  containerRef: React.RefObject<HTMLDivElement | null>;
}

function ChartInner(props: ChartInnerProps) {
  const { width, height } = props;
  if (width < 10 || height < 10) {
    return null;
  }
  return <ChartCore {...props} />;
}

const ChartCore = memo(function ChartCore({
  width,
  height,
  data,
  xDataKey,
  margin,
  animationDuration,
  enterTransition,
  revealSignature = "",
  candleGap,
  candleWidthProp,
  xDomain,
  xDomainSlotCount,
  children,
  containerRef,
}: ChartInnerProps) {
  const [isLoaded, setIsLoaded] = useState(false);
  const [revealEpoch, setRevealEpoch] = useState(1);

  const innerWidth = width - margin.left - margin.right;
  const innerHeight = height - margin.top - margin.bottom;

  const xAccessor = useCallback(
    (d: Record<string, unknown>): Date => {
      const value = d[xDataKey];
      return value instanceof Date ? value : new Date(value as string | number);
    },
    [xDataKey]
  );

  const bisectDate = useMemo(
    () => bisector<Record<string, unknown>, Date>((d) => xAccessor(d)).left,
    [xAccessor]
  );

  const slotCount =
    xDomain && xDomainSlotCount != null ? xDomainSlotCount : data.length;
  const slotWidth = innerWidth / Math.max(slotCount, 1);
  const xScale = useMemo(() => {
    const minTime = xDomain
      ? xDomain[0].getTime()
      : Math.min(...data.map((d) => xAccessor(d).getTime()));
    const maxTime = xDomain
      ? xDomain[1].getTime()
      : Math.max(...data.map((d) => xAccessor(d).getTime()));
    const padding = slotWidth / 2;
    return scaleTime()
      .domain([minTime, maxTime])
      .range([padding, innerWidth - padding]);
  }, [innerWidth, data, xAccessor, slotWidth, xDomain]);

  const yScale = useMemo(() => {
    let minVal = Number.POSITIVE_INFINITY;
    let maxVal = Number.NEGATIVE_INFINITY;
    for (const d of data) {
      const low = d.low as number | undefined;
      const high = d.high as number | undefined;
      if (typeof low === "number" && low < minVal) {
        minVal = low;
      }
      if (typeof high === "number" && high > maxVal) {
        maxVal = high;
      }
    }
    if (minVal === Number.POSITIVE_INFINITY) {
      minVal = 0;
    }
    if (maxVal === Number.NEGATIVE_INFINITY) {
      maxVal = 100;
    }
    const padding = (maxVal - minVal) * 0.05 || 1;
    return scaleLinear()
      .domain([minVal - padding, maxVal + padding])
      .nice()
      .range([innerHeight, 0]);
  }, [innerHeight, data]);

  const columnWidth = slotWidth;
  const bandWidth = candleWidthProp ?? slotWidth * (1 - candleGap);

  const lines: LineConfig[] = useMemo(
    () => [
      { dataKey: "close", stroke: "var(--chart-line-primary)", strokeWidth: 0 },
    ],
    []
  );

  const renderData = useMemo(
    () => decimateOhlcData(data, maxRenderPointsForWidth(innerWidth)),
    [data, innerWidth]
  );

  const dateLabels = useMemo(
    () => data.map((d) => shortDateFmt.format(xAccessor(d))),
    [data, xAccessor]
  );

  // Replay the reveal when motion settings change. Adjusted during render
  // ("store previous props in state") instead of setState in an effect, so a
  // replay costs one render rather than a commit plus a cascading re-render.
  const [revealKey, setRevealKey] = useState({
    animationDuration,
    revealSignature,
  });
  if (
    revealKey.animationDuration !== animationDuration ||
    revealKey.revealSignature !== revealSignature
  ) {
    setRevealKey({ animationDuration, revealSignature });
    setRevealEpoch((n) => n + 1);
    setIsLoaded(false);
  }

  // biome-ignore lint/correctness/useExhaustiveDependencies: revealSignature
  useEffect(() => {
    const timer = setTimeout(() => setIsLoaded(true), animationDuration);
    return () => clearTimeout(timer);
  }, [animationDuration, revealSignature]);

  const { hoverStore, interactionHandlers, interactionStyle } =
    useChartInteraction({
      xScale,
      yScale,
      yScales: wrapSingleYScale(yScale),
      data,
      lines,
      margin,
      xAccessor,
      bisectDate,
      canInteract: isLoaded,
    });

  // Candles read hover through the merged context value, so this chart
  // re-renders on hover (unlike the time-series shell).
  const { tooltipData, setTooltipData, selection, clearSelection } =
    useSyncExternalStore(
      hoverStore.subscribe,
      hoverStore.getSnapshot,
      hoverStore.getSnapshot
    );

  const hoveredCandleIndex = tooltipData?.index ?? null;

  const isDefsComponent = (child: ReactElement): boolean => {
    const displayName =
      (child.type as { displayName?: string })?.displayName ||
      (child.type as { name?: string })?.name ||
      "";
    return (
      displayName.includes("Gradient") ||
      displayName.includes("Pattern") ||
      displayName === "LinearGradient" ||
      displayName === "RadialGradient" ||
      displayName === "Lines" ||
      displayName === "PatternLines"
    );
  };

  const defsChildren: ReactElement[] = [];
  const clipExcludedChildren: ReactElement[] = [];
  const underlayChildren: ReactElement[] = [];
  const preOverlayChildren: ReactElement[] = [];
  const postOverlayChildren: ReactElement[] = [];
  Children.forEach(children, (rawChild) => {
    if (!isValidElement(rawChild)) {
      return;
    }
    const child = renderableChartChild(rawChild);
    const resolvedChild = resolveChartChildElement(rawChild);
    if (isDefsComponent(resolvedChild)) {
      defsChildren.push(child);
    } else if (isPostOverlayComponent(resolvedChild)) {
      postOverlayChildren.push(child);
    } else if (isClipExcludedComponent(resolvedChild)) {
      clipExcludedChildren.push(child);
    } else if (isUnderlayComponent(resolvedChild)) {
      underlayChildren.push(child);
    } else {
      preOverlayChildren.push(child);
    }
  });

  const referenceAreas = useMemo(
    () => extractReferenceAreaConfigs(children),
    [children]
  );

  const yScales = useMemo(() => wrapSingleYScale(yScale), [yScale]);

  const contextValue = useMemo(
    () => ({
      ...DEFAULT_CHART_LIFECYCLE,
      data,
      renderData,
      xScale,
      yScale,
      yScales,
      width,
      height,
      innerWidth,
      innerHeight,
      margin,
      columnWidth,
      tooltipData,
      setTooltipData,
      containerRef,
      lines,
      referenceAreas,
      isLoaded,
      animationDuration,
      enterTransition,
      revealEpoch,
      xAccessor,
      dateLabels,
      selection: selection ?? null,
      clearSelection,
      bandWidth,
      hoveredCandleIndex,
    }),
    [
      data,
      renderData,
      xScale,
      yScale,
      yScales,
      width,
      height,
      innerWidth,
      innerHeight,
      margin,
      columnWidth,
      tooltipData,
      setTooltipData,
      containerRef,
      lines,
      referenceAreas,
      isLoaded,
      animationDuration,
      enterTransition,
      revealEpoch,
      xAccessor,
      dateLabels,
      selection,
      clearSelection,
      bandWidth,
      hoveredCandleIndex,
    ]
  );

  return (
    <ChartProvider value={contextValue}>
      <svg
        aria-hidden="true"
        className="overflow-visible"
        height={height}
        width={width}
      >
        <defs>
          {/* Default vertical gradients for positive/negative candles (--chart-positive / --chart-negative) */}
          <linearGradient id="candlestick-positive" x1="0" x2="0" y1="1" y2="0">
            <stop
              offset="0%"
              stopColor="var(--chart-positive, var(--color-emerald-500))"
            />
            <stop
              offset="100%"
              stopColor="var(--chart-positive, var(--color-emerald-500))"
            />
          </linearGradient>
          <linearGradient id="candlestick-negative" x1="0" x2="0" y1="1" y2="0">
            <stop
              offset="0%"
              stopColor="var(--chart-negative, var(--color-red-500))"
            />
            <stop
              offset="100%"
              stopColor="var(--chart-negative, var(--color-red-500))"
            />
          </linearGradient>
          {defsChildren}
        </defs>
        <rect fill="transparent" height={height} width={width} x={0} y={0} />
        <g
          {...interactionHandlers}
          style={interactionStyle}
          transform={`translate(${margin.left},${margin.top})`}
        >
          <rect
            fill="transparent"
            height={innerHeight}
            width={innerWidth}
            x={0}
            y={0}
          />
          {clipExcludedChildren}
          {underlayChildren}
          {preOverlayChildren}
          {postOverlayChildren}
        </g>
      </svg>
    </ChartProvider>
  );
});

export function CandlestickChart({
  data,
  xDataKey = "date",
  margin: marginProp,
  animationDuration = 1100,
  enterTransition,
  revealSignature,
  aspectRatio = "2 / 1",
  className = "",
  style,
  candleGap = 0.2,
  candleWidth,
  xDomain,
  xDomainSlotCount,
  children,
}: CandlestickChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const margin = { ...DEFAULT_MARGIN, ...marginProp };
  const dataAsRecords = data as unknown as Record<string, unknown>[];

  return (
    <LazyMotion features={domAnimation}>
      <div
        className={cn("relative w-full", className)}
        ref={containerRef}
        style={{ aspectRatio, touchAction: "none", ...style }}
      >
        <ParentSize debounceTime={10}>
          {({ width, height }) => (
            <ChartInner
              animationDuration={animationDuration}
              candleGap={candleGap}
              candleWidthProp={candleWidth}
              containerRef={containerRef}
              data={dataAsRecords}
              enterTransition={enterTransition}
              height={height}
              margin={margin}
              revealSignature={revealSignature}
              width={width}
              xDataKey={xDataKey}
              xDomain={xDomain}
              xDomainSlotCount={xDomainSlotCount}
            >
              {children}
            </ChartInner>
          )}
        </ParentSize>
      </div>
    </LazyMotion>
  );
}

CandlestickChart.displayName = "CandlestickChart";

export default CandlestickChart;

"use client";

import type { Transition } from "motion/react";
import { m } from "motion/react";
import { memo, useMemo } from "react";
import { useChart, useYScale } from "./chart-context";
import { useChartLegendHover } from "./chart-legend-hover";
import { transitionWithDelay } from "./motion-utils";

const DEFAULT_POSITIVE = "url(#candlestick-positive)";
const DEFAULT_NEGATIVE = "url(#candlestick-negative)";

const SOLID_POSITIVE = "var(--chart-positive, var(--color-emerald-500))";
const SOLID_NEGATIVE = "var(--chart-negative, var(--color-red-500))";
const WICK_WIDTH = 1.5;

export interface CandlestickProps {
  /** Whether to animate the candlesticks. Default: true */
  animate?: boolean;
  /** Fill for positive (close >= open) candles. Color or url(#gradient). Default: --chart-positive (emerald) */
  positiveFill?: string;
  /** Fill for negative candles. Color or url(#gradient). Default: --chart-negative (red) */
  negativeFill?: string;
  /** Optional pattern URL for body only (e.g. url(#pattern)). When set, body is drawn solid first, then pattern overlaid and masked to the body rect. */
  bodyPatternPositive?: string;
  /** Optional pattern URL for negative candle body. */
  bodyPatternNegative?: string;
  /** Inner border width on the body (drawn inside so it does not expand the shape). Default: 0 (off). */
  insideStrokeWidth?: number;
  /** Opacity when another candle is hovered. Default: 0.3 */
  fadedOpacity?: number;
  /** Dim non-hovered candles on hover. Default: true */
  showHoverFade?: boolean;
  /**
   * Y-scale group id (Recharts `yAxisId`). Inside `ComposedChart`, put price
   * candles on their own axis (e.g. `"right"`) so volume bars or other series
   * keep a zero baseline on `"left"`. Default: `"left"`.
   */
  yAxisId?: string | number;
  /**
   * Body width as a fraction of the slot between two x values (0–1). Only
   * used outside `CandlestickChart` (e.g. in `ComposedChart`); `CandlestickChart`
   * sizes candles with `candleGap` / `candleWidth`. Default: 0.6
   */
  widthRatio?: number;
}

interface CandleGeometry {
  time: number;
  centerX: number;
  bodyTop: number;
  bodyHeight: number;
  bodyLeft: number;
  candleWidth: number;
  wickTop: number;
  wickHeight: number;
  wickLeft: number;
  bodySolidFill: string;
  wickFill: string;
  bodyPattern?: string;
  insideStrokeWidth: number;
  isPositive: boolean;
}

function getSolidColor(isPositive: boolean): string {
  return isPositive ? SOLID_POSITIVE : SOLID_NEGATIVE;
}

function computeGeometries(
  renderData: Record<string, unknown>[],
  xScale: (value: Date) => number | undefined,
  yScale: (value: number) => number | undefined,
  xAccessor: (d: Record<string, unknown>) => Date,
  candleWidth: number,
  positiveFill: string,
  negativeFill: string,
  bodyPatternPositive: string | undefined,
  bodyPatternNegative: string | undefined,
  insideStrokeWidth: number
): CandleGeometry[] {
  return renderData.map((d) => {
    const date = xAccessor(d);
    const open = d.open as number;
    const high = d.high as number;
    const low = d.low as number;
    const close = d.close as number;
    const centerX = xScale(date) ?? 0;
    const yHigh = yScale(high) ?? 0;
    const yLow = yScale(low) ?? 0;
    const yOpen = yScale(open) ?? 0;
    const yClose = yScale(close) ?? 0;
    const bodyTop = Math.min(yOpen, yClose);
    const bodyHeight = Math.abs(yClose - yOpen) || 1;
    const bodyLeft = centerX - candleWidth / 2;
    const wickTop = Math.min(yHigh, yLow);
    const wickHeight = Math.abs(yLow - yHigh) || 1;
    const isPositive = close >= open;
    const fill = isPositive ? positiveFill : negativeFill;
    const bodyPattern = isPositive ? bodyPatternPositive : bodyPatternNegative;
    const hasPatternOverlay = Boolean(bodyPattern);
    const bodySolidFill = hasPatternOverlay ? getSolidColor(isPositive) : fill;

    return {
      time: date.getTime(),
      centerX,
      bodyTop,
      bodyHeight,
      bodyLeft,
      candleWidth,
      wickTop,
      wickHeight,
      wickLeft: centerX - WICK_WIDTH / 2,
      bodySolidFill,
      wickFill: hasPatternOverlay ? bodySolidFill : fill,
      bodyPattern: hasPatternOverlay ? bodyPattern : undefined,
      insideStrokeWidth,
      isPositive,
    };
  });
}

function geometryDimOpacity(
  geometry: CandleGeometry,
  fadedOpacity: number,
  legendHoveredIndex: number | null,
  hoveredTime: number | null
): number {
  if (legendHoveredIndex !== null) {
    const dimFromLegend =
      (legendHoveredIndex === 0 && !geometry.isPositive) ||
      (legendHoveredIndex === 1 && geometry.isPositive);
    return dimFromLegend ? fadedOpacity : 1;
  }
  if (hoveredTime !== null && geometry.time !== hoveredTime) {
    return fadedOpacity;
  }
  return 1;
}

const CandlestickBody = memo(function CandlestickBody({
  geometry,
}: {
  geometry: CandleGeometry;
}) {
  const {
    wickLeft,
    wickTop,
    wickHeight,
    wickFill,
    bodyLeft,
    bodyTop,
    bodyHeight,
    candleWidth,
    bodySolidFill,
    bodyPattern,
    insideStrokeWidth,
  } = geometry;

  return (
    <>
      <rect
        fill={wickFill}
        height={wickHeight}
        width={WICK_WIDTH}
        x={wickLeft}
        y={wickTop}
      />
      <rect
        fill={bodySolidFill}
        height={bodyHeight}
        rx={1}
        ry={1}
        stroke={bodySolidFill}
        strokeWidth={1}
        width={candleWidth}
        x={bodyLeft}
        y={bodyTop}
      />
      {bodyPattern ? (
        <rect
          fill={bodyPattern}
          height={bodyHeight}
          rx={1}
          ry={1}
          width={candleWidth}
          x={bodyLeft}
          y={bodyTop}
        />
      ) : null}
      {insideStrokeWidth > 0 ? (
        <rect
          fill="none"
          height={Math.max(0, bodyHeight - insideStrokeWidth)}
          rx={1}
          ry={1}
          stroke={bodySolidFill}
          strokeWidth={insideStrokeWidth}
          width={Math.max(0, candleWidth - insideStrokeWidth)}
          x={bodyLeft + insideStrokeWidth / 2}
          y={bodyTop + insideStrokeWidth / 2}
        />
      ) : null}
    </>
  );
});

const CandlestickBodies = memo(function CandlestickBodies({
  geometries,
  fadedOpacity,
  legendHoveredIndex,
  hoveredTime,
}: {
  geometries: CandleGeometry[];
  fadedOpacity: number;
  legendHoveredIndex: number | null;
  hoveredTime: number | null;
}) {
  return (
    <>
      {geometries.map((geometry) => (
        <g
          key={geometry.time}
          opacity={geometryDimOpacity(
            geometry,
            fadedOpacity,
            legendHoveredIndex,
            hoveredTime
          )}
          style={{ transition: "opacity 0.15s ease-in-out" }}
        >
          <CandlestickBody geometry={geometry} />
        </g>
      ))}
    </>
  );
});

interface AnimatedCandleProps {
  geometry: CandleGeometry;
  delay: number;
  enterTransition: Transition;
  revealEpoch: number;
}

function AnimatedCandle({
  geometry,
  delay,
  enterTransition,
  revealEpoch,
}: AnimatedCandleProps) {
  const t = transitionWithDelay(enterTransition, delay);
  const bodyOrigin = `${geometry.centerX}px ${geometry.bodyTop + geometry.bodyHeight / 2}px`;
  const wickCenterY = geometry.wickTop + geometry.wickHeight / 2;

  return (
    <m.g
      animate={{ opacity: 1 }}
      initial={{ opacity: 0 }}
      key={`candle-enter-${geometry.time}-${revealEpoch}`}
      style={{ transformOrigin: `${geometry.centerX}px ${wickCenterY}px` }}
      transition={{ ...t, opacity: { duration: 0.15 } }}
    >
      <m.rect
        animate={{ scaleY: 1 }}
        fill={geometry.wickFill}
        height={geometry.wickHeight}
        initial={{ scaleY: 0 }}
        style={{ transformOrigin: `${geometry.centerX}px ${wickCenterY}px` }}
        transition={t}
        width={WICK_WIDTH}
        x={geometry.wickLeft}
        y={geometry.wickTop}
      />
      <m.rect
        animate={{ scaleY: 1 }}
        fill={geometry.bodySolidFill}
        height={geometry.bodyHeight}
        initial={{ scaleY: 0 }}
        rx={1}
        ry={1}
        stroke={geometry.bodySolidFill}
        strokeWidth={1}
        style={{ transformOrigin: bodyOrigin }}
        transition={t}
        width={geometry.candleWidth}
        x={geometry.bodyLeft}
        y={geometry.bodyTop}
      />
      {geometry.bodyPattern ? (
        <m.rect
          animate={{ scaleY: 1 }}
          fill={geometry.bodyPattern}
          height={geometry.bodyHeight}
          initial={{ scaleY: 0 }}
          rx={1}
          ry={1}
          style={{ transformOrigin: bodyOrigin }}
          transition={t}
          width={geometry.candleWidth}
          x={geometry.bodyLeft}
          y={geometry.bodyTop}
        />
      ) : null}
    </m.g>
  );
}

export function Candlestick({
  animate = true,
  positiveFill = DEFAULT_POSITIVE,
  negativeFill = DEFAULT_NEGATIVE,
  bodyPatternPositive,
  bodyPatternNegative,
  insideStrokeWidth = 0,
  fadedOpacity = 0.3,
  showHoverFade = true,
  yAxisId,
  widthRatio = 0.6,
}: CandlestickProps) {
  const {
    data,
    xScale,
    xAccessor,
    animationDuration,
    enterTransition,
    revealEpoch = 0,
    isLoaded,
    bandWidth,
    columnWidth,
    hoveredCandleIndex: chartHoveredCandleIndex,
    tooltipData,
  } = useChart();
  const yScale = useYScale(yAxisId);
  const { hoveredIndex: legendHoveredIndex } = useChartLegendHover();
  // `CandlestickChart` publishes `bandWidth` and the default gradient defs;
  // inside other time-series shells (ComposedChart) size candles from the
  // column width and fall back to the equivalent solid fills.
  const inCandlestickChart = bandWidth != null;
  const hoveredCandleIndex =
    chartHoveredCandleIndex ?? tooltipData?.index ?? null;
  const ratio = Math.min(Math.max(widthRatio, 0.05), 1);
  const candleWidth = Math.max(
    1,
    Math.min(
      bandWidth ?? columnWidth * ratio,
      columnWidth || Number.POSITIVE_INFINITY
    )
  );
  const resolvedPositiveFill =
    !inCandlestickChart && positiveFill === DEFAULT_POSITIVE
      ? SOLID_POSITIVE
      : positiveFill;
  const resolvedNegativeFill =
    !inCandlestickChart && negativeFill === DEFAULT_NEGATIVE
      ? SOLID_NEGATIVE
      : negativeFill;

  const geometries = useMemo(
    () =>
      computeGeometries(
        data,
        xScale,
        yScale,
        xAccessor,
        candleWidth,
        resolvedPositiveFill,
        resolvedNegativeFill,
        bodyPatternPositive,
        bodyPatternNegative,
        insideStrokeWidth
      ),
    [
      data,
      xScale,
      yScale,
      xAccessor,
      candleWidth,
      resolvedPositiveFill,
      resolvedNegativeFill,
      bodyPatternPositive,
      bodyPatternNegative,
      insideStrokeWidth,
    ]
  );

  const hoveredTime = useMemo(() => {
    if (hoveredCandleIndex == null) {
      return null;
    }
    const point = data[hoveredCandleIndex];
    return point ? xAccessor(point).getTime() : null;
  }, [hoveredCandleIndex, data, xAccessor]);

  const highlightGeometry = useMemo(() => {
    if (hoveredCandleIndex == null) {
      return null;
    }
    const point = data[hoveredCandleIndex];
    if (!point) {
      return null;
    }
    return (
      computeGeometries(
        [point],
        xScale,
        yScale,
        xAccessor,
        candleWidth,
        resolvedPositiveFill,
        resolvedNegativeFill,
        bodyPatternPositive,
        bodyPatternNegative,
        insideStrokeWidth
      )[0] ?? null
    );
  }, [
    hoveredCandleIndex,
    data,
    xScale,
    yScale,
    xAccessor,
    candleWidth,
    resolvedPositiveFill,
    resolvedNegativeFill,
    bodyPatternPositive,
    bodyPatternNegative,
    insideStrokeWidth,
  ]);

  const defaultEnter: Transition = {
    type: "spring",
    duration: 0.8,
    bounce: 0.15,
  };
  const enter = enterTransition ?? defaultEnter;
  const staggerDelayMs =
    data.length > 0 ? (animationDuration * 0.6) / data.length : 0;

  if (animate && !isLoaded) {
    return (
      <g className="chart-candlesticks">
        {geometries.map((geometry, index) => (
          <AnimatedCandle
            delay={(index * staggerDelayMs) / 1000}
            enterTransition={enter}
            geometry={geometry}
            key={geometry.time}
            revealEpoch={revealEpoch}
          />
        ))}
      </g>
    );
  }

  return (
    <g className="chart-candlesticks">
      <CandlestickBodies
        fadedOpacity={fadedOpacity}
        geometries={geometries}
        hoveredTime={showHoverFade ? hoveredTime : null}
        legendHoveredIndex={legendHoveredIndex}
      />
      {highlightGeometry ? (
        <g>
          <CandlestickBody geometry={highlightGeometry} />
        </g>
      ) : null}
    </g>
  );
}

Candlestick.displayName = "Candlestick";

export default Candlestick;

"use client";

import { createPortal } from "react-dom";
import type { ChartBrushOverlayHost } from "./chart-brush-track-overlay";
import { useChartPortalContainer, useChartStable } from "./chart-context";

/** Matches shadcn `ResizableHandle` withHandle pill (`h-6 w-1 rounded-lg`). */
const HANDLE_HEIGHT_PX = 24;
const HANDLE_WIDTH_PX = 4;

/** Props passed to a brush handle renderer (same shape as visx `BrushHandleRenderProps`). */
export interface BrushHandleRenderProps {
  x: number;
  y: number;
  width: number;
  height: number;
  /** `visx-brush-handle-left` / `visx-brush-handle-right`. */
  className: string;
  /** False while the brush is empty (extent -1). */
  isBrushActive: boolean;
}

/**
 * Invisible hit target for a brush resize handle.
 * Visible pills render in `ChartBrushHandleOverlay` above the blur layer.
 */
function brushHandleCursor(className: string) {
  return className.includes("left") || className.includes("right")
    ? "ew-resize"
    : "ns-resize";
}

export function renderChartBrushHandle({
  x,
  y,
  width,
  height,
  className,
}: BrushHandleRenderProps) {
  return (
    <rect
      className={className}
      fill="transparent"
      height={height}
      style={{ cursor: brushHandleCursor(className) }}
      width={width}
      x={x}
      y={y}
    />
  );
}

export interface ChartBrushHandleOverlayProps {
  innerWidth: number;
  innerHeight: number;
  /** Pixel x of the selection start within the plot area. */
  selectionX0: number;
  /** Pixel x of the selection end within the plot area. */
  selectionX1: number;
}

/** Renders brush resize pills above the outside blur portal (`z-[2]`). */
export function ChartBrushHandleOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
}: ChartBrushHandleOverlayProps & ChartBrushOverlayHost) {
  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const edges = x0 === x1 ? [x0] : [x0, x1];

  const plotLeft = margin.left;
  const plotTop = margin.top;
  const handleTop = plotTop + (innerHeight - HANDLE_HEIGHT_PX) / 2;

  return createPortal(
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[2]"
    >
      {edges.map((edgeX) => (
        <div
          className="absolute shrink-0 rounded-lg"
          key={edgeX}
          style={{
            top: handleTop,
            left: plotLeft + edgeX - HANDLE_WIDTH_PX / 2,
            width: HANDLE_WIDTH_PX,
            height: HANDLE_HEIGHT_PX,
            backgroundColor: "var(--chart-brush-border)",
          }}
        />
      ))}
    </div>,
    container
  );
}

export function ChartBrushHandleOverlay(props: ChartBrushHandleOverlayProps) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushHandleOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}

"use client";

import {
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import type { ChartBrushSelection } from "./chart-brush";
import { resolveBrushTrackXExtent } from "./filter-data-by-x-domain";

export interface ChartBrushLayoutState {
  xDomain: [Date, Date] | undefined;
  xDomainSlotCount: number | undefined;
  brushSelection: ChartBrushSelection | null;
  onBrushSelectionChange: (selection: ChartBrushSelection | null) => void;
}

export interface ChartBrushLayoutProps {
  /** Full dataset backing the brush strip and main chart. */
  data: Record<string, unknown>[];
  xDataKey?: string;
  /** Extends the brush track max beyond the last data row (e.g. projection horizon). */
  xExtentMax?: Date;
  /** When false, children render without brush zoom state. */
  enabled: boolean;
  /** Fixed height of the brush strip in pixels. */
  height: number;
  /** When true, the main chart area hugs content instead of growing to fill space. */
  fitMainContent?: boolean;
  className?: string;
  children: (layout: ChartBrushLayoutState) => ReactNode;
  /** Mini chart + brush handles rendered below the main chart when `enabled`. */
  brushStrip?: (layout: ChartBrushLayoutState) => ReactNode;
}

function createXAccessor(xDataKey: string) {
  return (d: Record<string, unknown>): Date => {
    const value = d[xDataKey];
    return value instanceof Date ? value : new Date(value as string | number);
  };
}

export const ChartBrushLayout = memo(function ChartBrushLayout({
  data,
  xDataKey = "date",
  xExtentMax,
  enabled,
  height,
  fitMainContent = false,
  className,
  children,
  brushStrip,
}: ChartBrushLayoutProps) {
  const xAccessor = useMemo(() => createXAccessor(xDataKey), [xDataKey]);
  const fullExtent = useMemo(
    () => resolveBrushTrackXExtent(data, xAccessor, xExtentMax),
    [data, xAccessor, xExtentMax]
  );
  const [brushSelection, setBrushSelection] =
    useState<ChartBrushSelection | null>(null);
  const previousExtent = useRef<typeof fullExtent>(null);

  useEffect(() => {
    // Reconnecting a hidden chart's effects preserves the selected range.
    if (previousExtent.current === fullExtent) return;
    previousExtent.current = fullExtent;
    if (!fullExtent) {
      setBrushSelection(null);
      return;
    }
    setBrushSelection({ start: fullExtent[0], end: fullExtent[1] });
  }, [fullExtent]);

  const handleBrushSelectionChange = useCallback(
    (selection: ChartBrushSelection | null) => {
      if (!selection) {
        if (fullExtent) {
          setBrushSelection({ start: fullExtent[0], end: fullExtent[1] });
        }
        return;
      }
      setBrushSelection(selection);
    },
    [fullExtent]
  );

  const layoutState = useMemo<ChartBrushLayoutState>(
    () => ({
      xDomain:
        enabled && brushSelection
          ? ([brushSelection.start, brushSelection.end] as [Date, Date])
          : undefined,
      xDomainSlotCount: enabled ? data.length : undefined,
      brushSelection,
      onBrushSelectionChange: handleBrushSelectionChange,
    }),
    [brushSelection, data.length, enabled, handleBrushSelectionChange]
  );

  return (
    <div
      className={cn(
        "flex size-full min-h-0 min-w-0 flex-col",
        fitMainContent ? "justify-start gap-1" : "gap-3",
        className
      )}
    >
      <div
        className={cn(
          "min-h-0 min-w-0",
          fitMainContent ? "shrink-0" : "flex-1"
        )}
      >
        {children(layoutState)}
      </div>
      {enabled && brushStrip ? (
        <div className="min-h-0 shrink-0" style={{ height }}>
          {brushStrip(layoutState)}
        </div>
      ) : null}
    </div>
  );
});

"use client";

import { useId } from "react";
import { createPortal } from "react-dom";
import type { ChartBrushOverlayHost } from "./chart-brush-track-overlay";
import { useChartPortalContainer, useChartStable } from "./chart-context";
import {
  type PatternPresetId,
  type PatternPresetOptions,
  renderPatternPreset,
} from "./pattern-preset";

export type ChartBrushPatternPreset = PatternPresetId;

export interface ChartBrushSelectionPattern extends PatternPresetOptions {
  preset: ChartBrushPatternPreset;
  color: string;
  opacity?: number;
}

export interface ChartBrushSelectionOverlayProps {
  innerWidth: number;
  innerHeight: number;
  selectionX0: number;
  selectionX1: number;
  pattern?: ChartBrushSelectionPattern;
}

/** Pattern fill between brush handles (`z-[1]`, above blur panes). */
export function ChartBrushSelectionOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
  pattern,
}: ChartBrushSelectionOverlayProps & ChartBrushOverlayHost) {
  const patternId = useId().replace(/:/g, "");

  const container = useChartPortalContainer(containerRef);
  if (!(container && pattern && pattern.preset !== "none")) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const selectionWidth = x1 - x0;
  if (selectionWidth <= 0) {
    return null;
  }

  const plotLeft = margin.left;
  const plotTop = margin.top;
  const patternNode = renderPatternPreset(pattern.preset, patternId, {
    color: pattern.color,
    scale: pattern.scale,
    strokeWidth: pattern.strokeWidth,
    radius: pattern.radius,
    complement: pattern.complement,
    fill: pattern.fill,
    tileBackground: pattern.tileBackground,
  });
  if (!patternNode) {
    return null;
  }

  return createPortal(
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[1]"
      height="100%"
      width="100%"
    >
      <defs>{patternNode}</defs>
      <rect
        fill={`url(#${patternId})`}
        fillOpacity={pattern.opacity ?? 1}
        height={innerHeight}
        width={selectionWidth}
        x={plotLeft + x0}
        y={plotTop}
      />
    </svg>,
    container
  );
}

export function ChartBrushSelectionOverlay(
  props: ChartBrushSelectionOverlayProps
) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushSelectionOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}

/**
 * Pure state machine behind `ChartBrush`, reproducing `@visx/brush` 4.0.0
 * (`Brush` + `BaseBrush` + `BrushSelection` + `BrushHandle` + `@visx/drag`)
 * step for step, so the emitted selections stay identical:
 *
 * - Pixel state is `start` / `end` (committed corners) plus `extent` (what is
 *   drawn). An empty brush has `extent` -1 on every side.
 * - Pointer down on the track starts a new selection at the pointer
 *   (`extent` -1, so the brush emits `null`); down on the selection moves it;
 *   down on a handle resizes from that edge. Each start emits `onChange`.
 * - Moves are offsets from the pointer-down position. With window move events
 *   (the bklit default) the offset is in page pixels and every mode is clamped
 *   to the track; without, it is in SVG units and only `move` / the right
 *   handle are clamped (visx behaviour).
 * - Pointer up commits: `onBrushEnd` then `onChange` (local mode emits one
 *   more `onChange` for `move` / handle drags). A click without a drag on the
 *   track commits `null`.
 * - Pixels convert to the domain through `scale.invert`, widened by visx's
 *   `SAFE_PIXEL` (2 px) on each side; a zero-width extent inverts to
 *   start === end, which `ChartBrush` reports as `null`.
 */

export type BrushDirection = "horizontal" | "vertical" | "both";

/** What a pointer drag does: draw a new selection, move it, or resize it. */
export type BrushingType = "select" | "move" | "left" | "right";

export type BrushHandleType = "left" | "right";

export interface BrushPoint {
  x: number;
  y: number;
}

export interface BrushExtent {
  x0: number;
  x1: number;
  y0: number;
  y1: number;
}

export interface BrushStage {
  width: number;
  height: number;
  direction: BrushDirection;
}

export interface BrushState {
  start: BrushPoint;
  end: BrushPoint;
  extent: BrushExtent;
  isBrushing: boolean;
  brushingType: BrushingType | undefined;
  /** Only set by local-mode handle drags (visx `activeHandle`). */
  activeHandle: BrushHandleType | null;
}

/**
 * `true` = window move events (page-pixel offsets, everything clamped to the
 * track); `false` = local pointer events on the brush (SVG-unit offsets).
 */
export type BrushMoveMode = "window" | "local";

/** visx `SAFE_PIXEL`: the selection is widened by this many px before inverting. */
export const BRUSH_SAFE_PIXEL = 2;

const EMPTY_EXTENT: BrushExtent = { x0: -1, x1: -1, y0: -1, y1: -1 };

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/** visx `BaseBrush.getExtent`: normalise two corners for the brush direction. */
export function getBrushExtent(
  start: Partial<BrushPoint>,
  end: Partial<BrushPoint>,
  stage: BrushStage
): BrushExtent {
  const { direction, width, height } = stage;
  return {
    x0: direction === "vertical" ? 0 : Math.min(start.x || 0, end.x || 0),
    x1: direction === "vertical" ? width : Math.max(start.x || 0, end.x || 0),
    y0: direction === "horizontal" ? 0 : Math.min(start.y || 0, end.y || 0),
    y1:
      direction === "horizontal" ? height : Math.max(start.y || 0, end.y || 0),
  };
}

export interface BrushInitialPosition {
  start?: { x?: number; y?: number };
  end?: { x?: number; y?: number };
}

/** visx `BaseBrush` constructor state (`initialBrushPosition` in pixels). */
export function createBrushState(
  stage: BrushStage,
  initial?: BrushInitialPosition | null
): BrushState {
  const extent = initial
    ? getBrushExtent(initial.start ?? {}, initial.end ?? {}, stage)
    : { ...EMPTY_EXTENT };
  return {
    start: { x: Math.max(0, extent.x0), y: Math.max(0, extent.y0) },
    end: { x: Math.max(0, extent.x1), y: Math.max(0, extent.y1) },
    extent,
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  };
}

/** visx `BaseBrush.getIdleState` (double-click on the track). */
export function idleBrushState(): BrushState {
  return {
    start: { x: 0, y: 0 },
    end: { x: 0, y: 0 },
    extent: { ...EMPTY_EXTENT },
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  };
}

/** Pointer down on the track: start a new selection at `point` (plot px). */
export function beginBrushSelect(
  state: BrushState,
  point: BrushPoint
): BrushState {
  return {
    ...state,
    start: point,
    end: { ...point },
    extent: { ...EMPTY_EXTENT },
    isBrushing: true,
    brushingType: "select",
  };
}

/** Pointer down on the selection (`move`) or a handle. */
export function beginBrushDrag(
  state: BrushState,
  type: Exclude<BrushingType, "select">
): BrushState {
  return { ...state, brushingType: type, isBrushing: true };
}

function moveSelection(
  state: BrushState,
  offset: BrushPoint,
  stage: BrushStage
): BrushState {
  const { start, end } = state;
  const validDx =
    offset.x > 0
      ? Math.min(offset.x, stage.width - end.x)
      : Math.max(offset.x, 0 - start.x);
  const validDy =
    offset.y > 0
      ? Math.min(offset.y, stage.height - end.y)
      : Math.max(offset.y, 0 - start.y);
  return {
    ...state,
    isBrushing: true,
    extent: {
      ...state.extent,
      x0: start.x + validDx,
      x1: end.x + validDx,
      y0: start.y + validDy,
      y1: end.y + validDy,
    },
  };
}

/**
 * Pointer moved by `offset` since pointer down. Returns `state` unchanged when
 * no drag is in progress.
 */
export function dragBrush(
  state: BrushState,
  offset: BrushPoint,
  stage: BrushStage,
  mode: BrushMoveMode
): BrushState {
  const { brushingType } = state;
  if (!(state.isBrushing && brushingType)) {
    return state;
  }
  if (brushingType === "move") {
    return moveSelection(state, offset, stage);
  }
  if (brushingType === "select") {
    const end =
      mode === "window"
        ? {
            x: clamp(state.start.x + offset.x, 0, stage.width),
            y: clamp(state.start.y + offset.y, 0, stage.height),
          }
        : { x: state.start.x + offset.x, y: state.start.y + offset.y };
    return { ...state, end, extent: getBrushExtent(state.start, end, stage) };
  }

  // Resize from the left / right handle.
  if (mode === "window") {
    const { x: x0, y: y0 } = state.start;
    const { x: x1, y: y1 } = state.end;
    return {
      ...state,
      isBrushing: true,
      extent: {
        ...state.extent,
        ...getBrushExtent(
          {
            x:
              brushingType === "left"
                ? clamp(x0 + offset.x, 0, stage.width)
                : x0,
            y: y0,
          },
          {
            x:
              brushingType === "right"
                ? clamp(x1 + offset.x, 0, stage.width)
                : x1,
            y: y1,
          },
          stage
        ),
      },
    };
  }
  const { start, end } = state;
  if (brushingType === "right") {
    const move = Math.max(start.x, end.x) + offset.x;
    return {
      ...state,
      activeHandle: "right",
      extent: {
        ...state.extent,
        x0: Math.max(Math.min(move, start.x), 0),
        x1: Math.min(Math.max(move, start.x), stage.width),
      },
    };
  }
  const move = Math.min(start.x, end.x) + offset.x;
  return {
    ...state,
    activeHandle: "left",
    extent: {
      ...state.extent,
      x0: Math.min(move, end.x),
      x1: Math.max(move, end.x),
    },
  };
}

export interface BrushEndResult {
  state: BrushState;
  /** How many `onChange` calls follow the single `onBrushEnd`. */
  changeCount: 1 | 2;
}

/** Pointer up: commit the drawn extent. `null` when no drag was in progress. */
export function endBrush(
  state: BrushState,
  mode: BrushMoveMode
): BrushEndResult | null {
  const { brushingType, extent } = state;
  if (!brushingType) {
    return null;
  }
  const idle = {
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  } as const;

  if (mode === "window" || brushingType === "move") {
    return {
      state: {
        ...state,
        ...idle,
        start: {
          x: Math.min(extent.x0, extent.x1),
          y: mode === "window" ? extent.y0 : Math.min(extent.y0, extent.y1),
        },
        end: {
          x: Math.max(extent.x0, extent.x1),
          y: Math.max(extent.y0, extent.y1),
        },
      },
      changeCount: mode === "window" ? 1 : 2,
    };
  }
  if (brushingType === "select") {
    return {
      state: {
        ...state,
        ...idle,
        start: { x: extent.x0, y: extent.y0 },
        end: { x: extent.x1, y: extent.y1 },
      },
      changeCount: 1,
    };
  }
  const start = { x: Math.min(extent.x0, extent.x1), y: extent.y0 };
  const end = {
    x: Math.max(extent.x0, extent.x1),
    y: Math.max(extent.y0, extent.y1),
  };
  return {
    state: {
      ...state,
      ...idle,
      start,
      end,
      extent: {
        x0: Math.min(start.x, end.x),
        x1: Math.max(start.x, end.x),
        y0: Math.min(start.y, end.y),
        y1: Math.max(start.y, end.y),
      },
    },
    changeCount: 2,
  };
}

/** visx selection rect geometry (`getBrushWidth` / `getBrushHeight`). */
export function brushSelectionRect(extent: BrushExtent) {
  return {
    x: Math.min(extent.x0, extent.x1),
    y: Math.min(extent.y0, extent.y1),
    width: Math.max(
      Math.max(extent.x0, extent.x1) - Math.min(extent.x0, extent.x1),
      0
    ),
    height: Math.max(
      Math.max(extent.y0, extent.y1) - Math.min(extent.y0, extent.y1),
      0
    ),
  };
}

/**
 * Handle hit rects, in visx DOM order (`right` then `left`, so `left` wins
 * where they overlap). Height is the full stage, as visx passes
 * `height: stageHeight` to `renderBrushHandle`.
 */
export function brushHandleRects(
  extent: BrushExtent,
  handleSize: number,
  stageHeight: number
): {
  type: BrushHandleType;
  x: number;
  y: number;
  width: number;
  height: number;
}[] {
  const offset = handleSize / 2;
  return [
    {
      type: "right",
      x: extent.x1 - offset,
      y: extent.y0 - offset,
      width: handleSize,
      height: stageHeight,
    },
    {
      type: "left",
      x: extent.x0 - offset,
      y: extent.y0 - offset,
      width: handleSize,
      height: stageHeight,
    },
  ];
}

export interface BrushDomainBounds {
  x0: number;
  x1: number;
}

type InvertibleScale = (value: number) => unknown;

function invertToNumber(invert: InvertibleScale, value: number): number {
  return Number((invert(value) as { valueOf(): number }).valueOf());
}

/**
 * visx `Brush.convertRangeToDomain` for the x axis: `null` for an empty brush,
 * otherwise the extent widened by `SAFE_PIXEL` and inverted (numbers, e.g.
 * epoch ms for a time scale; NaN falls back to 0 like visx's `|| 0`).
 */
export function brushExtentToDomain(
  extent: BrushExtent,
  invert: InvertibleScale
): BrushDomainBounds | null {
  const { x0, x1 } = extent;
  if (typeof x0 === "undefined" || x0 < 0) {
    return null;
  }
  const start = x0 || 0;
  const end = x1 || 0;
  const invertedStart = invertToNumber(
    invert,
    start + (start < end ? -BRUSH_SAFE_PIXEL : BRUSH_SAFE_PIXEL)
  );
  const invertedEnd = invertToNumber(
    invert,
    end + (end < start ? -BRUSH_SAFE_PIXEL : BRUSH_SAFE_PIXEL)
  );
  return {
    x0: Math.min(invertedStart, invertedEnd) || 0,
    x1: Math.max(invertedStart, invertedEnd) || 0,
  };
}

"use client";

import type { CSSProperties, RefObject } from "react";
import { createPortal } from "react-dom";
import type { Margin } from "./chart-context";
import { useChartPortalContainer, useChartStable } from "./chart-context";

/** Fade dimming panes at the outer track ends — matches series edge fade (15%). */
const BRUSH_TRACK_OUTER_FADE = 0.15;

export interface ChartBrushTrackOverlayStyle {
  /** Backdrop blur in px (0–5). Default: 1.5 */
  blurPx?: number;
  /** Fade blur at the outer left/right track ends. Default: true */
  fadeOuterEdges?: boolean;
}

function outsidePaneStyle(
  edge: "left" | "right",
  style: Required<ChartBrushTrackOverlayStyle>
): CSSProperties {
  const fadeStop = `${BRUSH_TRACK_OUTER_FADE * 100}%`;
  let mask: string | undefined;
  if (style.fadeOuterEdges) {
    mask =
      edge === "left"
        ? `linear-gradient(to right, transparent 0%, black ${fadeStop}, black 100%)`
        : `linear-gradient(to left, transparent 0%, black ${fadeStop}, black 100%)`;
  }

  return {
    pointerEvents: "none",
    backdropFilter: style.blurPx > 0 ? `blur(${style.blurPx}px)` : undefined,
    WebkitBackdropFilter:
      style.blurPx > 0 ? `blur(${style.blurPx}px)` : undefined,
    maskImage: mask,
    WebkitMaskImage: mask,
  };
}

export interface ChartBrushTrackOverlayProps
  extends ChartBrushTrackOverlayStyle {
  innerWidth: number;
  innerHeight: number;
  /** Pixel x of the selection start within the plot area. */
  selectionX0: number;
  /** Pixel x of the selection end within the plot area. */
  selectionX1: number;
}

export interface ChartBrushOverlayHost {
  containerRef: RefObject<HTMLDivElement | null>;
  margin: Margin;
}

export function ChartBrushTrackOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
  blurPx = 1.5,
  fadeOuterEdges = true,
}: ChartBrushTrackOverlayProps & ChartBrushOverlayHost) {
  const overlayStyle: Required<ChartBrushTrackOverlayStyle> = {
    blurPx: Math.min(5, Math.max(0, blurPx)),
    fadeOuterEdges,
  };

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const leftWidth = Math.max(0, x0);
  const rightWidth = Math.max(0, innerWidth - x1);

  if (leftWidth <= 0 && rightWidth <= 0) {
    return null;
  }

  const plotLeft = margin.left;
  const plotTop = margin.top;

  return createPortal(
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[1]"
    >
      {leftWidth > 0 ? (
        <div
          className="absolute"
          style={{
            ...outsidePaneStyle("left", overlayStyle),
            top: plotTop,
            left: plotLeft,
            width: leftWidth,
            height: innerHeight,
          }}
        />
      ) : null}
      {rightWidth > 0 ? (
        <div
          className="absolute"
          style={{
            ...outsidePaneStyle("right", overlayStyle),
            top: plotTop,
            left: plotLeft + x1,
            width: rightWidth,
            height: innerHeight,
          }}
        />
      ) : null}
    </div>,
    container
  );
}

export function ChartBrushTrackOverlay(props: ChartBrushTrackOverlayProps) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushTrackOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}

"use client";

import type React from "react";
import {
  Fragment,
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  ChartBrushHandleOverlay,
  renderChartBrushHandle,
} from "./chart-brush-handle";
import {
  ChartBrushSelectionOverlay,
  type ChartBrushSelectionPattern,
} from "./chart-brush-selection-overlay";
import {
  type BrushDirection,
  type BrushDomainBounds,
  type BrushInitialPosition,
  type BrushingType,
  type BrushMoveMode,
  type BrushPoint,
  type BrushState,
  beginBrushDrag,
  beginBrushSelect,
  brushExtentToDomain,
  brushHandleRects,
  brushSelectionRect,
  createBrushState,
  dragBrush,
  endBrush,
  idleBrushState,
} from "./chart-brush-state";
import {
  ChartBrushTrackOverlay,
  type ChartBrushTrackOverlayStyle,
} from "./chart-brush-track-overlay";
import { chartCssVars, useChartStable } from "./chart-context";
import { localPoint } from "./local-point";

type Bounds = BrushDomainBounds;

interface BrushMargin {
  top: number;
  left: number;
  right: number;
  bottom: number;
}

const ZERO_MARGIN: BrushMargin = { top: 0, left: 0, right: 0, bottom: 0 };

const DEFAULT_SELECTED_BOX_STYLE: React.SVGProps<SVGRectElement> = {
  fill: "transparent",
  fillOpacity: 0,
  stroke: chartCssVars.brushBorder,
  strokeWidth: 1,
};

/** `@visx/brush` debounces window move events by 1 ms; kept for parity. */
const WINDOW_MOVE_DEBOUNCE_MS = 1;

interface BrushInteractionProps {
  xScale: unknown;
  width: number;
  height: number;
  brushDirection: BrushDirection;
  handleSize: number;
  initialBrushPosition?: BrushInitialPosition;
  /** Offset subtracted from the SVG pointer position when a selection starts. */
  startMargin: BrushMargin;
  moveMode: BrushMoveMode;
  selectedBoxStyle: React.SVGProps<SVGRectElement>;
  onChange: (bounds: Bounds | null) => void;
  onBrushEnd: (bounds: Bounds | null) => void;
}

interface ActiveBrushDrag {
  pointerId: number;
  target: Element;
  /** SVG-space pointer position at pointer down. */
  local: BrushPoint;
}

function scaleInverter(scale: unknown): (value: number) => unknown {
  const invert = (scale as { invert?: (value: number) => unknown } | null)
    ?.invert;
  // Without `invert` visx reports `{ x0: 0, x1: 0 }` (NaN -> `|| 0`).
  return typeof invert === "function"
    ? (value) => invert.call(scale, value)
    : () => Number.NaN;
}

function toDomain(state: BrushState, scale: unknown): Bounds | null {
  return brushExtentToDomain(state.extent, scaleInverter(scale));
}

/**
 * Hand-written replacement for `@visx/brush` `Brush`: one transparent hit rect
 * for the track (draw a new selection, or move the current one), the visible
 * selection rect, and the two edge handles. Pointer capture replaces visx's
 * window listeners; `chart-brush-state.ts` holds the parity rules.
 */
const ChartBrushInteraction = memo(function ChartBrushInteraction({
  xScale,
  width,
  height,
  brushDirection,
  handleSize,
  initialBrushPosition,
  startMargin,
  moveMode,
  selectedBoxStyle,
  onChange,
  onBrushEnd,
}: BrushInteractionProps) {
  const stage = useMemo(
    () => ({ width, height, direction: brushDirection }),
    [width, height, brushDirection]
  );
  const [state, setState] = useState(() =>
    createBrushState(stage, initialBrushPosition)
  );
  const stateRef = useRef(state);
  const dragRef = useRef<ActiveBrushDrag | null>(null);
  const moveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Latest props for the debounced window-move timer.
  const latestRef = useRef({ stage, xScale, onChange });
  useLayoutEffect(() => {
    latestRef.current = { stage, xScale, onChange };
  });

  useEffect(
    () => () => {
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
      }
    },
    []
  );

  const commitState = useCallback((next: BrushState) => {
    stateRef.current = next;
    setState(next);
  }, []);

  const startDrag = useCallback(
    (
      event: React.PointerEvent<Element>,
      next: BrushState,
      local: BrushPoint
    ) => {
      const target = event.target as Element;
      try {
        target.setPointerCapture(event.pointerId);
      } catch {
        // Pointer already gone (synthetic event); moves still bubble here.
      }
      dragRef.current = {
        pointerId: event.pointerId,
        target,
        local,
      };
      commitState(next);
      onChange(toDomain(next, xScale));
    },
    [commitState, onChange, xScale]
  );

  // Which drag starts is decided by DOM hit-testing, as in visx: the overlay
  // draws a new selection, the selection rect moves it, a handle resizes.
  const handleOverlayPointerDown = useCallback(
    (event: React.PointerEvent<SVGRectElement>) => {
      if (dragRef.current) {
        return;
      }
      const point = localPoint(event) ?? { x: 0, y: 0 };
      const next = beginBrushSelect(stateRef.current, {
        x: point.x - startMargin.left,
        y: point.y - startMargin.top,
      });
      startDrag(event, next, point);
    },
    [startDrag, startMargin.left, startMargin.top]
  );

  const handleDragPointerDown = useCallback(
    (
      type: Exclude<BrushingType, "select">,
      event: React.PointerEvent<Element>
    ) => {
      if (dragRef.current) {
        return;
      }
      const point = localPoint(event) ?? { x: 0, y: 0 };
      startDrag(event, beginBrushDrag(stateRef.current, type), point);
    },
    [startDrag]
  );

  const applyOffset = useCallback(
    (offset: BrushPoint) => {
      const latest = latestRef.current;
      const current = stateRef.current;
      if (!current.isBrushing) {
        return;
      }
      const next = dragBrush(current, offset, latest.stage, moveMode);
      commitState(next);
      latest.onChange(toDomain(next, latest.xScale));
    },
    [commitState, moveMode]
  );

  const handlePointerMove = useCallback(
    (event: React.PointerEvent<Element>) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId) {
        return;
      }
      const point = localPoint(drag.target, event);
      if (!point) {
        return;
      }
      const offset = { x: point.x - drag.local.x, y: point.y - drag.local.y };
      if (moveMode === "local") {
        applyOffset(offset);
        return;
      }
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
      }
      moveTimerRef.current = setTimeout(() => {
        moveTimerRef.current = null;
        if (drag === dragRef.current) {
          applyOffset(offset);
        }
      }, WINDOW_MOVE_DEBOUNCE_MS);
    },
    [applyOffset, moveMode]
  );

  const handlePointerEnd = useCallback(
    (event: React.PointerEvent<Element>) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId) {
        return;
      }
      // Like visx, a window move still waiting on its debounce is dropped.
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
        moveTimerRef.current = null;
      }
      const result = endBrush(stateRef.current, moveMode);
      if (result) {
        commitState(result.state);
      }
      dragRef.current = null;
      try {
        if (drag.target.hasPointerCapture(drag.pointerId)) {
          drag.target.releasePointerCapture(drag.pointerId);
        }
      } catch {
        // Element already detached.
      }
      if (!result) {
        return;
      }
      onBrushEnd(toDomain(result.state, xScale));
      for (let i = 0; i < result.changeCount; i++) {
        onChange(toDomain(result.state, xScale));
      }
    },
    [commitState, moveMode, onBrushEnd, onChange, xScale]
  );

  // visx resets on a double-click of the overlay (not the selection).
  const handleOverlayDoubleClick = useCallback(() => {
    const next = idleBrushState();
    commitState(next);
    onChange(toDomain(next, xScale));
  }, [commitState, onChange, xScale]);

  const selection = brushSelectionRect(state.extent);
  const isBrushActive = state.extent.x0 !== -1 && state.extent.x1 !== -1;
  const { brushingType } = state;
  const selectionLocked = state.isBrushing || state.activeHandle !== null;
  const fill = "transparent";

  // Same tree as visx 4.0.0 BaseBrush (Group > overlay Drag, BrushSelection,
  // right / left BrushHandle), including the transparent "dragging" rects
  // each @visx/drag <Drag> adds while its drag is in progress. Moves and
  // pointer-up reach the group through pointer capture on the pressed target.
  return (
    <g
      className="visx-group visx-brush"
      onLostPointerCapture={handlePointerEnd}
      onPointerCancel={handlePointerEnd}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerEnd}
      transform="translate(0, 0)"
    >
      {/* Attribute objects keep visx's attribute order in the DOM. */}
      {brushingType === "select" ? <rect {...{ width, height, fill }} /> : null}
      <rect
        {...{
          className: "visx-bar visx-brush-overlay",
          fill,
          x: 0,
          y: 0,
          width,
          height,
          onDoubleClick: handleOverlayDoubleClick,
          onPointerDown: handleOverlayPointerDown,
          style: { cursor: "crosshair" },
        }}
      />
      {brushingType === "move" ? (
        <rect {...{ width: selection.width, height: selection.height, fill }} />
      ) : null}
      <g>
        {brushingType === "move" ? (
          <rect {...{ width, height, fill, style: { cursor: "move" } }} />
        ) : null}
        <rect
          {...{
            ...selection,
            className: "visx-brush-selection",
            onPointerDown: (event: React.PointerEvent<SVGRectElement>) =>
              handleDragPointerDown("move", event),
            style: {
              pointerEvents: selectionLocked ? "none" : "all",
              cursor: "move",
            },
            ...selectedBoxStyle,
          }}
        />
      </g>
      {brushHandleRects(state.extent, handleSize, height).map((handle) => (
        <Fragment key={`handle-${handle.type}`}>
          {brushingType === handle.type ? (
            <rect {...{ width, height, fill }} />
          ) : null}
          <g>
            {brushingType === handle.type ? (
              <rect
                {...{ fill, width, height, style: { cursor: "ew-resize" } }}
              />
            ) : null}
            <g
              onPointerDown={(event) =>
                handleDragPointerDown(handle.type, event)
              }
            >
              {renderChartBrushHandle({
                x: handle.x,
                y: handle.y,
                width: handle.width,
                height: handle.height,
                className: `visx-brush-handle-${handle.type}`,
                isBrushActive,
              })}
            </g>
          </g>
        </Fragment>
      ))}
    </g>
  );
});

export interface ChartBrushSelection {
  start: Date;
  end: Date;
}

export interface ChartBrushProps {
  /** Callback when brush selection ends. Domain is the selected time range. */
  onSelectionChange?: (domain: ChartBrushSelection | null) => void;
  /** Brush direction. Default: "horizontal" for time range selection. */
  brushDirection?: "horizontal" | "vertical" | "both";
  /** Fill style for the selected region. Default: chart segment style. */
  selectedBoxStyle?: React.SVGProps<SVGRectElement>;
  /** Initial selection so the brush overlay is visible on load (e.g. first 50% of range). */
  initialSelection?: ChartBrushSelection | null;
  /** Current selection (e.g. from parent state). When set, a visible selection rect is drawn. */
  selection?: ChartBrushSelection | null;
  /** Use window move events for brush (can fix coordinate offset when SVG is in transformed container). Default: true for brush-in-strip. */
  useWindowMoveEvents?: boolean;
  /** Backdrop blur on dimmed track (0–5 px). Default: 1.5 */
  blurPx?: number;
  /** Fade dimmed regions at the outer track edges. Default: true */
  fadeOuterEdges?: boolean;
  /** Optional pattern overlay inside the brush selection window. */
  selectionPattern?: ChartBrushSelectionPattern;
}

interface ChartBrushInnerProps extends ChartBrushTrackOverlayStyle {
  brushDirection?: ChartBrushProps["brushDirection"];
  selectedBoxStyle?: ChartBrushProps["selectedBoxStyle"];
  initialSelection?: ChartBrushProps["initialSelection"];
  useWindowMoveEvents?: ChartBrushProps["useWindowMoveEvents"];
  xScale: ReturnType<typeof useChartStable>["xScale"];
  innerWidth: number;
  innerHeight: number;
  margin: ReturnType<typeof useChartStable>["margin"];
  onBrushPreview?: (bounds: Bounds | null) => void;
  onBrushCommit: (bounds: Bounds | null) => void;
  selectionPattern?: ChartBrushSelectionPattern;
}

function toDate(value: number | Date | unknown): Date {
  if (value instanceof Date) {
    return value;
  }
  if (typeof value === "number") {
    return new Date(value);
  }
  return new Date(Number(value));
}

function boundsToPixelExtent(
  bounds: Bounds | null,
  xScale: ReturnType<typeof useChartStable>["xScale"],
  innerWidth: number
): { x0: number; x1: number } | null {
  if (
    !bounds ||
    typeof bounds.x0 === "undefined" ||
    typeof bounds.x1 === "undefined"
  ) {
    return null;
  }

  const start = toDate(bounds.x0);
  const end = toDate(bounds.x1);
  const xScaleFn = xScale as (d: Date) => number;
  const x0 = Math.max(0, xScaleFn(start < end ? start : end) ?? 0);
  const x1 = Math.min(
    innerWidth,
    xScaleFn(end > start ? end : start) ?? innerWidth
  );

  if (x1 <= x0) {
    return null;
  }

  return { x0, x1 };
}

const ChartBrushInner = memo(function ChartBrushInner({
  brushDirection = "horizontal",
  selectedBoxStyle,
  initialSelection,
  useWindowMoveEvents = true,
  xScale,
  innerWidth,
  innerHeight,
  margin,
  onBrushPreview,
  onBrushCommit,
  blurPx,
  fadeOuterEdges,
  selectionPattern,
}: ChartBrushInnerProps) {
  const initialBrushPosition = useMemo(() => {
    if (!initialSelection || innerWidth <= 0 || innerHeight <= 0) {
      return undefined;
    }
    const xScaleFn = xScale as (d: Date) => number;
    const x0 = Math.max(0, xScaleFn(initialSelection.start) ?? 0);
    const x1 = Math.min(
      innerWidth,
      xScaleFn(initialSelection.end) ?? innerWidth
    );
    if (x1 <= x0) {
      return undefined;
    }
    return {
      start: { x: x0, y: 0 },
      end: { x: x1, y: innerHeight },
    };
  }, [initialSelection, xScale, innerWidth, innerHeight]);

  const [pixelExtent, setPixelExtent] = useState(() => ({
    x0: initialBrushPosition?.start.x ?? 0,
    x1: initialBrushPosition?.end.x ?? innerWidth,
  }));

  // Reset the extent when the initial selection / width change — adjusted
  // during render ("store previous props in state"), not setState in an effect.
  const [extentSource, setExtentSource] = useState({
    initialBrushPosition,
    innerWidth,
  });
  if (
    extentSource.initialBrushPosition !== initialBrushPosition ||
    extentSource.innerWidth !== innerWidth
  ) {
    setExtentSource({ initialBrushPosition, innerWidth });
    setPixelExtent({
      x0: initialBrushPosition?.start.x ?? 0,
      x1: initialBrushPosition?.end.x ?? innerWidth,
    });
  }

  const updatePixelExtent = useCallback(
    (bounds: Bounds | null) => {
      const pixels = boundsToPixelExtent(bounds, xScale, innerWidth);
      if (pixels) {
        setPixelExtent(pixels);
      }
    },
    [innerWidth, xScale]
  );

  const handleBrushPreview = useCallback(
    (bounds: Bounds | null) => {
      updatePixelExtent(bounds);
      onBrushPreview?.(bounds);
    },
    [onBrushPreview, updatePixelExtent]
  );

  const handleBrushCommit = useCallback(
    (bounds: Bounds | null) => {
      updatePixelExtent(bounds);
      onBrushCommit(bounds);
    },
    [onBrushCommit, updatePixelExtent]
  );

  return (
    <g className="chart-brush">
      <ChartBrushTrackOverlay
        blurPx={blurPx}
        fadeOuterEdges={fadeOuterEdges}
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushSelectionOverlay
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        pattern={selectionPattern}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushHandleOverlay
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushInteraction
        brushDirection={brushDirection}
        handleSize={8}
        height={innerHeight}
        initialBrushPosition={initialBrushPosition}
        key={`brush-${innerWidth}-${innerHeight}`}
        moveMode={useWindowMoveEvents ? "window" : "local"}
        onBrushEnd={handleBrushCommit}
        onChange={handleBrushPreview}
        selectedBoxStyle={selectedBoxStyle ?? DEFAULT_SELECTED_BOX_STYLE}
        startMargin={useWindowMoveEvents ? margin : ZERO_MARGIN}
        width={innerWidth}
        xScale={xScale}
      />
    </g>
  );
});

export function ChartBrush({
  onSelectionChange,
  brushDirection = "horizontal",
  selectedBoxStyle,
  initialSelection,
  useWindowMoveEvents = true,
  blurPx,
  fadeOuterEdges,
  selectionPattern,
}: ChartBrushProps) {
  const { xScale, innerWidth, innerHeight, margin, isLoaded } =
    useChartStable();

  const boundsToSelection = useCallback(
    (bounds: Bounds | null): ChartBrushSelection | null => {
      if (
        !bounds ||
        typeof bounds.x0 === "undefined" ||
        typeof bounds.x1 === "undefined"
      ) {
        return null;
      }
      const start = toDate(bounds.x0);
      const end = toDate(bounds.x1);
      if (start.getTime() === end.getTime()) {
        return null;
      }
      return {
        start: start < end ? start : end,
        end: end > start ? end : start,
      };
    },
    []
  );

  const notifySelectionChange = useCallback(
    (bounds: Bounds | null) => {
      if (!onSelectionChange) {
        return;
      }
      onSelectionChange(boundsToSelection(bounds));
    },
    [onSelectionChange, boundsToSelection]
  );

  const handleBrushPreview = useCallback(
    (bounds: Bounds | null) => {
      notifySelectionChange(bounds);
    },
    [notifySelectionChange]
  );

  const handleBrushCommit = useCallback(
    (bounds: Bounds | null) => {
      notifySelectionChange(bounds);
    },
    [notifySelectionChange]
  );

  if (!isLoaded || innerWidth <= 0 || innerHeight <= 0) {
    return null;
  }

  return (
    <ChartBrushInner
      blurPx={blurPx}
      brushDirection={brushDirection}
      fadeOuterEdges={fadeOuterEdges}
      initialSelection={initialSelection}
      innerHeight={innerHeight}
      innerWidth={innerWidth}
      margin={margin}
      onBrushCommit={handleBrushCommit}
      onBrushPreview={handleBrushPreview}
      selectedBoxStyle={selectedBoxStyle}
      selectionPattern={selectionPattern}
      useWindowMoveEvents={useWindowMoveEvents}
      xScale={xScale}
    />
  );
}

