  // Container ref for portals
  containerRef: RefObject<HTMLDivElement | null>;

  // Line configurations (extracted from children)
  lines: LineConfig[];

  /** `<Band>` configs (time-series charts) — tooltip range rows and edge dots. */
  bands?: BandConfig[];

  /** {@link ReferenceArea} bands — drives y-axis label colors in range. */
  referenceAreas: ReferenceAreaConfig[];

  // Loading / lifecycle (LineChart status transitions)
  chartPhase: ChartPhase;
  chartStatus: ChartStatus;
  /** Centered label while `chartPhase` shows loading chrome. */
  loadingLabel?: string;
  /** Y-domain tween duration when transitioning loading ↔ ready (ms). */
  yDomainTweenDuration: number;
  /** Nice’d y-domains per axis from skeleton data (placeholder). */
  yDomainSkeletonByAxis: Record<string, YDomain>;
  /** Nice’d y-domains per axis from the current target data. */
  yDomainTargetByAxis: Record<string, YDomain>;

  // Animation state
  isLoaded: boolean;
  animationDuration: number;
  /** CSS easing for clip-reveal / line draw (cartesian charts). */
  animationEasing?: string;
  /** Motion enter transition (spring or tween) — drives clip reveal when spring. */
  enterTransition?: Transition;
  /** Increments when enter animation should replay. */
  revealEpoch?: number;
  /** Fired when a one-shot loading pulse (exit / enter) completes. */
  notifyLoadingPulseComplete?: () => void;

  // X accessor - how to get the x value from data points
  xAccessor: (d: Record<string, unknown>) => Date;

  // Pre-computed date labels for ticker animation
  dateLabels: string[];

  /** Active brush zoom range — when set, axis ticks align to visible data rows. */
  xDomain?: [Date, Date];
  /** Full dataset length when brush zoom is enabled (for zoom vs full-range detection). */
  xDomainSlotCount?: number;

  // Bar chart specific (optional - only present in BarChart)
  /** Band scale for categorical x-axis (bar charts) */
  barScale?: ScaleBand<string>;
  /** Width of each bar band */
  bandWidth?: number;
  /** X accessor for bar charts (returns string instead of Date) */
  barXAccessor?: (d: Record<string, unknown>) => string;
  /** Bar chart orientation */
  orientation?: "vertical" | "horizontal";
  /** Whether bars are stacked */
  stacked?: boolean;
  /** Stack offsets: Map of data index -> Map of dataKey -> cumulative offset */
  stackOffsets?: Map<number, Map<string, number>>;
  /** Squares variant — snap tooltip to top square and size ring dots. */
  squareSnap?: { squareGap: number; groupGap?: number; fit?: boolean };

  // ComposedChart + SeriesBar (optional)
  /** `SeriesBar` dataKeys in tree order, for grouped columns at each x */
  composedBarDataKeys?: string[];
  /** Target bar width in px (Recharts `barSize` style). */
  composedBarSize?: number;
  /** Max bar width in px (Recharts `maxBarSize`). */
  composedMaxBarSize?: number;
  /** Gap between grouped `SeriesBar` columns in px. */
  composedBarGap?: number;
  /** When true, `SeriesBar` segments stack in child order at each x. */
  composedStacked?: boolean;
  /** Per-row cumulative offsets for stacked `SeriesBar` (data index → dataKey → offset). */
  composedStackOffsets?: Map<number, Map<string, number>>;
  /** Vertical gap in px between stacked `SeriesBar` segments. Default: 0 */
  composedStackGap?: number;

  /**
   * Hover resolves to the nearest point in 2D rather than the nearest x column
   * (e.g. `ScatterChart` with `jitter`). `ChartTooltip` hides its crosshair
   * line by default when set, since the line would not mark a single x value.
   */
  nearestPointHover?: boolean;
}

/**
 * Stable slice of the chart context — everything that doesn't change on hover
 * (data, scales, dimensions, animation state, layout config). Consumers that
 * subscribe via `useChartStable()` skip re-renders on every mouse move.
 */
export type ChartStableContextValue = Omit<
  ChartContextValue,
  keyof ChartHoverContextValue
>;

/** `useLayoutEffect` in the browser, `useEffect` on the server (no SSR warning). */
const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

const ChartStableContext = createContext<ChartStableContextValue | null>(null);
const ChartHoverContext = createContext<ChartHoverContextValue | null>(null);

/**
 * Subscribable hover/selection state. Time-series charts keep hover in one of
 * these instead of React state, so a pointer move re-renders only the
 * components that read hover — not the chart shell and its layers.
 */
export interface ChartHoverStore {
  getSnapshot: () => ChartHoverContextValue;
  subscribe: (listener: () => void) => () => void;
}

/** A {@link ChartHoverStore} the owning chart writes to. */
export interface WritableChartHoverStore extends ChartHoverStore {
  setTooltipData: Dispatch<SetStateAction<TooltipData | null>>;
  setSelection: (selection: ChartSelection | null) => void;
}

const ChartHoverStoreContext = createContext<ChartHoverStore | null>(null);

export function createChartHoverStore(): WritableChartHoverStore {
  const listeners = new Set<() => void>();
  let tooltipData: TooltipData | null = null;
  let selection: ChartSelection | null = null;
  const emit = () => {
    snapshot = { ...snapshot, tooltipData, selection };
    for (const listener of listeners) {
      listener();
    }
  };
  const setTooltipData: Dispatch<SetStateAction<TooltipData | null>> = (
    action
  ) => {
    const next = typeof action === "function" ? action(tooltipData) : action;
    if (next === tooltipData) {
      return;
    }
    tooltipData = next;
    emit();
  };
  const setSelection = (next: ChartSelection | null) => {
    if (next === selection) {
      return;
    }
    selection = next;
    emit();
  };
  let snapshot: ChartHoverContextValue = {
    tooltipData,
    setTooltipData,
    selection,
    clearSelection: () => setSelection(null),
  };
  return {
    getSnapshot: () => snapshot,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    setTooltipData,
    setSelection,
  };
}

const noop = () => undefined;

/** Read-only store over a plain hover value (re-created when it changes). */
function staticChartHoverStore(value: ChartHoverContextValue): ChartHoverStore {
  return {
    getSnapshot: () => value,
    subscribe: () => noop,
  };
}

/**
 * Publishes a hover store to `useChartHover()` (whole slice, re-renders on
 * every change) and `useChartHoverSelector()` (re-renders only when the
 * selected value changes). Only this provider re-renders on a hover change;
 * `children` keeps its identity, so the subtree is skipped apart from hover
 * consumers.
 */
export function ChartHoverStoreProvider({
  children,
  store,
}: {
  children: ReactNode;
  store: ChartHoverStore;
}) {
  const hover = useSyncExternalStore(
    store.subscribe,
    store.getSnapshot,
    store.getSnapshot
  );
  return (
    <ChartHoverStoreContext.Provider value={store}>
      <ChartHoverContext.Provider value={hover}>
        {children}
      </ChartHoverContext.Provider>
    </ChartHoverStoreContext.Provider>
  );
}

/**
 * Splits the merged `value` into a stable slice and a volatile hover slice,
 * publishing each to its own context. Each slice is memoized on its own
 * field identities, so changing `tooltipData` does not bust the stable
 * slice — consumers of `useChartStable()` skip re-renders on hover.
 */
export function ChartProvider({
  children,
  value,
}: {
  children: ReactNode;
  value: ChartContextValue;
}) {
  const stable = useMemo<ChartStableContextValue>(
    () => ({
      data: value.data,
      renderData: value.renderData,
      xScale: value.xScale,
      yScale: value.yScale,
      yScales: value.yScales,
      width: value.width,
      height: value.height,
      innerWidth: value.innerWidth,
      innerHeight: value.innerHeight,
      margin: value.margin,
      columnWidth: value.columnWidth,
      containerRef: value.containerRef,
      lines: value.lines,
      bands: value.bands,
      referenceAreas: value.referenceAreas,
      chartPhase: value.chartPhase,
      chartStatus: value.chartStatus,
      loadingLabel: value.loadingLabel,
      yDomainTweenDuration: value.yDomainTweenDuration,
      yDomainSkeletonByAxis: value.yDomainSkeletonByAxis,
      yDomainTargetByAxis: value.yDomainTargetByAxis,
      isLoaded: value.isLoaded,
      animationDuration: value.animationDuration,
      animationEasing: value.animationEasing,
      enterTransition: value.enterTransition,
      revealEpoch: value.revealEpoch,
      notifyLoadingPulseComplete: value.notifyLoadingPulseComplete,
      xAccessor: value.xAccessor,
      dateLabels: value.dateLabels,
      xDomain: value.xDomain,
      xDomainSlotCount: value.xDomainSlotCount,
      barScale: value.barScale,
      bandWidth: value.bandWidth,
      barXAccessor: value.barXAccessor,
      orientation: value.orientation,
      stacked: value.stacked,
      stackOffsets: value.stackOffsets,
      composedBarDataKeys: value.composedBarDataKeys,
      composedBarSize: value.composedBarSize,
      composedMaxBarSize: value.composedMaxBarSize,
      composedBarGap: value.composedBarGap,
      composedStacked: value.composedStacked,
      composedStackOffsets: value.composedStackOffsets,
      composedStackGap: value.composedStackGap,
      nearestPointHover: value.nearestPointHover,
    }),
    [
      value.data,
      value.renderData,
      value.xScale,
      value.yScale,
      value.yScales,
      value.width,
      value.height,
      value.innerWidth,
      value.innerHeight,
      value.margin,
      value.columnWidth,
      value.containerRef,
      value.lines,
      value.bands,
      value.referenceAreas,
      value.chartPhase,
      value.chartStatus,
      value.loadingLabel,
      value.yDomainTweenDuration,
      value.yDomainSkeletonByAxis,
      value.yDomainTargetByAxis,
      value.isLoaded,
      value.animationDuration,
      value.animationEasing,
      value.enterTransition,
      value.revealEpoch,
      value.notifyLoadingPulseComplete,
      value.xAccessor,
      value.dateLabels,
      value.xDomain,
      value.xDomainSlotCount,
      value.barScale,
      value.bandWidth,
      value.barXAccessor,
      value.orientation,
      value.stacked,
      value.stackOffsets,
      value.composedBarDataKeys,
      value.composedBarSize,
      value.composedMaxBarSize,
      value.composedBarGap,
      value.composedStacked,
      value.composedStackOffsets,
      value.composedStackGap,
      value.nearestPointHover,
    ]
  );

  const hover = useMemo<ChartHoverContextValue>(
    () => ({
      tooltipData: value.tooltipData,
      setTooltipData: value.setTooltipData,
      selection: value.selection,
      clearSelection: value.clearSelection,
      hoveredBarIndex: value.hoveredBarIndex,
      setHoveredBarIndex: value.setHoveredBarIndex,
      hoveredCandleIndex: value.hoveredCandleIndex,
      setHoveredCandleIndex: value.setHoveredCandleIndex,
    }),
    [
      value.tooltipData,
      value.setTooltipData,
      value.selection,
      value.clearSelection,
      value.hoveredBarIndex,
      value.setHoveredBarIndex,
      value.hoveredCandleIndex,
      value.setHoveredCandleIndex,
    ]
  );

  const hoverStore = useMemo(() => staticChartHoverStore(hover), [hover]);

  return (
    <ChartStableContext.Provider value={stable}>
      <ChartHoverStoreContext.Provider value={hoverStore}>
        <ChartHoverContext.Provider value={hover}>
          {children}
        </ChartHoverContext.Provider>
      </ChartHoverStoreContext.Provider>
    </ChartStableContext.Provider>
  );
}

/** Stable-slice context, for chart shells that build the slice themselves. */
export const ChartStableContextProvider = ChartStableContext.Provider;

/**
 * Stable slice — data, scales, dimensions, animation state, layout config.
 * Subscribers skip re-renders on hover (the hover slice lives in a separate
 * context). Prefer this in cold consumers like axes, grid, pattern fills.
 */
export function useChartStable(): ChartStableContextValue {
  const context = useContext(ChartStableContext);
  if (!context) {
    throw new Error(
      "useChartStable must be used within a ChartProvider. " +
        "Make sure your component is wrapped in <LineChart>, <AreaChart>, <BarChart>, or <ComposedChart>."
    );
  }
  return context;
}

/**
 * Resolves a chart container element to use as a `createPortal` target.
 *
 * The element is kept in state: it is seeded once from the ref (already
 * attached when the chart renders after its container measured), then
 * re-captured after mount. Returns `null` during SSR and when the ref is not
 * attached on the first render.
 *
 * - Layout effect: when the container is a sibling or ancestor already
 *   attached, the synchronous re-render puts portalled axes and tooltips in
 *   the same painted frame as the plot.
 * - Passive effect: React attaches refs child-first in the layout phase, so a
 *   portal rendered *inside* its container (heatmap, choropleth tooltips) sees
 *   `null` above. By the passive phase every ref is attached; this picks it up.
 */
export function useChartPortalContainer<T extends HTMLElement>(
  containerRef: RefObject<T | null> | undefined
): T | null {
  const [container, setContainer] = useState<T | null>(null);
  useIsomorphicLayoutEffect(() => {
    setContainer(containerRef?.current ?? null);
  }, [containerRef]);
  useEffect(() => {
    const element = containerRef?.current ?? null;
    setContainer((previous) => (previous === element ? previous : element));
  }, [containerRef]);
  return container;
}

/**
 * Same margin object while its four numbers are unchanged, so an inline
 * `margin={{…}}` (or the default merge) doesn't defeat memoised chart cores.
 */
export function useStableMargin(margin: Margin): Margin {
  const { top, right, bottom, left } = margin;
  return useMemo(
    () => ({ top, right, bottom, left }),
    [top, right, bottom, left]
  );
}

/** Y-scale for a series axis (`yAxisId` on Line / Area / YAxis). */
export function useYScale(
  yAxisId?: string | number
): ScaleLinear<number> {
  const { yScales, yScale } = useChartStable();
  const id =
    yAxisId == null || yAxisId === "" ? DEFAULT_Y_AXIS_ID : String(yAxisId);
  return yScales[id] ?? yScale;
}

/**
 * Y-scale at the end of the y-domain tween (the target domain), for series
 * that animate toward their final pixels rather than the mid-tween scale.
 * Falls back to {@link useYScale} when no target domain is published.
 */
export function useSettledYScale(
  yAxisId?: string | number
): ScaleLinear<number> {
  const { yDomainTargetByAxis, innerHeight } = useChartStable();
  const liveScale = useYScale(yAxisId);
  const id =
    yAxisId == null || yAxisId === "" ? DEFAULT_Y_AXIS_ID : String(yAxisId);
  const domain =
    yDomainTargetByAxis?.[id] ?? yDomainTargetByAxis?.[DEFAULT_Y_AXIS_ID];
  const min = domain?.[0];
  const max = domain?.[1];
  const settled = useMemo(
    () =>
      min == null || max == null
        ? null
        : scaleLinear().domain([min, max]).range([innerHeight, 0]),
    [min, max, innerHeight]
  );
  return settled ?? liveScale;
}

/**
 * Hover slice — tooltipData, selection, hovered bar / candle indices.
 * Subscribers re-render on every mouse move. Use only when the component
 * actually reads hover state.
 */
export function useChartHover(): ChartHoverContextValue {
  const context = useContext(ChartHoverContext);
  if (!context) {
    throw new Error(
      "useChartHover must be used within a ChartProvider. " +
        "Make sure your component is wrapped in <LineChart>, <AreaChart>, <BarChart>, or <ComposedChart>."
    );
  }
  return context;
}

/**
 * One derived value from the hover slice; re-renders only when it changes
 * (by `Object.is`). Return a primitive or a reference taken from the hover
 * state (e.g. `s.tooltipData`), not a fresh object or array. Prefer this over
 * `useChartHover()` for components that only care about part of hover, such
 * as "is the chart hovered" or "which index".
 */
export function useChartHoverSelector<T>(
  selector: (hover: ChartHoverContextValue) => T
): T {
  const store = useContext(ChartHoverStoreContext);
  if (!store) {
    throw new Error(
      "useChartHoverSelector must be used within a ChartProvider. " +
        "Make sure your component is wrapped in <LineChart>, <AreaChart>, <BarChart>, or <ComposedChart>."
    );
  }
  const getSelected = () => selector(store.getSnapshot());
  return useSyncExternalStore(store.subscribe, getSelected, getSelected);
}

/**
 * The hover store itself, for components that drive motion values straight
 * from hover changes without re-rendering. `null` outside a chart.
 */
export function useChartHoverStore(): ChartHoverStore | null {
  return useContext(ChartHoverStoreContext);
}

export function selectTooltipData(
  hover: ChartHoverContextValue
): TooltipData | null {
  return hover.tooltipData;
}

/** Whether the chart is hovered or a drag-selection is active. */
export function selectIsChartHovering(hover: ChartHoverContextValue): boolean {
  return hover.tooltipData !== null || hover.selection?.active === true;
}

/**
 * Merged stable + hover context. Convenient for components that need both,
 * but re-renders on every hover (because hover changes). Prefer
 * `useChartStable()` or `useChartHover()` for hot consumers that only need
 * one slice.
 */
export function useChart(): ChartContextValue {
  const stable = useChartStable();
  const hover = useChartHover();
  // Identity changes on every hover (hover is the volatile slice) — that's
  // fine for consumers using this merged hook; they explicitly opted in to
  // re-rendering on hover.
  return { ...stable, ...hover };
}

export default ChartStableContext;

import {
  Children,
  isValidElement,
  type ReactElement,
  type ReactNode,
} from "react";

export function getChartChildComponentName(child: ReactElement): string {
  const childType = child.type as { displayName?: string; name?: string };
  return typeof child.type === "function"
    ? childType.displayName || childType.name || ""
    : "";
}

const VISX_PATTERN_COMPONENT_NAMES = new Set([
  "Lines",
  "Circles",
  "Waves",
  "Hexagons",
  "Path",
  "Pattern",
]);

/** Vendored pattern exports use short names (e.g. `Lines`); also match *Pattern* displayNames. */
export function isPatternDefComponent(child: ReactElement): boolean {
  const name = getChartChildComponentName(child);
  return name.includes("Pattern") || VISX_PATTERN_COMPONENT_NAMES.has(name);
}

export function isGradientDefComponent(child: ReactElement): boolean {
  const name = getChartChildComponentName(child);
  return (
    name.includes("Gradient") ||
    name === "LinearGradient" ||
    name === "RadialGradient"
  );
}

export function isChartDefsComponent(child: ReactElement): boolean {
  return isPatternDefComponent(child) || isGradientDefComponent(child);
}

/** Split hoisted defs: pattern nodes already wrap `<defs>` and render at the svg root. */
export function partitionChartDefNodes(defNodes: ReactElement[]): {
  patternDefNodes: ReactElement[];
  gradientDefNodes: ReactElement[];
} {
  const patternDefNodes: ReactElement[] = [];
  const gradientDefNodes: ReactElement[] = [];

  for (const node of defNodes) {
    if (isPatternDefComponent(node)) {
      patternDefNodes.push(node);
    } else {
      gradientDefNodes.push(node);
    }
  }

  return { patternDefNodes, gradientDefNodes };
}

export function collectChartDefsChildren(children: ReactNode): ReactElement[] {
  const defNodes: ReactElement[] = [];

  Children.forEach(children, (child) => {
    if (isValidElement(child) && isChartDefsComponent(child)) {
      defNodes.push(child);
    }
  });

  return defNodes;
}

export const shortDateFmt = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
});

export const weekdayDateFmt = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
});

export const hmsTimeFmt = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
});

// `Intl.NumberFormat.prototype.format` is a bound getter — safe to extract.
export const intFmt = new Intl.NumberFormat("en-US").format;
export const valueLabelFmt = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 0,
}).format;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

/**
 * Tooltip value for a `<Band>` row: `"low – high"` (ordered), the value itself
 * when both edges read the same key, or `null` when either edge is missing
 * (e.g. Bollinger warm-up rows).
 */
export function formatBandRange(
  point: Record<string, unknown>,
  upperKey: string,
  lowerKey: string,
  format: (value: number) => string = intFmt
): string | number | null {
  const upper = point[upperKey];
  const lower = point[lowerKey];
  if (!(isFiniteNumber(upper) && isFiniteNumber(lower))) {
    return null;
  }
  if (upperKey === lowerKey) {
    return upper;
  }
  return `${format(Math.min(lower, upper))} – ${format(Math.max(lower, upper))}`;
}

/** Below this many rows labels are formatted up front (cheap, no proxy). */
const EAGER_LABEL_LIMIT = 64;

/** `prop` as an array index below `length`, or -1. */
function toArrayIndex(prop: string | symbol, length: number): number {
  if (typeof prop !== "string" || prop.length === 0) {
    return -1;
  }
  const first = prop.charCodeAt(0);
  if (first < 48 || first > 57) {
    return -1;
  }
  const index = Number(prop);
  return Number.isInteger(index) && index < length && String(index) === prop
    ? index
    : -1;
}

/**
 * A `string[]` of per-row labels formatted on first read. Charts expose one
 * label per row (date pill, axis ticks) but usually read only a handful, and
 * `Intl.DateTimeFormat#format` costs ~1 µs per call, so formatting 10k rows up
 * front would add ~10 ms to every mount and data update. Behaves like a
 * regular array (length, indexing, iteration, `map`, `Array.isArray`).
 */
export function lazyLabels(
  length: number,
  format: (index: number) => string
): string[] {
  if (length <= EAGER_LABEL_LIMIT) {
    return Array.from({ length }, (_, index) => format(index));
  }
  const cache: string[] = new Array(length);
  return new Proxy(cache, {
    get(target, prop, receiver) {
      const index = toArrayIndex(prop, length);
      if (index === -1) {
        return Reflect.get(target, prop, receiver);
      }
      let label = target[index];
      if (label === undefined) {
        label = format(index);
        target[index] = label;
      }
      return label;
    },
    has(target, prop) {
      return toArrayIndex(prop, length) !== -1 || Reflect.has(target, prop);
    },
  });
}

"use client";

import { createContext, type ReactNode, useContext, useMemo } from "react";

interface ChartLegendHoverContextValue {
  hoveredIndex: number | null;
  setHoveredIndex: (index: number | null) => void;
}

const ChartLegendHoverContext =
  createContext<ChartLegendHoverContextValue | null>(null);

export function ChartLegendHoverProvider({
  hoveredIndex,
  onHoverChange,
  children,
}: {
  hoveredIndex: number | null;
  onHoverChange: (index: number | null) => void;
  children: ReactNode;
}) {
  const value = useMemo(
    () => ({ hoveredIndex, setHoveredIndex: onHoverChange }),
    [hoveredIndex, onHoverChange]
  );

  return (
    <ChartLegendHoverContext.Provider value={value}>
      {children}
    </ChartLegendHoverContext.Provider>
  );
}

export function useChartLegendHover(): ChartLegendHoverContextValue {
  const context = useContext(ChartLegendHoverContext);
  return (
    context ?? {
      hoveredIndex: null,
      setHoveredIndex: () => {
        /* noop outside ChartLegendHoverProvider */
      },
    }
  );
}

"use client";

import { m } from "motion/react";
import { cn } from "@/lib/utils";
import { ShimmeringText } from "./shimmering-text";
import {
  LINE_LOADING_PULSE_EASE,
  LOADING_LABEL_EXIT_S,
  LOADING_LABEL_EXIT_Y_PX,
} from "./line-loading-timing";

export interface ChartLoadingLabelProps {
  /** Label shown centered over the chart. */
  text?: string;
  className?: string;
  /** Animate down, fade, and blur during loading → ready handoff. */
  exiting?: boolean;
}

export function ChartLoadingLabel({
  text = "Loading",
  className,
  exiting = false,
}: ChartLoadingLabelProps) {
  if (!text.trim()) {
    return null;
  }

  return (
    <m.div
      animate={{
        y: exiting ? LOADING_LABEL_EXIT_Y_PX : 0,
        opacity: exiting ? 0 : 1,
        filter: exiting ? "blur(2px)" : "blur(0px)",
      }}
      aria-live="polite"
      className={cn(
        "pointer-events-none absolute inset-0 flex items-center justify-center",
        className
      )}
      initial={false}
      role="status"
      transition={{
        duration: LOADING_LABEL_EXIT_S,
        ease: [...LINE_LOADING_PULSE_EASE],
      }}
    >
      <ShimmeringText
        className="whitespace-nowrap font-medium text-sm tracking-normal [--color:var(--muted-foreground)] [--shimmering-color:var(--foreground)]"
        text={text}
      />
    </m.div>
  );
}

export default ChartLoadingLabel;

"use client";

import {
  type CSSProperties,
  type ReactNode,
  type RefObject,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

/** `useLayoutEffect` in the browser, `useEffect` on the server (no SSR warning). */
export const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

export interface ElementSize {
  width: number;
  height: number;
}

const ZERO_SIZE: ElementSize = { width: 0, height: 0 };

/**
 * Layout size of `element`, unaffected by CSS transforms. Fractional like
 * `ResizeObserver`'s `contentRect`, so the observer's first notification
 * matches and doesn't trigger a second render.
 */
function readElementSize(element: HTMLElement): ElementSize {
  const style = getComputedStyle(element);
  const width = Number.parseFloat(style.width);
  const height = Number.parseFloat(style.height);
  return {
    width: Number.isFinite(width) ? width : element.clientWidth,
    height: Number.isFinite(height) ? height : element.clientHeight,
  };
}

export interface ElementSizeOptions {
  /**
   * - `"layout"` (default): measure in a layout effect so the sized render
   *   commits before the first paint; later `ResizeObserver` changes are
   *   throttled to one update per `debounceTime`.
   * - `"observer"`: visx `useParentSize` timing, for charts whose enter
   *   motion was tuned on it. Stays 0×0 until the observer's first
   *   notification (applied in the next animation frame), reads the
   *   content-box size (`contentRect`), and debounces like visx: the first
   *   change applies at once, later ones once `debounceTime` passes without
   *   another.
   */
  timing?: "layout" | "observer";
}

const sameSize = (a: ElementSize, b: ElementSize) =>
  a.width === b.width && a.height === b.height;

/**
 * visx `debounce(fn, wait, { leading: true })`: fires on the first call, then
 * once more with the latest argument `wait` ms after the last call (only if
 * there were calls after the leading one).
 */
function leadingDebounce<A>(fn: (arg: A) => void, wait: number) {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  let pending: { arg: A } | null = null;
  const debounced = (arg: A) => {
    if (timeout === undefined) {
      fn(arg);
      pending = null;
    } else {
      pending = { arg };
    }
    clearTimeout(timeout);
    timeout = setTimeout(() => {
      timeout = undefined;
      if (pending !== null) {
        fn(pending.arg);
        pending = null;
      }
    }, wait);
  };
  debounced.cancel = () => {
    clearTimeout(timeout);
    timeout = undefined;
    pending = null;
  };
  return debounced;
}

/**
 * Tracks an element's size. The first measurement happens in a layout effect,
 * so the sized render commits before the browser paints its first frame
 * (no blank frame while a `ResizeObserver` round-trips). Later changes come
 * from a `ResizeObserver`; `debounceTime` coalesces bursts after an
 * immediate leading update. `timing: "observer"` keeps visx `useParentSize`
 * behaviour instead (see {@link ElementSizeOptions}).
 */
export function useElementSize<T extends HTMLElement>(
  ref: RefObject<T | null>,
  debounceTime = 0,
  { timing = "layout" }: ElementSizeOptions = {}
): ElementSize {
  const [size, setSize] = useState<ElementSize>(ZERO_SIZE);

  // visx useParentSize: passive effect, rAF-deferred observer callbacks.
  useEffect(() => {
    const element = ref.current;
    if (
      timing !== "observer" ||
      !element ||
      typeof ResizeObserver === "undefined"
    ) {
      return;
    }
    const resize = leadingDebounce<ElementSize>((next) => {
      setSize((prev) => (sameSize(prev, next) ? prev : next));
    }, debounceTime);
    let frame = 0;
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        frame = requestAnimationFrame(() => resize({ width, height }));
      }
    });
    observer.observe(element);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      resize.cancel();
    };
  }, [ref, debounceTime, timing]);

  useIsomorphicLayoutEffect(() => {
    const element = ref.current;
    if (timing !== "layout" || !element) {
      return;
    }
    const apply = () => {
      const next = readElementSize(element);
      setSize((prev) => (sameSize(prev, next) ? prev : next));
    };
    apply();

    if (typeof ResizeObserver === "undefined") {
      return;
    }
    let timeout: ReturnType<typeof setTimeout> | null = null;
    let trailing = false;
    const observer = new ResizeObserver(() => {
      if (debounceTime <= 0) {
        apply();
        return;
      }
      if (timeout !== null) {
        trailing = true;
        return;
      }
      apply();
      const flush = () => {
        if (trailing) {
          trailing = false;
          apply();
          timeout = setTimeout(flush, debounceTime);
          return;
        }
        timeout = null;
      };
      timeout = setTimeout(flush, debounceTime);
    });
    observer.observe(element);
    return () => {
      observer.disconnect();
      if (timeout !== null) {
        clearTimeout(timeout);
      }
    };
  }, [ref, debounceTime, timing]);

  return size;
}

export interface ChartParentSizeProps {
  children: (size: { width: number; height: number }) => ReactNode;
  className?: string;
  debounceTime?: number;
  style?: CSSProperties;
}

/**
 * Drop-in for visx `<ParentSize>` without its `overflow: hidden` measuring
 * layer, so tooltips, markers, and strokes at the chart edge aren't clipped.
 * Measures before first paint (see {@link useElementSize}).
 */
export function ParentSize({
  children,
  className,
  debounceTime,
  style,
}: ChartParentSizeProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(parentRef, debounceTime ?? 300);
  return (
    <div
      className={className}
      style={{ position: "relative", width: "100%", height: "100%", ...style }}
    >
      <div ref={parentRef} style={{ position: "absolute", inset: 0 }}>
        {children({ width, height })}
      </div>
    </div>
  );
}

/** Consumer-facing fetch / display status on time-series charts. */
export type ChartStatus = "loading" | "ready";

/** Loading animation style: the default traveling pulse, or a diagonal
 * shimmer that sweeps across the skeleton. */
export type LoadingStyle = "pulse" | "sweep";

/**
 * Internal visual lifecycle phase. Forward and reverse transitions add
 * intermediate phases in later stack branches.
 */
export type ChartPhase =
  | "loading"
  | "exiting"
  | "gridTweenReady"
  | "revealing"
  | "ready"
  | "exitingReady"
  | "gridTweenLoading"
  | "revealingLoading";

export const DEFAULT_CHART_STATUS: ChartStatus = "ready";

/** Default Y-domain tween when transitioning loading ↔ ready (ms). */
export const DEFAULT_Y_DOMAIN_TWEEN_MS = 500;

/** Relative domain delta below which Y tween may be skipped (see plan). */
export const Y_DOMAIN_TWEEN_SKIP_THRESHOLD = 0.02;

/** Resting phase for a given status before transition orchestration runs. */
export function resolveRestingChartPhase(status: ChartStatus): ChartPhase {
  return status === "loading" ? "loading" : "ready";
}

export function isChartInteractionPhase(phase: ChartPhase): boolean {
  return phase === "ready";
}

export const DEFAULT_CHART_LIFECYCLE = {
  chartPhase: "ready",
  chartStatus: "ready",
  loadingLabel: undefined,
  yDomainTweenDuration: DEFAULT_Y_DOMAIN_TWEEN_MS,
  yDomainSkeletonByAxis: { left: [0, 100] as [number, number] },
  // No target: charts without a y-domain tween (bar, candlestick, scatter,
  // live line) have no settled domain distinct from the live scale, so
  // `useSettledYScale` must fall back to it. A placeholder here made `YAxis`
  // tick 0–100 on top of the real data scale.
  yDomainTargetByAxis: {} as Record<string, [number, number]>,
} as const satisfies {
  chartPhase: ChartPhase;
  chartStatus: ChartStatus;
  loadingLabel: undefined;
  yDomainTweenDuration: number;
  yDomainSkeletonByAxis: Record<string, [number, number]>;
  yDomainTargetByAxis: Record<string, [number, number]>;
};

"use client";

import type { Transition } from "motion/react";
import { m } from "motion/react";
import { clipRevealTransition } from "./animation";

export type ChartRevealClipMode = "reveal" | "conceal";

export interface ChartRevealClipProps {
  clipPathId: string;
  height: number;
  targetWidth: number;
  enterTransition?: Transition;
  /** Bumps when motion settings change to replay the reveal. */
  revealEpoch: number;
  /** Extra inset around the clip rect so edge glyphs are not cut off. */
  padding?: number;
  /**
   * Vertical inset above and below the clip rect. Defaults to `padding`.
   * The reveal only animates x, so this can be larger than `padding` to let
   * point markers and strokes at the top/bottom of the plot render in full.
   */
  paddingY?: number;
  /** When false, clip stays at full width (no grow animation). */
  animating?: boolean;
  /** Reveal grows 0 → full; conceal shrinks full → 0 (ready → loading). */
  mode?: ChartRevealClipMode;
  /** Called when a conceal animation finishes. */
  onComplete?: () => void;
}

/**
 * Left-to-right clip reveal for cartesian series.
 * Grows clip rect width from 0 → full (true LTR; scaleX is avoided — it reveals from center).
 */
export function ChartRevealClip({
  clipPathId,
  height,
  targetWidth,
  enterTransition,
  revealEpoch,
  padding = 0,
  paddingY = padding,
  animating = true,
  mode = "reveal",
  onComplete,
}: ChartRevealClipProps) {
  const transition = clipRevealTransition(enterTransition);
  const paddedWidth = Math.max(0, targetWidth + padding * 2);
  const paddedHeight = height + paddingY * 2;

  if (!animating) {
    return (
      <clipPath id={clipPathId}>
        <rect
          height={paddedHeight}
          width={paddedWidth}
          x={-padding}
          y={-paddingY}
        />
      </clipPath>
    );
  }

  if (mode === "conceal") {
    // Mirror the LTR reveal: advance the clip's left edge rightward while width
    // shrinks (same geometry as `LineLoadingPulseStroke` exit half-cycle).
    const rightEdge = -padding + paddedWidth;

    return (
      <clipPath id={clipPathId}>
        <m.rect
          animate={{ width: 0, x: rightEdge }}
          height={paddedHeight}
          initial={{ width: paddedWidth, x: -padding }}
          key={`conceal-${revealEpoch}`}
          onAnimationComplete={() => onComplete?.()}
          transition={transition}
          y={-paddingY}
        />
      </clipPath>
    );
  }

  return (
    <clipPath id={clipPathId}>
      <m.rect
        animate={{ width: paddedWidth }}
        height={paddedHeight}
        initial={{ width: 0 }}
        key={`reveal-${revealEpoch}`}
        transition={transition}
        width={paddedWidth}
        x={-padding}
        y={-paddingY}
      />
    </clipPath>
  );
}

