export default ChoroplethDotGrid;

"use client";

import { geoCentroid } from "d3-geo";
import { m, useTransform } from "motion/react";
import { memo, useCallback, useMemo } from "react";
import { useEnterComplete } from "../use-enter-complete";
import { useMountProgress } from "../use-mount-progress";
import { useChoroplethCamera } from "./choropleth-camera";
import {
  type ChoroplethFeature as ChoroplethFeatureType,
  defaultChoroplethColors,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./choropleth-context";

export interface ChoroplethFeatureProps {
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  fadedOpacity?: number;
  getFeatureColor?: (feature: ChoroplethFeatureType, index: number) => string;
  patterns?: React.ReactNode;
  getFeaturePattern?: (
    feature: ChoroplethFeatureType,
    index: number
  ) => string | null | undefined;
}

interface FeatureRecord {
  index: number;
  path: string;
  fill: string;
  feature: ChoroplethFeatureType;
  centroid: { x: number; y: number } | null;
}

function resolveFeatureFill(
  feature: ChoroplethFeatureType,
  index: number,
  fill: string | undefined,
  getFeatureColor: ChoroplethFeatureProps["getFeatureColor"],
  getFeaturePattern: ChoroplethFeatureProps["getFeaturePattern"]
): string {
  const patternId = getFeaturePattern?.(feature, index);
  if (patternId) {
    return `url(#${patternId})`;
  }
  if (fill) {
    return fill;
  }
  if (getFeatureColor) {
    return getFeatureColor(feature, index);
  }
  return (
    defaultChoroplethColors[index % defaultChoroplethColors.length] ??
    "var(--chart-1)"
  );
}

const StaticFeatureLayer = memo(function StaticFeatureLayer({
  records,
  stroke,
  strokeWidth,
  baseOpacity,
  dimOpacity,
  hoveredIndex,
  focusedIndex,
  onFeatureEnter,
  onFeatureLeave,
  onFeatureClick,
}: {
  records: FeatureRecord[];
  stroke: string;
  strokeWidth: number;
  baseOpacity: number;
  dimOpacity: number;
  hoveredIndex: number | null;
  /** Region the camera is focused on — never dimmed. */
  focusedIndex: number | null;
  onFeatureEnter: (record: FeatureRecord) => void;
  onFeatureLeave: () => void;
  onFeatureClick: (index: number) => void;
}) {
  const isDimmed = hoveredIndex !== null;

  if (!isDimmed) {
    return (
      <g opacity={baseOpacity}>
        {records.map((record) => (
          // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
          <path
            className="cursor-pointer"
            data-region={record.feature.id ?? record.feature.properties.name}
            d={record.path}
            fill={record.fill}
            key={`base-${record.index}`}
            onClick={() => onFeatureClick(record.index)}
            onPointerUp={event => { if (event.pointerType !== "mouse") onFeatureEnter(record); }}
            onMouseEnter={() => onFeatureEnter(record)}
            onMouseLeave={onFeatureLeave}
            stroke={stroke}
            strokeWidth={strokeWidth}
          />
        ))}
      </g>
    );
  }

  const isLit = (index: number) =>
    index === hoveredIndex || index === focusedIndex;
  // Focused region first so a hovered neighbour draws on top of it.
  const highlighted = records
    .filter((record) => isLit(record.index))
    .sort((a) => (a.index === hoveredIndex ? 1 : -1));

  return (
    <>
      <g opacity={dimOpacity} style={{ transition: "opacity 0.18s ease-out" }}>
        {records
          .filter((record) => !isLit(record.index))
          .map((record) => (
            // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
            <path
              className="cursor-pointer"
              data-region={record.feature.id ?? record.feature.properties.name}
            d={record.path}
              fill={record.fill}
              key={`base-${record.index}`}
              onClick={() => onFeatureClick(record.index)}
              onPointerUp={event => { if (event.pointerType !== "mouse") onFeatureEnter(record); }}
            onMouseEnter={() => onFeatureEnter(record)}
              onMouseLeave={onFeatureLeave}
              stroke={stroke}
              strokeWidth={strokeWidth}
            />
          ))}
      </g>
      {highlighted.map((record) => (
        // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
        <path
          className="cursor-pointer"
          data-region={record.feature.id ?? record.feature.properties.name}
            d={record.path}
          fill={record.fill}
          key={`highlight-${record.index}`}
          onClick={() => onFeatureClick(record.index)}
          onPointerUp={event => { if (event.pointerType !== "mouse") onFeatureEnter(record); }}
            onMouseEnter={() => onFeatureEnter(record)}
          onMouseLeave={onFeatureLeave}
          opacity={1}
          stroke={stroke}
          strokeWidth={strokeWidth}
          style={{ transition: "opacity 0.18s ease-out" }}
        />
      ))}
    </>
  );
});

const EnterFeatureLayer = memo(function EnterFeatureLayer({
  records,
  stroke,
  strokeWidth,
  baseOpacity,
  dimOpacity,
  hoveredIndex,
  focusedIndex,
  onFeatureEnter,
  onFeatureLeave,
  onFeatureClick,
  revealEpoch,
}: {
  records: FeatureRecord[];
  stroke: string;
  strokeWidth: number;
  baseOpacity: number;
  dimOpacity: number;
  hoveredIndex: number | null;
  /** Region the camera is focused on — never dimmed. */
  focusedIndex: number | null;
  onFeatureEnter: (record: FeatureRecord) => void;
  onFeatureLeave: () => void;
  onFeatureClick: (index: number) => void;
  revealEpoch: number;
}) {
  const { enterTransition, animationDuration } = useChoroplethStable();
  const mountProgress = useMountProgress(
    enterTransition,
    0,
    `choropleth-layer-${revealEpoch}`
  );
  const enterComplete = useEnterComplete(mountProgress);
  const layerOpacity = useTransform(mountProgress, (t) => t * baseOpacity);

  if (enterComplete) {
    return (
      <StaticFeatureLayer
        baseOpacity={baseOpacity}
        dimOpacity={dimOpacity}
        focusedIndex={focusedIndex}
        hoveredIndex={hoveredIndex}
        onFeatureClick={onFeatureClick}
        onFeatureEnter={onFeatureEnter}
        onFeatureLeave={onFeatureLeave}
        records={records}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    );
  }

  return (
    <m.g
      key={`enter-${revealEpoch}`}
      opacity={layerOpacity}
      transition={{
        duration: animationDuration / 1000,
        ease: "easeOut",
      }}
    >
      {records.map((record) => (
        // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
        <path
          className="cursor-pointer"
          data-region={record.feature.id ?? record.feature.properties.name}
            d={record.path}
          fill={record.fill}
          key={`enter-${record.index}`}
          onClick={() => onFeatureClick(record.index)}
          onPointerUp={event => { if (event.pointerType !== "mouse") onFeatureEnter(record); }}
            onMouseEnter={() => onFeatureEnter(record)}
          onMouseLeave={onFeatureLeave}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      ))}
    </m.g>
  );
});

export const ChoroplethFeature = memo(function ChoroplethFeature({
  fill,
  stroke = "var(--background)",
  strokeWidth = 0.5,
  fadedOpacity = 0.4,
  getFeatureColor,
  patterns,
  getFeaturePattern,
}: ChoroplethFeatureProps) {
  const {
    features,
    featurePaths,
    pathGenerator,
    projectPoint,
    isLoaded,
    revealEpoch,
    width,
    height,
  } = useChoroplethStable();
  const { hoveredFeatureIndex, setHoveredFeatureIndex, setTooltipData } =
    useChoroplethInteraction();

  const featureCentroids = useMemo(() => {
    return features.map((feature) => {
      try {
        const centroid = geoCentroid(feature);
        if (
          centroid &&
          !Number.isNaN(centroid[0]) &&
          !Number.isNaN(centroid[1])
        ) {
          const projected = projectPoint(centroid as [number, number]);
          if (projected) {
            const padding = 60;
            return {
              x: Math.max(padding, Math.min(width - padding, projected[0])),
              y: Math.max(padding, Math.min(height - padding, projected[1])),
            };
          }
        }
      } catch {
        // Some geometries may not have valid centroids
      }
      return null;
    });
  }, [features, projectPoint, width, height]);

  const records = useMemo(() => {
    const items: FeatureRecord[] = [];
    for (let index = 0; index < features.length; index++) {
      const feature = features[index];
      if (!feature) {
        continue;
      }

      const path = featurePaths[index] ?? pathGenerator(feature);
      if (!path) {
        continue;
      }

      items.push({
        index,
        path,
        fill: resolveFeatureFill(
          feature,
          index,
          fill,
          getFeatureColor,
          getFeaturePattern
        ),
        feature,
        centroid: featureCentroids[index] ?? null,
      });
    }
    return items;
  }, [
    featureCentroids,
    featurePaths,
    features,
    fill,
    getFeatureColor,
    getFeaturePattern,
    pathGenerator,
  ]);

  const camera = useChoroplethCamera();
  const handleFeatureEnter = useCallback(
    (record: FeatureRecord) => {
      if (!camera.isHoverable(`feature:${record.index}`)) {
        return;
      }
      setHoveredFeatureIndex(record.index);
      setTooltipData({
        featureIndex: record.index,
        x: record.centroid?.x ?? width / 2,
        y: record.centroid?.y ?? height / 2,
        feature: record.feature,
      });
    },
    [camera, height, setHoveredFeatureIndex, setTooltipData, width]
  );

  const handleFeatureLeave = useCallback(() => {
    setHoveredFeatureIndex(null);
    setTooltipData(null);
  }, [setHoveredFeatureIndex, setTooltipData]);

  const handleFeatureClick = useCallback(
    (index: number) => {
      if (camera.enabled && !camera.wasDrag()) {
        camera.focusFeature(index);
      }
    },
    [camera]
  );

  const layerProps = {
    baseOpacity: 0.85,
    onFeatureClick: handleFeatureClick,
    dimOpacity: fadedOpacity,
    hoveredIndex: hoveredFeatureIndex,
    focusedIndex: camera.focusedFeatureIndex,
    onFeatureEnter: handleFeatureEnter,
    onFeatureLeave: handleFeatureLeave,
    records,
    stroke,
    strokeWidth,
  };

  return (
    <g className="choropleth-features">
      {patterns ? <defs>{patterns}</defs> : null}
      {isLoaded ? (
        <StaticFeatureLayer {...layerProps} />
      ) : (
        <EnterFeatureLayer {...layerProps} revealEpoch={revealEpoch} />
      )}
    </g>
  );
});

ChoroplethFeature.displayName = "ChoroplethFeature";

export default ChoroplethFeature;

"use client";

import { memo, useMemo } from "react";
import { useChoroplethCamera } from "./choropleth-camera";
import { useChoroplethStable } from "./choropleth-context";
import { graticulePath } from "./choropleth-projection";

export interface ChoroplethGraticuleProps {
  /** Stroke color for graticule lines. Default: rgba(255,255,255,0.1) */
  stroke?: string;
  /** Stroke width for graticule lines. Default: 0.5 */
  strokeWidth?: number;
  /** Step intervals for graticule lines [longitude, latitude] in degrees. Default: [10, 10] */
  step?: [number, number];
  /** Fade the lines out while the camera is focused on a region or marker. Default: true */
  hideOnFocus?: boolean;
}

export const ChoroplethGraticule = memo(function ChoroplethGraticule({
  stroke = "rgba(255,255,255,0.1)",
  strokeWidth = 0.5,
  step,
  hideOnFocus = true,
}: ChoroplethGraticuleProps) {
  const { rawPathGenerator } = useChoroplethStable();
  const { focusedKey } = useChoroplethCamera();
  const hidden = hideOnFocus && focusedKey !== null;
  const stepX = step?.[0];
  const stepY = step?.[1];

  const d = useMemo(
    () =>
      graticulePath(
        rawPathGenerator,
        stepX === undefined || stepY === undefined ? undefined : [stepX, stepY]
      ),
    [rawPathGenerator, stepX, stepY]
  );

  // Same markup as visx <Graticule>: a group wrapping one unfilled path.
  return (
    <g
      className="visx-group visx-geo-graticule"
      style={{ opacity: hidden ? 0 : 1, transition: "opacity 0.3s ease-out" }}
      transform="translate(0, 0)"
    >
      <path d={d} fill="none" stroke={stroke} strokeWidth={strokeWidth} />
    </g>
  );
});

ChoroplethGraticule.displayName = "ChoroplethGraticule";

export default ChoroplethGraticule;

"use client";

import { memo, useCallback, useId } from "react";
import { cn } from "@/lib/utils";
import {
  CHOROPLETH_CAMERA_SCALE_VAR,
  useChoroplethCamera,
} from "./choropleth-camera";
import {
  useChoroplethInteraction,
  useChoroplethStable,
  useChoroplethZoom,
} from "./choropleth-context";

export type ChoroplethMarkerShape =
  | "circle"
  | "triangle"
  | "square"
  | "diamond"
  | "pin";

export type ChoroplethMarkerPulse = "none" | "hover" | "always";

export interface ChoroplethMarkerProps {
  /** `[longitude, latitude]` */
  coordinates: [number, number];
  /** Localized accessible action name for interactive maps. */
  zoomLabel?: string;
  /** Name shown in the tooltip (and next to the marker with `showLabel`). */
  label: string;
  /** Default: "circle" */
  shape?: ChoroplethMarkerShape;
  /** Marker size in px. It stays this size while the map zooms. Default: 9 */
  size?: number;
  /** Default: `var(--foreground)` */
  color?: string;
  /** Outline colour; omit for no outline. */
  stroke?: string;
  /** Outline width in px (only with `stroke`). Default: 1.5 */
  strokeWidth?: number;
  /** Ripple ring: off, while hovered/focused, or always. Default: "hover" */
  pulse?: ChoroplethMarkerPulse;
  /** Soft outer glow blur in px; `0` turns it off. Default: 0 */
  glow?: number;
  /** Always show the label beside the marker. Default: false */
  showLabel?: boolean;
  className?: string;
}

function shapePath(shape: ChoroplethMarkerShape, r: number) {
  switch (shape) {
    case "triangle":
      return `M0,${-r * 1.15}L${r * 1.05},${r * 0.7}L${-r * 1.05},${r * 0.7}Z`;
    case "square": {
      const s = r * 0.88;
      return `M${-s},${-s}H${s}V${s}H${-s}Z`;
    }
    case "diamond":
      return `M0,${-r * 1.2}L${r * 1.2},0L0,${r * 1.2}L${-r * 1.2},0Z`;
    case "pin": {
      // Tip sits on the coordinate; round head above it.
      const cy = -r * 1.9;
      const hx = r * 0.82;
      const hy = cy + r * 0.57;
      return `M0,0L${-hx},${hy}A${r},${r} 0 1,1 ${hx},${hy}Z`;
    }
    default:
      return `M${-r},0a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0`;
  }
}

const PULSE_CLASS: Record<ChoroplethMarkerPulse, string> = {
  always: "animate-ping",
  hover:
    "group-hover/marker:animate-ping group-focus-visible/marker:animate-ping",
  none: "hidden",
};

/** Stable per-label offset so "always" pulses don't fire in lockstep. */
function pulseDelay(label: string) {
  let h = 0;
  for (let i = 0; i < label.length; i++) {
    h = (h * 31 + label.charCodeAt(i)) % 997;
  }
  return `${-(h % 10) * 110}ms`;
}

export const ChoroplethMarker = memo(function ChoroplethMarker({
  coordinates,
  label,
  zoomLabel,
  shape = "circle",
  size = 9,
  color = "var(--foreground)",
  stroke,
  strokeWidth = 1.5,
  pulse = "hover",
  glow = 0,
  showLabel = false,
  className,
}: ChoroplethMarkerProps) {
  const { projectPoint } = useChoroplethStable();
  const { setMarkerTooltip, setHoveredFeatureIndex, setTooltipData } =
    useChoroplethInteraction();
  const { zoom } = useChoroplethZoom();
  const camera = useChoroplethCamera();
  const glowId = `choropleth-marker-glow-${useId().replace(/:/g, "")}`;

  const [lon, lat] = coordinates;
  const point = projectPoint([lon, lat]);

  const hoverable = camera.isHoverable(`point:${label}`);
  const show = useCallback(() => {
    if (!hoverable) {
      return;
    }
    setHoveredFeatureIndex(null);
    setTooltipData(null);
    setMarkerTooltip?.({ label, coordinates: [lon, lat] });
  }, [
    hoverable,
    label,
    lat,
    lon,
    setHoveredFeatureIndex,
    setMarkerTooltip,
    setTooltipData,
  ]);

  const hide = useCallback(() => setMarkerTooltip?.(null), [setMarkerTooltip]);

  const focus = useCallback(() => {
    if (camera.enabled) {
      camera.focusPoint([lon, lat], label);
    }
  }, [camera, label, lat, lon]);

  if (!point) {
    return null;
  }

  const r = size / 2;
  const d = shapePath(shape, r);
  const isPin = shape === "pin";
  const headY = isPin ? -r * 1.9 : 0;
  const zoomScale = zoom?.transformMatrix.scaleX ?? 1;
  const interactive = camera.enabled;
  const pulseClass =
    pulse === "hover" && !hoverable ? "hidden" : PULSE_CLASS[pulse];
  // Zoomed in on something else: stay clickable, skip hover feedback.
  const hoverScale = hoverable ? "group-hover/marker:scale-115" : "";

  return (
    <g transform={`translate(${point[0]} ${point[1]})`}>
      {/* biome-ignore lint/a11y/noStaticElementInteractions: role set when clickable */}
      <g
        aria-label={interactive ? (zoomLabel ?? `Zoom to ${label}`) : undefined}
        className={cn(
          "group/marker outline-none",
          interactive && "cursor-pointer",
          className
        )}
        onBlur={hide}
        onClick={(event) => {
          event.stopPropagation();
          if (!camera.wasDrag()) {
            focus();
          }
        }}
        onFocus={show}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            focus();
          }
        }}
        onMouseEnter={show}
        onMouseLeave={hide}
        role={interactive ? "button" : undefined}
        style={{
          // Constant on-screen size while the camera and drag-zoom scale the map.
          transform: `scale(calc(1 / (var(${CHOROPLETH_CAMERA_SCALE_VAR}, 1) * ${zoomScale})))`,
        }}
        tabIndex={interactive ? 0 : undefined}
      >
        {/* Hit area stays still while the shape scales. */}
        <circle cy={headY * 0.6} fill="transparent" r={Math.max(r * 2, 22)} />
        <circle
          className={cn(
            "pointer-events-none origin-center [transform-box:fill-box] motion-reduce:animate-none",
            pulseClass
          )}
          cy={headY}
          fill="none"
          r={r}
          stroke={color}
          strokeWidth={1.5}
          style={
            pulse === "always"
              ? { animationDelay: pulseDelay(label) }
              : undefined
          }
        />
        {glow > 0 ? (
          <>
            <defs>
              <filter
                height="500%"
                id={glowId}
                width="500%"
                x="-200%"
                y="-200%"
              >
                <feGaussianBlur stdDeviation={glow} />
              </filter>
            </defs>
            <path
              className={cn(
                hoverable &&
                  "group-hover/marker:scale-115 group-hover/marker:opacity-100",
                "pointer-events-none opacity-55 transition-[opacity,scale] duration-150 ease-out [transform-box:fill-box] group-focus-visible/marker:opacity-100 group-focus-visible/marker:opacity-100 motion-reduce:transition-none",
                isPin ? "origin-bottom" : "origin-center"
              )}
              d={d}
              fill={color}
              filter={`url(#${glowId})`}
            />
          </>
        ) : null}
        <path
          className={cn(
            hoverScale,
            "transition-[scale] duration-150 ease-out [transform-box:fill-box] group-focus-visible/marker:stroke-foreground motion-reduce:transition-none",
            isPin ? "origin-bottom" : "origin-center"
          )}
          d={d}
          fill={color}
          paintOrder="stroke"
          // No outline unless asked for; keyboard focus still draws one.
          stroke={stroke ?? "none"}
          strokeWidth={stroke ? strokeWidth : 2}
        />
        {isPin ? (
          <circle
            className="pointer-events-none"
            cy={headY}
            fill="var(--background)"
            r={r * 0.38}
          />
        ) : null}
        {showLabel ? (
          <text
            className="pointer-events-none select-none font-medium text-[11px]"
            dy="0.35em"
            fill="var(--foreground)"
            paintOrder="stroke"
            stroke="var(--background)"
            strokeLinejoin="round"
            strokeWidth={3}
            x={r + 6}
            y={headY}
          >
            {label}
          </text>
        ) : null}
      </g>
    </g>
  );
});

ChoroplethMarker.displayName = "ChoroplethMarker";

export default ChoroplethMarker;

import {
  type GeoPath,
  type GeoPermissibleObjects,
  type GeoProjection,
  geoGraticule,
  geoMercator,
  geoPath,
} from "d3-geo";
import type { MultiLineString } from "geojson";

/** What the choropleth reads from its projection (visx `<Mercator>` render props). */
export interface ChoroplethMercator {
  path: GeoPath<unknown, GeoPermissibleObjects>;
  projection: GeoProjection;
}

export interface ChoroplethMercatorConfig {
  scale?: number;
  translate?: [number, number];
  center?: [number, number];
}

/**
 * d3 equivalent of visx `<Mercator scale translate center>`: visx applied
 * each option only when truthy, in this order (so `scale={0}` keeps d3's
 * default scale).
 */
export function createChoroplethMercator({
  scale,
  translate,
  center,
}: ChoroplethMercatorConfig): ChoroplethMercator {
  const projection = geoMercator();
  if (scale) {
    projection.scale(scale);
  }
  if (translate) {
    projection.translate(translate);
  }
  if (center) {
    projection.center(center);
  }
  return { path: geoPath(projection), projection };
}

/** One SVG path string per feature (null when the geometry draws nothing). */
export function projectFeaturePaths(
  mercator: ChoroplethMercator,
  features: readonly GeoPermissibleObjects[]
): (string | null)[] {
  return features.map((feature) => mercator.path(feature) ?? null);
}

/**
 * Graticule path as visx `<Graticule graticule={...} step={step}>` drew it:
 * the full `geoGraticule()` MultiLineString (minor `step`, default 10°, plus
 * the major lines) through the projection's path, `""` when empty.
 */
export function graticulePath(
  path: (object: MultiLineString) => string | null | undefined,
  step?: [number, number]
): string {
  const graticule = geoGraticule();
  if (step) {
    graticule.step(step);
  }
  return path(graticule()) || "";
}

"use client";

import { intFmt } from "../chart-formatters";
import { CursorTooltipBox } from "../tooltip/cursor-tooltip-box";
import { TooltipContent, type TooltipRow } from "../tooltip/tooltip-content";
import {
  TOOLTIP_HIDE_DELAY_MS,
  useDelayedTooltipData,
} from "../tooltip/use-delayed-tooltip-data";
import {
  type ChoroplethFeature,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./choropleth-context";

export interface ChoroplethTooltipProps {
  /** Custom content renderer for feature tooltips */
  content?: (props: {
    feature: ChoroplethFeature;
    index: number;
  }) => React.ReactNode;
  /** Value formatter function */
  formatValue?: (value: number) => string;
  /** Get the display name for a feature. Default: uses feature.properties.name */
  getFeatureName?: (feature: ChoroplethFeature, index: number) => string;
  /** Get the value for a feature (for display in tooltip) */
  getFeatureValue?: (
    feature: ChoroplethFeature,
    index: number
  ) => number | undefined;
  /** Label for the value row. Default: "Value" */
  valueLabel?: string;
  locationLabel?: string;
  /** Custom class name */
  className?: string;
  /** Inline styles for the tooltip panel (background, blur, etc.). */
  panelStyle?: React.CSSProperties;
  /**
   * Tooltip panel background color (CSS variable or color value).
   * Default: `var(--chart-tooltip-background)`.
   */
  backgroundColor?: string;
  /** Fade the panel out when hover ends. Default: true */
  exit?: boolean;
  /**
   * Grace period before hiding when the pointer leaves a feature (ms).
   * Bridges border gaps so the panel springs to the next feature instead of
   * fading out and back in. Default: `120`.
   */
  hideDelay?: number;
}

export function ChoroplethTooltip({
  content,
  formatValue = intFmt,
  getFeatureName,
  getFeatureValue,
  valueLabel = "Value",
  locationLabel = "Location",
  className = "",
  panelStyle,
  backgroundColor,
  exit = true,
  hideDelay = TOOLTIP_HIDE_DELAY_MS,
}: ChoroplethTooltipProps) {
  const { containerRef, features } = useChoroplethStable();
  const { tooltipData: hoverData, markerTooltip: hoverMarker } =
    useChoroplethInteraction();
  const tooltipData = useDelayedTooltipData(hoverData, 0, hideDelay);
  const marker = useDelayedTooltipData(hoverMarker ?? null, 0, hideDelay);

  const feature = tooltipData ? features[tooltipData.featureIndex] : undefined;

  let body: React.ReactNode = null;
  if (marker) {
    const [lon, lat] = marker.coordinates;
    body = (
      <TooltipContent
        rows={[
          {
            color: "var(--chart-foreground-muted)",
            label: locationLabel,
            value: `${lat.toFixed(2)}°, ${lon.toFixed(2)}°`,
          },
        ]}
        title={marker.label}
      />
    );
  } else if (tooltipData && feature) {
    const index = tooltipData.featureIndex;
    if (content) {
      body = content({ feature, index });
    } else {
      const featureName = getFeatureName
        ? getFeatureName(feature, index)
        : (feature.properties?.name ?? `Feature ${index}`);
      const value = getFeatureValue?.(feature, index);
      const rows: TooltipRow[] =
        value === undefined
          ? []
          : [
              {
                color: "var(--chart-1)",
                label: valueLabel,
                value: formatValue(value),
              },
            ];
      body = <TooltipContent rows={rows} title={featureName} />;
    }
  }

  // Always mounted so the panel can fade out; `visible` drives presence. The
  // panel follows the cursor (Motion values, no re-render per move); React
  // only re-renders here when the hovered feature changes.
  return (
    <CursorTooltipBox
      backgroundColor={backgroundColor}
      className={className}
      containerRef={containerRef}
      exit={exit}
      panelStyle={panelStyle}
      visible={Boolean(marker || (tooltipData && feature))}
    >
      {body}
    </CursorTooltipBox>
  );
}

ChoroplethTooltip.displayName = "ChoroplethTooltip";

export default ChoroplethTooltip;

/**
 * 2D affine matrix helpers for the choropleth zoom. Same fields, formulas and
 * operation order as `@visx/zoom` 4.0.0 `util/matrix`, so every wheel / drag /
 * button step produces a bit-identical transform.
 */

export interface TransformMatrix {
  scaleX: number;
  scaleY: number;
  translateX: number;
  translateY: number;
  skewX: number;
  skewY: number;
}

export interface Point {
  x: number;
  y: number;
}

export type Translate = Pick<TransformMatrix, "translateX" | "translateY">;
export type Scale = Pick<TransformMatrix, "scaleX" | "scaleY">;

export interface ScaleSignature {
  scaleX: TransformMatrix["scaleX"];
  scaleY?: TransformMatrix["scaleY"];
  point?: Point;
}

export interface ScaleLimits {
  scaleXMin: number;
  scaleXMax: number;
  scaleYMin: number;
  scaleYMax: number;
}

export function identityMatrix(): TransformMatrix {
  return {
    scaleX: 1,
    scaleY: 1,
    translateX: 0,
    translateY: 0,
    skewX: 0,
    skewY: 0,
  };
}

export function createMatrix({
  scaleX = 1,
  scaleY = 1,
  translateX = 0,
  translateY = 0,
  skewX = 0,
  skewY = 0,
}: Partial<TransformMatrix>): TransformMatrix {
  return { scaleX, scaleY, translateX, translateY, skewX, skewY };
}

export function inverseMatrix({
  scaleX,
  scaleY,
  translateX,
  translateY,
  skewX,
  skewY,
}: TransformMatrix): TransformMatrix {
  const denominator = scaleX * scaleY - skewY * skewX;
  return {
    scaleX: scaleY / denominator,
    scaleY: scaleX / denominator,
    translateX: (scaleY * translateX - skewX * translateY) / -denominator,
    translateY: (skewY * translateX - scaleX * translateY) / denominator,
    skewX: skewX / -denominator,
    skewY: skewY / -denominator,
  };
}

export function applyMatrixToPoint(
  matrix: TransformMatrix,
  { x, y }: Point
): Point {
  return {
    x: matrix.scaleX * x + matrix.skewX * y + matrix.translateX,
    y: matrix.skewY * x + matrix.scaleY * y + matrix.translateY,
  };
}

export function applyInverseMatrixToPoint(
  matrix: TransformMatrix,
  { x, y }: Point
): Point {
  return applyMatrixToPoint(inverseMatrix(matrix), { x, y });
}

export function scaleMatrix(
  scaleX: number,
  maybeScaleY: number | undefined = undefined
): TransformMatrix {
  const scaleY = maybeScaleY || scaleX;
  return createMatrix({ scaleX, scaleY });
}

export function translateMatrix(
  translateX: number,
  translateY: number
): TransformMatrix {
  return createMatrix({ translateX, translateY });
}

export function multiplyMatrices(
  matrix1: TransformMatrix,
  matrix2: TransformMatrix
): TransformMatrix {
  return {
    scaleX: matrix1.scaleX * matrix2.scaleX + matrix1.skewX * matrix2.skewY,
    scaleY: matrix1.skewY * matrix2.skewX + matrix1.scaleY * matrix2.scaleY,
    translateX:
      matrix1.scaleX * matrix2.translateX +
      matrix1.skewX * matrix2.translateY +
      matrix1.translateX,
    translateY:
      matrix1.skewY * matrix2.translateX +
      matrix1.scaleY * matrix2.translateY +
      matrix1.translateY,
    skewX: matrix1.scaleX * matrix2.skewX + matrix1.skewX * matrix2.scaleY,
    skewY: matrix1.skewY * matrix2.scaleX + matrix1.scaleY * matrix2.skewY,
  };
}

/** Left-to-right composition (visx folds pairwise from the left). */
export function composeMatrices(
  ...matrices: [TransformMatrix, ...TransformMatrix[]]
): TransformMatrix {
  let result = matrices[0];
  for (let i = 1; i < matrices.length; i++) {
    result = multiplyMatrices(result, matrices[i] as TransformMatrix);
  }
  return result;
}

/** `matrix(a, b, c, d, e, f)` exactly as visx `toString()` writes it. */
export function matrixToString({
  scaleX,
  scaleY,
  translateX,
  translateY,
  skewX,
  skewY,
}: TransformMatrix): string {
  return `matrix(${scaleX}, ${skewY}, ${skewX}, ${scaleY}, ${translateX}, ${translateY})`;
}

/**
 * visx default `constrain`: reject (keep `prev`) when the next scale leaves
 * the limits. Pan is never constrained.
 */
export function constrainScale(
  next: TransformMatrix,
  prev: TransformMatrix,
  { scaleXMin, scaleXMax, scaleYMin, scaleYMax }: ScaleLimits
): TransformMatrix {
  const { scaleX, scaleY } = next;
  const shouldConstrainScaleX = scaleX > scaleXMax || scaleX < scaleXMin;
  const shouldConstrainScaleY = scaleY > scaleYMax || scaleY < scaleYMin;
  if (shouldConstrainScaleX || shouldConstrainScaleY) {
    return prev;
  }
  return next;
}

/**
 * visx `scale()`: scale by `scaleX` / `scaleY` (defaults to `scaleX`) around
 * `point` (in container coordinates; centre of `width` x `height` if absent).
 */
export function scaleMatrixAroundPoint(
  matrix: TransformMatrix,
  { scaleX, scaleY: maybeScaleY, point }: ScaleSignature,
  width: number,
  height: number
): TransformMatrix {
  const scaleY = maybeScaleY || scaleX;
  const cleanPoint = point || { x: width / 2, y: height / 2 };
  const translate = applyInverseMatrixToPoint(matrix, cleanPoint);
  return composeMatrices(
    matrix,
    translateMatrix(translate.x, translate.y),
    scaleMatrix(scaleX, scaleY),
    translateMatrix(-translate.x, -translate.y)
  );
}

/** visx default `wheelDelta` (Zoom without a custom one). */
export function defaultWheelDelta(event: { deltaY: number }): Scale {
  return -event.deltaY > 0
    ? { scaleX: 1.1, scaleY: 1.1 }
    : { scaleX: 0.9, scaleY: 0.9 };
}

/** The `wheelDelta` ChoroplethChart passes: 5% per wheel event. */
export function choroplethWheelDelta(event: { deltaY: number }): Scale {
  const zoomScale = event.deltaY > 0 ? 0.95 : 1.05;
  return { scaleX: zoomScale, scaleY: zoomScale };
}

/** Pinch progress handed to `pinchDelta` (the use-gesture fields visx read). */
export interface PinchDeltaState {
  /** `[scale offset, angle]` now. */
  offset: [number, number];
  /** `[scale offset, angle]` when the pinch started. */
  lastOffset: [number, number];
  /** Pinch centre in client coordinates. */
  origin: [number, number];
}

/** visx default `pinchDelta`: a 10% step towards the pinch direction. */
export function defaultPinchDelta({
  offset: [s],
  lastOffset: [lastS],
}: PinchDeltaState): Scale {
  return {
    scaleX: s - lastS < 0 ? 0.9 : 1.1,
    scaleY: s - lastS < 0 ? 0.9 : 1.1,
  };
}

const LINE_HEIGHT = 40;
const PAGE_HEIGHT = 800;

/** use-gesture `wheelValues()[1]`: deltaY in pixels. */
export function wheelDeltaYPixels(event: {
  deltaY: number;
  deltaMode: number;
}): number {
  if (event.deltaMode === 1) {
    return event.deltaY * LINE_HEIGHT;
  }
  if (event.deltaMode === 2) {
    return event.deltaY * PAGE_HEIGHT;
  }
  return event.deltaY;
}

/** use-gesture `PINCH_WHEEL_RATIO`: ctrl+wheel pixels per unit of pinch. */
export const PINCH_WHEEL_RATIO = 100;

/** use-gesture drag `tapsThreshold` (also the drag start threshold). */
export const DRAG_THRESHOLD_PX = 3;

"use client";

import type { WheelEvent as ReactWheelEvent, RefObject } from "react";
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { type LocalPointEvent, localPoint } from "../local-point";
import {
  applyInverseMatrixToPoint,
  applyMatrixToPoint,
  composeMatrices,
  constrainScale,
  DRAG_THRESHOLD_PX,
  defaultPinchDelta,
  defaultWheelDelta,
  identityMatrix,
  inverseMatrix,
  matrixToString,
  PINCH_WHEEL_RATIO,
  type PinchDeltaState,
  type Point,
  type Scale,
  type ScaleSignature,
  scaleMatrixAroundPoint,
  type TransformMatrix,
  type Translate,
  translateMatrix,
  wheelDeltaYPixels,
} from "./choropleth-zoom-matrix";

/**
 * Hand-written replacement for `@visx/zoom` 4.0.0 `<Zoom>` and the
 * `@use-gesture/react` recognisers it binds.
 *
 * The zoom API below is a transcription of visx's Zoom.js: the same React
 * state (`transformMatrix`, `isDragging`, `startPoint`, `startTranslate`),
 * the same matrix ref updated inside the `setTransformMatrix` updater, and
 * the same render-time closures. That matters beyond style: on the first
 * ctrl+wheel of a trackpad pinch, use-gesture calls the wheel handler and
 * then the pinch handler in one event, and whether the pinch step sees the
 * wheel step depends on whether React computed the first update eagerly.
 * Mirroring visx's state lets React make that call exactly as it did.
 *
 * The gesture layer reproduces use-gesture:
 * - Drag-pan with the primary button / one finger: pointer capture on the hit
 *   element, starts once the pointer moved 3 px on an axis (the first 3 px
 *   are not applied), the pointer-up position is applied once more, and a
 *   click after a real drag (> 3 px) is swallowed in the capture phase.
 * - Wheel (non-passive): one `wheelDelta` step per event around the cursor,
 *   skipped while pinching.
 * - Pinch: two pointers, ctrl+wheel (trackpads) or WebKit gesture events
 *   (desktop Safari). Each pinch event applies one `pinchDelta` step (default
 *   0.9 / 1.1) around the pinch centre minus the container's client rect,
 *   including one step when the pinch starts and one when it ends (a
 *   ctrl+wheel pinch ends 140 ms after its last event). A pinch cancels a
 *   drag.
 * - Scale steps that would leave `scaleXMin..scaleXMax` /
 *   `scaleYMin..scaleYMax` are rejected (not clamped). Pan is unconstrained.
 */

export interface ProvidedZoom<ElementType> {
  /** Sets translateX/Y to the center defined by width and height. */
  center: () => void;
  /** Sets the transform matrix to the identity matrix. */
  clear: () => void;
  /** Scales around `point` (or the centre of the canvas). */
  scale: (scale: ScaleSignature) => void;
  /** Multiplies the current transform matrix by the specified translation. */
  translate: (translate: Translate) => void;
  /** Translates to a specific x,y point. */
  translateTo: (point: Point) => void;
  /** Sets the translation of the current transform matrix. */
  setTranslate: (translate: Translate) => void;
  /** Sets the transform matrix, constraining its scale. */
  setTransformMatrix: (matrix: TransformMatrix) => void;
  /** Resets the transform to the initial transform. */
  reset: () => void;
  /** Wheel handler: one `wheelDelta` step around the pointer. */
  handleWheel: (event: ReactWheelEvent | WheelEvent) => void;
  /** Sets isDragging to false. */
  dragEnd: () => void;
  /** Pans by the pointer's distance from the drag start. */
  dragMove: (
    event: LocalPointEvent,
    options?: { offsetX?: number; offsetY?: number }
  ) => void;
  /** Records the drag start point and sets isDragging to true. */
  dragStart: (event: LocalPointEvent) => void;
  /** `matrix(scaleX, skewY, skewX, scaleY, translateX, translateY)` */
  toString: () => string;
  /** Inverse of the current transform matrix. */
  invert: () => TransformMatrix;
  /** String form of the inverse matrix. */
  toStringInvert: () => string;
  applyToPoint: (point: Point) => Point;
  applyInverseToPoint: (point: Point) => Point;
  /** Ref for the element that receives the gestures. */
  containerRef: RefObject<ElementType | null>;
}

export interface ZoomState {
  initialTransformMatrix: TransformMatrix;
  transformMatrix: TransformMatrix;
  isDragging: boolean;
}

export type ZoomInstance<E extends Element> = ProvidedZoom<E> & ZoomState;

export interface ChoroplethZoomOptions {
  width: number;
  height: number;
  initialTransformMatrix?: TransformMatrix;
  scaleXMin?: number;
  scaleXMax?: number;
  scaleYMin?: number;
  scaleYMax?: number;
  wheelDelta?: (event: ReactWheelEvent | WheelEvent) => Scale;
  pinchDelta?: (state: PinchDeltaState) => Scale;
  constrain?: (
    transform: TransformMatrix,
    prevTransform: TransformMatrix
  ) => TransformMatrix;
}

const DEFAULT_INITIAL: TransformMatrix = identityMatrix();
/** use-gesture `TimeoutStore` default: a ctrl+wheel pinch ends 140 ms after its last event. */
const WHEEL_END_MS = 140;

export interface DragGesture {
  pointerId: number;
  /** Pointer is down and tracked (use-gesture `_pointerActive`). */
  pointerActive: boolean;
  /** Gesture not ended / cancelled (use-gesture `_active`). */
  active: boolean;
  /** Past the threshold at least once (use-gesture `state.active`). */
  started: boolean;
  last: [number, number];
  movement: [number, number];
  distance: [number, number];
  intentional: boolean;
  /** Last event handed to the handlers (re-sent after a cancel). */
  event: PointerEvent | null;
}

interface PinchGesture {
  active: boolean;
  source: "pointer" | "wheel" | "gesture" | null;
  /** Persistent scale offset (use-gesture pinch `offset[0]`, starts at 1). */
  offset: number;
  lastOffset: number;
  /** ctrl+wheel: accumulated movement. */
  movement: number;
  initialDistance: number;
  origin: [number, number];
  memo: { top: number; left: number } | undefined;
  pointers: Map<number, { clientX: number; clientY: number }>;
}

/** What visx `handlePinch` read from the use-gesture pinch state. */
interface PinchHandlerState extends PinchDeltaState {
  memo: { top: number; left: number } | undefined;
}

export function createDragGesture(
  event: Pick<PointerEvent, "pointerId" | "clientX" | "clientY">
): DragGesture {
  return {
    pointerId: event.pointerId,
    pointerActive: true,
    active: true,
    started: false,
    last: [event.clientX, event.clientY],
    movement: [0, 0],
    distance: [0, 0],
    intentional: false,
    event: null,
  };
}

/**
 * Feed one pointer move into the drag (use-gesture `pointerMove` +
 * `compute`): `none` below the 3 px threshold, `first` on the move that
 * crosses it, `move` afterwards.
 */
export function advanceDragGesture(
  drag: DragGesture,
  clientX: number,
  clientY: number
): "none" | "first" | "move" {
  const dx = clientX - drag.last[0];
  const dy = clientY - drag.last[1];
  drag.last = [clientX, clientY];
  drag.movement[0] += dx;
  drag.movement[1] += dy;
  if (drag.active) {
    drag.distance[0] += Math.abs(dx);
    drag.distance[1] += Math.abs(dy);
  }
  if (
    !drag.intentional &&
    (Math.abs(drag.movement[0]) >= DRAG_THRESHOLD_PX ||
      Math.abs(drag.movement[1]) >= DRAG_THRESHOLD_PX)
  ) {
    drag.intentional = true;
  }
  if (!(drag.intentional && drag.active)) {
    return "none";
  }
  const first = !drag.started;
  drag.started = true;
  return first ? "first" : "move";
}

/** Distance and midpoint (client px) of the first two pinch pointers. */
function pinchPayload(
  pointers: PinchGesture["pointers"]
): { distance: number; origin: [number, number] } | null {
  const [a, b] = Array.from(pointers.values());
  if (!(a && b)) {
    return null;
  }
  return {
    distance: Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY),
    origin: [(b.clientX + a.clientX) / 2, (b.clientY + a.clientY) / 2],
  };
}

function supportsGestureEvents(): boolean {
  return (
    typeof window !== "undefined" &&
    !("ontouchstart" in window) &&
    "GestureEvent" in window
  );
}

export function useChoroplethZoomState<E extends Element>({
  width,
  height,
  initialTransformMatrix = DEFAULT_INITIAL,
  scaleXMin = 0,
  scaleXMax = Number.POSITIVE_INFINITY,
  scaleYMin = 0,
  scaleYMax = Number.POSITIVE_INFINITY,
  wheelDelta = defaultWheelDelta,
  pinchDelta = defaultPinchDelta,
  constrain,
}: ChoroplethZoomOptions): ZoomInstance<E> {
  // --- visx Zoom.js -------------------------------------------------------

  const containerRef = useRef<E | null>(null);
  const matrixStateRef = useRef<TransformMatrix>(initialTransformMatrix);
  const [transformMatrix, setTransformMatrixState] = useState(
    initialTransformMatrix
  );
  const [isDragging, setIsDragging] = useState(false);
  const [startTranslate, setStartTranslate] = useState<Translate | undefined>(
    undefined
  );
  const [startPoint, setStartPoint] = useState<Point | undefined>(undefined);

  const defaultConstrain = useCallback(
    (next: TransformMatrix, prev: TransformMatrix) =>
      constrain
        ? constrain(next, prev)
        : constrainScale(next, prev, {
            scaleXMin,
            scaleXMax,
            scaleYMin,
            scaleYMax,
          }),
    [constrain, scaleXMin, scaleXMax, scaleYMin, scaleYMax]
  );

  const setTransformMatrix = useCallback(
    (next: TransformMatrix) => {
      setTransformMatrixState((prev) => {
        const updated = defaultConstrain(next, prev);
        matrixStateRef.current = updated;
        return updated;
      });
    },
    [defaultConstrain]
  );

  const applyToPoint = useCallback(
    ({ x, y }: Point) => applyMatrixToPoint(transformMatrix, { x, y }),
    [transformMatrix]
  );
  const applyInverseToPoint = useCallback(
    ({ x, y }: Point) => applyInverseMatrixToPoint(transformMatrix, { x, y }),
    [transformMatrix]
  );
  const reset = useCallback(() => {
    setTransformMatrix(initialTransformMatrix);
  }, [initialTransformMatrix, setTransformMatrix]);

  const scale = useCallback(
    ({ scaleX, scaleY, point }: ScaleSignature) => {
      // visx reads the ref, not state: the wheel listener has no fresh state.
      setTransformMatrix(
        scaleMatrixAroundPoint(
          matrixStateRef.current,
          { scaleX, scaleY, point },
          width,
          height
        )
      );
      if (isDragging) {
        const { translateX, translateY } = matrixStateRef.current;
        setStartPoint(point);
        setStartTranslate({ translateX, translateY });
      }
    },
    [height, width, isDragging, setTransformMatrix]
  );

  const translate = useCallback(
    ({ translateX, translateY }: Translate) => {
      setTransformMatrix(
        composeMatrices(
          transformMatrix,
          translateMatrix(translateX, translateY)
        )
      );
    },
    [setTransformMatrix, transformMatrix]
  );
  const setTranslate = useCallback(
    ({ translateX, translateY }: Translate) => {
      setTransformMatrix({ ...transformMatrix, translateX, translateY });
    },
    [setTransformMatrix, transformMatrix]
  );
  const translateTo = useCallback(
    ({ x, y }: Point) => {
      const point = applyInverseMatrixToPoint(transformMatrix, { x, y });
      setTranslate({ translateX: point.x, translateY: point.y });
    },
    [setTranslate, transformMatrix]
  );
  const invert = useCallback(
    () => inverseMatrix(transformMatrix),
    [transformMatrix]
  );
  const toStringInvert = useCallback(() => matrixToString(invert()), [invert]);

  const dragStart = useCallback(
    (event: LocalPointEvent) => {
      const { translateX, translateY } = transformMatrix;
      setStartPoint(localPoint(event) || undefined);
      setStartTranslate({ translateX, translateY });
      setIsDragging(true);
    },
    [transformMatrix]
  );
  const dragMove = useCallback(
    (
      event: LocalPointEvent,
      options?: { offsetX?: number; offsetY?: number }
    ) => {
      if (!(isDragging && startPoint && startTranslate)) {
        return;
      }
      const currentPoint = localPoint(event);
      const dx = currentPoint
        ? -(startPoint.x - currentPoint.x)
        : -startPoint.x;
      const dy = currentPoint
        ? -(startPoint.y - currentPoint.y)
        : -startPoint.y;
      let translateX = startTranslate.translateX + dx;
      if (options?.offsetX) {
        translateX += options.offsetX ?? 0;
      }
      let translateY = startTranslate.translateY + dy;
      if (options?.offsetY) {
        translateY += options.offsetY ?? 0;
      }
      setTranslate({ translateX, translateY });
    },
    [isDragging, setTranslate, startPoint, startTranslate]
  );
  const dragEnd = useCallback(() => {
    setStartPoint(undefined);
    setStartTranslate(undefined);
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback(
    (event: ReactWheelEvent | WheelEvent) => {
      event.preventDefault();
      const point = localPoint(event as LocalPointEvent) || undefined;
      const { scaleX, scaleY } = wheelDelta(event);
      scale({ scaleX, scaleY, point });
    },
    [scale, wheelDelta]
  );

  const handlePinch = useCallback(
    (state: PinchHandlerState) => {
      const {
        origin: [ox, oy],
        memo,
      } = state;
      let currentMemo = memo;
      if (containerRef.current) {
        const { top, left } =
          currentMemo ?? containerRef.current.getBoundingClientRect();
        if (!currentMemo) {
          currentMemo = { top, left };
        }
        const { scaleX, scaleY } = pinchDelta(state);
        scale({ scaleX, scaleY, point: { x: ox - left, y: oy - top } });
      }
      return currentMemo;
    },
    [scale, pinchDelta]
  );

  const toMatrixString = useCallback(
    () => matrixToString(transformMatrix),
    [transformMatrix]
  );
  const center = useCallback(() => {
    const centerPoint = { x: width / 2, y: height / 2 };
    const inverseCentroid = applyInverseToPoint(centerPoint);
    translate({
      translateX: inverseCentroid.x - centerPoint.x,
      translateY: inverseCentroid.y - centerPoint.y,
    });
  }, [height, width, applyInverseToPoint, translate]);
  const clear = useCallback(() => {
    setTransformMatrix(identityMatrix());
  }, [setTransformMatrix]);

  // use-gesture applies the latest render's handlers during render.
  const api = { dragStart, dragMove, dragEnd, handleWheel, handlePinch };
  const apiRef = useRef(api);
  useLayoutEffect(() => {
    apiRef.current = { dragStart, dragMove, dragEnd, handleWheel, handlePinch };
  }, [dragStart, dragMove, dragEnd, handleWheel, handlePinch]);

  // --- gestures (use-gesture drag / wheel / pinch engines) ----------------

  const pointerIdsRef = useRef(new Set<number>());
  const dragRef = useRef<DragGesture | null>(null);
  const tapRef = useRef(false);
  /** use-gesture drag `state.last`: survives into the next gesture. */
  const dragLastRef = useRef(false);
  const pinchRef = useRef<PinchGesture>({
    active: false,
    source: null,
    offset: 1,
    lastOffset: 1,
    movement: 0,
    initialDistance: 0,
    origin: [0, 0],
    memo: undefined,
    pointers: new Map(),
  });
  const wheelPinchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cancelTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /** One pinch handler call (visx `handlePinch`); keeps its memo. */
  const emitPinch = useCallback(() => {
    const pinch = pinchRef.current;
    pinch.memo = apiRef.current.handlePinch({
      offset: [pinch.offset, 0],
      lastOffset: [pinch.lastOffset, 0],
      origin: pinch.origin,
      memo: pinch.memo,
    });
  }, []);

  const startPinch = useCallback((source: PinchGesture["source"]) => {
    const pinch = pinchRef.current;
    pinch.active = true;
    pinch.source = source;
    pinch.lastOffset = pinch.offset;
    pinch.movement = 0;
    pinch.memo = undefined;
  }, []);

  const endPinch = useCallback(() => {
    const pinch = pinchRef.current;
    pinch.active = false;
    pinch.source = null;
    emitPinch();
  }, [emitPinch]);

  /** use-gesture drag handler: onDragStart (first), onDrag, onDragEnd (last). */
  const emitDrag = useCallback(
    (event: PointerEvent, first: boolean, last: boolean) => {
      const handlers = apiRef.current;
      const drag = dragRef.current;
      if (first) {
        handlers.dragStart(event);
      }
      if (pinchRef.current.active) {
        // visx: `cancel(); dragEnd();`. The cancel re-emits on a timeout.
        if (drag?.active) {
          drag.active = false;
          drag.pointerActive = false;
          cancelTimerRef.current = setTimeout(() => {
            cancelTimerRef.current = null;
            dragLastRef.current = true;
            const latest = apiRef.current;
            if (pinchRef.current.active) {
              latest.dragEnd();
            } else if (drag.event) {
              latest.dragMove(drag.event);
            }
            latest.dragEnd();
          }, 0);
        }
        handlers.dragEnd();
      } else {
        handlers.dragMove(event);
      }
      if (last) {
        handlers.dragEnd();
      }
    },
    []
  );

  const dragPointerDown = useCallback((event: PointerEvent) => {
    const drag = dragRef.current;
    if (
      !(event.buttons == null || event.buttons === 1) ||
      (pointerIdsRef.current.size > 1 && drag?.pointerActive)
    ) {
      return;
    }
    // use-gesture resets `tap` when a drag starts.
    tapRef.current = false;
    dragRef.current = createDragGesture(event);
  }, []);

  const dragPointerMove = useCallback(
    (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!(drag?.pointerActive && event.pointerId === drag.pointerId)) {
        return;
      }
      const step = advanceDragGesture(drag, event.clientX, event.clientY);
      if (step === "none") {
        return;
      }
      drag.event = event;
      if (step === "first") {
        dragLastRef.current = false;
      }
      emitDrag(event, step === "first", false);
    },
    [emitDrag]
  );

  const dragPointerEnd = useCallback(
    (event: PointerEvent) => {
      const drag = dragRef.current;
      if (
        !(
          drag?.active &&
          drag.pointerActive &&
          event.pointerId === drag.pointerId
        )
      ) {
        return;
      }
      drag.pointerActive = false;
      drag.active = false;
      tapRef.current =
        drag.distance[0] <= DRAG_THRESHOLD_PX &&
        drag.distance[1] <= DRAG_THRESHOLD_PX;
      if (drag.started) {
        drag.event = event;
        dragLastRef.current = true;
        emitDrag(event, false, true);
      } else if (tapRef.current) {
        // A tap still reaches the handlers (filterTaps); `last` is whatever
        // the previous drag left, so a tap after a drag calls dragEnd.
        emitDrag(event, false, dragLastRef.current);
      }
    },
    [emitDrag]
  );

  const pinchPointerDown = useCallback(
    (event: PointerEvent) => {
      // Desktop Safari pinches through gesture events instead.
      if (supportsGestureEvents()) {
        return;
      }
      const pinch = pinchRef.current;
      const ids = pointerIdsRef.current;
      if (
        pinch.active &&
        Array.from(pinch.pointers.keys()).every((id) => ids.has(id))
      ) {
        return;
      }
      if (pinch.pointers.size < 2) {
        pinch.pointers.set(event.pointerId, {
          clientX: event.clientX,
          clientY: event.clientY,
        });
      }
      const payload = pinchPayload(pinch.pointers);
      if (!payload) {
        return;
      }
      if (!pinch.active) {
        startPinch("pointer");
      }
      pinch.initialDistance = payload.distance;
      pinch.origin = payload.origin;
      // Movement is 0 at the start, so offset === lastOffset (a 1.1 step).
      pinch.offset = pinch.lastOffset;
      emitPinch();
    },
    [emitPinch, startPinch]
  );

  const pinchPointerMove = useCallback(
    (event: PointerEvent) => {
      const pinch = pinchRef.current;
      if (!pinch.pointers.has(event.pointerId)) {
        return;
      }
      pinch.pointers.set(event.pointerId, {
        clientX: event.clientX,
        clientY: event.clientY,
      });
      const payload = pinchPayload(pinch.pointers);
      if (!(pinch.active && pinch.source === "pointer" && payload)) {
        return;
      }
      pinch.origin = payload.origin;
      const movement = payload.distance / pinch.initialDistance - 1;
      pinch.offset = (1 + movement) * pinch.lastOffset;
      emitPinch();
    },
    [emitPinch]
  );

  const pinchPointerEnd = useCallback(
    (event: PointerEvent) => {
      const pinch = pinchRef.current;
      if (!pinch.pointers.delete(event.pointerId)) {
        return;
      }
      if (
        pinch.active &&
        pinch.source === "pointer" &&
        pinch.pointers.size < 2
      ) {
        endPinch();
      }
    },
    [endPinch]
  );

  const handlePointerDown = useCallback(
    (event: PointerEvent) => {
      if (!(event.buttons == null || event.buttons % 2 === 1)) {
        return;
      }
      pointerIdsRef.current.add(event.pointerId);
      try {
        (event.target as Element).setPointerCapture(event.pointerId);
      } catch {
        // Not capturable (synthetic event).
      }
      dragPointerDown(event);
      pinchPointerDown(event);
    },
    [dragPointerDown, pinchPointerDown]
  );

  const handlePointerMove = useCallback(
    (event: PointerEvent) => {
      dragPointerMove(event);
      pinchPointerMove(event);
    },
    [dragPointerMove, pinchPointerMove]
  );

  const handlePointerEnd = useCallback(
    (event: PointerEvent) => {
      if (event.type === "pointerup" || event.type === "pointercancel") {
        pointerIdsRef.current.delete(event.pointerId);
      }
      const target = event.target as Element;
      try {
        if (target.hasPointerCapture?.(event.pointerId)) {
          target.releasePointerCapture(event.pointerId);
        }
      } catch {
        // Detached.
      }
      dragPointerEnd(event);
      pinchPointerEnd(event);
    },
    [dragPointerEnd, pinchPointerEnd]
  );

  const handleWheelEvent = useCallback(
    (event: WheelEvent) => {
      // use-gesture's wheel recogniser runs before the pinch one, so the first
      // ctrl+wheel of a pinch reaches both handlers in the same event.
      if (!pinchRef.current.active) {
        apiRef.current.handleWheel(event);
      }
      if (!event.ctrlKey) {
        return;
      }
      const pinch = pinchRef.current;
      if (!pinch.active) {
        startPinch("wheel");
      }
      if (event.cancelable) {
        event.preventDefault();
      }
      pinch.movement +=
        (-wheelDeltaYPixels(event) / PINCH_WHEEL_RATIO) * pinch.offset;
      pinch.origin = [event.clientX, event.clientY];
      pinch.offset = pinch.movement + pinch.lastOffset;
      emitPinch();
      if (wheelPinchTimerRef.current) {
        clearTimeout(wheelPinchTimerRef.current);
      }
      wheelPinchTimerRef.current = setTimeout(() => {
        wheelPinchTimerRef.current = null;
        if (pinchRef.current.active) {
          endPinch();
        }
      }, WHEEL_END_MS);
    },
    [emitPinch, endPinch, startPinch]
  );

  const handleGesture = useCallback(
    (event: Event) => {
      const gesture = event as Event & {
        scale: number;
        clientX: number;
        clientY: number;
      };
      const pinch = pinchRef.current;
      if (event.type === "gestureend") {
        if (pinch.active) {
          endPinch();
        }
        return;
      }
      if (event.cancelable) {
        event.preventDefault();
      }
      if (event.type === "gesturestart") {
        if (pinch.active) {
          return;
        }
        startPinch("gesture");
        pinch.origin = [gesture.clientX, gesture.clientY];
        pinch.offset = pinch.lastOffset;
        emitPinch();
        return;
      }
      if (!pinch.active) {
        return;
      }
      pinch.origin = [gesture.clientX, gesture.clientY];
      pinch.offset = (1 + (gesture.scale - 1)) * pinch.lastOffset;
      emitPinch();
    },
    [emitPinch, endPinch, startPinch]
  );

  const handleClickCapture = useCallback((event: MouseEvent) => {
    if (!tapRef.current && event.detail > 0) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, []);

  // Bind native (non-passive) listeners to the container; rebind if the
  // element is replaced.
  const handlersRef = useRef({
    handlePointerDown,
    handlePointerMove,
    handlePointerEnd,
    handleWheelEvent,
    handleGesture,
    handleClickCapture,
  });
  const boundRef = useRef<{ element: E; cleanup: () => void } | null>(null);
  useEffect(() => {
    const element = containerRef.current;
    if (boundRef.current?.element === element) {
      return;
    }
    boundRef.current?.cleanup();
    boundRef.current = null;
    if (!element) {
      return;
    }
    const handlers = handlersRef.current;
    const types = [
      "pointerdown",
      "pointermove",
      "pointerup",
      "pointercancel",
      "lostpointercapture",
      "wheel",
      ...(supportsGestureEvents()
        ? ["gesturestart", "gesturechange", "gestureend"]
        : []),
    ];
    const listener = (event: Event) => {
      if (event.type === "pointerdown") {
        handlers.handlePointerDown(event as PointerEvent);
      } else if (event.type === "pointermove") {
        handlers.handlePointerMove(event as PointerEvent);
      } else if (event.type === "wheel") {
        handlers.handleWheelEvent(event as WheelEvent);
      } else if (event.type.startsWith("gesture")) {
        handlers.handleGesture(event);
      } else {
        handlers.handlePointerEnd(event as PointerEvent);
      }
    };
    const clickListener = (event: Event) =>
      handlers.handleClickCapture(event as MouseEvent);
    for (const type of types) {
      element.addEventListener(type, listener, { passive: false });
    }
    element.addEventListener("click", clickListener, {
      capture: true,
      passive: false,
    });
    boundRef.current = {
      element,
      cleanup: () => {
        for (const type of types) {
          element.removeEventListener(type, listener);
        }
        element.removeEventListener("click", clickListener, true);
      },
    };
  });
  useEffect(
    () => () => {
      boundRef.current?.cleanup();
      boundRef.current = null;
      for (const timer of [wheelPinchTimerRef, cancelTimerRef]) {
        if (timer.current) {
          clearTimeout(timer.current);
        }
      }
    },
    []
  );

  // A fresh object every render, like visx's `zoom`.
  return {
    initialTransformMatrix,
    transformMatrix,
    isDragging,
    center,
    clear,
    scale,
    translate,
    translateTo,
    setTranslate,
    setTransformMatrix,
    reset,
    handleWheel,
    dragEnd,
    dragMove,
    dragStart,
    toString: toMatrixString,
    invert,
    toStringInvert,
    applyToPoint,
    applyInverseToPoint,
    containerRef,
  };
}

"use client";

/** Cursor y published by `ChartCrosshair`, read by the matching `YAxis`. */
export interface CrosshairYState {
  /** Plot-relative y of the cursor. */
  y: number;
  /** Normalised `yAxisId` the value pill sits on. */
  axisId: string;
}

interface CrosshairStore {
  state: CrosshairYState | null;
  listeners: Set<() => void>;
}

// Keyed by chart container: `ChartCrosshair` and `YAxis` are siblings with no
// shared provider, but both portal into the same container element.
const stores = new WeakMap<HTMLElement, CrosshairStore>();

function getStore(container: HTMLElement): CrosshairStore {
  let store = stores.get(container);
  if (!store) {
    store = { state: null, listeners: new Set() };
    stores.set(container, store);
  }
  return store;
}

export function setCrosshairY(
  container: HTMLElement,
  state: CrosshairYState | null
) {
  const store = getStore(container);
  const prev = store.state;
  if (
    prev === state ||
    (prev && state && prev.y === state.y && prev.axisId === state.axisId)
  ) {
    return;
  }
  store.state = state;
  for (const listener of store.listeners) {
    listener();
  }
}

/**
 * Listen to crosshair moves without React: the listener runs synchronously in
 * the pointer handler, so write to the DOM there instead of setting state.
 * Called once on subscribe with the current state.
 */
export function subscribeCrosshair(
  container: HTMLElement,
  listener: (state: CrosshairYState | null) => void
): () => void {
  const store = getStore(container);
  const notify = () => listener(store.state);
  store.listeners.add(notify);
  notify();
  return () => {
    store.listeners.delete(notify);
  };
}

/** Fade zone (px) beyond the pill edge — matches the x-axis date ticker. */
const TICK_FADE_BUFFER = 20;

/**
 * Tick label opacity under the crosshair value pill: hidden beneath it,
 * fading back in over {@link TICK_FADE_BUFFER} px — the y-axis twin of the
 * x-axis date-ticker fade.
 */
export function crosshairTickOpacity(
  state: CrosshairYState | null,
  axisId: string,
  tickY: number,
  pillHalfHeight: number
): number {
  if (!state || state.axisId !== axisId) {
    return 1;
  }
  const distance = Math.abs(tickY - state.y);
  if (distance < pillHalfHeight) {
    return 0;
  }
  if (distance < pillHalfHeight + TICK_FADE_BUFFER) {
    return (distance - pillHalfHeight) / TICK_FADE_BUFFER;
  }
  return 1;
}

"use client";

import { useId } from "react";

export interface DashTailStrokeProps {
  /** SVG path `d` for the full series (single curved path). */
  pathD: string | null;
  /** Total length of `pathD` in user units. */
  pathLength: number;
  /** Path length at which the dashed tail begins. */
  dashStartLength: number;
  /** X coordinate (chart inner space) where the tail clip begins. */
  dashStartX: number;
  innerWidth: number;
  innerHeight: number;
  /** Stroke paint — solid color or gradient url. */
  stroke: string;
  strokeWidth: number;
  dashArray: string;
}

export function DashTailStroke({
  pathD,
  pathLength,
  dashStartLength,
  dashStartX,
  innerWidth,
  innerHeight,
  stroke,
  strokeWidth,
  dashArray,
}: DashTailStrokeProps) {
  const clipPathId = useId().replace(/:/g, "");

  if (!pathD || pathLength <= 0 || dashStartLength >= pathLength) {
    return null;
  }

  const pad = strokeWidth * 2;
  const tailWidth = Math.max(0, innerWidth - dashStartX + pad);

  return (
    <>
      <defs>
        <clipPath id={clipPathId}>
          <rect
            height={innerHeight + pad}
            width={tailWidth}
            x={dashStartX - strokeWidth}
            y={-strokeWidth}
          />
        </clipPath>
      </defs>
      {/* Solid head — same curved path, gradient/fade preserved */}
      <path
        d={pathD}
        fill="none"
        stroke={stroke}
        strokeDasharray={`${dashStartLength} ${Math.max(1, pathLength - dashStartLength)}`}
        strokeLinecap="round"
        strokeWidth={strokeWidth}
      />
      {/* Dashed tail — clipped to x ≥ dashStartX so dashes follow the curve */}
      <path
        clipPath={`url(#${clipPathId})`}
        d={pathD}
        fill="none"
        stroke={stroke}
        strokeDasharray={dashArray}
        strokeLinecap="round"
        strokeWidth={strokeWidth}
      />
    </>
  );
}

"use client";

import { useCallback, useSyncExternalStore } from "react";

/**
 * Whether a `ChartTooltip` date pill is mounted in a chart. `XAxis` reads it
 * to pick its hover effect: fade the labels the pill covers, or (with no
 * pill) highlight the labels near the crosshair instead.
 */
interface DatePillStore {
  /** Mounted tooltips with an enabled date pill. */
  count: number;
  listeners: Set<() => void>;
}

// Keyed by chart container: `ChartTooltip` and `XAxis` are siblings with no
// shared provider, but both portal into the same container element.
const stores = new WeakMap<HTMLElement, DatePillStore>();

function getStore(container: HTMLElement): DatePillStore {
  let store = stores.get(container);
  if (!store) {
    store = { count: 0, listeners: new Set() };
    stores.set(container, store);
  }
  return store;
}

/** Marks a date pill as present until the returned cleanup runs. */
export function registerDatePill(container: HTMLElement): () => void {
  const store = getStore(container);
  store.count += 1;
  for (const listener of store.listeners) {
    listener();
  }
  return () => {
    store.count -= 1;
    for (const listener of store.listeners) {
      listener();
    }
  };
}

const noopUnsubscribe = () => undefined;
const serverSnapshot = () => false;

/** `true` while any `ChartTooltip` in `container` shows a date pill. */
export function useDatePillPresent(container: HTMLElement | null): boolean {
  const subscribe = useCallback(
    (listener: () => void) => {
      if (!container) {
        return noopUnsubscribe;
      }
      const store = getStore(container);
      store.listeners.add(listener);
      return () => {
        store.listeners.delete(listener);
      };
    },
    [container]
  );
  const getSnapshot = useCallback(
    () => (container ? getStore(container).count > 0 : false),
    [container]
  );
  return useSyncExternalStore(subscribe, getSnapshot, serverSnapshot);
}

/**
 * Largest-Triangle-Three-Buckets downsampling for time-series SVG paths.
 * Keeps first/last points and picks visually significant points per bucket.
 */
export function decimateTimeSeries<T extends Record<string, unknown>>(
  data: T[],
  maxPoints: number,
  valueKeys: string[] = []
): T[] {
  const len = data.length;
  if (maxPoints >= len || maxPoints < 3) {
    return data;
  }

  const getY = (point: T, index: number): number => {
    if (valueKeys.length === 0) {
      for (const val of Object.values(point)) {
        if (typeof val === "number") {
          return val;
        }
      }
      return index;
    }

    let sum = 0;
    let count = 0;
    for (const key of valueKeys) {
      const val = point[key];
      if (typeof val === "number") {
        sum += val;
        count++;
      }
    }
    return count > 0 ? sum / count : index;
  };

  const sampled: T[] = [data[0] as T];
  const bucketSize = (len - 2) / (maxPoints - 2);
  let previousIndex = 0;

  for (let i = 0; i < maxPoints - 2; i++) {
    const rangeStart = Math.floor((i + 1) * bucketSize) + 1;
    const rangeEnd = Math.min(Math.floor((i + 2) * bucketSize) + 1, len - 1);

    const nextRangeStart = Math.floor((i + 2) * bucketSize) + 1;
    const nextRangeEnd = Math.min(Math.floor((i + 3) * bucketSize) + 1, len);
    const nextCount = Math.max(0, nextRangeEnd - nextRangeStart);

    let avgX = len - 1;
    let avgY = getY(data[len - 1] as T, len - 1);
    if (nextCount > 0) {
      avgX = 0;
      avgY = 0;
      for (let j = nextRangeStart; j < nextRangeEnd; j++) {
        avgX += j;
        avgY += getY(data[j] as T, j);
      }
      avgX /= nextCount;
      avgY /= nextCount;
    }

    const pointA = data[previousIndex] as T;
    const ax = previousIndex;
    const ay = getY(pointA, previousIndex);

    let maxArea = -1;
    let maxIndex = rangeStart;

    for (let j = rangeStart; j < rangeEnd; j++) {
      const area =
        Math.abs(
          (ax - avgX) * (getY(data[j] as T, j) - ay) - (ax - j) * (avgY - ay)
        ) * 0.5;
      if (area > maxArea) {
        maxArea = area;
        maxIndex = j;
      }
    }

    sampled.push(data[maxIndex] as T);
    previousIndex = maxIndex;
  }

  sampled.push(data[len - 1] as T);
  return sampled;
}

/** ~1.5 points per pixel — enough for crisp curves without over-drawing. */
export function maxRenderPointsForWidth(innerWidth: number): number {
  return Math.max(64, Math.ceil(innerWidth * 1.5));
}

/** Bucket OHLC rows into fewer candles while preserving high/low extremes. */
export function decimateOhlcData<T extends Record<string, unknown>>(
  data: T[],
  maxPoints: number
): T[] {
  const len = data.length;
  if (maxPoints >= len || maxPoints < 2) {
    return data;
  }

  const bucketSize = len / maxPoints;
  const sampled: T[] = [];

  for (let i = 0; i < maxPoints; i++) {
    const start = Math.floor(i * bucketSize);
    const end = Math.min(len, Math.floor((i + 1) * bucketSize));
    if (start >= end) {
      continue;
    }

    const bucket = data.slice(start, end);
    const first = bucket[0] as T;
    const last = bucket.at(-1) as T;

    let high = Number.NEGATIVE_INFINITY;
    let low = Number.POSITIVE_INFINITY;
    for (const row of bucket) {
      const rowHigh = row.high;
      const rowLow = row.low;
      if (typeof rowHigh === "number" && rowHigh > high) {
        high = rowHigh;
      }
      if (typeof rowLow === "number" && rowLow < low) {
        low = rowLow;
      }
    }

    sampled.push({
      ...last,
      open: first.open,
      high: Number.isFinite(high) ? high : last.high,
      low: Number.isFinite(low) ? low : last.low,
      close: last.close,
    } as T);
  }

  return sampled;
}

/**
 * Which side(s) of a series should fade to transparent at the chart edges.
 * - `true`  → fade both edges (default for `<Line>`)
 * - `false` → no fade (default for `<Area>`)
 * - `"left"` / `"right"` → fade only that side
 * - `{ left, right }` → fade zone per side, as % of the plot width (0–50);
 *   `0` or omitted means that side doesn't fade
 */
export type FadeEdges =
  | boolean
  | "left"
  | "right"
  | { left?: number; right?: number };

export interface FadeSides {
  /** Whether the left edge should fade out. */
  left: boolean;
  /** Whether the right edge should fade out. */
  right: boolean;
  /** True if either side fades — use to gate gradient/mask defs. */
  any: boolean;
  /** Left fade zone, % of the plot width. */
  leftLength: number;
  /** Right fade zone, % of the plot width. */
  rightLength: number;
}

/** Default fade zone per faded side, as % of the plot width. */
export const DEFAULT_FADE_EDGES_LENGTH = 15;

/** Clamp a fade zone length (% per side) to 0–50. */
export function clampFadeEdgesLength(length: number): number {
  return Math.min(50, Math.max(0, length));
}

function fadeSides(leftLength: number, rightLength: number): FadeSides {
  const l = clampFadeEdgesLength(leftLength);
  const r = clampFadeEdgesLength(rightLength);
  return {
    left: l > 0,
    right: r > 0,
    any: l > 0 || r > 0,
    leftLength: l,
    rightLength: r,
  };
}

export function resolveFadeSides(fade: FadeEdges): FadeSides {
  const d = DEFAULT_FADE_EDGES_LENGTH;
  if (fade === false) {
    return fadeSides(0, 0);
  }
  if (fade === "left") {
    return fadeSides(d, 0);
  }
  if (fade === "right") {
    return fadeSides(0, d);
  }
  if (typeof fade === "object" && fade !== null) {
    return fadeSides(fade.left ?? 0, fade.right ?? 0);
  }
  return fadeSides(d, d);
}

export interface FadeGradientStop {
  offset: string;
  opacity: number;
}

/**
 * Stops for a horizontal fade gradient with opacity 0 at the faded side(s)
 * and opacity 1 in the middle, using each side's fade zone (default 15% →
 * the historic 0/15/85/100 pattern).
 */
export function fadeGradientStops(sides: FadeSides): FadeGradientStop[] {
  return dedupeStops([
    { offset: "0%", opacity: sides.left ? 0 : 1 },
    { offset: `${sides.left ? sides.leftLength : 0}%`, opacity: 1 },
    { offset: `${100 - (sides.right ? sides.rightLength : 0)}%`, opacity: 1 },
    { offset: "100%", opacity: sides.right ? 0 : 1 },
  ]);
}

/**
 * Drop a stop that repeats the previous offset with the same opacity (a 0%
 * fade zone) — keeps offsets unique, so they're safe as React keys.
 */
function dedupeStops<T extends { offset: string | number; opacity: number }>(
  stops: T[]
): T[] {
  return stops.filter(
    (stop, i) =>
      i === 0 ||
      stop.offset !== stops[i - 1]?.offset ||
      stop.opacity !== stops[i - 1]?.opacity
  );
}

/**
 * Vertical (top → baseline) opacity stops for an area fill. With `fadeBottom`
 * (% of the area height, 0–100) the fill holds `topOpacity` and then fades to
 * 0 over the bottom `fadeBottom`%. Without it, the legacy `gradientToOpacity`
 * / `gradientSpan` gradient applies.
 */
export function areaVerticalFadeStops({
  topOpacity,
  fadeBottom,
  gradientToOpacity,
  gradientSpan = 1,
}: {
  topOpacity: number;
  fadeBottom?: number;
  gradientToOpacity: number;
  gradientSpan?: number;
}): { offset: number; opacity: number }[] {
  if (fadeBottom !== undefined) {
    const zone = Math.min(100, Math.max(0, fadeBottom)) / 100;
    if (zone <= 0) {
      return [
        { offset: 0, opacity: topOpacity },
        { offset: 1, opacity: topOpacity },
      ];
    }
    return dedupeStops([
      { offset: 0, opacity: topOpacity },
      { offset: 1 - zone, opacity: topOpacity },
      { offset: 1, opacity: 0 },
    ]);
  }
  const span = Math.min(1, Math.max(0.01, gradientSpan));
  const stops = [
    { offset: 0, opacity: topOpacity },
    { offset: span, opacity: gradientToOpacity },
  ];
  if (span < 1) {
    stops.push({ offset: 1, opacity: gradientToOpacity });
  }
  return stops;
}

/** A colour stop on a horizontal stroke gradient. `offset` is 0–1 across the plot. */
export interface StrokeGradientStop {
  offset: number;
  color: string;
}

/**
 * Horizontal stroke colours, left → right across the plot. Plain colours are
 * spaced evenly; pass `{ offset, color }` stops for explicit positions.
 */
export type StrokeGradient = readonly string[] | readonly StrokeGradientStop[];

export interface PaintGradientStop {
  offset: string;
  color: string;
  opacity: number;
}

export function resolveStrokeGradientStops(
  gradient: StrokeGradient | undefined
): StrokeGradientStop[] | null {
  if (!gradient || gradient.length === 0) {
    return null;
  }
  const last = Math.max(1, gradient.length - 1);
  return gradient
    .map((stop, index) =>
      typeof stop === "string"
        ? { offset: gradient.length === 1 ? 0 : index / last, color: stop }
        : {
            offset: Math.min(1, Math.max(0, stop.offset)),
            color: stop.color,
          }
    )
    .sort((a, b) => a.offset - b.offset);
}

function percentToFraction(offset: string): number {
  return Number.parseFloat(offset) / 100;
}

function roundPercent(value: number): number {
  return Math.round(value * 10_000) / 100;
}

/** Colour at `t` on piecewise-linear stops (sRGB, matching SVG gradient interpolation). */
function colorAt(stops: StrokeGradientStop[], t: number): string {
  const first = stops[0] as StrokeGradientStop;
  const last = stops.at(-1) as StrokeGradientStop;
  if (t <= first.offset) {
    return first.color;
  }
  if (t >= last.offset) {
    return last.color;
  }
  for (let i = 1; i < stops.length; i++) {
    const b = stops[i] as StrokeGradientStop;
    if (t > b.offset) {
      continue;
    }
    const a = stops[i - 1] as StrokeGradientStop;
    if (t === b.offset || b.offset === a.offset) {
      return b.color;
    }
    const mix = roundPercent((t - a.offset) / (b.offset - a.offset));
    return `color-mix(in srgb, ${b.color} ${mix}%, ${a.color})`;
  }
  return last.color;
}

function opacityAt(stops: FadeGradientStop[], t: number): number {
  let prev = stops[0] as FadeGradientStop;
  for (const stop of stops) {
    const offset = percentToFraction(stop.offset);
    const prevOffset = percentToFraction(prev.offset);
    if (t <= offset) {
      if (offset === prevOffset) {
        return stop.opacity;
      }
      const progress = (t - prevOffset) / (offset - prevOffset);
      return prev.opacity + (stop.opacity - prev.opacity) * progress;
    }
    prev = stop;
  }
  return prev.opacity;
}

/**
 * Stops for a horizontal stroke paint that combines a colour gradient with the
 * edge-fade opacity stops. Either input may be absent; offsets are merged so
 * the colour ramp and the fade compose instead of replacing each other.
 */
export function horizontalPaintStops({
  color,
  colorStops,
  fadeStops,
}: {
  /** Solid colour used when there is no colour gradient. */
  color: string;
  colorStops: StrokeGradientStop[] | null;
  fadeStops: FadeGradientStop[] | null;
}): PaintGradientStop[] {
  const offsets = new Set<number>();
  for (const stop of colorStops ?? []) {
    offsets.add(stop.offset);
  }
  for (const stop of fadeStops ?? []) {
    offsets.add(percentToFraction(stop.offset));
  }
  if (offsets.size === 0) {
    offsets.add(0);
  }
  return [...offsets]
    .sort((a, b) => a - b)
    .map((t) => ({
      offset: `${roundPercent(t)}%`,
      color: colorStops ? colorAt(colorStops, t) : color,
      opacity: fadeStops ? opacityAt(fadeStops, t) : 1,
    }));
}

/** Horizontal fade gradient pinned to the chart viewport (not the series path bounds). */
export function viewportFadeGradientAttrs(innerWidth: number) {
  return {
    gradientUnits: "userSpaceOnUse" as const,
    x1: 0,
    x2: innerWidth,
    y1: 0,
    y2: 0,
  };
}

import type { Area, Line } from "d3-shape";

/**
 * Formats like d3-path's `appendRound(3)`: `String(Math.round(v * 1000) / 1000)`.
 * Builds the decimal from the rounded integer instead of formatting a
 * fractional double, which is the bulk of the cost of a long path `d`.
 * For |v| below 1e9 the result is identical: a decimal with at most 12
 * significant digits is the shortest round-trip form of its double.
 */
function formatCoordinate(value: number): string {
  const scaled = Math.round(value * 1000);
  if (!(scaled > -1e12 && scaled < 1e12)) {
    // NaN, ±Infinity and huge values: keep d3's exact formatting.
    return String(scaled / 1000);
  }
  if (scaled === 0) {
    return "0";
  }
  const negative = scaled < 0;
  const abs = negative ? -scaled : scaled;
  const whole = Math.floor(abs / 1000);
  const fraction = abs - whole * 1000;
  const head = negative ? `-${whole}` : `${whole}`;
  if (fraction === 0) {
    return head;
  }
  if (fraction % 100 === 0) {
    return `${head}.${fraction / 100}`;
  }
  if (fraction % 10 === 0) {
    return `${head}.${fraction < 100 ? "0" : ""}${fraction / 10}`;
  }
  let pad = "";
  if (fraction < 10) {
    pad = "00";
  } else if (fraction < 100) {
    pad = "0";
  }
  return `${head}.${pad}${fraction}`;
}

/**
 * Path context for d3 shape generators that emits the same `d` string as
 * d3-path with 3 digits (d3-shape's default), but faster. Curves only call
 * moveTo / lineTo / bezierCurveTo / quadraticCurveTo / closePath; anything
 * else marks the result unsupported so the caller falls back to d3-path.
 */
class FastPath {
  d = "";
  unsupported = false;
  private open = false;

  moveTo(x: number, y: number) {
    this.d += `M${formatCoordinate(+x)},${formatCoordinate(+y)}`;
    this.open = true;
  }

  lineTo(x: number, y: number) {
    this.d += `L${formatCoordinate(+x)},${formatCoordinate(+y)}`;
    this.open = true;
  }

  closePath() {
    if (this.open) {
      this.d += "Z";
    }
  }

  quadraticCurveTo(x1: number, y1: number, x: number, y: number) {
    this.d += `Q${formatCoordinate(+x1)},${formatCoordinate(+y1)},${formatCoordinate(+x)},${formatCoordinate(+y)}`;
    this.open = true;
  }

  bezierCurveTo(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    x: number,
    y: number
  ) {
    this.d += `C${formatCoordinate(+x1)},${formatCoordinate(+y1)},${formatCoordinate(+x2)},${formatCoordinate(+y2)},${formatCoordinate(+x)},${formatCoordinate(+y)}`;
    this.open = true;
  }

  arcTo() {
    this.unsupported = true;
  }

  arc() {
    this.unsupported = true;
  }

  rect() {
    this.unsupported = true;
  }
}

type Generator<Datum> = Line<Datum> | Area<Datum>;

/**
 * `generator(data) || ""` for a d3 `line()` / `area()` that uses the default
 * 3-digit rounding and no context of its own — same string, built faster.
 */
export function fastShapePath<Datum>(
  generator: Generator<Datum>,
  data: Datum[]
): string {
  const context = new FastPath();
  // The path context type is a CanvasRenderingContext2D-like interface;
  // FastPath implements the subset d3 shapes call.
  generator.context(context as unknown as CanvasRenderingContext2D);
  (generator as (data: Datum[]) => unknown)(data);
  generator.context(null);
  if (context.unsupported) {
    return ((generator as (data: Datum[]) => string | null)(data) ?? "") || "";
  }
  return context.d;
}

export function filterDataByXDomain(
  data: Record<string, unknown>[],
  xDomain: [Date, Date],
  xAccessor: (d: Record<string, unknown>) => Date
): Record<string, unknown>[] {
  const start = xDomain[0].getTime();
  const end = xDomain[1].getTime();
  const minTime = Math.min(start, end);
  const maxTime = Math.max(start, end);

  return data.filter((d) => {
    const time = xAccessor(d).getTime();
    return time >= minTime && time <= maxTime;
  });
}

export function resolveDataXExtent(
  data: Record<string, unknown>[],
  xAccessor: (d: Record<string, unknown>) => Date
): [Date, Date] | null {
  if (data.length === 0) {
    return null;
  }

  let minTime = Number.POSITIVE_INFINITY;
  let maxTime = Number.NEGATIVE_INFINITY;

  for (const point of data) {
    const time = xAccessor(point).getTime();
    if (time < minTime) {
      minTime = time;
    }
    if (time > maxTime) {
      maxTime = time;
    }
  }

  if (minTime === Number.POSITIVE_INFINITY) {
    return null;
  }

  return [new Date(minTime), new Date(maxTime)];
}

/** Brush track extent — optionally extends past the last data row (e.g. projections). */
export function resolveBrushTrackXExtent(
  data: Record<string, unknown>[],
  xAccessor: (d: Record<string, unknown>) => Date,
  xExtentMax?: Date
): [Date, Date] | null {
  const extent = resolveDataXExtent(data, xAccessor);
  if (!extent) {
    return null;
  }
  if (!xExtentMax || xExtentMax.getTime() <= extent[1].getTime()) {
    return extent;
  }
  return [extent[0], xExtentMax];
}

const DEFAULT_SKELETON_DATA_KEY = "value";
const DEFAULT_SKELETON_POINT_COUNT = 7;

export interface GenerateChartSkeletonDataOptions {
  /** Key used for y values in each row. Default: `"value"`. */
  dataKey?: string;
  /** Number of points. Default: 7. */
  pointCount?: number;
  /** Start date for the x axis. Default: 2025-01-01. */
  baseDate?: Date;
}

/** Placeholder series used while `status="loading"` and data is empty. */
export function generateChartSkeletonData(
  options: GenerateChartSkeletonDataOptions = {}
): Record<string, unknown>[] {
  const dataKey = options.dataKey ?? DEFAULT_SKELETON_DATA_KEY;
  const pointCount = options.pointCount ?? DEFAULT_SKELETON_POINT_COUNT;
  const baseDate = options.baseDate ?? new Date("2025-01-01");

  return Array.from({ length: pointCount }, (_, index) => {
    const date = new Date(baseDate);
    date.setDate(baseDate.getDate() + index);
    return {
      date,
      [dataKey]: Math.round(110 + Math.sin(index * 1.15) * 36 + index * 9),
    };
  });
}

/** Skeleton rows that mirror target dates/count with lower magnitudes for Y tween. */
export function generateChartSkeletonFromTarget(
  targetData: Record<string, unknown>[],
  dataKey: string
): Record<string, unknown>[] {
  return targetData.map((row, index) => ({
    ...row,
    [dataKey]: Math.round(95 + Math.sin(index * 1.05) * 28 + index * 7),
  }));
}

export { DEFAULT_SKELETON_DATA_KEY, DEFAULT_SKELETON_POINT_COUNT };

import type { CSSProperties, ReactElement, SVGProps } from "react";

/**
 * Grid rows / columns that render what `@visx/grid` 4.0.0 `GridRows` and
 * `GridColumns` did (minus the `visx-group` / `visx-rows` / `visx-columns` /
 * `visx-line` classes), so charts keep identical markup without the dep.
 */

/** Any scale a grid can read: d3 linear / time / band / point. */
export interface GridScale<Value> {
  (value: Value): number | { valueOf(): number } | undefined;
  domain(): Value[];
  ticks?: (count?: number) => Value[];
  bandwidth?: () => number;
}

/**
 * Tick values the way visx resolves them: explicit `tickValues`, else
 * `scale.ticks(numTicks)`, else the domain thinned to about `numTicks`
 * entries (every `round((n - 1) / numTicks)`-th value) when it is longer.
 */
export function gridTickValues<Value>(
  scale: GridScale<Value>,
  numTicks: number | undefined = 10,
  tickValues?: Value[]
): Value[] {
  if (tickValues) {
    return tickValues;
  }
  if ("ticks" in scale && scale.ticks) {
    return scale.ticks(numTicks);
  }
  return scale
    .domain()
    .filter(
      (_, index, all) =>
        numTicks == null ||
        all.length <= numTicks ||
        index % Math.round((all.length - 1) / numTicks) === 0
    );
}

/**
 * Pixel position of each grid line: `scale(tick)` (0 when unmapped) plus
 * `offset` plus half the band for band scales (visx `getScaleBandwidth`).
 */
export function gridLinePositions<Value>(
  scale: GridScale<Value>,
  {
    numTicks,
    offset,
    tickValues,
  }: { numTicks?: number; offset?: number; tickValues?: Value[] } = {}
): number[] {
  const bandOffset =
    "bandwidth" in scale && scale.bandwidth ? scale.bandwidth() / 2 : 0;
  const scaleOffset = (offset ?? 0) + bandOffset;
  return gridTickValues(scale, numTicks, tickValues).map((tick) => {
    const mapped = scale(tick);
    const value =
      mapped != null && typeof mapped === "object" ? mapped.valueOf() : mapped;
    return (value ?? 0) + scaleOffset;
  });
}

type GridLineSvgProps = Omit<
  SVGProps<SVGLineElement>,
  "x1" | "x2" | "y1" | "y2" | "ref" | "scale" | "offset" | "className"
>;

interface GridLinesBaseProps<Value> extends GridLineSvgProps {
  scale: GridScale<Value>;
  /** Group offsets (`translate(left, top)`). Default: 0 */
  top?: number;
  left?: number;
  /** Class on the wrapping `<g>`. */
  className?: string;
  /** Default: 10 (ignored when `tickValues` is set). */
  numTicks?: number;
  tickValues?: Value[];
  /** Extra pixel offset added to every line. */
  offset?: number;
  lineStyle?: CSSProperties;
  /** Default: `#eaf0f6` (visx). */
  stroke?: string;
  /** Default: 1 */
  strokeWidth?: string | number;
  strokeDasharray?: string;
}

export interface GridRowsProps<Value> extends GridLinesBaseProps<Value> {
  /** Line length. */
  width: number;
}

export interface GridColumnsProps<Value> extends GridLinesBaseProps<Value> {
  /** Line length. */
  height: number;
}

/** visx `Line` attributes, in visx order; rest props come after. */
function gridLine(
  key: string,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  {
    stroke,
    strokeWidth,
    strokeDasharray,
    lineStyle,
    rest,
  }: {
    stroke: string;
    strokeWidth: string | number;
    strokeDasharray?: string;
    lineStyle?: CSSProperties;
    rest: GridLineSvgProps;
  }
) {
  const rectilinear = x1 === x2 || y1 === y2;
  // An object, not JSX attributes, so the formatter can't re-sort them.
  const props: SVGProps<SVGLineElement> = {
    x1,
    y1,
    x2,
    y2,
    fill: "transparent",
    shapeRendering: rectilinear ? "crispEdges" : "auto",
    stroke,
    strokeWidth,
    strokeDasharray,
    style: lineStyle,
    ...rest,
  };
  return <line key={key} {...props} />;
}

/**
 * The visx group wrapper (`translate(left, top)` + `className`), skipped when
 * it would be an identity transform with no class — one less node per grid.
 */
function wrapGridLines(
  lines: ReactElement[],
  { className, left, top }: { className?: string; left: number; top: number }
) {
  if (left === 0 && top === 0 && !className) {
    return <>{lines}</>;
  }
  return (
    <g className={className} transform={`translate(${left}, ${top})`}>
      {lines}
    </g>
  );
}

export function GridRows<Value>({
  top = 0,
  left = 0,
  scale,
  width,
  stroke = "#eaf0f6",
  strokeWidth = 1,
  strokeDasharray,
  className,
  numTicks = 10,
  lineStyle,
  offset,
  tickValues,
  ...rest
}: GridRowsProps<Value>) {
  const positions = gridLinePositions(scale, { numTicks, offset, tickValues });
  const lines = positions.map((y, index) =>
    gridLine(`row-line-${index}`, 0, y, width, y, {
      stroke,
      strokeWidth,
      strokeDasharray,
      lineStyle,
      rest,
    })
  );
  return wrapGridLines(lines, { className, left, top });
}

export function GridColumns<Value>({
  top = 0,
  left = 0,
  scale,
  height,
  stroke = "#eaf0f6",
  strokeWidth = 1,
  strokeDasharray,
  className,
  numTicks = 10,
  lineStyle,
  offset,
  tickValues,
  ...rest
}: GridColumnsProps<Value>) {
  const positions = gridLinePositions(scale, { numTicks, offset, tickValues });
  const lines = positions.map((x, index) =>
    gridLine(`column-line-${index}`, x, 0, x, height, {
      stroke,
      strokeWidth,
      strokeDasharray,
      lineStyle,
      rest,
    })
  );
  return wrapGridLines(lines, { className, left, top });
}

"use client";

import { m } from "motion/react";
