   * Useful for projecting incomplete periods, e.g. dashed from yesterday through today.
   */
  dashFromIndex?: number;
  /** Dash pattern for the tail segment when `dashFromIndex` is set. Default: "6,4" */
  dashArray?: string;
  /**
   * Show the loading pulse overlay. Default: follows chart loading phase.
   * Set `false` to disable even during loading.
   */
  loading?: boolean;
  /** Stroke color for the loading pulse overlay. Default: var(--foreground) */
  loadingStroke?: string;
  /** Loading pulse stroke opacity. Default: 0.5 */
  loadingStrokeOpacity?: number;
  /** Override pulse animation mode (loop / exit / enter). */
  loadingPulseMode?: LineLoadingPulseMode;
  /** Called when a loop-mode pulse cycle completes. */
  onLoadingPulseCycleComplete?: () => void;
  /**
   * Loading animation while the chart is in loading status: the default
   * traveling `"pulse"`, or a diagonal `"sweep"` shimmer across the skeleton
   * line. Default: `"pulse"`.
   */
  loadingStyle?: LoadingStyle;
}

function LineSeriesStroke({
  animatedPathD,
  filter,
  pathRef,
  staticPathD,
  strokeOpacity,
  strokeWidth,
  drawAnimatedPath,
  visibleStroke,
}: {
  animatedPathD: string;
  filter?: string;
  pathRef?: RefObject<SVGPathElement | null>;
  /** `d` of the resting line (unused while `drawAnimatedPath`). */
  staticPathD: string;
  strokeOpacity?: number;
  strokeWidth: number;
  drawAnimatedPath: boolean;
  visibleStroke: string;
}) {
  if (drawAnimatedPath) {
    return (
      <path
        d={animatedPathD}
        fill="none"
        filter={filter}
        ref={pathRef}
        stroke={visibleStroke}
        strokeLinecap="round"
        strokeOpacity={strokeOpacity}
        strokeWidth={strokeWidth}
      />
    );
  }

  return (
    <LinePath
      d={staticPathD}
      filter={filter}
      innerRef={pathRef}
      stroke={visibleStroke}
      strokeLinecap="round"
      strokeOpacity={strokeOpacity}
      strokeWidth={strokeWidth}
    />
  );
}

// Memoised: a series re-render (data update, every morph frame) passes the
// same props, so the overlays and their children are skipped.
const LineLoadingOverlays = memo(function LineLoadingOverlays({
  curve,
  handleLoadingPulseComplete,
  innerWidth,
  loadingStroke,
  loadingStrokeOpacity,
  loadingStyle,
  pathD,
  pulseEpoch,
  pulseMode,
  showLoadingPulse,
  strokeWidth,
}: {
  curve: CurveFactory;
  handleLoadingPulseComplete: () => void;
  innerWidth: number;
  loadingStroke: string;
  loadingStrokeOpacity: number;
  loadingStyle: LoadingStyle;
  pathD: string | null;
  pulseEpoch: number;
  pulseMode: LineLoadingPulseMode | null;
  showLoadingPulse: boolean;
  strokeWidth: number;
}) {
  const sweepLoading =
    showLoadingPulse && innerWidth > 0 && loadingStyle === "sweep";
  const pulseLoading = showLoadingPulse && innerWidth > 0 && !sweepLoading;

  return (
    <>
      {sweepLoading ? (
        <LineLoadingSweep
          curve={curve}
          key="loading-sweep"
          mode={pulseMode ?? "loop"}
          onTransitionComplete={handleLoadingPulseComplete}
          stroke={loadingStroke}
          strokeOpacity={loadingStrokeOpacity}
          strokeWidth={strokeWidth}
        />
      ) : null}
      {pulseLoading && pathD ? (
        <LineLoadingPulseStroke
          key="loading-pulse"
          loopEpoch={pulseEpoch}
          mode={pulseMode ?? undefined}
          onCycleComplete={handleLoadingPulseComplete}
          pathD={pathD}
          stroke={loadingStroke}
          strokeOpacity={loadingStrokeOpacity}
          strokeWidth={strokeWidth}
        />
      ) : null}
    </>
  );
});

function resolveLineGlow(
  glow: boolean | LineGlow,
  strokeWidth: number
): Required<LineGlow> | null {
  if (!glow) {
    return null;
  }
  const options = glow === true ? {} : glow;
  return {
    blur: options.blur ?? DEFAULT_GLOW_BLUR,
    opacity: options.opacity ?? DEFAULT_GLOW_OPACITY,
    strokeWidth: options.strokeWidth ?? strokeWidth * 2,
  };
}

function GradientStops({ stops }: { stops: PaintGradientStop[] }) {
  return stops.map((stop) => (
    <stop
      key={stop.offset}
      offset={stop.offset}
      style={{ stopColor: stop.color, stopOpacity: stop.opacity }}
    />
  ));
}

/**
 * Resolved hover-highlight paint. The highlight re-strokes at full opacity, so
 * by default it keeps the line's colour ramp but not the edge fade;
 * `highlight.strokeGradient` / `.stroke` override the line's paint.
 */
function useLineHighlightPaint({
  colorStops,
  enabled,
  glowFilterId,
  gradientId,
  highlight,
  stroke,
  strokeWidth,
}: {
  colorStops: ReturnType<typeof resolveStrokeGradientStops>;
  enabled: boolean;
  glowFilterId: string;
  gradientId: string;
  highlight: LineHighlight | undefined;
  stroke: string;
  strokeWidth: number;
}) {
  const gradient = highlight?.strokeGradient;
  const color = highlight?.stroke;
  const stops = useMemo(() => {
    const ownStops = gradient ? resolveStrokeGradientStops(gradient) : null;
    if (ownStops) {
      return horizontalPaintStops({
        color: color ?? stroke,
        colorStops: ownStops,
        fadeStops: null,
      });
    }
    if (color || !colorStops) {
      return null;
    }
    return horizontalPaintStops({ color: stroke, colorStops, fadeStops: null });
  }, [colorStops, color, gradient, stroke]);
  const width = highlight?.strokeWidth ?? strokeWidth;
  const glow = resolveLineGlow(
    enabled ? (highlight?.glow ?? false) : false,
    width
  );
  return {
    stops,
    stroke: stops ? `url(#${gradientId})` : (color ?? stroke),
    strokeWidth: width,
    /** Filter def to render, or `null` when the segment has no glow. */
    glowFilter: glow ? { id: glowFilterId, blur: glow.blur } : null,
    /** `HighlightSegment` glow props. */
    segmentGlow: glow
      ? {
          filter: `url(#${glowFilterId})`,
          opacity: glow.opacity,
          strokeWidth: glow.strokeWidth,
        }
      : undefined,
    dimOpacity: highlight?.dimOpacity ?? DEFAULT_HIGHLIGHT_DIM_OPACITY,
  };
}

function GlowFilter({
  blur,
  id,
  innerHeight,
  innerWidth,
}: {
  blur: number;
  id: string;
  innerHeight: number;
  innerWidth: number;
}) {
  // Filter region in user space: a near-flat line has a thin bounding box, so
  // the default objectBoundingBox region would crop the blur vertically.
  const pad = blur * 3;
  return (
    <filter
      colorInterpolationFilters="sRGB"
      filterUnits="userSpaceOnUse"
      height={innerHeight + pad * 2}
      id={id}
      width={innerWidth + pad * 2}
      x={-pad}
      y={-pad}
    >
      <feGaussianBlur stdDeviation={blur} />
    </filter>
  );
}

// Memoised for the same reason as `LineLoadingOverlays`.
const LineStrokeDefs = memo(function LineStrokeDefs({
  glowBlur,
  glowFilterId,
  gradientId,
  highlightGlow,
  highlightGradientId,
  highlightStops,
  innerHeight,
  innerWidth,
  paintStops,
}: {
  glowBlur: number;
  glowFilterId: string | null;
  gradientId: string;
  highlightGlow: { id: string; blur: number } | null;
  highlightGradientId: string;
  highlightStops: PaintGradientStop[] | null;
  innerHeight: number;
  innerWidth: number;
  paintStops: PaintGradientStop[] | null;
}) {
  if (!(paintStops || highlightStops || glowFilterId || highlightGlow)) {
    return null;
  }
  return (
    <defs>
      {paintStops ? (
        <linearGradient
          id={gradientId}
          {...viewportFadeGradientAttrs(innerWidth)}
        >
          <GradientStops stops={paintStops} />
        </linearGradient>
      ) : null}
      {highlightStops ? (
        <linearGradient
          id={highlightGradientId}
          {...viewportFadeGradientAttrs(innerWidth)}
        >
          <GradientStops stops={highlightStops} />
        </linearGradient>
      ) : null}
      {glowFilterId ? (
        <GlowFilter
          blur={glowBlur}
          id={glowFilterId}
          innerHeight={innerHeight}
          innerWidth={innerWidth}
        />
      ) : null}
      {highlightGlow ? (
        <GlowFilter
          blur={highlightGlow.blur}
          id={highlightGlow.id}
          innerHeight={innerHeight}
          innerWidth={innerWidth}
        />
      ) : null}
    </defs>
  );
});

/** Loading pulse mode for the line, or `null` when no pulse shows. */
function resolveLinePulseMode(
  chartPhase: ChartPhase,
  loading: boolean | undefined,
  loadingPulseMode: LineLoadingPulseMode | undefined
): LineLoadingPulseMode | null {
  if (loading === false) {
    return null;
  }
  return (
    loadingPulseMode ??
    (loading === true ? "loop" : resolveLineLoadingPulseMode(chartPhase))
  );
}

export function Line({
  dataKey,
  yAxisId,
  stroke = chartCssVars.linePrimary,
  strokeWidth = 2.5,
  curve = curveNatural,
  animate = true,
  fadeEdges = true,
  strokeGradient,
  glow = false,
  showHighlight = true,
  highlight,
  showMarkers = false,
  markers,
  dashFromIndex,
  dashArray = "6,4",
  loading,
  loadingStroke = chartCssVars.foreground,
  loadingStrokeOpacity = 0.5,
  loadingPulseMode,
  onLoadingPulseCycleComplete,
  loadingStyle = "pulse",
}: LineProps) {
  // Stable slice only: hover state lives inside `<SeriesHoverDim>` and
  // `<SeriesHighlightLayer>` so this component (and its expensive
  // <SeriesDashTailOverlay> child) does not re-render on cursor motion.
  // The reveal-clip is now a single shared clipPath at the chart-shell
  // level (`time-series-chart-shell.tsx`); we no longer render a per-line
  // `<ChartRevealClip>` or read `revealEpoch` here.
  const {
    data,
    renderData,
    xScale,
    innerHeight,
    innerWidth,
    xAccessor,
    lines,
    chartPhase,
    notifyLoadingPulseComplete,
    yDomainTweenDuration,
  } = useChartStable();
  const yScale = useYScale(yAxisId);
  const settledYScale = useSettledYScale(yAxisId);
  const useDataTransitionPath = animate && chartPhase === "ready";
  const { pathD: animatedPathD } = useAnimatedSeriesPath({
    chartPhase,
    curve,
    dataKey,
    durationMs: yDomainTweenDuration,
    enabled: useDataTransitionPath,
    innerWidth,
    renderData,
    settledYScale,
    xAccessor,
    xScale,
    yScale,
  });

  const pulseMode = resolveLinePulseMode(chartPhase, loading, loadingPulseMode);
  const showLoadingPulse = pulseMode != null;
  const [pulseEpoch, setPulseEpoch] = useState(0);
  const effectiveShowHighlight = showHighlight && !showLoadingPulse;

  const handleLoadingPulseComplete = useCallback(() => {
    onLoadingPulseCycleComplete?.();
    if (pulseMode === "loop") {
      window.setTimeout(() => {
        setPulseEpoch((epoch) => epoch + 1);
      }, LINE_LOADING_LOOP_PAUSE_MS);
      return;
    }
    notifyLoadingPulseComplete?.();
  }, [notifyLoadingPulseComplete, onLoadingPulseCycleComplete, pulseMode]);

  const seriesIndex = useMemo(() => {
    const index = lines.findIndex((line) => line.dataKey === dataKey);
    return index >= 0 ? index : 0;
  }, [lines, dataKey]);

  const pathRef = useRef<SVGPathElement>(null);
  const hasDashTail = resolveDashTailBounds(dashFromIndex, data.length);
  const { pathLength, pathD } = usePathStrokeMetrics(
    pathRef,
    [
      renderData,
      innerWidth,
      dashFromIndex,
      animate,
      useDataTransitionPath ? animatedPathD : null,
    ],
    // Only the dash tail and loading pulse read the metrics; outside the
    // resting "ready" phase keep measuring so a pulse starts on a fresh path.
    hasDashTail || showLoadingPulse || chartPhase !== "ready"
  );

  const reactId = useId();
  const gradientId = `line-gradient-${dataKey}-${reactId}`;
  const highlightGradientId = `${gradientId}-highlight`;
  const glowFilterId = `line-glow-${dataKey}-${reactId}`;

  // While the data-transition tween runs, `animatedPathD` (per frame) is drawn
  // on a plain `<path>`; at rest the same hook `pathD` (built from the same
  // scales, curve and y accessor as a `linePathD` call) is the static `d`, so
  // the path is generated once rather than twice per render.
  const drawAnimatedPath = useDataTransitionPath && Boolean(animatedPathD);

  const colorStops = useMemo(
    () => resolveStrokeGradientStops(strokeGradient),
    [strokeGradient]
  );
  const paintStops = useMemo(() => {
    const sides = resolveFadeSides(fadeEdges);
    if (!(sides.any || colorStops)) {
      return null;
    }
    return horizontalPaintStops({
      color: stroke,
      colorStops,
      fadeStops: sides.any ? fadeGradientStops(sides) : null,
    });
  }, [colorStops, fadeEdges, stroke]);
  const highlightPaint = useLineHighlightPaint({
    colorStops,
    enabled: effectiveShowHighlight,
    glowFilterId: `${glowFilterId}-highlight`,
    gradientId: highlightGradientId,
    highlight,
    stroke,
    strokeWidth,
  });
  const lineStroke = paintStops ? `url(#${gradientId})` : stroke;
  const glowOptions = resolveLineGlow(glow, strokeWidth);
  const showSeriesStroke =
    chartPhase === "revealing" ||
    chartPhase === "ready" ||
    chartPhase === "exitingReady";
  let visibleStroke = "transparent";
  if (showSeriesStroke && !hasDashTail) {
    visibleStroke = lineStroke;
  }

  return (
    <>
      <LineStrokeDefs
        glowBlur={glowOptions?.blur ?? 0}
        glowFilterId={glowOptions ? glowFilterId : null}
        gradientId={gradientId}
        highlightGlow={highlightPaint.glowFilter}
        highlightGradientId={highlightGradientId}
        highlightStops={highlightPaint.stops}
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        paintStops={paintStops}
      />

      <SeriesHoverDim
        dimOpacity={highlightPaint.dimOpacity}
        enabled={effectiveShowHighlight}
        seriesIndex={seriesIndex}
      >
        {glowOptions && showSeriesStroke ? (
          <LineSeriesStroke
            animatedPathD={animatedPathD}
            drawAnimatedPath={drawAnimatedPath}
            filter={`url(#${glowFilterId})`}
            staticPathD={animatedPathD}
            strokeOpacity={glowOptions.opacity}
            strokeWidth={glowOptions.strokeWidth}
            visibleStroke={lineStroke}
          />
        ) : null}
        <LineSeriesStroke
          animatedPathD={animatedPathD}
          drawAnimatedPath={drawAnimatedPath}
          pathRef={pathRef}
          staticPathD={animatedPathD}
          strokeWidth={strokeWidth}
          visibleStroke={visibleStroke}
        />

        {/* Only mounted with a dash tail: it takes `data` as a prop. */}
        {hasDashTail ? (
          <SeriesDashTailOverlay
            dashArray={dashArray}
            dashFromIndex={dashFromIndex}
            data={data}
            innerHeight={innerHeight}
            innerWidth={innerWidth}
            pathD={pathD}
            pathLength={pathLength}
            stroke={lineStroke}
            strokeWidth={strokeWidth}
            xAccessor={xAccessor}
            xScale={xScale}
          />
        ) : null}
      </SeriesHoverDim>

      {showMarkers ? (
        <SeriesMarkers
          animate={animate}
          dataKey={dataKey}
          {...markers}
          fill={markers?.fill ?? stroke}
          stroke={markers?.stroke ?? markers?.fill ?? stroke}
        />
      ) : null}

      <SeriesHighlightLayer
        enabled={effectiveShowHighlight}
        fadeLength={highlight?.fadeLength}
        glow={highlightPaint.segmentGlow}
        height={innerHeight}
        pathRef={pathRef}
        span={highlight?.span}
        stroke={highlightPaint.stroke}
        strokeWidth={highlightPaint.strokeWidth}
      />

      <LineLoadingOverlays
        curve={curve}
        handleLoadingPulseComplete={handleLoadingPulseComplete}
        innerWidth={innerWidth}
        loadingStroke={loadingStroke}
        loadingStrokeOpacity={loadingStrokeOpacity}
        loadingStyle={loadingStyle}
        pathD={pathD}
        pulseEpoch={pulseEpoch}
        pulseMode={pulseMode}
        showLoadingPulse={showLoadingPulse}
        strokeWidth={strokeWidth}
      />
    </>
  );
}

Line.displayName = "Line";

export default Line;

"use client";

import { scaleLinear } from "d3-scale";
import type { CurveFactory } from "d3-shape";
import { m, useReducedMotion } from "motion/react";
import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { chartCssVars, useChartStable } from "./chart-context";
import {
  LINE_LOADING_PULSE_EASE,
  LOADING_LABEL_EXIT_S,
} from "./line-loading-timing";
import { areaClosedD, LinePath, linePathD } from "./line-path";

/**
 * Shared "sweep" loading visuals. A soft diagonal shimmer band travels across a
 * self-contained skeleton silhouette on a loop, painted via an SVG mask. The
 * silhouette re-randomizes between passes (held steady during a pass, re-rolled
 * once the band clears the right edge) so it reads as live and still loading,
 * without warping mid-sweep. Used as the `loadingStyle="sweep"` alternative to
 * the traveling pulse on `<Line>` and `<Area>`, and as the skeleton for
 * `<BarChart status="loading">`.
 */

/** One shimmer sweep, in seconds. */
const DEFAULT_SWEEP_DURATION_S = 2;
/** Sweep travel in objectBoundingBox space: off the left edge to off the right. */
const SWEEP_START_X = -1;
const SWEEP_END_X = 2;
/** Diagonal tilt of the shimmer band, in degrees. */
const SWEEP_ANGLE_DEG = 25;
const HEIGHT_MIN_PCT = 20;
const HEIGHT_MAX_PCT = 80;
const DEFAULT_POINT_COUNT = 14;
const DEFAULT_BAR_COUNT = 12;
const DEFAULT_FILL = "var(--foreground)";
const DEFAULT_BAR_FILL_OPACITY = 0.45;
const LINE_STROKE_OPACITY = 0.55;
const AREA_FILL_TOP_OPACITY = 0.18;
const AREA_FILL_BOTTOM_OPACITY = 0.02;
/** Bar width as a fraction of its band (the rest is the inter-bar gap). */
const DEFAULT_BAR_FRACTION = 0.7;

// ─── Pure, SSR-safe helpers ──────────────────────────────────────────────
// Heights come from a deterministic hash of (index, seed), never
// `Math.random()`, so the first server render and first client render agree
// (no Next.js hydration mismatch). Re-randomizing only bumps the numeric seed
// on the client, after a sweep completes.

/** Cheap deterministic hash to a fractional part in [0, 1). */
function hashFract(n: number): number {
  const x = Math.sin(n) * 43_758.5453;
  return x - Math.floor(x);
}

/** Deterministic heights (percentages of the available height) for a seed. */
export function getSkeletonHeights(
  count: number,
  seed = 0,
  min = HEIGHT_MIN_PCT,
  max = HEIGHT_MAX_PCT
): number[] {
  const range = max - min;
  return Array.from(
    { length: count },
    (_, i) => min + Math.floor(hashFract((i + 1) * 12.9898 + seed) * range)
  );
}

/** Deterministic up/down (±1) per bar for the "center" baseline. */
function getSkeletonSigns(count: number, seed = 0): number[] {
  return Array.from({ length: count }, (_, i) =>
    hashFract((i + 1) * 78.233 + seed) < 0.5 ? -1 : 1
  );
}

/** Bell-curve opacity stops (sin squared) for the shimmer band's soft edges. */
function generateEasedGradientStops(
  steps = 17,
  minOpacity = 0.05,
  maxOpacity = 0.9
) {
  return Array.from({ length: steps }, (_, i) => {
    const t = i / (steps - 1);
    const eased = Math.sin(t * Math.PI) ** 2;
    const opacity = minOpacity + eased * (maxOpacity - minOpacity);
    return {
      offset: `${(t * 100).toFixed(0)}%`,
      opacity: Number(opacity.toFixed(3)),
    };
  });
}

// ─── Shared mask defs (`${chartId}-mask` is the mask id) ─────────────────────

function LoadingSweepMask({
  chartId,
  width,
  height,
  durationSeconds,
  onSweepComplete,
}: {
  chartId: string;
  width: number;
  height: number;
  durationSeconds: number;
  onSweepComplete: () => void;
}) {
  const gradientStops = useMemo(() => generateEasedGradientStops(), []);
  const lastXRef = useRef(SWEEP_START_X);

  const handleUpdate = useCallback(
    (latest: { x?: number }) => {
      const xValue = typeof latest.x === "number" ? latest.x : SWEEP_START_X;
      // Re-roll once the band has cleared the visible area (crossed past 1),
      // so the silhouette never changes shape under the user's eye.
      if (xValue >= 1 && lastXRef.current < 1) {
        onSweepComplete();
      }
      lastXRef.current = xValue;
    },
    [onSweepComplete]
  );

  return (
    <>
      <linearGradient id={`${chartId}-grad`} x1="0" x2="1" y1="0" y2="0">
        {gradientStops.map(({ offset, opacity }) => (
          <stop
            key={offset}
            offset={offset}
            stopColor="white"
            stopOpacity={opacity}
          />
        ))}
      </linearGradient>
      <pattern
        height="1"
        id={`${chartId}-pattern`}
        patternContentUnits="objectBoundingBox"
        patternTransform={`rotate(${SWEEP_ANGLE_DEG})`}
        patternUnits="objectBoundingBox"
        width={3}
        x="0"
        y="0"
      >
        <m.rect
          animate={{ x: SWEEP_END_X }}
          fill={`url(#${chartId}-grad)`}
          height="1"
          initial={{ x: SWEEP_START_X }}
          onUpdate={handleUpdate}
          transition={{
            duration: durationSeconds,
            ease: "linear",
            repeat: Number.POSITIVE_INFINITY,
            repeatType: "loop",
          }}
          width="1"
          y="0"
        />
      </pattern>
      <mask id={`${chartId}-mask`} maskUnits="userSpaceOnUse">
        <rect fill={`url(#${chartId}-pattern)`} height={height} width={width} />
      </mask>
    </>
  );
}

// ─── Line / Area loading sweep (its own re-randomizing silhouette) ───────────

export interface LineLoadingSweepProps {
  /** Curve factory from the host `<Line>` / `<Area>`, so the silhouette matches
   * the chart's interpolation (step, smooth, linear, …). */
  curve: CurveFactory;
  /** Fill the silhouette as an area (for `<Area>`); otherwise stroke only. */
  withArea?: boolean;
  /** Loading phase: `"loop"` (steady), `"exit"` (loading → ready), or `"enter"`
   * (ready → loading). Exit/enter fade the silhouette and then signal the chart
   * to continue its reveal. Default: `"loop"`. */
  mode?: "loop" | "exit" | "enter";
  /** Fired when an exit/enter transition finishes, to advance the chart phase. */
  onTransitionComplete?: () => void;
  stroke?: string;
  strokeOpacity?: number;
  strokeWidth?: number;
  pointCount?: number;
  durationSeconds?: number;
}

/**
 * Renders a placeholder line/area silhouette (its own, not the chart's skeleton)
 * with the shimmer sweeping across it. The silhouette re-randomizes between
 * passes. Reads inner dimensions from chart context.
 */
export function LineLoadingSweep({
  curve,
  withArea = false,
  mode = "loop",
  onTransitionComplete,
  stroke = chartCssVars.foreground,
  strokeOpacity = LINE_STROKE_OPACITY,
  strokeWidth = 2,
  pointCount = DEFAULT_POINT_COUNT,
  durationSeconds = DEFAULT_SWEEP_DURATION_S,
}: LineLoadingSweepProps) {
  const { innerWidth, innerHeight } = useChartStable();
  const reduceMotion = useReducedMotion();
  const reactId = useId();
  const chartId = `line-sweep-${reactId.replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const isLoop = mode === "loop";

  const [tick, setTick] = useState(0);
  // Re-randomize only while looping; hold the silhouette steady through a
  // transition so it fades out (or in) as one piece.
  const onSweepComplete = useCallback(() => {
    if (isLoop) {
      setTick((prev) => prev + 1);
    }
  }, [isLoop]);
  const heights = useMemo(
    () => getSkeletonHeights(pointCount, tick),
    [pointCount, tick]
  );

  // With reduced motion there is no fade to await, so signal the handoff
  // immediately or the phase machine would stall mid-transition.
  useEffect(() => {
    if (reduceMotion && !isLoop) {
      onTransitionComplete?.();
    }
  }, [reduceMotion, isLoop, onTransitionComplete]);

  if (innerWidth <= 0 || innerHeight <= 0 || heights.length < 2) {
    return null;
  }

  const xScale = scaleLinear()
    .domain([0, heights.length - 1])
    .range([0, innerWidth]);
  const yScale = scaleLinear().domain([0, 100]).range([innerHeight, 0]);
  const points = heights.map((value, index) => ({ index, value }));
  const getX = (d: { index: number }) => xScale(d.index);
  const getY = (d: { value: number }) => yScale(d.value);

  const silhouette = (
    <>
      {withArea ? (
        <path
          d={areaClosedD(points, { curve, x: getX, y: getY, yScale })}
          fill={`url(#${chartId}-area)`}
        />
      ) : null}
      <LinePath
        d={linePathD(points, { curve, x: getX, y: getY })}
        fill="none"
        stroke={stroke}
        strokeLinecap="round"
        strokeOpacity={strokeOpacity}
        strokeWidth={strokeWidth}
      />
    </>
  );

  const areaGradient = withArea ? (
    <linearGradient id={`${chartId}-area`} x1="0" x2="0" y1="0" y2="1">
      <stop
        offset="0%"
        stopColor={stroke}
        stopOpacity={AREA_FILL_TOP_OPACITY}
      />
      <stop
        offset="100%"
        stopColor={stroke}
        stopOpacity={AREA_FILL_BOTTOM_OPACITY}
      />
    </linearGradient>
  ) : null;

  if (reduceMotion) {
    return (
      <>
        {areaGradient ? <defs>{areaGradient}</defs> : null}
        {silhouette}
      </>
    );
  }

  const maskUrl = `url(#${chartId}-mask)`;
  const defs = (
    <defs>
      {areaGradient}
      <LoadingSweepMask
        chartId={chartId}
        durationSeconds={durationSeconds}
        height={innerHeight}
        onSweepComplete={onSweepComplete}
        width={innerWidth}
      />
    </defs>
  );

  if (isLoop) {
    return (
      <>
        {defs}
        <g mask={maskUrl}>{silhouette}</g>
      </>
    );
  }

  // Transition: fade the swept silhouette out (exit) or in (enter), then hand
  // off to the chart so it can reveal the real series.
  return (
    <>
      {defs}
      <m.g
        animate={{ opacity: mode === "exit" ? 0 : 1 }}
        initial={{ opacity: mode === "exit" ? 1 : 0 }}
        mask={maskUrl}
        onAnimationComplete={onTransitionComplete}
        transition={{
          duration: LOADING_LABEL_EXIT_S,
          ease: [...LINE_LOADING_PULSE_EASE],
        }}
      >
        {silhouette}
      </m.g>
    </>
  );
}

LineLoadingSweep.displayName = "LineLoadingSweep";

// ─── Bar loading skeleton (seeded bars under the sweep, inner coords) ─────────

function SkeletonBars({
  heights,
  signs,
  innerWidth,
  innerHeight,
  baseline,
  barFraction,
  fill,
  fillOpacity,
}: {
  heights: number[];
  signs: number[];
  innerWidth: number;
  innerHeight: number;
  baseline: "bottom" | "center";
  barFraction: number;
  fill: string;
  fillOpacity: number;
}) {
  const bandWidth = innerWidth / heights.length;
  const barW = bandWidth * barFraction;
  const cornerRadius = Math.min(barW / 2, 8);
  const xOffset = (bandWidth * (1 - barFraction)) / 2;
  const isCenter = baseline === "center";
  const baselineY = isCenter ? innerHeight / 2 : innerHeight;
  const halfBarH = isCenter ? innerHeight / 2 : innerHeight;

  return (
    <>
      {heights.map((value, i) => {
        const sign = isCenter ? (signs[i] ?? 1) : 1;
        const barH = Math.max(1, halfBarH * (value / 100));
        const x = i * bandWidth + xOffset;
        const y = sign === 1 ? baselineY - barH : baselineY;
        return (
          <rect
            fill={fill}
            fillOpacity={fillOpacity}
            height={barH}
            key={`${x.toFixed(2)}-${value}`}
            rx={cornerRadius}
            width={barW}
            x={x}
            y={y}
          />
        );
      })}
    </>
  );
}

export interface BarLoadingSkeletonProps {
  innerWidth: number;
  innerHeight: number;
  /** Number of skeleton bars. Default: 12 */
  barCount?: number;
  /** Bar fill color. Default: `var(--foreground)` */
  fill?: string;
  /** Bar fill opacity. Default: 0.45 */
  fillOpacity?: number;
  /** Bars rise from the bottom or diverge from the vertical center. Default: `"bottom"` */
  baseline?: "bottom" | "center";
  /** Bar width as a fraction of its band (0–1). Default: 0.7 */
  barFraction?: number;
  /** One shimmer sweep, in seconds. Default: 2 */
  durationSeconds?: number;
}

/**
 * Skeleton bars masked by the shimmer sweep, re-randomizing between passes.
 * Rendered in the chart's inner coordinate space (origin at the inner top-left),
 * so a `BarChart` drops it inside its margin-translated group.
 */
export function BarLoadingSkeleton({
  innerWidth,
  innerHeight,
  barCount = DEFAULT_BAR_COUNT,
  fill = DEFAULT_FILL,
  fillOpacity = DEFAULT_BAR_FILL_OPACITY,
  baseline = "bottom",
  barFraction = DEFAULT_BAR_FRACTION,
  durationSeconds = DEFAULT_SWEEP_DURATION_S,
}: BarLoadingSkeletonProps) {
  const reduceMotion = useReducedMotion();
  const reactId = useId();
  const chartId = `bar-sweep-${reactId.replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const [tick, setTick] = useState(0);
  const onSweepComplete = useCallback(() => setTick((prev) => prev + 1), []);
  const heights = useMemo(
    () => getSkeletonHeights(barCount, tick),
    [barCount, tick]
  );
  const signs = useMemo(
    () => getSkeletonSigns(barCount, tick),
    [barCount, tick]
  );

  if (innerWidth <= 0 || innerHeight <= 0) {
    return null;
  }

  const bars = (
    <SkeletonBars
      barFraction={barFraction}
      baseline={baseline}
      fill={fill}
      fillOpacity={fillOpacity}
      heights={heights}
      innerHeight={innerHeight}
      innerWidth={innerWidth}
      signs={signs}
    />
  );

  if (reduceMotion) {
    return bars;
  }

  return (
    <>
      <defs>
        <LoadingSweepMask
          chartId={chartId}
          durationSeconds={durationSeconds}
          height={innerHeight}
          onSweepComplete={onSweepComplete}
          width={innerWidth}
        />
      </defs>
      <g mask={`url(#${chartId}-mask)`}>{bars}</g>
    </>
  );
}

