import { localPointFromSvg } from "./scatter-svg";

export interface LocalPoint {
  x: number;
  y: number;
}

interface ClientPointLike {
  clientX: number;
  clientY: number;
}

interface TouchEventLike {
  changedTouches: ArrayLike<ClientPointLike>;
}

/** Native/React mouse, pointer, touch or focus event, or a `Touch`. */
export type LocalPointEvent =
  | Event
  | ClientPointLike
  | TouchEventLike
  | { nativeEvent: Event; target: EventTarget | null };

function isElement(value: unknown): value is Element {
  return typeof Element !== "undefined" && value instanceof Element;
}

function isEvent(
  value: unknown
): value is Event | { nativeEvent: Event; target: EventTarget | null } {
  if (typeof Event === "undefined" || !value) {
    return false;
  }
  return (
    value instanceof Event ||
    ("nativeEvent" in (value as object) &&
      (value as { nativeEvent: unknown }).nativeEvent instanceof Event)
  );
}

function clientCoords(event: LocalPointEvent): LocalPoint {
  if ("changedTouches" in event) {
    const touch = event.changedTouches[0];
    return touch ? { x: touch.clientX, y: touch.clientY } : { x: 0, y: 0 };
  }
  if ("clientX" in event) {
    return { x: event.clientX, y: event.clientY };
  }
  // Focus (and other coordinate-less) events: centre of the target.
  const target = (event as { target?: unknown }).target;
  if (
    target &&
    typeof target === "object" &&
    "getBoundingClientRect" in target
  ) {
    const rect = (target as Element).getBoundingClientRect();
    return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
  }
  return { x: 0, y: 0 };
}

function localPointFromNode(node: Element, event: LocalPointEvent): LocalPoint {
  const coords = clientCoords(event);

  if (node instanceof SVGElement) {
    const svg = node instanceof SVGSVGElement ? node : node.ownerSVGElement;
    const point = localPointFromSvg(svg, coords.x, coords.y);
    if (point) {
      return point;
    }
  }

  // HTML overlays are positioned in layout pixels, even in a scaled chart.
  const rect = node.getBoundingClientRect();
  const scaleX =
    node instanceof HTMLElement && rect.width ? node.offsetWidth / rect.width : 1;
  const scaleY =
    node instanceof HTMLElement && rect.height ? node.offsetHeight / rect.height : 1;
  return {
    x: (coords.x - rect.left) * scaleX - node.clientLeft,
    y: (coords.y - rect.top) * scaleY - node.clientTop,
  };
}

export function localPoint(event: LocalPointEvent): LocalPoint | null;
export function localPoint(
  node: Element | null | undefined,
  event: LocalPointEvent
): LocalPoint | null;
export function localPoint(
  nodeOrEvent: Element | LocalPointEvent | null | undefined,
  maybeEvent?: LocalPointEvent
): LocalPoint | null {
  if (isElement(nodeOrEvent) && maybeEvent) {
    return localPointFromNode(nodeOrEvent, maybeEvent);
  }
  if (isEvent(nodeOrEvent)) {
    const node = nodeOrEvent.target;
    if (isElement(node)) {
      return localPointFromNode(node, nodeOrEvent);
    }
  }
  return null;
}

import type { Transition } from "motion/react";
import { DEFAULT_CHART_ENTER_TRANSITION } from "./animation";

export function transitionWithDelay(
  transition: Transition | undefined,
  delaySeconds: number,
  fallback: Transition = DEFAULT_CHART_ENTER_TRANSITION
): Transition {
  const base = transition ?? fallback;
  return { ...base, delay: delaySeconds };
}

export interface SpringOptions {
  stiffness: number;
  damping: number;
  mass?: number;
}

export function springOptionsFromTransition(
  transition?: Transition,
  fallback: SpringOptions = { stiffness: 60, damping: 20 }
): SpringOptions {
  if (!transition) {
    return fallback;
  }
  if (transition.type === "spring") {
    const bounce =
      typeof transition.bounce === "number" ? transition.bounce : undefined;
    const baseStiffness =
      typeof transition.stiffness === "number"
        ? transition.stiffness
        : fallback.stiffness;
    const baseDamping =
      typeof transition.damping === "number"
        ? transition.damping
        : fallback.damping;
    return {
      stiffness:
        bounce == null
          ? baseStiffness
          : Math.min(400, Math.max(80, baseStiffness * (1 + bounce * 0.35))),
      damping:
        bounce == null
          ? baseDamping
          : Math.max(8, baseDamping * (1 - bounce * 0.25)),
      mass:
        typeof transition.mass === "number" ? transition.mass : fallback.mass,
    };
  }
  const duration =
    "duration" in transition && typeof transition.duration === "number"
      ? transition.duration
      : 0.8;
  return {
    stiffness: Math.min(500, Math.max(40, 280 / duration)),
    damping: Math.min(40, Math.max(12, 18 + duration * 4)),
  };
}

// biome-ignore-all lint/correctness/useExhaustiveDependencies: usePathStrokeMetrics intentionally accepts caller-controlled deps
import { type RefObject, useEffect, useState } from "react";

export function findPathLengthAtX(
  path: SVGPathElement | null,
  pathLength: number,
  targetX: number
): number {
  if (!path || pathLength === 0) {
    return 0;
  }
  let low = 0;
  let high = pathLength;
  const tolerance = 0.5;

  while (high - low > tolerance) {
    const mid = (low + high) / 2;
    const point = path.getPointAtLength(mid);
    if (point.x < targetX) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return (low + high) / 2;
}

interface PathStrokeMetrics {
  pathD: string | null;
  pathLength: number;
}

const EMPTY_METRICS: PathStrokeMetrics = { pathD: null, pathLength: 0 };

/**
 * Caller passes the references that drive the rendered path (renderData,
 * innerWidth, etc.) as `deps`. A stringified summary like
 * `${renderData.length}:${innerWidth}` is *not* safe here — same-length
 * in-place mutations of `renderData` keep the summary identical, so the
 * effect would never re-fire and `pathD`/`pathLength` would stay frozen on
 * the previous geometry (the area fill repaints from `renderData` directly
 * and would diverge from the stroke).
 */
export function usePathStrokeMetrics(
  pathRef: RefObject<SVGPathElement | null>,
  [renderData, innerWidth, dashFromIndex, animated, pathData]: readonly [unknown, number, number | undefined, boolean, string | null],
  /**
   * Skip measuring while nothing reads the metrics (no dash tail / loading
   * pulse): `getTotalLength()` on a long path plus the follow-up render is
   * real work on every data update. Flipping to true re-measures.
   */
  enabled = true
): PathStrokeMetrics {
  const [metrics, setMetrics] = useState<PathStrokeMetrics>(EMPTY_METRICS);

  useEffect(() => {
    const path = pathRef.current;
    if (!(enabled && path)) {
      return;
    }
    const d = path.getAttribute("d");
    const len = d ? path.getTotalLength() : 0;
    setMetrics((prev) =>
      prev.pathD === d && prev.pathLength === len
        ? prev
        : { pathD: d, pathLength: len }
    );
  }, [enabled, pathRef, renderData, innerWidth, dashFromIndex, animated, pathData]);

  return metrics;
}

export function resolveDashTailBounds(
  dashFromIndex: number | undefined,
  dataLength: number
): boolean {
  return (
    dashFromIndex != null &&
    dashFromIndex >= 0 &&
    dashFromIndex < dataLength - 1
  );
}

export function resolveDashStartX(
  data: Record<string, unknown>[],
  dashFromIndex: number,
  xScale: (value: Date | number) => number | undefined,
  xAccessor: (datum: Record<string, unknown>) => Date | number
): number {
  const dashFromPoint = data[dashFromIndex];
  if (!dashFromPoint) {
    return 0;
  }
  return xScale(xAccessor(dashFromPoint)) ?? 0;
}

