  RadarProvider,
} from "./radar-context";

export interface RadarChartProps {
  /** Data array - each item represents a data series (polygon) */
  data: RadarData[];
  /** Metrics to display on the radar */
  metrics: RadarMetric[];
  /** Chart size in pixels. If not provided, uses parent container size */
  size?: number;
  /** Number of concentric grid circles. Default: 5 */
  levels?: number;
  /** Margin around the chart. Default: 60 */
  margin?: number;
  /** Enable animations. Default: true */
  animate?: boolean;
  /** Enter animation budget in ms. Default: 1100 */
  enterDurationMs?: number;
  /** Scales stagger timing (1 = default). */
  staggerScale?: number;
  /** Motion enter transition (spring or cubic-bezier tween). */
  enterTransition?: Transition;
  /** Changes when motion settings change — replays enter animations. */
  motionReplayKey?: string;
  /** Controlled hover state - index of hovered area */
  hoveredIndex?: number | null;
  /** Callback when hover state changes */
  onHoverChange?: (index: number | null) => void;
  /** Additional class name for the container */
  className?: string;
  /** Child components (RadarGrid, RadarAxis, RadarLabels, RadarArea) */
  children: ReactNode;
}

interface RadarChartInnerProps {
  width: number;
  height: number;
  data: RadarData[];
  metrics: RadarMetric[];
  levels: number;
  margin: number;
  animate: boolean;
  enterDurationMs: number;
  staggerScale: number;
  enterTransition?: Transition;
  motionReplayKey: string;
  children: ReactNode;
  hoveredIndexProp?: number | null;
  onHoverChange?: (index: number | null) => void;
}

function RadarChartInner({
  width,
  height,
  data,
  metrics,
  levels,
  margin,
  animate,
  enterDurationMs,
  staggerScale,
  enterTransition,
  motionReplayKey,
  children,
  hoveredIndexProp,
  onHoverChange,
}: RadarChartInnerProps) {
  const [internalHoveredIndex, setInternalHoveredIndex] = useState<
    number | null
  >(null);

  // Use controlled or uncontrolled hover state
  const isControlled = hoveredIndexProp !== undefined;
  const hoveredIndex = isControlled ? hoveredIndexProp : internalHoveredIndex;
  const setHoveredIndex = useCallback(
    (index: number | null) => {
      if (isControlled) {
        onHoverChange?.(index);
      } else {
        setInternalHoveredIndex(index);
      }
    },
    [isControlled, onHoverChange]
  );

  // Use the smaller dimension
  const size = Math.min(width, height);
  const radius = (size - margin * 2) / 2;

  // Scale for converting values (0-100) to radius
  const yScale = useCallback(
    (value: number) => {
      const scale = scaleLinear<number>().domain([0, 100]).range([0, radius]);
      return scale(value) ?? 0;
    },
    [radius]
  );

  // Get angle for a metric index (rotated so first metric is at top)
  const getAngle = useCallback(
    (metricIndex: number) => {
      const step = (Math.PI * 2) / metrics.length;
      const angleOffset = -Math.PI / 2; // Rotate so first axis is at top
      return metricIndex * step + angleOffset;
    },
    [metrics.length]
  );

  // Get x,y position for a metric at a given value
  const getPointPosition = useCallback(
    (metricIndex: number, value: number) => {
      const angle = getAngle(metricIndex);
      const r = yScale(value);
      return {
        x: r * Math.cos(angle),
        y: r * Math.sin(angle),
      };
    },
    [getAngle, yScale]
  );

  // Get color for a data index
  const getColor = useCallback(
    (index: number) => {
      const item = data[index];
      if (item?.color) {
        return item.color;
      }
      return defaultRadarColors[index % defaultRadarColors.length] as string;
    },
    [data]
  );

  // Early return if dimensions not ready
  if (size < 10) {
    return null;
  }

  const contextValue: RadarContextValue = {
    data,
    metrics,
    size,
    radius,
    levels,
    hoveredIndex,
    setHoveredIndex,
    animate,
    enterDurationMs,
    staggerScale,
    enterTransition,
    motionReplayKey,
    getColor,
    getAngle,
    getPointPosition,
    yScale,
  };

  return (
    <RadarProvider value={contextValue}>
      <svg
        aria-hidden="true"
        height={size}
        style={{ overflow: "visible" }}
        width={size}
      >
        {/* Same transform string visx Group emitted (note the space). */}
        <g transform={`translate(${size / 2}, ${size / 2})`}>{children}</g>
      </svg>
    </RadarProvider>
  );
}

export function RadarChart({
  data,
  metrics,
  size: fixedSize,
  levels = 5,
  margin = 60,
  animate = true,
  enterDurationMs = 1100,
  staggerScale = 1,
  enterTransition,
  motionReplayKey = "",
  className = "",
  hoveredIndex,
  onHoverChange,
  children,
}: RadarChartProps) {
  // If fixed size is provided, use it directly
  if (fixedSize) {
    return (
      <LazyMotion features={domAnimation}>
        <div
          className={cn("relative flex items-center justify-center", className)}
          style={{ width: fixedSize, height: fixedSize }}
        >
          <RadarChartInner
            animate={animate}
            data={data}
            enterDurationMs={enterDurationMs}
            enterTransition={enterTransition}
            height={fixedSize}
            hoveredIndexProp={hoveredIndex}
            levels={levels}
            margin={margin}
            metrics={metrics}
            motionReplayKey={motionReplayKey}
            onHoverChange={onHoverChange}
            staggerScale={staggerScale}
            width={fixedSize}
          >
            {children}
          </RadarChartInner>
        </div>
      </LazyMotion>
    );
  }

  // Otherwise use ParentSize for responsive sizing
  return (
    <LazyMotion features={domAnimation}>
      <div className={cn("relative aspect-square w-full", className)}>
        <ParentSize debounceTime={10}>
          {({ width, height }) => (
            <RadarChartInner
              animate={animate}
              data={data}
              enterDurationMs={enterDurationMs}
              enterTransition={enterTransition}
              height={height}
              hoveredIndexProp={hoveredIndex}
              levels={levels}
              margin={margin}
              metrics={metrics}
              motionReplayKey={motionReplayKey}
              onHoverChange={onHoverChange}
              staggerScale={staggerScale}
              width={width}
            >
              {children}
            </RadarChartInner>
          )}
        </ParentSize>
      </div>
    </LazyMotion>
  );
}

export default RadarChart;

"use client";

import type { Transition } from "motion/react";
import { createContext, type ReactNode, useContext, useMemo } from "react";

// CSS variable references for radar chart theming
export const radarCssVars = {
  background: "var(--chart-background)",
  foreground: "var(--chart-foreground)",
  foregroundMuted: "var(--chart-foreground-muted)",
  label: "var(--chart-label, oklch(0.65 0.01 260))",
  grid: "var(--chart-grid)",
  border: "var(--border)",
  // Default radar colors from chart palette
  area1: "var(--chart-1)",
  area2: "var(--chart-2)",
  area3: "var(--chart-3)",
  area4: "var(--chart-4)",
  area5: "var(--chart-5)",
};

// Default radar color palette
export const defaultRadarColors = [
  radarCssVars.area1,
  radarCssVars.area2,
  radarCssVars.area3,
  radarCssVars.area4,
  radarCssVars.area5,
];

export interface RadarMetric {
  /** Unique key for the metric */
  key: string;
  /** Display label for the metric */
  label: string;
}

export interface RadarData {
  /** Display label for this data series */
  label: string;
  /** Color for this data series (defaults to chart-1 through chart-5) */
  color?: string;
  /** Metric values (key -> value, normalized 0-100) */
  values: Record<string, number>;
}

export interface RadarHoverContextValue {
  hoveredIndex: number | null;
  setHoveredIndex: (index: number | null) => void;
}

export interface RadarStableContextValue {
  // Data
  data: RadarData[];
  metrics: RadarMetric[];

  // Dimensions
  size: number;
  radius: number;
  levels: number;

  // Animation
  animate: boolean;
  /** Total enter animation budget in ms */
  enterDurationMs: number;
  /** Scales stagger delays between grid / campaigns / metrics */
  staggerScale: number;
  /** Motion enter transition (spring or cubic-bezier tween). */
  enterTransition?: Transition;
  /** Changes when motion settings change — replays enter animations. */
  motionReplayKey: string;

  // Computed helpers
  getColor: (index: number) => string;
  getAngle: (metricIndex: number) => number;
  getPointPosition: (
    metricIndex: number,
    value: number
  ) => { x: number; y: number };
  yScale: (value: number) => number;
}

export type RadarContextValue = RadarStableContextValue &
  RadarHoverContextValue;

const RadarStableContext = createContext<RadarStableContextValue | null>(null);
const RadarHoverContext = createContext<RadarHoverContextValue | null>(null);

export function RadarProvider({
  children,
  value,
}: {
  children: ReactNode;
  value: RadarContextValue;
}) {
  const stable = useMemo<RadarStableContextValue>(
    () => ({
      data: value.data,
      metrics: value.metrics,
      size: value.size,
      radius: value.radius,
      levels: value.levels,
      animate: value.animate,
      enterDurationMs: value.enterDurationMs,
      staggerScale: value.staggerScale,
      enterTransition: value.enterTransition,
      motionReplayKey: value.motionReplayKey,
      getColor: value.getColor,
      getAngle: value.getAngle,
      getPointPosition: value.getPointPosition,
      yScale: value.yScale,
    }),
    [
      value.data,
      value.metrics,
      value.size,
      value.radius,
      value.levels,
      value.animate,
      value.enterDurationMs,
      value.staggerScale,
      value.enterTransition,
      value.motionReplayKey,
      value.getColor,
      value.getAngle,
      value.getPointPosition,
      value.yScale,
    ]
  );

  const hover = useMemo<RadarHoverContextValue>(
    () => ({
      hoveredIndex: value.hoveredIndex,
      setHoveredIndex: value.setHoveredIndex,
    }),
    [value.hoveredIndex, value.setHoveredIndex]
  );

  return (
    <RadarStableContext.Provider value={stable}>
      <RadarHoverContext.Provider value={hover}>
        {children}
      </RadarHoverContext.Provider>
    </RadarStableContext.Provider>
  );
}

export function useRadarStable(): RadarStableContextValue {
  const context = useContext(RadarStableContext);
  if (!context) {
    throw new Error(
      "useRadarStable must be used within a RadarProvider. " +
        "Make sure your component is wrapped in <RadarChart>."
    );
  }
  return context;
}

export function useRadarHover(): RadarHoverContextValue {
  const context = useContext(RadarHoverContext);
  if (!context) {
    throw new Error(
      "useRadarHover must be used within a RadarProvider. " +
        "Make sure your component is wrapped in <RadarChart>."
    );
  }
  return context;
}

export function useRadar(): RadarContextValue {
  return { ...useRadarStable(), ...useRadarHover() };
}

export default RadarStableContext;

"use client";

import { scaleLinear } from "d3-scale";
import { lineRadial } from "d3-shape";
import { m } from "motion/react";
import {
  GRID_RING_SPRING,
  GRID_RING_STAGGER_S,
  GRID_VALUE_LABEL_STAGGER_S,
  gridLabelDelay,
} from "./animation";
import { transitionWithDelay } from "./motion-utils";
import { radarCssVars, useRadarStable } from "./radar-context";

export interface RadarGridProps {
  /** Show level value labels. Default: true */
  showLabels?: boolean;
  /** Grid line stroke color. Default: var(--border) */
  stroke?: string;
  /** Grid line stroke opacity. Default: 0.6 */
  strokeOpacity?: number;
  /** Additional class name */
  className?: string;
}

export interface RadarGridRingProps {
  /** One point per metric, plus a closing point back at the first angle */
  data: { angle: number }[];
  /** Maps a datum to its angle in radians */
  angle: (d: { angle: number }) => number;
  /** Ring radius (constant for every point) */
  radius: number;
  stroke: string;
  strokeOpacity: number;
}

/**
 * One polygon ring of the grid. Renders the same `<path>` visx `LineRadial`
 * did (minus its `visx-line-radial` class): d3 `lineRadial` with the default
 * linear curve and `d` / `fill` emitted before the stroke props.
 */
export function RadarGridRing({
  data,
  angle,
  radius,
  stroke,
  strokeOpacity,
}: RadarGridRingProps) {
  const path = lineRadial<{ angle: number }>().angle(angle);
  // visx only applied `radius` when truthy; a 0 radius kept d3's default
  // accessor (`d[1]` -> NaN). Mirror that so the output is byte-identical.
  if (radius) {
    path.radius(radius);
  }
  return (
    <path
      d={path(data) || ""}
      fill="none"
      stroke={stroke}
      strokeLinecap="round"
      strokeOpacity={strokeOpacity}
      strokeWidth={1}
    />
  );
}

export function RadarGrid({
  showLabels = true,
  stroke = radarCssVars.border,
  strokeOpacity = 0.6,
  className = "",
}: RadarGridProps) {
  const {
    metrics,
    radius,
    levels,
    animate,
    enterTransition,
    staggerScale,
    enterDurationMs,
    motionReplayKey,
  } = useRadarStable();

  const durationFactor = enterDurationMs / 1100;
  const gridStagger = GRID_RING_STAGGER_S * staggerScale * durationFactor;

  // Generate angles for the radial lines (one per metric)
  const degrees = 360;
  const angles = [...new Array(metrics.length + 1)].map((_, i) => ({
    angle: i * (degrees / metrics.length) + degrees / metrics.length / 2,
  }));

  // Radial scale for converting degrees to radians
  const radialScale = scaleLinear<number>()
    .domain([degrees, 0])
    .range([0, Math.PI * 2]);

  const labelDelay = gridLabelDelay(levels, gridStagger);

  return (
    <g className={className}>
      {/* Concentric grid circles */}
      {[...new Array(levels)].map((_, i) => {
        const targetRadius = ((i + 1) * radius) / levels;
        return (
          <m.g
            animate={{ scale: 1, opacity: 1 }}
            initial={
              animate ? { scale: 0, opacity: 0 } : { scale: 1, opacity: 1 }
            }
            // biome-ignore lint/suspicious/noArrayIndexKey: Static grid levels
            key={`grid-${i}-${motionReplayKey}`}
            style={{ transformOrigin: "0px 0px" }}
            transition={
              animate
                ? transitionWithDelay(
                    enterTransition,
                    i * gridStagger,
                    GRID_RING_SPRING
                  )
                : undefined
            }
          >
            <RadarGridRing
              angle={(d) => radialScale(d.angle) ?? 0}
              data={angles}
              radius={targetRadius}
              stroke={stroke}
              strokeOpacity={strokeOpacity}
            />
          </m.g>
        );
      })}

      {/* Grid level labels */}
      {showLabels &&
        [...new Array(levels)].map((_, i) => (
          <m.g
            animate={{ opacity: 1 }}
            initial={animate ? { opacity: 0 } : { opacity: 1 }}
            // biome-ignore lint/suspicious/noArrayIndexKey: Static grid levels
            key={`level-label-${i}-${motionReplayKey}`}
            transition={
              animate
                ? transitionWithDelay(
                    enterTransition,
                    labelDelay + i * GRID_VALUE_LABEL_STAGGER_S * durationFactor
                  )
                : undefined
            }
          >
            <text
              dominantBaseline="middle"
              fill={radarCssVars.foregroundMuted}
              fontSize={9}
              textAnchor="start"
              x={4}
              y={-((i + 1) * radius) / levels}
            >
              {((i + 1) * 100) / levels}
            </text>
          </m.g>
        ))}
    </g>
  );
}

RadarGrid.displayName = "RadarGrid";

export default RadarGrid;

"use client";

import { m } from "motion/react";
import {
  GRID_ANGLE_LABEL_FADE_S,
  GRID_ANGLE_LABEL_STAGGER_S,
  GRID_SPOKE_SPRING,
  gridLabelDelay,
} from "./animation";
import { radarCssVars, useRadarStable } from "./radar-context";

export interface RadarLabelsProps {
  /** Distance from the chart edge. Default: 24 */
  offset?: number;
  /** Font size for labels. Default: 11 */
  fontSize?: number;
  /** Enable interactive hover on labels. Default: false */
  interactive?: boolean;
  /** Additional class name */
  className?: string;
}

export function RadarLabels({
  offset = 24,
  fontSize = 11,
  interactive = false,
  className = "",
}: RadarLabelsProps) {
  const { metrics, radius, levels, getAngle, animate } = useRadarStable();

  // Label animation delay (starts after grid begins)
  const labelDelay = gridLabelDelay(levels);

  const labelRadius = radius + offset;

  return (
    <g className={className}>
      {metrics.map((metric, i) => {
        const angle = getAngle(i);
        const x = labelRadius * Math.cos(angle);
        const y = labelRadius * Math.sin(angle);

        return (
          <m.g
            animate={{ opacity: 1, x, y }}
            initial={
              animate ? { opacity: 0, x: 0, y: 0 } : { opacity: 1, x, y }
            }
            key={`label-${metric.key}`}
            transition={{
              opacity: {
                duration: GRID_ANGLE_LABEL_FADE_S,
                delay: animate
                  ? labelDelay + i * GRID_ANGLE_LABEL_STAGGER_S
                  : 0,
              },
              x: GRID_SPOKE_SPRING,
              y: GRID_SPOKE_SPRING,
            }}
          >
            <text
              className={
                interactive
                  ? "cursor-pointer transition-opacity duration-150 hover:opacity-100"
                  : ""
              }
              dominantBaseline="middle"
              fontSize={fontSize}
              fontWeight={500}
              opacity={interactive ? 0.8 : 1}
              style={{ fill: radarCssVars.label }}
              textAnchor="middle"
              x={0}
              y={0}
            >
              {metric.label}
            </text>
          </m.g>
        );
      })}
    </g>
  );
}

