"use client";

import { m } from "motion/react";
import type { ReactNode } from "react";
import { selectIsChartHovering, useChartHoverSelector } from "./chart-context";
import { useChartLegendHover } from "./chart-legend-hover";

interface SeriesHoverDimProps {
  /** Skip the dim entirely. */
  enabled?: boolean;
  /** Opacity to fade to while the chart is being hovered. */
  dimOpacity?: number;
  /** Tween duration in seconds. */
  durationSec?: number;
  /** Series index for multi-series legend hover dimming. */
  seriesIndex?: number;
  /** Stable chart visuals — area fill, stroke line, dashed tail, etc. */
  children: ReactNode;
}

/**
 * Wraps stable series visuals with a hover-driven opacity animation.
 *
 * The wrapper subscribes to chart hover state internally so the parent (Area /
 * Line) can stay on the stable context slice. Children come in as a React prop:
 * because the parent is not re-rendering on hover, the children element
 * reference stays identical and React skips re-rendering them when this
 * wrapper re-renders. That keeps expensive subtrees (`SeriesDashTailOverlay`
 * and its `getPointAtLength` binary search) quiescent on cursor motion.
 */
export function SeriesHoverDim({
  enabled = true,
  dimOpacity = 0.5,
  durationSec = 0.4,
  seriesIndex,
  children,
}: SeriesHoverDimProps) {
  // Boolean selector: re-renders on hover enter / leave, not on every move.
  const isChartHovering = useChartHoverSelector(selectIsChartHovering);
  const { hoveredIndex: legendHoveredIndex } = useChartLegendHover();
  const isLegendDimmed =
    legendHoveredIndex !== null &&
    seriesIndex !== undefined &&
    legendHoveredIndex !== seriesIndex;
  const opacity =
    enabled && (isChartHovering || isLegendDimmed) ? dimOpacity : 1;
  return (
    <m.g
      animate={{ opacity }}
      initial={{ opacity: 1 }}
      transition={{ duration: durationSec, ease: "easeInOut" }}
    >
      {children}
    </m.g>
  );
}

SeriesHoverDim.displayName = "SeriesHoverDim";

export default SeriesHoverDim;

"use client";

import { type ReactNode, useCallback, useMemo } from "react";
import { clipRevealTransition } from "./animation";
import {
  type ChartHoverContextValue,
  defaultScatterColors,
  useChartHover,
  useChartHoverSelector,
  useChartStable,
  useYScale,
} from "./chart-context";
import { useChartLegendHover } from "./chart-legend-hover";
import {
  getSeriesMarkerVisualExtent,
  SeriesPointMarker,
  type SeriesPointMarkerStyle,
  StaticSeriesPointMarker,
} from "./series-point-marker";

export interface SeriesMarkersProps extends SeriesPointMarkerStyle {
  dataKey: string;
  /** Marker fill color. Defaults to series stroke or chart palette color. */
  fill?: string;
  /** Whether to animate markers with clip reveal. Default: true */
  animate?: boolean;
  /**
   * Optional per-point pixel offset (e.g. scatter jitter). Must be
   * deterministic for a given `(index, seriesIndex)` pair.
   */
  getPointOffset?: (
    index: number,
    seriesIndex: number
  ) => { x: number; y: number };
}

interface PointAt {
  index: number;
  cx: number;
  cy: number;
  revealDelay: number;
}

interface MarkerStyle {
  fill: string;
  stroke: string;
  strokeWidth: number;
  ringGap: number;
  outlineWidth: number;
  outlineColor?: string;
  radius: number;
}

export function SeriesMarkers({
  dataKey,
  fill,
  stroke,
  strokeWidth = 2,
  ringGap = 2,
  outlineWidth = 0,
  outlineColor,
  radius = 5,
  animate = true,
  fadeOnHover = true,
  inactiveOpacity = 0.5,
  inactiveBlur = 2,
  enterBlur = 2,
  showActiveHighlight = true,
  getPointOffset,
}: SeriesMarkersProps) {
  // Stable slice only. Hover-driven dim + active-highlight live in the inner
  // <SeriesMarkersDimWrapper> / <SeriesMarkersActiveHighlight> components, so
  // mouse motion does not re-render the full point grid.
  const {
    data,
    xScale,
    innerWidth,
    enterTransition,
    animationDuration,
    revealEpoch,
    isLoaded,
    xAccessor,
    lines,
  } = useChartStable();

  const seriesIndex = useMemo(() => {
    const index = lines.findIndex((line) => line.dataKey === dataKey);
    return index >= 0 ? index : 0;
  }, [lines, dataKey]);

  const seriesConfig = lines[seriesIndex];
  const yScale = useYScale(seriesConfig?.yAxisId);
  const seriesColor =
    defaultScatterColors[seriesIndex % defaultScatterColors.length] ??
    defaultScatterColors[0];

  const resolvedFill = fill ?? seriesConfig?.stroke ?? seriesColor;
  const resolvedStroke = stroke ?? resolvedFill;

  const visualExtent = useMemo(
    () =>
      getSeriesMarkerVisualExtent({
        radius,
        strokeWidth,
        ringGap,
        outlineWidth,
        showActiveHighlight,
      }),
    [radius, strokeWidth, ringGap, outlineWidth, showActiveHighlight]
  );

  const revealDurationSec =
    clipRevealTransition(enterTransition).duration ?? animationDuration / 1000;
  const enterDuration = 0.5;
  const isRevealing = animate && !isLoaded;

  const getY = useCallback(
    (d: Record<string, unknown>) => {
      const value = d[dataKey];
      return typeof value === "number" ? (yScale(value) ?? 0) : null;
    },
    [dataKey, yScale]
  );

  const points = useMemo<PointAt[]>(
    () =>
      data.flatMap((d, index) => {
        const cy = getY(d);
        if (cy === null) {
          return [];
        }
        const offset = getPointOffset?.(index, seriesIndex);
        const cx = (xScale(xAccessor(d)) ?? 0) + (offset?.x ?? 0);
        const leadingEdge = Math.max(0, cx - visualExtent);
        const revealDelay =
          innerWidth > 0 && isRevealing
            ? (leadingEdge / innerWidth) * revealDurationSec
            : 0;

        return [{ index, cx, cy: cy + (offset?.y ?? 0), revealDelay }];
      }),
    [
      data,
      getY,
      xScale,
      xAccessor,
      innerWidth,
      isRevealing,
      revealDurationSec,
      visualExtent,
      getPointOffset,
      seriesIndex,
    ]
  );

  // Memo so the inner <SeriesMarkersActiveHighlight> sees a stable prop and
  // can be cheaply re-rendered on hover without re-creating the spread.
  const markerStyle = useMemo<MarkerStyle>(
    () => ({
      fill: resolvedFill,
      stroke: resolvedStroke,
      strokeWidth,
      ringGap,
      outlineWidth,
      outlineColor,
      radius,
    }),
    [
      resolvedFill,
      resolvedStroke,
      strokeWidth,
      ringGap,
      outlineWidth,
      outlineColor,
      radius,
    ]
  );

  if (isRevealing) {
    return (
      <g>
        {points.map((point) => (
          <SeriesPointMarker
            cx={point.cx}
            cy={point.cy}
            dataKey={dataKey}
            enterBlur={enterBlur}
            enterDuration={enterDuration}
            index={point.index}
            key={`${dataKey}-${point.index}`}
            revealDelay={point.revealDelay}
            revealEpoch={revealEpoch ?? 0}
            {...markerStyle}
          />
        ))}
      </g>
    );
  }

  // Stable base layer — its children come from the parent and stay
  // referentially identical when the dim wrapper re-renders for hover.
  // Plain dots render as bare circles (no component per point) — same
  // output as `StaticSeriesPointMarker`, a fraction of the mount cost.
  const plainDots = strokeWidth <= 0 && outlineWidth <= 0;
  const baseMarkers = points.map((point) =>
    plainDots ? (
      <circle
        cx={point.cx}
        cy={point.cy}
        fill={resolvedFill}
        key={`${dataKey}-${point.index}`}
        r={radius}
      />
    ) : (
      <StaticSeriesPointMarker
        cx={point.cx}
        cy={point.cy}
        key={`${dataKey}-${point.index}`}
        {...markerStyle}
      />
    )
  );
  const activeScale = showActiveHighlight ? 1.35 : 1;

  return (
    <g>
      <SeriesMarkersDimWrapper
        enabled={fadeOnHover}
        inactiveBlur={inactiveBlur}
        inactiveOpacity={inactiveOpacity}
        seriesIndex={seriesIndex}
      >
        {baseMarkers}
      </SeriesMarkersDimWrapper>
      <SeriesMarkersActiveHighlight
        activeScale={activeScale}
        dataKey={dataKey}
        enabled={fadeOnHover}
        markerStyle={markerStyle}
        points={points}
      />
    </g>
  );
}

SeriesMarkers.displayName = "SeriesMarkers";

interface SeriesMarkersDimWrapperProps {
  enabled: boolean;
  inactiveOpacity: number;
  inactiveBlur: number;
  seriesIndex: number;
  children: ReactNode;
}

/**
 * Wraps the stable point grid with hover-driven opacity + blur. Subscribes to
 * hover internally so the grid (passed as `children`) keeps a stable reference
 * and React skips reconciling it when this wrapper re-renders.
 */
const selectIsTooltipShown = (hover: ChartHoverContextValue) =>
  hover.tooltipData !== null;

function SeriesMarkersDimWrapper({
  enabled,
  inactiveOpacity,
  inactiveBlur,
  seriesIndex,
  children,
}: SeriesMarkersDimWrapperProps) {
  const isHovered = useChartHoverSelector(selectIsTooltipShown);
  const { hoveredIndex: legendHoveredIndex } = useChartLegendHover();
  const isLegendDimmed =
    legendHoveredIndex !== null && legendHoveredIndex !== seriesIndex;
  const dimBase = enabled && (isHovered || isLegendDimmed);
  return (
    <g
      opacity={dimBase ? inactiveOpacity : 1}
      style={{
        transition: "opacity 0.15s ease-in-out, filter 0.15s ease-in-out",
        filter:
          dimBase && inactiveBlur > 0 ? `blur(${inactiveBlur}px)` : "none",
      }}
    >
      {children}
    </g>
  );
}

interface SeriesMarkersActiveHighlightProps {
  dataKey: string;
  enabled: boolean;
  points: PointAt[];
  markerStyle: MarkerStyle;
  activeScale: number;
}

/**
 * Renders the scaled "active" marker on top of the base grid. Subscribes to
 * hover internally; the parent doesn't re-render on cursor motion.
 */
function SeriesMarkersActiveHighlight({
  dataKey,
  enabled,
  points,
  markerStyle,
  activeScale,
}: SeriesMarkersActiveHighlightProps) {
  const { tooltipData } = useChartHover();
  if (!enabled || tooltipData === null) {
    return null;
  }
  // Nearest-point hover (jittered scatter): only the hovered series' point.
  if (
    tooltipData.activeDataKey !== undefined &&
    tooltipData.activeDataKey !== dataKey
  ) {
    return null;
  }
  const activePoint = points.find((point) => point.index === tooltipData.index);
  if (!activePoint) {
    return null;
  }
  return (
    <StaticSeriesPointMarker
      cx={activePoint.cx}
      cy={activePoint.cy}
      scale={activeScale}
      {...markerStyle}
    />
  );
}

export default SeriesMarkers;

import type { CurveFactory } from "d3-shape";
import { line as d3Line } from "d3-shape";
import { fastShapePath } from "./fast-path";

export interface SeriesPathPoint {
  x: number;
  y: number;
  key: string;
}

export function computeSeriesPathPoints(
  data: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  xScale: (value: Date) => number | undefined,
  yScale: (value: number) => number | undefined,
  dataKey: string
): SeriesPathPoint[] {
  return data.map((datum, index) => {
    const xValue = xAccessor(datum);
    const yValue = datum[dataKey];
    return {
      x: xScale(xValue) ?? 0,
      y: typeof yValue === "number" ? (yScale(yValue) ?? 0) : 0,
      key: String(xValue.getTime?.() ?? index),
    };
  });
}

export function interpolateSeriesPathPoints(
  from: SeriesPathPoint[],
  to: SeriesPathPoint[],
  progress: number
): SeriesPathPoint[] {
  if (progress >= 1) {
    return to;
  }
  if (progress <= 0) {
    return from.length > 0 ? from : to;
  }

  const fromByKey = new Map(from.map((point) => [point.key, point]));

  return to.map((target, index) => {
    const source = fromByKey.get(target.key);
    if (source) {
      return {
        key: target.key,
        x: source.x + (target.x - source.x) * progress,
        y: source.y + (target.y - source.y) * progress,
      };
    }

    const previousTarget = index > 0 ? to[index - 1] : undefined;
    const previousSource = previousTarget
      ? fromByKey.get(previousTarget.key)
      : undefined;
    const nextTarget = index < to.length - 1 ? to[index + 1] : undefined;
    const nextSource = nextTarget ? fromByKey.get(nextTarget.key) : undefined;
    const anchor = previousSource ?? nextSource ?? from[0] ?? target;

    return {
      key: target.key,
      x: anchor.x + (target.x - anchor.x) * progress,
      y: anchor.y + (target.y - anchor.y) * progress,
    };
  });
}

export function seriesPathFromPoints(
  points: SeriesPathPoint[],
  curve: CurveFactory
): string {
  if (points.length === 0) {
    return "";
  }

  const generator = d3Line<SeriesPathPoint>()
    .x((point) => point.x)
    .y((point) => point.y)
    .curve(curve);

  return fastShapePath(generator, points);
}

const CURVE_SEGMENT_STEPS = 12;

/**
 * Records a d3 curve as a dense polyline (beziers subdivided) so the rendered
 * curve can be sampled as y(x).
 */
class PolylineRecorder {
  points: SeriesPathPoint[] = [];
  private x = 0;
  private y = 0;

  private push(x: number, y: number) {
    this.points.push({ x, y, key: "" });
    this.x = x;
    this.y = y;
  }

  moveTo(x: number, y: number) {
    this.push(x, y);
  }

  lineTo(x: number, y: number) {
    this.push(x, y);
  }

  bezierCurveTo(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    x: number,
    y: number
  ) {
    const x0 = this.x;
    const y0 = this.y;
    for (let step = 1; step <= CURVE_SEGMENT_STEPS; step++) {
      const t = step / CURVE_SEGMENT_STEPS;
      const u = 1 - t;
      const a = u * u * u;
      const b = 3 * u * u * t;
      const c = 3 * u * t * t;
      const d = t * t * t;
      this.push(
        a * x0 + b * x1 + c * x2 + d * x,
        a * y0 + b * y1 + c * y2 + d * y
      );
    }
  }

  quadraticCurveTo(x1: number, y1: number, x: number, y: number) {
    const x0 = this.x;
    const y0 = this.y;
    for (let step = 1; step <= CURVE_SEGMENT_STEPS; step++) {
      const t = step / CURVE_SEGMENT_STEPS;
      const u = 1 - t;
      this.push(
        u * u * x0 + 2 * u * t * x1 + t * t * x,
        u * u * y0 + 2 * u * t * y1 + t * t * y
      );
    }
  }

  closePath() {
    // Open series paths only.
  }
}

/** Flattens the curve through `points` into a dense polyline sorted by x. */
export function flattenSeriesPath(
  points: SeriesPathPoint[],
  curve: CurveFactory
): SeriesPathPoint[] {
  if (points.length < 2) {
    return points;
  }
  const recorder = new PolylineRecorder();
  d3Line<SeriesPathPoint>()
    .x((point) => point.x)
    .y((point) => point.y)
    .curve(curve)
    // Minimal CanvasPath recorder — only implements the commands d3 curves emit.
    .context(recorder as unknown as CanvasRenderingContext2D)(points);
  return recorder.points.sort((a, b) => a.x - b.x);
}

/** y of a polyline (sorted by x) at `x`, clamped to its end points. */
export function samplePolylineY(polyline: SeriesPathPoint[], x: number) {
  const first = polyline[0];
  const last = polyline.at(-1);
  if (!(first && last)) {
    return 0;
  }
  if (x <= first.x) {
    return first.y;
  }
  if (x >= last.x) {
    return last.y;
  }
  let low = 0;
  let high = polyline.length - 1;
  while (high - low > 1) {
    const mid = Math.floor((low + high) / 2);
    if ((polyline[mid]?.x ?? 0) <= x) {
      low = mid;
    } else {
      high = mid;
    }
  }
  const a = polyline[low] ?? first;
  const b = polyline[high] ?? last;
  const span = b.x - a.x;
  return span > 0 ? a.y + ((b.y - a.y) * (x - a.x)) / span : a.y;
}

/**
 * Vertical morph between two polylines: both are sampled on a shared x grid
 * spanning the target's extent, and only y is interpolated, so the line rises
 * and falls into its new shape instead of points sliding sideways.
 */
export function morphSeriesPolylines(
  from: SeriesPathPoint[],
  to: SeriesPathPoint[],
  progress: number,
  sampleSpacingPx = 2
): SeriesPathPoint[] {
  const first = to[0];
  const last = to.at(-1);
  if (!(first && last) || from.length === 0) {
    return to;
  }
  const span = last.x - first.x;
  const count = Math.max(2, Math.ceil(span / sampleSpacingPx) + 1);
  const result: SeriesPathPoint[] = new Array(count);
  for (let index = 0; index < count; index++) {
    const x = first.x + (span * index) / (count - 1);
    const fromY = samplePolylineY(from, x);
    const toY = samplePolylineY(to, x);
    result[index] = { x, y: fromY + (toY - fromY) * progress, key: "" };
  }
  return result;
}

/** Data-only signature (x/y values), ignoring scale domain and width. */
export function seriesDataSignature(
  renderData: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  dataKey: string
): string {
  return renderData
    .map((datum) => {
      const yValue = datum[dataKey];
      return `${xAccessor(datum).getTime()}:${typeof yValue === "number" ? yValue : ""}`;
    })
    .join(",");
}

export function seriesPathTransitionSignature({
  renderData,
  xAccessor,
  dataKey,
  innerWidth,
  xDomainMin,
  xDomainMax,
}: {
  renderData: Record<string, unknown>[];
  xAccessor: (datum: Record<string, unknown>) => Date;
  dataKey: string;
  innerWidth: number;
  xDomainMin: number;
  xDomainMax: number;
}): string {
  return seriesPathTransitionSignatureFromData(
    seriesDataSignature(renderData, xAccessor, dataKey),
    { innerWidth, xDomainMin, xDomainMax }
  );
}

/**
 * {@link seriesPathTransitionSignature} from an already-built
 * {@link seriesDataSignature}, so callers needing both walk the data once.
 */
export function seriesPathTransitionSignatureFromData(
  dataSignature: string,
  {
    innerWidth,
    xDomainMin,
    xDomainMax,
  }: { innerWidth: number; xDomainMin: number; xDomainMax: number }
): string {
  return `${innerWidth}|${xDomainMin}|${xDomainMax}|${dataSignature}`;
}

"use client";

import { MotionGlobalConfig } from "motion/react";
import { memo, useLayoutEffect, useRef } from "react";
import { DEFAULT_ANIMATION_EASING } from "./animation";

export interface SeriesPointMarkerStyle {
  /** Fill color for the inner circle */
  fill?: string;
  /** Outer ring stroke color. Default: same as `fill` */
  stroke?: string;
  /** Outer ring stroke width in px. Default: 2. Set to 0 to disable. */
  strokeWidth?: number;
  /** Gap between the inner fill and outer ring in px. Default: 2 */
  ringGap?: number;
  /** Optional outer outline beyond the ring. Default: 0 */
  outlineWidth?: number;
  /** Outer outline color. Default: same as `stroke` */
  outlineColor?: string;
  /** Point radius in px. Default: 5 */
  radius?: number;
  /** Dim non-active points while hovering. Default: true */
  fadeOnHover?: boolean;
  /** Opacity for non-hovered points when `fadeOnHover` is true. Default: 0.5 */
  inactiveOpacity?: number;
  /**
   * Blur in px for non-hovered points when `fadeOnHover` is true.
   * Applied once on the dimmed layer (not per dot) for performance. Default: 2
   */
  inactiveBlur?: number;
  /** Initial blur in px during enter animation. Default: 2 */
  enterBlur?: number;
  /** Enlarge the active point while hovering. Default: true */
  showActiveHighlight?: boolean;
}

interface MarkerCirclesProps {
  fill?: string;
  stroke?: string;
  strokeWidth: number;
  ringGap: number;
  outlineWidth: number;
  outlineColor?: string;
  radius: number;
}

function MarkerCircles({
  fill,
  stroke,
  strokeWidth,
  ringGap,
  outlineWidth,
  outlineColor,
  radius,
}: MarkerCirclesProps) {
  const resolvedStroke = stroke ?? fill ?? "currentColor";
  const resolvedOutlineColor = outlineColor ?? resolvedStroke;
  const ringOuter = strokeWidth > 0 ? radius + ringGap + strokeWidth : radius;
  const outlineRadius = outlineWidth > 0 ? ringOuter + outlineWidth / 2 : 0;

  return (
    <>
      {outlineWidth > 0 ? (
        <circle
          cx={0}
          cy={0}
          fill="none"
          r={outlineRadius}
          stroke={resolvedOutlineColor}
          strokeWidth={outlineWidth}
        />
      ) : null}
      <circle cx={0} cy={0} fill={fill} r={radius} />
      {strokeWidth > 0 ? (
        <circle
          cx={0}
          cy={0}
          fill="none"
          r={radius + ringGap + strokeWidth / 2}
          stroke={resolvedStroke}
          strokeWidth={strokeWidth}
        />
      ) : null}
    </>
  );
}

export interface StaticSeriesPointMarkerProps extends SeriesPointMarkerStyle {
  cx: number;
  cy: number;
  scale?: number;
}

export const StaticSeriesPointMarker = memo(function StaticSeriesPointMarker({
  cx,
  cy,
  scale = 1,
  fill,
  stroke,
  strokeWidth = 2,
  ringGap = 2,
  outlineWidth = 0,
  outlineColor,
  radius = 5,
}: StaticSeriesPointMarkerProps) {
  // Plain dot (no ring / outline): one positioned circle instead of a
  // translated group, halving DOM nodes for large scatter plots. Scaling a
  // lone circle about its centre is the same as scaling its radius.
  if (strokeWidth <= 0 && outlineWidth <= 0) {
    return <circle cx={cx} cy={cy} fill={fill} r={radius * scale} />;
  }
  return (
    <g transform={`translate(${cx}, ${cy}) scale(${scale})`}>
      <MarkerCircles
        fill={fill}
        outlineColor={outlineColor}
        outlineWidth={outlineWidth}
        radius={radius}
        ringGap={ringGap}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    </g>
  );
});

export interface SeriesPointMarkerProps extends SeriesPointMarkerStyle {
  dataKey: string;
  index: number;
  cx: number;
  cy: number;
  revealDelay: number;
  revealEpoch: number;
  enterDuration: number;
}

/** Marker style once the enter fade has finished (what Motion left inline). */
const MARKER_ENTERED_STYLE = { opacity: 1, filter: "blur(0px)" } as const;

/**
 * Enter marker — used only while the chart reveal is running.
 *
 * The fade/unblur is a Web Animation, not a Motion component: same keyframes,
 * delay, duration and easing (`DEFAULT_ANIMATION_EASING` is the chart enter
 * curve `[0.85, 0, 0.15, 1]`), but run by the browser, so a reveal with many
 * markers costs no per-frame JS and no Motion visual element per point. The
 * element renders its entered style and the animation's `backwards` fill
 * holds the hidden keyframe through the delay, before first paint. Like
 * Motion's mount animation the timing is fixed when it starts (a new
 * `revealEpoch` replays it), and `MotionGlobalConfig.skipAnimations` (OG
 * screenshots) shows the end state.
 */
export function SeriesPointMarker({
  dataKey,
  index,
  cx,
  cy,
  enterBlur = 2,
  revealDelay,
  revealEpoch,
  enterDuration,
  fill,
  stroke,
  strokeWidth = 2,
  ringGap = 2,
  outlineWidth = 0,
  outlineColor,
  radius = 5,
}: SeriesPointMarkerProps) {
  const enterRef = useRef<SVGGElement>(null);
  const timingRef = useRef({ enterBlur, revealDelay, enterDuration });
  useLayoutEffect(() => {
    timingRef.current = { enterBlur, revealDelay, enterDuration };
  }, [enterBlur, revealDelay, enterDuration]);

  // Replays per reveal epoch only; the timing is read when it starts.
  useLayoutEffect(() => {
    const element = enterRef.current;
    if (
      !element ||
      typeof element.animate !== "function" ||
      MotionGlobalConfig.skipAnimations ||
      MotionGlobalConfig.instantAnimations
    ) {
      return;
    }
    const timing = timingRef.current;
    const animation = element.animate(
      [
        { opacity: 0, filter: `blur(${timing.enterBlur}px)` },
        MARKER_ENTERED_STYLE,
      ],
      {
        delay: timing.revealDelay * 1000,
        duration: timing.enterDuration * 1000,
        easing: DEFAULT_ANIMATION_EASING,
        fill: "backwards",
      }
    );
    return () => animation.cancel();
  }, [revealEpoch]);

  return (
    <g transform={`translate(${cx}, ${cy})`}>
      <g
        key={`${dataKey}-${index}-${revealEpoch}`}
        ref={enterRef}
        style={MARKER_ENTERED_STYLE}
      >
        <MarkerCircles
          fill={fill}
          outlineColor={outlineColor}
          outlineWidth={outlineWidth}
          radius={radius}
          ringGap={ringGap}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      </g>
    </g>
  );
}

export function getSeriesMarkerVisualExtent(
  style: Pick<
    SeriesPointMarkerStyle,
    | "radius"
    | "strokeWidth"
    | "ringGap"
    | "outlineWidth"
    | "showActiveHighlight"
  >
): number {
  const radius = style.radius ?? 5;
  const strokeWidth = style.strokeWidth ?? 2;
  const ringGap = style.ringGap ?? 2;
  const outlineWidth = style.outlineWidth ?? 0;
  const showActiveHighlight = style.showActiveHighlight ?? true;
  const ring = strokeWidth > 0 ? ringGap + strokeWidth : 0;
  const outline = outlineWidth > 0 ? outlineWidth : 0;
  const highlightPad = showActiveHighlight ? radius * 0.35 : 0;
  return radius + ring + outline + highlightPad + 2;
}

"use client";

import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";

/**
 * Highlight band painted across the text. The gradient is 3× the text width
 * with the band in its middle third, so at either end of the sweep the visible
 * window is solid `--color` and the band enters/leaves fully off-text.
 */
const SHIMMER_GRADIENT =
  "linear-gradient(90deg, var(--color) 0%, var(--color) 40%, var(--shimmering-color) 50%, var(--color) 60%, var(--color) 100%)";
const SHIMMER_BG_SIZE = "300% 100%";
/** Band off the right edge → band off the left edge (left-to-right sweep). */
const SWEEP_FROM = "100% 0%";
const SWEEP_TO = "0% 0%";

export type ShimmeringTextProps = Omit<
  ComponentProps<typeof m.span>,
  "children"
> & {
  /** The text to render with the shimmering effect. */
  text: string;
  /**
   * Duration in seconds for one shimmer sweep across the text.
   * @defaultValue 1.5
   */
  duration?: number;
  /**
   * Pause the shimmer (e.g. when the hero leaves the viewport).
   * @defaultValue false
   */
  paused?: boolean;
  /**
   * Legacy alias for `paused`.
   * @defaultValue false
   */
  isStopped?: boolean;
};

export function ShimmeringText({
  text,
  duration = 1.5,
  isStopped = false,
  paused = false,
  className,
  style,
  ...props
}: ShimmeringTextProps) {
  const reducedMotion = useReducedMotion();
  const stopped = isStopped || paused || reducedMotion === true;

  // One gradient across the whole run (rather than per-character colors), so
  // the highlight is a smooth band and RTL / cursive scripts keep their glyph
  // joining and visual order.
  return (
    <LazyMotion features={domAnimation}>
      <m.span
        animate={
          stopped
            ? { backgroundPosition: SWEEP_TO }
            : { backgroundPosition: [SWEEP_FROM, SWEEP_TO] }
        }
        className={cn(
          "inline-block select-none whitespace-nowrap leading-none",
          "[--color:var(--muted-foreground)] [--shimmering-color:var(--foreground)]",
          className
        )}
        initial={{ backgroundPosition: SWEEP_FROM }}
        style={{
          backgroundImage: SHIMMER_GRADIENT,
          backgroundSize: SHIMMER_BG_SIZE,
          backgroundRepeat: "no-repeat",
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent",
          WebkitTextFillColor: "transparent",
          ...style,
        }}
        transition={
          stopped
            ? { duration: duration * 0.5, ease: "easeOut" }
            : {
                duration,
                ease: "easeInOut",
                repeat: Number.POSITIVE_INFINITY,
                repeatType: "loop",
                repeatDelay: duration * 0.4,
              }
        }
        {...props}
      >
        {text}
      </m.span>
    </LazyMotion>
  );
}

import {
  type CurveFactory,
  curveLinear,
  curveMonotoneX,
  curveNatural,
  curveStep,
  area as d3Area,
  line as d3Line,
} from "d3-shape";

export type SparklineCurve = "linear" | "monotone" | "natural" | "step";

export type SparklineDataKey<T> =
  | keyof T
  | ((datum: T, index: number) => number);

export interface SparklinePadding {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface SparklinePoint {
  x: number;
  y: number;
  /** NaN when the source value is missing. */
  value: number;
}

export interface SparklineLayout {
  points: SparklinePoint[];
  /** Pixel y of the baseline (0, clamped into the domain). */
  baselineY: number;
  /** Pixel width of one bar slot (bars only; 0 for line/area). */
  band: number;
  domain: [number, number];
}

const curves: Record<SparklineCurve, CurveFactory> = {
  linear: curveLinear,
  monotone: curveMonotoneX,
  natural: curveNatural,
  step: curveStep,
};

export function resolveSparklinePadding(
  padding: number | Partial<SparklinePadding> | undefined,
  fallback: number
): SparklinePadding {
  if (typeof padding === "number" || padding === undefined) {
    const p = padding ?? fallback;
    return { top: p, right: p, bottom: p, left: p };
  }
  return {
    top: padding.top ?? fallback,
    right: padding.right ?? fallback,
    bottom: padding.bottom ?? fallback,
    left: padding.left ?? fallback,
  };
}

export function resolveSparklineValues<T>(
  data: readonly T[],
  dataKey: SparklineDataKey<T>
): number[] {
  return data.map((datum, index) => {
    const raw =
      typeof dataKey === "function"
        ? dataKey(datum, index)
        : (datum as Record<PropertyKey, unknown>)[dataKey as PropertyKey];
    const value = typeof raw === "number" ? raw : Number(raw);
    return raw === null || raw === undefined ? Number.NaN : value;
  });
}

/**
 * Value domain for the sparkline. Bars always include zero so heights read
 * honestly; line/area hug the data unless `includeZero` is set.
 */
export function computeSparklineDomain(
  values: readonly number[],
  options: { yDomain?: [number?, number?]; includeZero?: boolean } = {}
): [number, number] {
  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  for (const value of values) {
    if (Number.isFinite(value)) {
      if (value < min) {
        min = value;
      }
      if (value > max) {
        max = value;
      }
    }
  }
  if (min === Number.POSITIVE_INFINITY) {
    min = 0;
    max = 0;
  }
  if (options.includeZero) {
    min = Math.min(min, 0);
    max = Math.max(max, 0);
  }
  min = options.yDomain?.[0] ?? min;
  max = options.yDomain?.[1] ?? max;
  if (min === max) {
    // Flat series: centre the line instead of pinning it to an edge.
    return [min - 1, max + 1];
  }
  return [min, max];
}

export function computeSparklineLayout(
  values: readonly number[],
  options: {
    width: number;
    height: number;
    padding: SparklinePadding;
    domain: [number, number];
    kind: "point" | "band";
  }
): SparklineLayout {
  const { width, height, padding, domain, kind } = options;
  const innerWidth = Math.max(0, width - padding.left - padding.right);
  const innerHeight = Math.max(0, height - padding.top - padding.bottom);
  const [d0, d1] = domain;
  const yOf = (value: number) =>
    padding.top + innerHeight - ((value - d0) / (d1 - d0)) * innerHeight;

  const n = values.length;
  const band = kind === "band" && n > 0 ? innerWidth / n : 0;
  const step = n > 1 ? innerWidth / (n - 1) : 0;

  const points = values.map((value, i) => ({
    x:
      kind === "band"
        ? padding.left + band * (i + 0.5)
        : padding.left + (n > 1 ? step * i : innerWidth / 2),
    y: Number.isFinite(value) ? yOf(value) : Number.NaN,
    value,
  }));

  const baseline = Math.min(Math.max(0, d0), d1);
  return { points, baselineY: yOf(baseline), band, domain };
}

const isDefined = (point: SparklinePoint) => Number.isFinite(point.y);

export function buildSparklineLinePath(
  points: readonly SparklinePoint[],
  curve: SparklineCurve
): string {
  return (
    d3Line<SparklinePoint>()
      .defined(isDefined)
      .x((p) => p.x)
      .y((p) => p.y)
      .curve(curves[curve])(points as SparklinePoint[]) ?? ""
  );
}

export function buildSparklineAreaPath(
  points: readonly SparklinePoint[],
  curve: SparklineCurve,
  baselineY: number
): string {
  return (
    d3Area<SparklinePoint>()
      .defined(isDefined)
      .x((p) => p.x)
      .y0(baselineY)
      .y1((p) => p.y)
      .curve(curves[curve])(points as SparklinePoint[]) ?? ""
  );
}

const round = (value: number) => Math.round(value * 100) / 100;

/** One bar as a path segment, rounding the corners away from the baseline. */
export function buildSparklineBarSegment(
  cx: number,
  barWidth: number,
  y: number,
  baselineY: number,
  radius: number
): string {
  const height = Math.abs(baselineY - y);
  if (height === 0 || barWidth <= 0) {
    return "";
  }
  const x0 = round(cx - barWidth / 2);
  const x1 = round(cx + barWidth / 2);
  const r = Math.min(radius, barWidth / 2, height);
  const up = y < baselineY;
  const tip = round(y);
  const base = round(baselineY);
  if (r <= 0) {
    return `M${x0},${base}V${tip}H${x1}V${base}Z`;
  }
  const dir = up ? 1 : -1;
  const rr = round(r);
  const sweep = up ? 1 : 0;
  return (
    `M${x0},${base}V${round(tip + dir * r)}` +
    `A${rr},${rr} 0 0 ${sweep} ${round(x0 + r)},${tip}` +
    `H${round(x1 - r)}` +
    `A${rr},${rr} 0 0 ${sweep} ${x1},${round(tip + dir * r)}` +
    `V${base}Z`
  );
}

export function sparklineBarWidth(band: number, gap: number): number {
  return Math.max(1, band - gap);
}

/** All bars as a single path — one DOM node regardless of point count. */
export function buildSparklineBarsPath(
  layout: SparklineLayout,
  options: { gap: number; radius: number }
): string {
  const barWidth = sparklineBarWidth(layout.band, options.gap);
  let d = "";
  for (const point of layout.points) {
    if (Number.isFinite(point.y)) {
      d += buildSparklineBarSegment(
        point.x,
        barWidth,
        point.y,
        layout.baselineY,
        options.radius
      );
    }
  }
  return d;
}

/** Nearest data index for a pointer x position (in chart pixels). */
export function sparklineIndexAtX(
  x: number,
  options: {
    count: number;
    width: number;
    padding: SparklinePadding;
    kind: "point" | "band";
  }
): number | null {
  const { count, width, padding, kind } = options;
  if (count === 0) {
    return null;
  }
  const innerWidth = width - padding.left - padding.right;
  if (innerWidth <= 0) {
    return 0;
  }
  const t = (x - padding.left) / innerWidth;
  const raw =
    kind === "band" ? Math.floor(t * count) : Math.round(t * (count - 1));
  return Math.min(count - 1, Math.max(0, raw));
}

function formatCompact(value: number): string {
  return new Intl.NumberFormat("en", {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(value);
}

/** Screen-reader summary, e.g. "12 points, from 3.1K to 4.2K, up 35%". */
export function describeSparkline(values: readonly number[]): string {
  const finite = values.filter(Number.isFinite);
  if (finite.length === 0) {
    return "No data";
  }
  const first = finite[0] as number;
  const last = finite.at(-1) as number;
  let summary = `${finite.length} points, from ${formatCompact(first)} to ${formatCompact(last)}`;
  if (first !== 0) {
    const change = ((last - first) / Math.abs(first)) * 100;
    const direction = change >= 0 ? "up" : "down";
    summary += `, ${direction} ${Math.abs(Math.round(change))}%`;
  }
  return summary;
}

/**
 * Tween frame between two layouts. Points take the target x; the previous
 * shape is resampled onto the target grid so series of different lengths
 * rise and fall into place. Missing values snap.
 */
export function interpolateSparklineLayout(
  from: SparklineLayout,
  to: SparklineLayout,
  t: number
): SparklineLayout {
  const m = from.points.length;
  const n = to.points.length;
  const fromYAt = (i: number): number => {
    if (m === 0) {
      return Number.NaN;
    }
    if (m === n) {
      return from.points[i]?.y ?? Number.NaN;
    }
    const position = n > 1 ? (i / (n - 1)) * (m - 1) : 0;
    const lo = Math.floor(position);
    const a = from.points[lo]?.y ?? Number.NaN;
    const b = from.points[Math.min(m - 1, lo + 1)]?.y ?? Number.NaN;
    return a + (b - a) * (position - lo);
  };
  return {
    ...to,
    baselineY: from.baselineY + (to.baselineY - from.baselineY) * t,
    points: to.points.map((point, i) => {
      const fromY = fromYAt(i);
      return Number.isFinite(fromY) && Number.isFinite(point.y)
        ? { ...point, y: fromY + (point.y - fromY) * t }
        : point;
    }),
  };
}

