  showCrosshair: showCrosshairProp,
  showDots = true,
  dotVariant = "dot",
  dotSize = 5,
  dotHaloScale,
  dotHaloOpacity,
  dotHaloBlur,
  dotRadiusFraction,
  dotScale = 1,
  dotStrokeWidth,
  indicatorColor: indicatorColorProp,
  indicatorEndColor,
  indicatorEnd = "plot",
  content,
  rows: rowsRenderer,
  dotColor: dotColorProp,
  children,
  className = "",
  container,
  springConfig,
  matchCrosshair = false,
  damping,
  indicatorDasharray,
  indicatorFadeEdges,
  indicatorFadeLength,
  boxSpringConfig,
