/**
 * Popover-style panel: rounded, 1px border, soft layered shadow and a 1px
 * edge highlight (`before:`) — matches shadcn / coss popovers using only theme
 * tokens (`border`, `--radius`) and Tailwind utilities.
 */
export const TOOLTIP_PANEL_CLASS_NAME =
  "relative min-w-[160px] rounded-xl border not-dark:bg-clip-padding text-chart-tooltip-foreground shadow-lg/5 before:pointer-events-none before:absolute before:inset-0 before:rounded-[calc(var(--radius-xl)-1px)] before:shadow-[0_1px_rgb(0_0_0/0.04)] dark:before:shadow-[0_-1px_rgb(255_255_255/0.06)]";

/** Clips content to the panel's inner radius without clipping the edge highlight. */
export const TOOLTIP_PANEL_INNER_CLASS_NAME =
  "overflow-hidden rounded-[calc(var(--radius-xl)-1px)]";

/** Panel scale/fade-in on show. */
const PANEL_ENTRANCE_SPRING = {
  type: "spring",
  stiffness: 300,
  damping: 25,
} as const;

/**
 * Panel size tween when its content grows or shrinks. Critically damped (no
 * overshoot, so a shrinking panel never dips under its content) and a little
 * quicker than the entrance, so it reads as the panel hugging the new content.
 */
const PANEL_SIZE_SPRING = {
  type: "spring",
  stiffness: 500,
  damping: 45,
} as const;

/** Layout sizes (unaffected by transforms) of the panel and its clip box. */
interface PanelSizes {
  panelWidth: number;
  panelHeight: number;
  clipWidth: number;
  clipHeight: number;
}

const mixNumber = (from: number, to: number, progress: number) =>
  from + (to - from) * progress;

function mixPanelSizes(
  from: PanelSizes,
  to: PanelSizes,
  progress: number
): PanelSizes {
  return {
    panelWidth: mixNumber(from.panelWidth, to.panelWidth, progress),
    panelHeight: mixNumber(from.panelHeight, to.panelHeight, progress),
    clipWidth: mixNumber(from.clipWidth, to.clipWidth, progress),
    clipHeight: mixNumber(from.clipHeight, to.clipHeight, progress),
  };
}

/** One 60 Hz frame (ms). */
const FRAME_MS = 1000 / 60;

/** Observe border-box sizes (what `readBorderBox` reads). */
const BORDER_BOX: ResizeObserverOptions = { box: "border-box" };

const samePanelSizes = (a: PanelSizes, b: PanelSizes) =>
  a.panelWidth === b.panelWidth &&
  a.panelHeight === b.panelHeight &&
  a.clipWidth === b.clipWidth &&
  a.clipHeight === b.clipHeight;

/** Pixel radius from the computed top-left radius, or `null` (e.g. `%`). */
function readPxRadius(element: HTMLElement): number | null {
  const value = getComputedStyle(element).borderTopLeftRadius;
  return value.endsWith("px") ? Number.parseFloat(value) : null;
}

/**
 * Radius `r` (px) as per-axis percentages of the drawn (scaled) size, so the
 * corners stay round while the box is scaled — Motion's own correction.
 */
function correctedRadius(r: number, width: number, height: number): string {
  const x = width === 0 ? 0 : (r / width) * 100;
  const y = height === 0 ? 0 : (r / height) * 100;
  return `${x}% / ${y}%`;
}

const ratio = (drawn: number, layout: number) =>
  layout === 0 ? 1 : drawn / layout;

interface PanelRadii {
  panel: number | null;
  clip: number | null;
  panelInline: string;
  clipInline: string;
}

/** Border-box layout size (fractional, unaffected by transforms). */
function readBorderBox(element: HTMLElement): [number, number] {
  const style = getComputedStyle(element);
  let width = Number.parseFloat(style.width);
  let height = Number.parseFloat(style.height);
  if (!(Number.isFinite(width) && Number.isFinite(height))) {
    return [element.offsetWidth, element.offsetHeight];
  }
  if (style.boxSizing !== "border-box") {
    width +=
      Number.parseFloat(style.paddingLeft) +
      Number.parseFloat(style.paddingRight) +
      Number.parseFloat(style.borderLeftWidth) +
      Number.parseFloat(style.borderRightWidth);
    height +=
      Number.parseFloat(style.paddingTop) +
      Number.parseFloat(style.paddingBottom) +
      Number.parseFloat(style.borderTopWidth) +
      Number.parseFloat(style.borderBottomWidth);
  }
  return [width, height];
}

function readPanelSizes(panel: HTMLElement, clip: HTMLElement): PanelSizes {
  const [panelWidth, panelHeight] = readBorderBox(panel);
  const [clipWidth, clipHeight] = readBorderBox(clip);
  return { panelWidth, panelHeight, clipWidth, clipHeight };
}

/**
 * One frame of the size tween at `progress` (0–1): the panel scaled to the
 * drawn size, the clip kept at its unscaled offset (the border) inside it and
 * scaled to its own drawn size, the content counter-scaled to 1.
 */
function drawPanelTween(
  {
    panel,
    clip,
    content,
  }: { panel: HTMLElement; clip: HTMLElement; content: HTMLElement },
  radii: PanelRadii,
  from: PanelSizes,
  target: PanelSizes,
  progress: number
) {
  const drawn = mixPanelSizes(from, target, progress);
  const scaleX = ratio(drawn.panelWidth, target.panelWidth);
  const scaleY = ratio(drawn.panelHeight, target.panelHeight);
  const clipScaleX = ratio(drawn.clipWidth, target.clipWidth);
  const clipScaleY = ratio(drawn.clipHeight, target.clipHeight);
  panel.style.transform = `scale(${scaleX}, ${scaleY})`;
  const offsetX = clip.offsetLeft / scaleX - clip.offsetLeft;
  const offsetY = clip.offsetTop / scaleY - clip.offsetTop;
  const translate =
    offsetX || offsetY ? `translate3d(${offsetX}px, ${offsetY}px, 0px) ` : "";
  clip.style.transform = `${translate}scale(${clipScaleX / scaleX}, ${
    clipScaleY / scaleY
  })`;
  content.style.transform = `scale(${1 / clipScaleX}, ${1 / clipScaleY})`;
  if (radii.panel !== null) {
    panel.style.borderRadius = correctedRadius(
      radii.panel,
      drawn.panelWidth,
      drawn.panelHeight
    );
  }
  if (radii.clip !== null) {
    clip.style.borderRadius = correctedRadius(
      radii.clip,
      drawn.clipWidth,
      drawn.clipHeight
    );
  }
}

/**
 * Tooltip panel size tween: the same FLIP scale Motion's `layout="size"`
 * produced, without the layout/projection feature bundle (so charts can use
 * `m` + `domAnimation`).
 *
 * When the panel's layout size changes, it is drawn at its previous size and
 * scaled to the new one with `PANEL_SIZE_SPRING` — a 0 → 1000 progress with
 * velocity 0 that starts on the next frame, like Motion's layout animation.
 * The clip box follows the panel (kept at its unscaled border offset) and the
 * content is counter-scaled, so it is drawn at its final size and revealed by
 * the clip — text never stretches. Radii are corrected per axis so the
 * corners stay round. A change mid-tween restarts from the size drawn now.
 *
 * Sizes are layout sizes (computed `width` / `height`, unaffected by
 * transforms), so the layout box (and the `offsetWidth` / `offsetHeight`
 * callers use for flip and clamp) is always the final size and a scaled
 * ancestor (entrance, Studio zoom) does not skew the tween. They are read in a
 * `ResizeObserver` callback (after layout, before paint — the frame the new
 * size first shows), so a re-render never forces a layout of its own; without
 * `ResizeObserver` they are checked after every render. The first
 * measurement only records the size: the entrance owns the mount.
 */
function usePanelSizeTween(
  panelRef: RefObject<HTMLDivElement | null>,
  clipRef: RefObject<HTMLDivElement | null>,
  contentRef: RefObject<HTMLDivElement | null>,
  enabled: boolean
) {
  const checkRef = useRef<(() => void) | null>(null);

  useLayoutEffect(() => {
    const panel = panelRef.current;
    const clip = clipRef.current;
    const content = contentRef.current;
    if (!(enabled && panel && clip && content)) {
      return;
    }

    const observing = typeof ResizeObserver !== "undefined";
    let target = readPanelSizes(panel, clip);
    let from: PanelSizes | null = null;
    let progress = 1;
    let controls: AnimationPlaybackControls | undefined;
    let pendingStart: Process | undefined;
    // Read when a tween starts; the inline values are restored when it ends.
    let radii: PanelRadii | null = null;

    const stop = () => {
      if (pendingStart) {
        cancelFrame(pendingStart);
        pendingStart = undefined;
      }
      controls?.stop();
      controls = undefined;
    };

    const reset = () => {
      panel.style.transform = "";
      clip.style.transform = "";
      content.style.transform = "";
      if (radii) {
        panel.style.borderRadius = radii.panelInline;
        clip.style.borderRadius = radii.clipInline;
        radii = null;
      }
    };

    const draw = (latest: number) => {
      progress = latest;
      if (from && radii) {
        drawPanelTween({ panel, clip, content }, radii, from, target, latest);
      }
    };

    const check = () => {
      const next = readPanelSizes(panel, clip);
      if (samePanelSizes(next, target)) {
        return;
      }
      from =
        from && progress < 1 ? mixPanelSizes(from, target, progress) : target;
      target = next;
      stop();
      radii ??= {
        panel: readPxRadius(panel),
        clip: readPxRadius(clip),
        panelInline: panel.style.borderRadius,
        clipInline: clip.style.borderRadius,
      };
      // This frame draws the old size; the spring starts on the next one.
      draw(0);
      const startTween = (elapsed: number) => {
        controls = animate(0, 1000, {
          ...PANEL_SIZE_SPRING,
          elapsed,
          velocity: 0,
          onUpdate: (latest) => draw(latest / 1000),
          onComplete: () => {
            progress = 1;
            from = null;
            controls = undefined;
            reset();
          },
        });
      };
      // The observer reports after this frame's Motion batch: date the spring
      // from that batch, as if it had started in it (t = 0 is this frame).
      // No batch ran this frame: start now, which still ticks next frame.
      if (observing) {
        const sinceFrame = performance.now() - frameData.timestamp;
        startTween(sinceFrame >= 0 && sinceFrame < FRAME_MS ? sinceFrame : 0);
        return;
      }
      pendingStart = frame.update(() => {
        pendingStart = undefined;
        startTween(0);
      });
    };

    if (!observing) {
      checkRef.current = check;
      return () => {
        checkRef.current = null;
        stop();
        reset();
      };
    }
    // Size changes are read after layout, before paint — never forcing a
    // layout per render — so the old size is drawn in the frame the new
    // layout first shows.
    const observer = new ResizeObserver(check);
    observer.observe(panel, BORDER_BOX);
    observer.observe(clip, BORDER_BOX);
    return () => {
      observer.disconnect();
      stop();
      reset();
    };
  }, [panelRef, clipRef, contentRef, enabled]);

  // No `ResizeObserver`: measure after every render (new content) instead.
  useLayoutEffect(() => {
    checkRef.current?.();
  });
}

const ORIGIN_TOP_LEFT: React.CSSProperties = { transformOrigin: "0 0" };

/**
 * The tooltip panel: an entrance wrapper (scale/slide pivoting on
 * `transformOrigin`) around the styled panel (fade + size), its clip box and
 * the content.
 *
 * `animateSize` tweens the panel to its new size when the content changes
 * (`usePanelSizeTween`). That is a transform, so the panel's layout box (and
 * the `offsetWidth` / `offsetHeight` used for flip and clamp) is always the
 * final size, and position stays with the caller's springs. The clip box
 * follows the panel, and the content is scale-corrected (drawn at its final
 * size and revealed by the clip), so text never stretches. All three are
 * anchored top-left, so the tween has no translate. The entrance lives on the
 * wrapper so its pivot can differ.
 *
 * No size tween on mount (the entrance owns that) or under `MotionConfig`
 * reduced motion. Callers pass `false` under reduced motion and when the
 * position is not animated.
 */
export function TooltipPanel({
  animateSize,
  entrance,
  transformOrigin,
  className,
  style,
  children,
}: {
  animateSize: boolean;
  /** Entrance scale/slide start, or `false` to only fade in. */
  entrance: { scale: number; x?: number } | false;
  transformOrigin: string;
  className: string;
  style: React.CSSProperties;
  children: React.ReactNode;
}) {
  const panelRef = useRef<HTMLDivElement>(null);
  const clipRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  // `MotionConfig reducedMotion` made Motion's layout tween instant.
  const reducedMotionConfig = useReducedMotionConfig() === true;
  usePanelSizeTween(
    panelRef,
    clipRef,
    contentRef,
    animateSize && !reducedMotionConfig
  );

  return (
    <m.div
      animate={{ scale: 1, x: 0 }}
      initial={entrance === false ? false : { x: 0, ...entrance }}
      style={{ transformOrigin }}
      transition={PANEL_ENTRANCE_SPRING}
    >
      <m.div
        animate={{ opacity: 1 }}
        className={className}
        initial={{ opacity: 0 }}
        ref={panelRef}
        style={{ ...style, ...ORIGIN_TOP_LEFT }}
        transition={PANEL_ENTRANCE_SPRING}
      >
        <div
          className={TOOLTIP_PANEL_INNER_CLASS_NAME}
          ref={clipRef}
          style={ORIGIN_TOP_LEFT}
        >
          <div ref={contentRef} style={ORIGIN_TOP_LEFT}>
            {children}
          </div>
        </div>
      </m.div>
    </m.div>
  );
}

/** Spring to `value`, or jump there (no animation) when `snap`. */
function moveTo(
  spring: MotionValue<number>,
  value: number,
  snap: boolean
): void {
  if (snap) {
    spring.jump(value);
  } else {
    spring.set(value);
  }
}

const DEFAULT_TOOLTIP_WIDTH = 180;
const DEFAULT_TOOLTIP_HEIGHT = 80;

/**
 * Stores the box's layout size (`offsetWidth` / `offsetHeight`, unaffected by
 * the size tween's transforms) in the refs, keeping the last size when it
 * reads 0 (e.g. hidden). Returns whether it changed.
 */
function readPanelBoxSize(
  el: HTMLElement,
  widthRef: { current: number },
  heightRef: { current: number }
): boolean {
  const w = el.offsetWidth;
  const h = el.offsetHeight;
  const changed =
    (w > 0 && w !== widthRef.current) || (h > 0 && h !== heightRef.current);
  if (w > 0) {
    widthRef.current = w;
  }
  if (h > 0) {
    heightRef.current = h;
  }
  return changed;
}

/** Panel position beside the cursor: flips left near the right edge and is
 * clamped vertically inside the container. */
function resolveTooltipTarget({
  x,
  flipX = x,
  y,
  width,
  height,
  offset,
  containerWidth,
  containerHeight,
}: {
  x: number;
  flipX?: number;
  y: number;
  width: number;
  height: number;
  offset: number;
  containerWidth: number;
  containerHeight: number;
}) {
  const flipped = flipX + width + offset > containerWidth;
  return {
    flipped,
    left: flipped ? x - offset - width : x + offset,
    top: Math.max(
      offset,
      Math.min(y - height / 2, containerHeight - height - offset)
    ),
  };
}

// Inner-only-on-visible so `useSpring` initializes at the cursor's actual x/y
// instead of (0, 0) on first hover.
export function TooltipBox(props: TooltipBoxProps) {
  const container = useChartPortalContainer(props.containerRef);
  if (!container) {
    return null;
  }
  const inner = props.visible ? (
    <TooltipBoxInner {...props} container={container} key="tooltip-box" />
  ) : null;
  // Own feature scope: the box also renders outside chart roots.
  return (
    <LazyMotion features={domAnimation}>
      {props.exit !== false && props.entrance !== false ? (
        <AnimatePresence>{inner}</AnimatePresence>
      ) : (
        inner
      )}
    </LazyMotion>
  );
}

function TooltipBoxInner({
  x,
  y,
  containerWidth,
  containerHeight,
  offset = 16,
  className = "",
  children,
  left: leftOverride,
  top: topOverride,
  flipped: flippedOverride,
  flipX,
  springConfig,
  animate = true,
  entrance = true,
  replayOnFlip = true,
  animateSize = true,
  panelStyle,
  backgroundColor = chartCssVars.tooltipBackground,
  container,
}: Omit<TooltipBoxProps, "visible" | "containerRef"> & {
  container: HTMLElement;
}) {
  const { tooltipBoxSpring } = useChartConfig();
  // Reduced motion: position jumps instead of springing and the panel skips
  // its scale/slide; opacity fades are kept.
  const reducedMotion = useReducedMotion() === true;
  const effectiveSpring = springConfig ?? tooltipBoxSpring;

  const tooltipRef = useRef<HTMLDivElement>(null);
  // Last measured panel size (flip and clamp are computed from it).
  const tooltipWidthRef = useRef(DEFAULT_TOOLTIP_WIDTH);
  const tooltipHeightRef = useRef(DEFAULT_TOOLTIP_HEIGHT);
  // Non-animated position: React only renders the mount position; the layout
  // effect below writes later positions straight to the element, so each
  // pointer move costs one render instead of render + sync re-render.
  const [staticPosition] = useState(() => ({ left: x, top: y }));
  // First measured position jumps (no spring from the estimated size).
  const hasPositionedRef = useRef(false);

  // Flip side + replay key for the panel entrance. Seeded from the default
  // size (the inner box mounts fresh on every show); refined from the measured
  // width in the layout effect, which only re-renders when the side changes.
  const [flip, setFlip] = useState(() => ({
    flipped: (flipX ?? x) + DEFAULT_TOOLTIP_WIDTH + offset > containerWidth,
    key: 0,
  }));
  const shouldFlipX = flip.flipped;

  const [initialTarget] = useState(() =>
    resolveTooltipTarget({
      x,
      flipX,
      y,
      width: DEFAULT_TOOLTIP_WIDTH,
      height: DEFAULT_TOOLTIP_HEIGHT,
      offset,
      containerWidth,
      containerHeight,
    })
  );
  const animatedLeft = useSpring(initialTarget.left, effectiveSpring);
  const animatedTop = useSpring(initialTarget.top, effectiveSpring);

  // Re-places the panel for the latest props; set by the layout effect below
  // and called by the size observer when the panel resizes.
  const placeRef = useRef<((fromObserver: boolean) => void) | null>(null);
  // The size is read synchronously once, on show. After that a
  // `ResizeObserver` reports changes after layout (before paint), so a
  // pointer move never forces a layout just to measure the panel.
  const sizeObservedRef = useRef(false);

  useLayoutEffect(() => {
    const el = tooltipRef.current;
    if (!el) {
      return;
    }
    if (!sizeObservedRef.current) {
      readPanelBoxSize(el, tooltipWidthRef, tooltipHeightRef);
      sizeObservedRef.current = typeof ResizeObserver !== "undefined";
    }
    const place = (fromObserver: boolean) => {
      const target = resolveTooltipTarget({
        x,
        flipX,
        y,
        width: tooltipWidthRef.current,
        height: tooltipHeightRef.current,
        offset,
        containerWidth,
        containerHeight,
      });
      const updateFlip = () =>
        setFlip((prev) =>
          prev.flipped === target.flipped
            ? prev
            : { flipped: target.flipped, key: prev.key + 1 }
        );
      // The observer runs outside React: commit a side change before paint,
      // as the update from this layout effect would.
      if (fromObserver) {
        flushSync(updateFlip);
      } else {
        updateFlip();
      }
      const tx = target.left;
      const ty = target.top;
      if (!animate) {
        const left = `${tx}px`;
        const top = `${ty}px`;
        if (el.style.left !== left) {
          el.style.left = left;
        }
        if (el.style.top !== top) {
          el.style.top = top;
        }
        return;
      }
      const snap = reducedMotion || !hasPositionedRef.current;
      hasPositionedRef.current = true;
      if (leftOverride === undefined) {
        moveTo(animatedLeft, tx, snap);
      }
      if (topOverride === undefined) {
        moveTo(animatedTop, ty, snap);
      }
    };
    placeRef.current = place;
    place(false);
  }, [
    x,
    flipX,
    y,
    containerWidth,
    containerHeight,
    offset,
    leftOverride,
    topOverride,
    animate,
    animatedLeft,
    animatedTop,
    reducedMotion,
  ]);

  // Content changes resize the panel: re-place it from the new size. The
  // callback runs after layout, so reading the size there is free.
  useLayoutEffect(() => {
    const el = tooltipRef.current;
    if (!el || typeof ResizeObserver === "undefined") {
      return;
    }
    const observer = new ResizeObserver(() => {
      if (readPanelBoxSize(el, tooltipWidthRef, tooltipHeightRef)) {
        placeRef.current?.(true);
      }
    });
    observer.observe(el, BORDER_BOX);
    return () => observer.disconnect();
  }, []);

  const flipKey = replayOnFlip ? flip.key : 0;

  const finalLeft = animate
    ? (leftOverride ?? animatedLeft)
    : staticPosition.left;
  const finalTop = animate ? (topOverride ?? animatedTop) : staticPosition.top;
  const isFlipped = flippedOverride ?? shouldFlipX;
  const transformOrigin = isFlipped ? "right top" : "left top";

  // Internal classes only (no caller className): no tailwind-merge needed.
  const panelClassName = `${TOOLTIP_PANEL_CLASS_NAME}${
    panelStyle?.backgroundColor === undefined &&
    backgroundColor === chartCssVars.tooltipBackground
      ? " bg-chart-tooltip-background"
      : ""
  }${panelStyle?.backdropFilter === undefined ? " backdrop-blur-md" : ""}`;
  const panelStyleResolved = {
    ...(panelStyle?.backgroundColor === undefined && {
      backgroundColor,
    }),
    ...panelStyle,
  };

  if (!entrance) {
    return createPortal(
      <div
        className={cn("pointer-events-none absolute z-50", className)}
        ref={tooltipRef}
        style={{ left: staticPosition.left, top: staticPosition.top }}
      >
        <div
          className={panelClassName}
          style={{ transformOrigin, ...panelStyleResolved }}
        >
          <div className={TOOLTIP_PANEL_INNER_CLASS_NAME}>{children}</div>
        </div>
      </div>,
      container
    );
  }

  return createPortal(
    <m.div
      animate={{ opacity: 1 }}
      className={cn("pointer-events-none absolute z-50", className)}
      exit={{ opacity: 0 }}
      initial={{ opacity: 0 }}
      ref={tooltipRef}
      style={{ left: finalLeft, top: finalTop }}
      transition={{ duration: 0.1 }}
    >
      <TooltipPanel
        // Positions jump in the static path (a re-render mid-commit), which a
        // layout animation would read as a move, and "no motion" means none.
        animateSize={animateSize && animate && !reducedMotion}
        className={panelClassName}
        entrance={
          reducedMotion ? false : { scale: 0.85, x: isFlipped ? 20 : -20 }
        }
        key={flipKey}
        style={panelStyleResolved}
        transformOrigin={transformOrigin}
      >
        {children}
      </TooltipPanel>
    </m.div>,
    container
  );
}

TooltipBox.displayName = "TooltipBox";

export default TooltipBox;

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { intFmt } from "../chart-formatters";

export interface TooltipRow {
  color: string;
  label: string;
  value: string | number;
}

export interface TooltipContentProps {
  title?: string;
  rows: TooltipRow[];
  /** Optional additional content (e.g., markers) */
  children?: ReactNode;
}

export interface TooltipHeaderProps {
  children: ReactNode;
  className?: string;
}

/**
 * Popover-style header row: medium-weight label separated from the body by a
 * full-width border. Use it at the top of custom `ChartTooltip` `content`.
 */
export function TooltipHeader({ children, className }: TooltipHeaderProps) {
  return (
    <div
      className={cn(
        "border-b px-3.5 py-2.5 text-left font-medium text-chart-tooltip-foreground text-sm",
        className
      )}
    >
      {children}
    </div>
  );
}

TooltipHeader.displayName = "TooltipHeader";

export function TooltipContent({ title, rows, children }: TooltipContentProps) {
  const hasBody = rows.length > 0 || Boolean(children);
  return (
    <div>
      {title && <TooltipHeader>{title}</TooltipHeader>}
      {hasBody && (
        <div className="px-3.5 py-3">
          {rows.length > 0 && (
            <div className="space-y-2">
              {rows.map((row) => (
                <div
                  className="flex items-center justify-between gap-6"
                  key={`${row.label}-${row.color}`}
                >
                  <div className="flex min-w-0 items-center gap-2">
                    <span
                      className="size-2 shrink-0 rounded-full"
                      style={{ backgroundColor: row.color }}
                    />
                    <span className="truncate text-chart-tooltip-muted text-sm">
                      {row.label}
                    </span>
                  </div>
                  <span className="text-right font-medium text-chart-tooltip-foreground text-sm tabular-nums">
                    {typeof row.value === "number"
                      ? intFmt(row.value)
                      : row.value}
                  </span>
                </div>
              ))}
            </div>
          )}

          {children && (
            <div
              className={
                rows.length > 0
                  ? "mt-2 transition-opacity duration-200 ease-out"
                  : "transition-opacity duration-200 ease-out"
              }
            >
              {children}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

TooltipContent.displayName = "TooltipContent";

export default TooltipContent;

"use client";

import { m, useSpring, useTransform } from "motion/react";
import { useId } from "react";
import { type SpringConfig, useChartConfig } from "../chart-config-context";
import { chartCssVars } from "../chart-context";

export interface TooltipDotProps {
  x: number;
  y: number;
  visible: boolean;
  color: string;
  /** Core dot radius; half-extent for ring squares. Default: 5 */
  size?: number;
  /** Outline color for the `dot` variant. Default: `var(--chart-background)` */
  strokeColor?: string;
  /**
   * `dot`: outline width around the core (default `0`, no outline).
   * `ring`: ring stroke width (default `1.5`).
   */
  strokeWidth?: number;
  /**
   * `dot` variant: halo radius as a multiple of `size`. The halo is a soft disc
   * in the series color behind the core. `0` hides it. Default: `2.6`
   */
  haloScale?: number;
  /** `dot` variant: halo opacity (0–1). Default: `0.3` */
  haloOpacity?: number;
  /**
   * `dot` variant: Gaussian blur (px) on the halo, turning the disc into a
   * soft glow. `0` keeps a crisp disc. Default: `0`
   */
  haloBlur?: number;
  /** Dot fill or transparent ring around the hovered mark. Default: "dot" */
  variant?: "dot" | "ring";
  /**
   * Ring corner radius as a fraction of side length (0 = square, 0.5 = circle).
   * Same semantics as bar square radius.
   */
  cornerRadiusFraction?: number;
  /** Per-chart override; falls back to `ChartConfigProvider.tooltipSpring`. */
  springConfig?: SpringConfig;
  /** Animate position with a spring. Default: true */
  animate?: boolean;
}

const DEFAULT_HALO_SCALE = 2.6;
const DEFAULT_HALO_OPACITY = 0.3;
/** Entrance spring for the core + halo radius (position uses the tooltip spring). */
const HALO_SPRING = { type: "spring", stiffness: 420, damping: 28 } as const;

function ringCornerRadius(
  halfExtent: number,
  cornerRadiusFraction: number
): number {
  const side = halfExtent * 2;
  return side * Math.max(0, Math.min(0.5, cornerRadiusFraction));
}

function AnimatedRingDot({
  x,
  y,
  halfExtent,
  cornerRadiusFraction,
  fill,
  stroke,
  strokeWidth,
  springConfig,
}: {
  x: number;
  y: number;
  halfExtent: number;
  cornerRadiusFraction: number;
  fill: string;
  stroke: string;
  strokeWidth: number;
  springConfig?: SpringConfig;
}) {
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;
  const animatedX = useSpring(x, effectiveSpring);
  const animatedY = useSpring(y, effectiveSpring);
  const side = halfExtent * 2;
  const rx = ringCornerRadius(halfExtent, cornerRadiusFraction);
  const rectX = useTransform(animatedX, (value) => value - halfExtent);
  const rectY = useTransform(animatedY, (value) => value - halfExtent);

  animatedX.set(x);
  animatedY.set(y);

  return (
    <m.rect
      fill={fill}
      height={side}
      rx={rx}
      ry={rx}
      stroke={stroke}
      strokeWidth={strokeWidth}
      width={side}
      x={rectX}
      y={rectY}
    />
  );
}

export function TooltipDot({
  x,
  y,
  visible,
  color,
  size = 5,
  strokeColor = chartCssVars.background,
  strokeWidth,
  haloScale = DEFAULT_HALO_SCALE,
  haloOpacity = DEFAULT_HALO_OPACITY,
  haloBlur = 0,
  variant = "dot",
  cornerRadiusFraction = 0.25,
  springConfig,
  animate = true,
}: TooltipDotProps) {
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;
  const animatedX = useSpring(x, effectiveSpring);
  const animatedY = useSpring(y, effectiveSpring);
  const haloFilterId = `tooltip-dot-halo-${useId()}`;

  const isRing = variant === "ring";

  if (animate && !isRing) {
    animatedX.set(x);
    animatedY.set(y);
  }

  if (!visible) {
    return null;
  }

  if (isRing) {
    const ringStrokeWidth = strokeWidth ?? 1.5;
    if (animate) {
      return (
        <AnimatedRingDot
          cornerRadiusFraction={cornerRadiusFraction}
          fill="transparent"
          halfExtent={size}
          springConfig={springConfig}
          stroke={color}
          strokeWidth={ringStrokeWidth}
          x={x}
          y={y}
        />
      );
    }

    const side = size * 2;
    const rx = ringCornerRadius(size, cornerRadiusFraction);

    return (
      <rect
        fill="transparent"
        height={side}
        rx={rx}
        ry={rx}
        stroke={color}
        strokeWidth={ringStrokeWidth}
        width={side}
        x={x - size}
        y={y - size}
      />
    );
  }

  const outlineWidth = strokeWidth ?? 0;
  const outline =
    outlineWidth > 0
      ? { stroke: strokeColor, strokeWidth: outlineWidth }
      : undefined;
  const haloRadius = Math.max(0, size * haloScale);
  const showHalo = haloRadius > size && haloOpacity > 0;
  const blurHalo = showHalo && haloBlur > 0;
  const haloFilter = blurHalo ? `url(#${haloFilterId})` : undefined;
  // Filter region: 3× the halo's bounding box leaves room for the blur's
  // falloff without cropping it into a square.
  const haloFilterDefs = blurHalo ? (
    <defs>
      <filter height="300%" id={haloFilterId} width="300%" x="-100%" y="-100%">
        <feGaussianBlur stdDeviation={haloBlur} />
      </filter>
    </defs>
  ) : null;

  if (!animate) {
    return (
      <g>
        {haloFilterDefs}
        {showHalo && (
          <circle
            cx={x}
            cy={y}
            fill={color}
            fillOpacity={haloOpacity}
            filter={haloFilter}
            r={haloRadius}
          />
        )}
        <circle cx={x} cy={y} fill={color} r={size} {...outline} />
      </g>
    );
  }

  return (
    <g>
      {haloFilterDefs}
      {showHalo && (
        <m.circle
          animate={{ r: haloRadius }}
          cx={animatedX}
          cy={animatedY}
          fill={color}
          fillOpacity={haloOpacity}
          filter={haloFilter}
          initial={{ r: size }}
          transition={HALO_SPRING}
        />
      )}
      <m.circle
        animate={{ r: size }}
        cx={animatedX}
        cy={animatedY}
        fill={color}
        initial={{ r: size * 0.5 }}
        transition={HALO_SPRING}
        {...outline}
      />
    </g>
  );
}

TooltipDot.displayName = "TooltipDot";

export default TooltipDot;

"use client";

import { m, useSpring } from "motion/react";
import { useEffect, useId } from "react";
import { type SpringConfig, useChartConfig } from "../chart-config-context";
import { chartCssVars } from "../chart-context";
import {
  type IndicatorFadeEdges,
  indicatorFadeGradientStops,
  resolveVerticalFadeSides,
} from "../indicator-fade";

export type IndicatorWidth =
  | number // Pixel width
  | "line" // 1px line (default)
  | "thin" // 2px
  | "medium" // 4px
  | "thick"; // 8px

export interface TooltipIndicatorProps {
  /** X position in pixels (center of the indicator) */
  x: number;
  /** Height of the indicator */
  height: number;
  /** Whether the indicator is visible */
  visible: boolean;
  /**
   * Width of the indicator - number (pixels) or preset.
   * Ignored if `span` is provided.
   */
  width?: IndicatorWidth;
  /**
   * Number of columns/days to span, with current point centered.
   * Requires `columnWidth` to be set.
   */
  span?: number;
  /** Width of a single column/day in pixels. Required when using `span`. */
  columnWidth?: number;
  /** Primary color at edges (10% and 90%) */
  colorEdge?: string;
  /** Secondary color at center (50%) */
  colorMid?: string;
  /**
   * Bottom colour for a vertical colour ramp: the indicator blends from
   * `colorMid` (top) to `colorEnd` (bottom). Composes with `fadeEdges`.
   */
  colorEnd?: string;
  /**
   * Y (px) where the indicator ends, e.g. the hovered point. Springs with the
   * indicator. Default: `height` (full plot).
   */
  bottom?: number;
  /** Vertical fade: both ends, top, bottom, or none (solid). */
  fadeEdges?: IndicatorFadeEdges | boolean;
  /** Fade zone size as a percentage of indicator height. Default: 10 */
  fadeLength?: number;
  /** Animate position with a spring. Default: true */
  animate?: boolean;
  /** Unique ID for the gradient. Default: generated per instance. */
  gradientId?: string;
  /** Per-chart override; falls back to `ChartConfigProvider.tooltipSpring`. */
  springConfig?: SpringConfig;
  /** SVG stroke dash pattern. When set, renders a dashed stroke instead of a solid fill. */
  strokeDasharray?: string;
}

function resolveWidth(width: IndicatorWidth): number {
  if (typeof width === "number") {
    return width;
  }
  switch (width) {
    case "line":
      return 1;
    case "thin":
      return 2;
    case "medium":
      return 4;
    case "thick":
      return 8;
    default:
      return 1;
  }
}

/** Colour at a gradient `offset` ("40%") on a top → bottom ramp. */
function verticalRampColor(top: string, end: string, offset: string): string {
  const percent = Number.parseFloat(offset);
  if (percent <= 0) {
    return top;
  }
  if (percent >= 100) {
    return end;
  }
  return `color-mix(in srgb, ${end} ${percent}%, ${top})`;
}

// Inner-only-on-visible so `useSpring` initializes at the real cursor x
// instead of 0 on first hover.
export function TooltipIndicator(props: TooltipIndicatorProps) {
  if (!props.visible) {
    return null;
  }
  return <TooltipIndicatorInner {...props} />;
}

function TooltipIndicatorInner({
  x,
  visible,
  height,
  width = "line",
  span,
  columnWidth,
  colorEdge = chartCssVars.crosshair,
  colorMid = chartCssVars.crosshair,
  colorEnd,
  bottom,
  fadeEdges = "both",
  fadeLength = 10,
  animate = true,
  gradientId: gradientIdProp,
  springConfig,
  strokeDasharray,
}: TooltipIndicatorProps) {
  // Per-instance id: a shared id makes every chart on the page resolve
  // `url(#…)` to the first chart's gradient (and its colours).
  const generatedId = useId();
  const gradientId =
    gradientIdProp ?? `tooltip-indicator-gradient-${generatedId}`;
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;

  const pixelWidth =
    span !== undefined && columnWidth !== undefined
      ? span * columnWidth
      : resolveWidth(width);

  const rectX = x - pixelWidth / 2;
  const lineX = x;
  const endY = Math.max(0, Math.min(height, bottom ?? height));
  const animatedX = useSpring(rectX, effectiveSpring);
  const animatedLineX = useSpring(lineX, effectiveSpring);
  const animatedEndY = useSpring(endY, effectiveSpring);

  if (animate) {
    animatedX.set(rectX);
    animatedLineX.set(lineX);
    animatedEndY.set(endY);
  }

  // biome-ignore lint/correctness/useExhaustiveDependencies: we need to jump the animatedX when the visible prop changes
  useEffect(() => {
    animatedX.set(rectX);
    animatedLineX.set(lineX);
    animatedEndY.set(endY);
  }, [animatedLineX, animatedX, animatedEndY, endY, lineX, rectX, visible]);

  const indicatorFill = colorMid || colorEdge;
  const fadeSides = resolveVerticalFadeSides(fadeEdges);
  const dashed = Boolean(strokeDasharray);

  if (dashed) {
    const strokeWidth = Math.max(1, pixelWidth);
    return animate ? (
      <m.line
        stroke={indicatorFill}
        strokeDasharray={strokeDasharray}
        strokeWidth={strokeWidth}
        x1={animatedLineX}
        x2={animatedLineX}
        y1={0}
        y2={animatedEndY}
      />
    ) : (
      <line
        stroke={indicatorFill}
        strokeDasharray={strokeDasharray}
        strokeWidth={strokeWidth}
        x1={lineX}
        x2={lineX}
        y1={0}
        y2={endY}
      />
    );
  }

  if (!(fadeSides.any || colorEnd)) {
    return animate ? (
      <m.rect
        fill={indicatorFill}
        height={animatedEndY}
        width={pixelWidth}
        x={animatedX}
        y={0}
      />
    ) : (
      <rect
        fill={indicatorFill}
        height={endY}
        width={pixelWidth}
        x={rectX}
        y={0}
      />
    );
  }

  const fadeStops = indicatorFadeGradientStops(fadeSides, fadeLength);
  if (colorEnd && fadeStops.length === 1) {
    fadeStops.push({ offset: "100%", opacity: 1 });
  }

  return (
    <g>
      <defs>
        <linearGradient id={gradientId} x1="0%" x2="0%" y1="0%" y2="100%">
          {fadeStops.map((stop) => (
            <stop
              key={stop.offset}
              offset={stop.offset}
              style={{
                stopColor: colorEnd
                  ? verticalRampColor(indicatorFill, colorEnd, stop.offset)
                  : indicatorFill,
                stopOpacity: stop.opacity,
              }}
            />
          ))}
        </linearGradient>
      </defs>
      {animate ? (
        <m.rect
          fill={`url(#${gradientId})`}
          height={animatedEndY}
          width={pixelWidth}
          x={animatedX}
          y={0}
        />
      ) : (
        <rect
          fill={`url(#${gradientId})`}
          height={endY}
          width={pixelWidth}
          x={rectX}
          y={0}
        />
      )}
    </g>
  );
}

TooltipIndicator.displayName = "TooltipIndicator";

export default TooltipIndicator;

"use client";

import { useEffect, useState } from "react";

/**
 * Default grace period (ms) before a tooltip hides after hover ends. Bridges
 * gaps between adjacent targets (heatmap cells, choropleth features) so the
 * panel springs to the next target instead of fading out and back in.
 */
export const TOOLTIP_HIDE_DELAY_MS = 120;

/**
 * Delays showing (`showDelay`) and hiding (`hideDelay`) hover tooltip data.
 * Once visible, changes to another target apply immediately.
 *
 * Immediate updates are applied during render ("adjust state when props
 * change") and delayed ones from timers, so no state is set synchronously in
 * an effect (React Compiler `react-hooks/set-state-in-effect`).
 */
export function useDelayedTooltipData<T>(
  tooltipData: T | null,
  showDelay = 0,
  hideDelay = TOOLTIP_HIDE_DELAY_MS
): T | null {
  const [displayData, setDisplayData] = useState<T | null>(null);
  const [prevTooltipData, setPrevTooltipData] = useState<T | null>(null);

  // The tooltip counts as showing while it has data on screen (including
  // while a hide is pending).
  const isShowing = displayData !== null;

  if (prevTooltipData !== tooltipData) {
    setPrevTooltipData(tooltipData);
    if (tooltipData) {
      if (isShowing || showDelay === 0) {
        setDisplayData(tooltipData);
      }
    } else if (hideDelay === 0) {
      setDisplayData(null);
    }
  }

  useEffect(() => {
    if (tooltipData) {
      if (displayData === tooltipData) {
        return;
      }
      const showTimer = setTimeout(() => {
        setDisplayData(tooltipData);
      }, showDelay);
      return () => clearTimeout(showTimer);
    }

    if (displayData === null) {
      return;
    }
    const hideTimer = setTimeout(() => {
      setDisplayData(null);
    }, hideDelay);
    return () => clearTimeout(hideTimer);
  }, [tooltipData, displayData, showDelay, hideDelay]);

  return displayData;
}

"use client";

import {
  type MotionValue,
  useSpring,
  useTransform,
  useVelocity,
} from "motion/react";
import { useLayoutEffect, useRef } from "react";

/** Tuning for the date pill's velocity swell (see `ChartTooltip` `datePillVelocity`). */
export interface DatePillVelocityConfig {
  /** Uniform growth at full speed (`0.06` = 6% bigger). Default: `0.06` */
  scale?: number;
  /** Extra horizontal stretch along the direction of travel at full speed. Default: `0.08` */
  stretch?: number;
  /** Speed (px/s) that counts as "full speed". Default: `1600` */
  maxVelocity?: number;
}

const DEFAULTS: Required<DatePillVelocityConfig> = {
  scale: 0.06,
  stretch: 0.08,
  maxVelocity: 1600,
};

/**
 * Settles the swell: fast enough to track a flick, damped so it eases back to
 * rest instead of wobbling when the pointer stops.
 */
const SWELL_SPRING = { stiffness: 420, damping: 32, mass: 0.6 };

export function resolveDatePillVelocity(
  value: boolean | DatePillVelocityConfig | undefined
): Required<DatePillVelocityConfig> | null {
  if (!value) {
    return null;
  }
  return value === true ? DEFAULTS : { ...DEFAULTS, ...value };
}

/** `0…1` swell for a speed: ease-out so small moves already register. */
export function velocitySwell(velocity: number, maxVelocity: number): number {
  if (maxVelocity <= 0) {
    return 0;
  }
  const t = Math.min(Math.abs(velocity) / maxVelocity, 1);
  return t * (2 - t);
}

/**
 * Glass-menu style swell: as `x` moves, the element grows slightly and
 * stretches along the motion, then springs back to `1` at rest. Pure motion
 * values — pointer moves never re-render React. Returns `scale: 1` values when
 * `config` is `null` (off or reduced motion).
 */
export function useVelocityStretch(
  x: MotionValue<number>,
  config: Required<DatePillVelocityConfig> | null
): { scaleX: MotionValue<number>; scaleY: MotionValue<number> } {
  // Transforms read the latest config from a ref, so a new config object
  // (or toggling off) applies without rebuilding the motion values.
  const configRef = useRef(config);
  useLayoutEffect(() => {
    configRef.current = config;
  });
  const velocity = useVelocity(x);
  const swell = useTransform(velocity, (v) => {
    const c = configRef.current;
    return c ? velocitySwell(v, c.maxVelocity) : 0;
  });
  const smooth = useSpring(swell, SWELL_SPRING);
  const scaleX = useTransform(smooth, (a) => {
    const c = configRef.current;
    return c ? 1 + a * (c.scale + c.stretch) : 1;
  });
  const scaleY = useTransform(smooth, (a) => {
    const c = configRef.current;
    return c ? 1 + a * c.scale : 1;
  });
  return { scaleX, scaleY };
}

"use client";

import type { CurveFactory } from "d3-shape";
import { curveLinear } from "d3-shape";
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { LINE_LOADING_PULSE_EASE } from "./line-loading-timing";
import {
  computeSeriesPathPoints,
  flattenSeriesPath,
  interpolateSeriesPathPoints,
  morphSeriesPolylines,
  type SeriesPathPoint,
  seriesDataSignature,
  seriesPathFromPoints,
  seriesPathTransitionSignatureFromData,
} from "./series-path-utils";

export interface UseAnimatedSeriesPathOptions {
  renderData: Record<string, unknown>[];
  xAccessor: (datum: Record<string, unknown>) => Date;
  xScale: (value: Date) => number | undefined;
  yScale: (value: number) => number | undefined;
  /**
   * Y-scale at the end of the y-domain tween. Data morphs animate toward this
   * scale so the line never chases a mid-tween domain out of the plot.
   * Default: `yScale`.
   */
  settledYScale?: (value: number) => number | undefined;
  dataKey: string;
  curve: CurveFactory;
  chartPhase: string;
  durationMs: number;
  innerWidth: number;
  enabled: boolean;
}

/**
 * Points currently on screen. `polyline` frames are dense samples of the
 * rendered curve (vertical morph) and are drawn with `curveLinear`.
 */
interface DisplayedSeriesPath {
  points: SeriesPathPoint[];
  polyline: boolean;
}

export function useAnimatedSeriesPath({
  renderData,
  xAccessor,
  xScale,
  yScale,
  settledYScale = yScale,
  dataKey,
  curve,
  chartPhase,
  durationMs,
  innerWidth,
  enabled,
}: UseAnimatedSeriesPathOptions) {
  const reducedMotion = useReducedMotion();
  const [animatedPath, setAnimatedPath] = useState<DisplayedSeriesPath | null>(
    null
  );
  const displayedRef = useRef<DisplayedSeriesPath | null>(null);
  const animatingRef = useRef(false);

  const xScaleDomain = useMemo(() => {
    const scaleWithDomain = xScale as { domain?: () => [Date, Date] };
    return scaleWithDomain.domain?.() ?? [new Date(0), new Date(0)];
  }, [xScale]);

  const targetPoints = useMemo(
    () =>
      computeSeriesPathPoints(renderData, xAccessor, xScale, yScale, dataKey),
    [renderData, xAccessor, xScale, yScale, dataKey]
  );

  const dataSignature = useMemo(
    () => seriesDataSignature(renderData, xAccessor, dataKey),
    [renderData, xAccessor, dataKey]
  );

  // Same string `seriesPathTransitionSignature` builds, without walking the
  // data a second time.
  const transitionSignature = useMemo(
    () =>
      seriesPathTransitionSignatureFromData(dataSignature, {
        innerWidth,
        xDomainMin: xScaleDomain[0]?.getTime?.() ?? 0,
        xDomainMax: xScaleDomain[1]?.getTime?.() ?? 0,
      }),
    [dataSignature, innerWidth, xScaleDomain]
  );

  const settledYDomainKey =
    (settledYScale as { domain?: () => number[] }).domain?.().join(",") ?? "";

  const prevTransitionSignatureRef = useRef(transitionSignature);
  const prevDataSignatureRef = useRef(dataSignature);
  const prevSettledYDomainKeyRef = useRef(settledYDomainKey);

  // Live scale/data inputs for the running tween. The y-domain tween rebuilds
  // `yScale` every frame, so these must not be effect deps — otherwise the
  // effect cleanup stops the path tween after its first frame.
  const latestRef = useRef({
    renderData,
    xAccessor,
    xScale,
    yScale,
    settledYScale,
    settledYDomainKey,
    targetPoints,
    dataKey,
    curve,
  });
  // Synced in a layout effect declared before the tween effect (not during
  // render) so `renderFrame(0)` and every animation frame see this commit's
  // inputs.
  useLayoutEffect(() => {
    latestRef.current = {
      renderData,
      xAccessor,
      xScale,
      yScale,
      settledYScale,
      settledYDomainKey,
      targetPoints,
      dataKey,
      curve,
    };
  });
  const computeLatestTarget = (settled = false) => {
    const latest = latestRef.current;
    return computeSeriesPathPoints(
      latest.renderData,
      latest.xAccessor,
      latest.xScale,
      settled ? latest.settledYScale : latest.yScale,
      latest.dataKey
    );
  };

  const shouldAnimate =
    enabled &&
    !reducedMotion &&
    chartPhase === "ready" &&
    durationMs > 0 &&
    renderData.length > 0;

  // Drop a stale tween frame as soon as animation is no longer allowed —
  // adjusted during render rather than via setState in the effect below.
  if (!shouldAnimate && animatedPath !== null) {
    setAnimatedPath(null);
  }

  // Layout effect so frame 0 (the previous shape) is committed before paint;
  // otherwise the new target flashes for a frame before the tween starts.
  // biome-ignore lint/correctness/useExhaustiveDependencies: scales/targets are read live via latestRef; only a new data signature should restart the tween
  useLayoutEffect(() => {
    const { curve, targetPoints, settledYDomainKey } = latestRef.current;
    const dataChanged = prevDataSignatureRef.current !== dataSignature;
    prevDataSignatureRef.current = dataSignature;
    const yDomainChanged =
      prevSettledYDomainKeyRef.current !== settledYDomainKey;
    prevSettledYDomainKeyRef.current = settledYDomainKey;

    if (!shouldAnimate) {
      animatingRef.current = false;
      displayedRef.current = { points: targetPoints, polyline: false };
      prevTransitionSignatureRef.current = transitionSignature;
      return;
    }

    if (prevTransitionSignatureRef.current === transitionSignature) {
      return;
    }
    prevTransitionSignatureRef.current = transitionSignature;

    const from = displayedRef.current ?? {
      points: targetPoints,
      polyline: false,
    };
    if (from.points.length === 0) {
      displayedRef.current = { points: targetPoints, polyline: false };
      return;
    }

    animatingRef.current = true;
    // New/removed data points: morph vertically on a shared x grid so the line
    // rises and falls into shape. Same data with a moved x-domain (brush pan /
    // resize): slide points by key so the series tracks the viewport.
    const morph = dataChanged || from.polyline;
    const fromPolyline = from.polyline
      ? from.points
      : flattenSeriesPath(from.points, curve);
    // When new data also moves the y-domain, hold the line in place while the
    // grid and y-axis tween to the new scale, then morph straight to its
    // settled pixels — morphing against the mid-tween scale sends the line
    // far outside the plot when the magnitude changes (e.g. ~15k → ~10).
    const holdForYDomain = morph && dataChanged && yDomainChanged;

    // The morph target only depends on these inputs (the settled scale, not
    // the mid-tween one), so its flattened polyline is reused across frames
    // until one of them changes.
    let targetPolylineCache: {
      inputs: readonly unknown[];
      polyline: SeriesPathPoint[];
    } | null = null;
    const settledTargetPolyline = () => {
      const latest = latestRef.current;
      const inputs = [
        latest.renderData,
        latest.xAccessor,
        latest.xScale,
        latest.settledYScale,
        latest.dataKey,
        latest.curve,
      ] as const;
      const cached = targetPolylineCache;
      if (cached && inputs.every((input, i) => input === cached.inputs[i])) {
        return cached.polyline;
      }
      const polyline = flattenSeriesPath(
        computeLatestTarget(true),
        latest.curve
      );
      targetPolylineCache = { inputs, polyline };
      return polyline;
    };

    const renderFrame = (progress: number) => {
      // Morphs target the settled scale; x-domain slides (brush) track the
      // live y-domain tween so the series stays glued to the grid.
      const next: DisplayedSeriesPath = morph
        ? {
            points: morphSeriesPolylines(
              fromPolyline,
              settledTargetPolyline(),
              progress
            ),
            polyline: true,
          }
        : {
            points: interpolateSeriesPathPoints(
              from.points,
              computeLatestTarget(false),
              progress
            ),
            polyline: false,
          };
      displayedRef.current = next;
      setAnimatedPath(next);
    };
    renderFrame(0);

    const control = animate(0, 1, {
      delay: holdForYDomain ? durationMs / 1000 : 0,
      duration: durationMs / 1000,
      ease: [...LINE_LOADING_PULSE_EASE],
      onUpdate: renderFrame,
      onComplete: () => {
        animatingRef.current = false;
        displayedRef.current = {
          points: computeLatestTarget(),
          polyline: false,
        };
        setAnimatedPath(null);
      },
    });

    return () => {
      control.stop();
      animatingRef.current = false;
    };
  }, [
    transitionSignature,
    dataSignature,
    shouldAnimate,
    chartPhase,
    durationMs,
    enabled,
    reducedMotion,
    renderData.length,
  ]);

  // Must run after the tween effect: on a data change the tween needs the
  // previously displayed points as its `from`, not the new target.
  useEffect(() => {
    if (!animatingRef.current) {
      displayedRef.current = { points: targetPoints, polyline: false };
    }
  }, [targetPoints]);

  const pathD = useMemo(
    () =>
      animatedPath
        ? seriesPathFromPoints(
            animatedPath.points,
            animatedPath.polyline ? curveLinear : curve
          )
        : seriesPathFromPoints(targetPoints, curve),
    [animatedPath, targetPoints, curve]
  );

  return {
    pathD,
    isPathAnimating: animatedPath != null,
  };
}

"use client";

import { animate, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import type { ChartPhase } from "./chart-phase";
import { LINE_LOADING_PULSE_EASE } from "./line-loading-timing";
import {
  domainsEqual,
  isYDomainTweenPhase,
  resolveAnimatedYDestinationDomains,
  shouldTweenYDomain,
  type YDomain,
} from "./y-domain-utils";

function lerpDomain(from: YDomain, to: YDomain, progress: number): YDomain {
  return [
    from[0] + (to[0] - from[0]) * progress,
    from[1] + (to[1] - from[1]) * progress,
  ];
}

function snapDomains(
  domains: Record<string, YDomain>,
  setAnimatedByAxis: (domains: Record<string, YDomain>) => void,
  animatedRef: { current: Record<string, YDomain> }
) {
  if (domainsEqual(animatedRef.current, domains)) {
    return;
  }
  setAnimatedByAxis(domains);
  animatedRef.current = domains;
}

function tweenDomains({
  destination,
  durationMs,
  enabled,
  reducedMotion,
  animatedRef,
  setAnimatedByAxis,
  onSettled,
}: {
  destination: Record<string, YDomain>;
  durationMs: number;
  enabled: boolean;
  reducedMotion: boolean | null;
  animatedRef: { current: Record<string, YDomain> };
  setAnimatedByAxis: (domains: Record<string, YDomain>) => void;
  onSettled?: () => void;
}) {
  if (domainsEqual(animatedRef.current, destination)) {
    onSettled?.();
    return;
  }

  if (!enabled || reducedMotion) {
    snapDomains(destination, setAnimatedByAxis, animatedRef);
    onSettled?.();
    return;
  }

  const axisIds = Object.keys(destination);
  const fromSnapshot = animatedRef.current;

  let needsTween = false;
  for (const axisId of axisIds) {
    const from =
      fromSnapshot[axisId] ?? destination[axisId] ?? ([0, 100] as YDomain);
    const to = destination[axisId] ?? from;
    if (shouldTweenYDomain(from, to)) {
      needsTween = true;
      break;
    }
  }

  if (!needsTween) {
    snapDomains(destination, setAnimatedByAxis, animatedRef);
    onSettled?.();
    return;
  }

  const fromByAxis: Record<string, YDomain> = {};
  for (const axisId of axisIds) {
    fromByAxis[axisId] = fromSnapshot[axisId] ??
      destination[axisId] ?? [0, 100];
  }

  const control = animate(0, 1, {
    duration: durationMs / 1000,
    ease: [...LINE_LOADING_PULSE_EASE],
    onUpdate: (progress) => {
      const next: Record<string, YDomain> = {};
      for (const axisId of axisIds) {
        const from =
          fromByAxis[axisId] ?? destination[axisId] ?? ([0, 100] as YDomain);
        const to = destination[axisId] ?? from;
        next[axisId] = shouldTweenYDomain(from, to)
          ? lerpDomain(from, to, progress)
          : to;
      }
      animatedRef.current = next;
      setAnimatedByAxis(next);
    },
    onComplete: () => {
      snapDomains(destination, setAnimatedByAxis, animatedRef);
      onSettled?.();
    },
  });

  return control;
}

export interface UseAnimatedYDomainsOptions {
  enabled: boolean;
  durationMs: number;
  chartPhase: ChartPhase;
  skeletonByAxis: Record<string, YDomain>;
  targetByAxis: Record<string, YDomain>;
  onSettled?: () => void;
  /** When true, tweens y-domains on target changes while the chart is in the ready phase (e.g. brush zoom). */
  tweenOnTargetChange?: boolean;
}

export function useAnimatedYDomains({
  enabled,
  durationMs,
  chartPhase,
  skeletonByAxis,
  targetByAxis,
  onSettled,
  tweenOnTargetChange = false,
}: UseAnimatedYDomainsOptions): Record<string, YDomain> {
  const reducedMotion = useReducedMotion();
  const destinationByAxis = resolveAnimatedYDestinationDomains(
    chartPhase,
    skeletonByAxis,
    targetByAxis
  );
  const destinationRef = useRef(destinationByAxis);
  const skeletonRef = useRef(skeletonByAxis);
  const targetRef = useRef(targetByAxis);

  const [animatedByAxis, setAnimatedByAxis] = useState(destinationByAxis);

  // Only grid-tween phases and (opt-in) ready-phase target changes animate.
  // Everything else snaps — resolved during render so the new domain lands in
  // the same commit as the data (a snap from an effect would paint a frame
  // with the old y-scale, then re-render).
  const mayTween =
    isYDomainTweenPhase(chartPhase) ||
    (tweenOnTargetChange &&
      chartPhase === "ready" &&
      enabled &&
      !reducedMotion);
  if (
    !mayTween &&
    animatedByAxis !== destinationByAxis &&
    !domainsEqual(animatedByAxis, destinationByAxis)
  ) {
    setAnimatedByAxis(destinationByAxis);
  }
  const animatedRef = useRef(animatedByAxis);
  const prevPhaseRef = useRef(chartPhase);
  const onSettledRef = useRef(onSettled);

  // Latest-value mirrors for the effects / animation callbacks below. Synced
  // in an effect (not during render) and declared first so they are current
  // before the tween effects run in the same commit.
  useEffect(() => {
    destinationRef.current = destinationByAxis;
    skeletonRef.current = skeletonByAxis;
    targetRef.current = targetByAxis;
    onSettledRef.current = onSettled;
  });

  useEffect(() => {
    animatedRef.current = animatedByAxis;
  }, [animatedByAxis]);

  useEffect(() => {
    if (prevPhaseRef.current === chartPhase) {
      return;
    }
    prevPhaseRef.current = chartPhase;

    const settle = () => {
      onSettledRef.current?.();
    };

    // Keep grid spacing frozen while the series exits the viewport.
    if (chartPhase === "exiting") {
      snapDomains(skeletonRef.current, setAnimatedByAxis, animatedRef);
      return;
    }
    if (chartPhase === "exitingReady") {
      snapDomains(targetRef.current, setAnimatedByAxis, animatedRef);
      return;
    }
    if (chartPhase === "loading") {
      snapDomains(skeletonRef.current, setAnimatedByAxis, animatedRef);
      return;
    }
    if (chartPhase === "revealing" || chartPhase === "ready") {
      snapDomains(targetRef.current, setAnimatedByAxis, animatedRef);
      return;
    }

    if (!isYDomainTweenPhase(chartPhase)) {
      return;
    }

    const control = tweenDomains({
      destination: destinationRef.current,
      durationMs,
      enabled,
      reducedMotion,
      animatedRef,
      setAnimatedByAxis,
      onSettled: settle,
    });

    return () => control?.stop();
  }, [chartPhase, durationMs, enabled, reducedMotion]);

  const targetSignature = JSON.stringify(targetByAxis);
  const prevTargetSignatureRef = useRef(targetSignature);

  useEffect(() => {
    const inLivePhase = chartPhase === "ready" || chartPhase === "revealing";

    if (!inLivePhase) {
      prevTargetSignatureRef.current = targetSignature;
      return;
    }

    if (prevTargetSignatureRef.current === targetSignature) {
      return;
    }
    prevTargetSignatureRef.current = targetSignature;

    if (tweenOnTargetChange && chartPhase === "ready") {
      const control = tweenDomains({
        destination: targetRef.current,
        durationMs,
        enabled,
        reducedMotion,
        animatedRef,
        setAnimatedByAxis,
        onSettled: () => onSettledRef.current?.(),
      });

      return () => control?.stop();
    }

    snapDomains(targetRef.current, setAnimatedByAxis, animatedRef);
  }, [
    chartPhase,
    durationMs,
    enabled,
    reducedMotion,
    targetSignature,
    tweenOnTargetChange,
  ]);

  return mayTween ? animatedByAxis : destinationByAxis;
}

"use client";

import type {
  ScaleLinear as D3ScaleLinear,
  ScaleTime as D3ScaleTime,
} from "d3-scale";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  type BandConfig,
  type ChartHoverStore,
  createChartHoverStore,
  type LineConfig,
  type Margin,
  type TooltipData,
} from "./chart-context";
import { localPoint } from "./local-point";
import { useScheduledTooltip } from "./use-scheduled-tooltip";
import { normalizeYAxisId } from "./y-axis-scales";

type ScaleTime = D3ScaleTime<number, number>;
type ScaleLinear = D3ScaleLinear<number, number>;

export interface ChartSelection {
  startX: number;
  endX: number;
  startIndex: number;
  endIndex: number;
  active: boolean;
}

interface UseChartInteractionParams {
  xScale: ScaleTime;
  yScale: ScaleLinear;
  yScales: Record<string, ScaleLinear>;
  data: Record<string, unknown>[];
  lines: LineConfig[];
  /** `<Band>` configs — edge y-positions for tooltip dots. */
  bands?: BandConfig[];
  margin: Margin;
  xAccessor: (d: Record<string, unknown>) => Date;
  bisectDate: (
    data: Record<string, unknown>[],
    date: Date,
    lo: number
  ) => number;
  canInteract: boolean;
}

interface ChartInteractionResult {
  /**
   * Tooltip + selection state. Lives outside React state so a pointer move
   * re-renders only hover consumers (publish it with `ChartHoverStoreProvider`).
   */
  hoverStore: ChartHoverStore;
  interactionHandlers: {
    onMouseMove?: (event: React.MouseEvent<SVGGElement>) => void;
    onMouseLeave?: () => void;
    onMouseDown?: (event: React.MouseEvent<SVGGElement>) => void;
    onMouseUp?: () => void;
    onTouchStart?: (event: React.TouchEvent<SVGGElement>) => void;
    onTouchMove?: (event: React.TouchEvent<SVGGElement>) => void;
    onTouchEnd?: () => void;
  };
  interactionStyle: React.CSSProperties;
}

/** Pixel y per line dataKey, plus band edge keys (line keys win on collisions). */
function resolveYPositions(
  d: Record<string, unknown>,
  lines: LineConfig[],
  bands: BandConfig[] | undefined,
  yScales: Record<string, ScaleLinear>,
  yScale: ScaleLinear
): Record<string, number> {
  const yPositions: Record<string, number> = {};
  const place = (key: string, yAxisId: string | number | undefined) => {
    const value = d[key];
    if (typeof value === "number") {
      const axisScale = yScales[normalizeYAxisId(yAxisId)] ?? yScale;
      yPositions[key] = axisScale(value) ?? 0;
    }
  };
  for (const band of bands ?? []) {
    if (band.showInTooltip) {
      place(band.upperKey, band.yAxisId);
      place(band.lowerKey, band.yAxisId);
    }
  }
  // Lines last so they win when a band edge shares a line's key.
  for (const line of lines) {
    place(line.dataKey, line.yAxisId);
  }
  return yPositions;
}

export function useChartInteraction({
  xScale,
  yScale,
  yScales,
  data,
  lines,
  bands,
  margin,
  xAccessor,
  bisectDate,
  canInteract,
}: UseChartInteractionParams): ChartInteractionResult {
  const [hoverStore] = useState(createChartHoverStore);
  const { setSelection } = hoverStore;
  const { scheduleTooltip, clearTooltip, resetTooltipDedupe } =
    useScheduledTooltip<TooltipData>(hoverStore.setTooltipData);

  const isDraggingRef = useRef(false);
  const dragStartXRef = useRef<number>(0);
  const lastHoveredXRef = useRef<number | null>(null);

  const resolveTooltipFromX = useCallback(
    (pixelX: number): TooltipData | null => {
      const x0 = xScale.invert(pixelX);
      const index = bisectDate(data, x0, 1);
      const d0 = data[index - 1];
      const d1 = data[index];

      if (!d0) {
        return null;
      }

      let d = d0;
      let finalIndex = index - 1;
      if (d1) {
        const d0Time = xAccessor(d0).getTime();
        const d1Time = xAccessor(d1).getTime();
        if (x0.getTime() - d0Time > d1Time - x0.getTime()) {
          d = d1;
          finalIndex = index;
        }
      }

      return {
        point: d,
        index: finalIndex,
        x: xScale(xAccessor(d)) ?? 0,
        yPositions: resolveYPositions(d, lines, bands, yScales, yScale),
      };
    },
    [xScale, yScale, yScales, data, lines, bands, xAccessor, bisectDate]
  );

  const resolveIndexFromX = useCallback(
    (pixelX: number): number => {
      const x0 = xScale.invert(pixelX);
      const index = bisectDate(data, x0, 1);
      const d0 = data[index - 1];
      const d1 = data[index];
      if (!d0) {
        return 0;
      }
      if (d1) {
        const d0Time = xAccessor(d0).getTime();
        const d1Time = xAccessor(d1).getTime();
        if (x0.getTime() - d0Time > d1Time - x0.getTime()) {
          return index;
        }
      }
      return index - 1;
    },
    [xScale, data, xAccessor, bisectDate]
  );

  const getChartX = useCallback(
    (
      event: React.MouseEvent<SVGGElement> | React.TouchEvent<SVGGElement>,
      touchIndex = 0
    ): number | null => {
      let point: { x: number; y: number } | null = null;

      if ("touches" in event) {
        const touch = event.touches[touchIndex];
        if (!touch) {
          return null;
        }
        const svg = event.currentTarget.ownerSVGElement;
        if (!svg) {
          return null;
        }
        point = localPoint(svg, touch);
      } else {
        point = localPoint(event);
      }

      if (!point) {
        return null;
      }
      return point.x - margin.left;
    },
    [margin.left]
  );

  const handleMouseMove = useCallback(
    (event: React.MouseEvent<SVGGElement>) => {
      const chartX = getChartX(event);
      if (chartX === null) {
        return;
      }

      if (isDraggingRef.current) {
        const startX = Math.min(dragStartXRef.current, chartX);
        const endX = Math.max(dragStartXRef.current, chartX);
        setSelection({
          startX,
          endX,
          startIndex: resolveIndexFromX(startX),
          endIndex: resolveIndexFromX(endX),
          active: true,
        });
        return;
      }

      lastHoveredXRef.current = chartX;
      const tooltip = resolveTooltipFromX(chartX);
      if (tooltip) {
        scheduleTooltip(tooltip);
      }
    },
    [
      getChartX,
      resolveTooltipFromX,
      resolveIndexFromX,
      scheduleTooltip,
      setSelection,
    ]
  );

  const handleMouseLeave = useCallback(() => {
    lastHoveredXRef.current = null;
    clearTooltip();
    if (isDraggingRef.current) {
      isDraggingRef.current = false;
    }
    setSelection(null);
  }, [clearTooltip, setSelection]);

  const handleMouseDown = useCallback(
    (event: React.MouseEvent<SVGGElement>) => {
      const chartX = getChartX(event);
      if (chartX === null) {
        return;
      }
      // Stop the drag from starting a native text selection across the page
      // (tooltip, labels, nearby copy).
      event.preventDefault();
      isDraggingRef.current = true;
      dragStartXRef.current = chartX;
      clearTooltip();
      setSelection(null);
    },
    [getChartX, clearTooltip, setSelection]
  );

  const handleMouseUp = useCallback(() => {
    if (isDraggingRef.current) {
      isDraggingRef.current = false;
    }
    setSelection(null);
  }, [setSelection]);

  const handleTouchStart = useCallback(
    (event: React.TouchEvent<SVGGElement>) => {
      if (event.touches.length === 1) {
        event.preventDefault();
        const chartX = getChartX(event, 0);
        if (chartX === null) {
          return;
        }
        lastHoveredXRef.current = chartX;
        const tooltip = resolveTooltipFromX(chartX);
        if (tooltip) {
          scheduleTooltip(tooltip);
        }
      } else if (event.touches.length === 2) {
        event.preventDefault();
        resetTooltipDedupe();
        clearTooltip();
        const x0 = getChartX(event, 0);
        const x1 = getChartX(event, 1);
        if (x0 === null || x1 === null) {
          return;
        }
        const startX = Math.min(x0, x1);
        const endX = Math.max(x0, x1);
        setSelection({
          startX,
          endX,
          startIndex: resolveIndexFromX(startX),
          endIndex: resolveIndexFromX(endX),
          active: true,
        });
      }
    },
    [
      getChartX,
      resolveTooltipFromX,
      resolveIndexFromX,
      scheduleTooltip,
      resetTooltipDedupe,
      clearTooltip,
      setSelection,
    ]
  );

  const handleTouchMove = useCallback(
    (event: React.TouchEvent<SVGGElement>) => {
      if (event.touches.length === 1) {
        event.preventDefault();
        const chartX = getChartX(event, 0);
        if (chartX === null) {
          return;
        }
        lastHoveredXRef.current = chartX;
        const tooltip = resolveTooltipFromX(chartX);
        if (tooltip) {
          scheduleTooltip(tooltip);
        }
      } else if (event.touches.length === 2) {
        event.preventDefault();
        const x0 = getChartX(event, 0);
        const x1 = getChartX(event, 1);
        if (x0 === null || x1 === null) {
          return;
        }
        const startX = Math.min(x0, x1);
        const endX = Math.max(x0, x1);
        setSelection({
          startX,
          endX,
          startIndex: resolveIndexFromX(startX),
          endIndex: resolveIndexFromX(endX),
          active: true,
        });
      }
    },
    [
      getChartX,
      resolveTooltipFromX,
      resolveIndexFromX,
      scheduleTooltip,
      setSelection,
    ]
  );

  const handleTouchEnd = useCallback(() => {
    clearTooltip();
    setSelection(null);
  }, [clearTooltip, setSelection]);

  // Re-anchor tooltip/crosshair when x-scale or visible data changes (e.g. brush zoom commit).
  useEffect(() => {
    if (!canInteract || lastHoveredXRef.current === null) {
      return;
    }
    const tooltip = resolveTooltipFromX(lastHoveredXRef.current);
    if (tooltip) {
      scheduleTooltip(tooltip, `${tooltip.index}:${Math.round(tooltip.x)}`);
      return;
    }
    clearTooltip();
  }, [canInteract, clearTooltip, resolveTooltipFromX, scheduleTooltip]);

  const interactionHandlers = canInteract
    ? {
        onMouseMove: handleMouseMove,
        onMouseLeave: handleMouseLeave,
        onMouseDown: handleMouseDown,
        onMouseUp: handleMouseUp,
        onTouchStart: handleTouchStart,
        onTouchMove: handleTouchMove,
        onTouchEnd: handleTouchEnd,
      }
    : {};

  const interactionStyle: React.CSSProperties = {
    cursor: canInteract ? "crosshair" : "default",
    touchAction: "none",
  };

  return {
    hoverStore,
    interactionHandlers,
    interactionStyle,
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import {
  type ChartPhase,
  type ChartStatus,
  resolveRestingChartPhase,
} from "./chart-phase";

export interface UseChartPhaseOrchestratorOptions {
  chartStatus: ChartStatus;
  targetData: Record<string, unknown>[];
  skeletonData: Record<string, unknown>[];
  animationDuration: number;
  yDomainTweenDuration: number;
  /** Signature of motion URL state — replays clip reveal in Studio. */
  revealSignature?: string;
  /** Skip mount/signature enter reveal (static docs previews). */
  skipEnterReveal?: boolean;
}

/**
 * Phase the reveal starts from on mount (or the resting phase when skipped).
 * A zero-duration reveal starts at rest: passing through "revealing" would
 * only cost a timer-driven re-render after the first paint.
 */
function resolveInitialChartPhase(
  chartStatus: ChartStatus,
  skipEnterReveal: boolean,
  animationDuration: number
): ChartPhase {
  if (chartStatus === "ready" && !skipEnterReveal && animationDuration > 0) {
    return "revealing";
  }
  return resolveRestingChartPhase(chartStatus);
}

/** Series data plotted for a phase: skeleton while loading / exiting. */
function resolvePlotData<T>(
  chartPhase: ChartPhase,
  chartStatus: ChartStatus,
  skeletonData: T,
  targetData: T
): T {
  if (chartPhase === "exiting") {
    return skeletonData;
  }
  if (chartPhase === "loading" && chartStatus === "loading") {
    return skeletonData;
  }
  return targetData;
}

interface PhaseInputs {
  chartStatus: ChartStatus;
  chartPhase: ChartPhase;
  animationDuration: number;
  revealSignature: string;
  skipEnterReveal: boolean;
}

interface PhaseTransition {
  nextPhase: ChartPhase;
  resetLoaded: boolean;
  bumpConceal: boolean;
  bumpReveal: boolean;
}

function phaseInputsEqual(a: PhaseInputs, b: PhaseInputs): boolean {
  return (
    a.chartStatus === b.chartStatus &&
    a.chartPhase === b.chartPhase &&
    a.animationDuration === b.animationDuration &&
    a.revealSignature === b.revealSignature &&
    a.skipEnterReveal === b.skipEnterReveal
  );
}

/** loading ↔ ready status flip: the phase to enter, or null when unchanged. */
function resolveStatusTransition(
  prevStatus: ChartStatus,
  chartStatus: ChartStatus,
  animationDuration: number,
  yDomainTweenDuration: number
): { phase: ChartPhase; conceal: boolean } | null {
  if (chartStatus === "ready" && prevStatus === "loading") {
    if (animationDuration > 0) {
      return { phase: "exiting", conceal: false };
    }
    return {
      phase: yDomainTweenDuration <= 0 ? "revealing" : "gridTweenReady",
      conceal: false,
    };
  }
  if (chartStatus === "loading" && prevStatus === "ready") {
    if (animationDuration > 0) {
      return { phase: "exitingReady", conceal: true };
    }
    return {
      phase: yDomainTweenDuration <= 0 ? "loading" : "gridTweenLoading",
      conceal: false,
    };
  }
  return null;
}

/** Motion replay (Studio motion URL state / duration change) while resting. */
function shouldReplayReveal(prev: PhaseInputs, next: PhaseInputs): boolean {
  if (next.skipEnterReveal || next.chartStatus !== "ready") {
    return false;
  }
  if (next.chartPhase !== "ready") {
    return false;
  }
  return (
    prev.animationDuration !== next.animationDuration ||
    prev.revealSignature !== next.revealSignature ||
    prev.skipEnterReveal !== next.skipEnterReveal
  );
}

/**
 * Pure transition for a change in inputs (props or the phase itself) —
 * mirrors the former status / replay / reveal-epoch effects.
 */
function resolvePhaseTransition(
  prev: PhaseInputs,
  next: PhaseInputs,
  yDomainTweenDuration: number
): PhaseTransition {
  let nextPhase = next.chartPhase;
  let resetLoaded = false;
  let bumpConceal = false;

  if (prev.chartStatus === next.chartStatus) {
    if (shouldReplayReveal(prev, next)) {
      nextPhase = "revealing";
      resetLoaded = true;
    }
  } else {
    const status = resolveStatusTransition(
      prev.chartStatus,
      next.chartStatus,
      next.animationDuration,
      yDomainTweenDuration
    );
    if (status) {
      nextPhase = status.phase;
      resetLoaded = true;
      bumpConceal = status.conceal;
    }
  }

  // Entering (or re-timing) the reveal starts a new reveal epoch.
  const bumpReveal =
    nextPhase === "revealing" &&
    (prev.chartPhase !== "revealing" ||
      nextPhase !== next.chartPhase ||
      prev.animationDuration !== next.animationDuration);

  return { nextPhase, resetLoaded, bumpConceal, bumpReveal };
}

/**
 * Visual lifecycle state machine for time-series charts.
 *
 * Transitions driven by props (status flips, motion replays) are applied
 * during render with the "store previous props in state" pattern instead of
 * `useEffect` + `setState`, so each transition costs one render rather than a
 * commit followed by a cascading re-render (React Compiler
 * `react-hooks/set-state-in-effect`). Transitions driven by animations
 * (`notify*`) use functional updates, so no ref mirrors of the phase are read
 * during render.
 */
export function useChartPhaseOrchestrator({
  chartStatus,
  targetData,
  skeletonData,
  animationDuration,
  yDomainTweenDuration,
  revealSignature = "",
  skipEnterReveal = false,
}: UseChartPhaseOrchestratorOptions) {
  const [chartPhase, setChartPhase] = useState<ChartPhase>(() =>
    resolveInitialChartPhase(chartStatus, skipEnterReveal, animationDuration)
  );
  const [revealEpoch, setRevealEpoch] = useState(() =>
    chartStatus === "ready" && !skipEnterReveal ? 1 : 0
  );
  const [concealEpoch, setConcealEpoch] = useState(0);
  const [isLoaded, setIsLoaded] = useState(
    () => chartStatus === "ready" && (skipEnterReveal || animationDuration <= 0)
  );

  // Previous inputs — compared during render to derive transitions.
  const [prev, setPrev] = useState<PhaseInputs>({
    chartStatus,
    chartPhase,
    animationDuration,
    revealSignature,
    skipEnterReveal,
  });

  const current: PhaseInputs = {
    chartStatus,
    chartPhase,
    animationDuration,
    revealSignature,
    skipEnterReveal,
  };
  if (!phaseInputsEqual(prev, current)) {
    const transition = resolvePhaseTransition(
      prev,
      current,
      yDomainTweenDuration
    );
    if (transition.resetLoaded) {
      setIsLoaded(false);
    }
    if (transition.bumpConceal) {
      setConcealEpoch((epoch) => epoch + 1);
    }
    if (transition.bumpReveal) {
      setRevealEpoch((epoch) => epoch + 1);
    }
    if (transition.nextPhase !== chartPhase) {
      setChartPhase(transition.nextPhase);
    }
    setPrev({ ...current, chartPhase: transition.nextPhase });
  }

  const plotData = resolvePlotData(
    chartPhase,
    chartStatus,
    skeletonData,
    targetData
  );

  /** Loading pulse exit finished — tween grid to ready spacing next. */
  const notifyLoadingPulseComplete = useCallback(() => {
    setChartPhase((phase) => (phase === "exiting" ? "gridTweenReady" : phase));
  }, []);

  /** Ready series conceal finished — tween grid to loading spacing next. */
  const notifyRevealConcealComplete = useCallback(() => {
    setChartPhase((phase) =>
      phase === "exitingReady" ? "gridTweenLoading" : phase
    );
  }, []);

  /** Grid tween finished — enter the next resting phase. */
  const notifyYDomainTweenComplete = useCallback(() => {
    setChartPhase((phase) => {
      if (phase === "gridTweenLoading") {
        return "loading";
      }
      if (phase === "gridTweenReady") {
        return "revealing";
      }
      return phase;
    });
  }, []);

  // Reveal timer — the only async transition owned by this hook.
  useEffect(() => {
    if (chartPhase !== "revealing") {
      return;
    }
    const timer = window.setTimeout(
      () => {
        setChartPhase("ready");
        setIsLoaded(true);
      },
      Math.max(0, animationDuration)
    );
    return () => window.clearTimeout(timer);
  }, [animationDuration, chartPhase]);

  return {
    chartPhase,
    plotData,
    revealEpoch,
    concealEpoch,
    isLoaded,
    notifyLoadingPulseComplete,
    notifyRevealConcealComplete,
    notifyYDomainTweenComplete,
  };
}

