import { useSpring } from "motion/react";
import { useCallback, useLayoutEffect, useRef } from "react";
import { useChartConfig } from "./chart-config-context";
import {
  type ChartHoverContextValue,
  DISCRETE_INTERACTION_LABEL_THRESHOLD,
  useChartHoverSelector,
  useChartHoverStore,
  useChartStable,
} from "./chart-context";
import {
  computeSegmentBounds,
  INACTIVE_SEGMENT,
  type SegmentBounds,
} from "./highlight-segment-bounds";

// Hover-highlight band for `line.tsx` and `area.tsx`. Computes the segment
// bounds and springs its x/width; `<HighlightSegment>` renders the clipped
// re-stroke. Spring tuning comes from `ChartConfigProvider.highlightSpring`.
//
// The springs are driven straight from the hover store, so a pointer move
// retargets them without a React render. Callers re-render only when the band
// shows or hides (`isActive`), or when their own props / the stable slice
// change.

export interface HighlightSegmentResult {
  xSpring: ReturnType<typeof useSpring>;
  widthSpring: ReturnType<typeof useSpring>;
  isActive: boolean;
}

/**
 * @param enabled set false when there is no stroke to highlight (e.g. an area
 *   with `showLine={false}`); defaults true.
 * @param span data points either side of the hovered point the band covers;
 *   defaults 1.
 */
export function useHighlightSegment({
  enabled = true,
  span = 1,
}: {
  enabled?: boolean;
  span?: number;
} = {}): HighlightSegmentResult {
  const { data, xScale, xAccessor, dateLabels } = useChartStable();
  const snap = dateLabels.length > DISCRETE_INTERACTION_LABEL_THRESHOLD;
  const store = useChartHoverStore();
  const { highlightSpring } = useChartConfig();

  const resolveBounds = useCallback(
    (hover: ChartHoverContextValue): SegmentBounds =>
      enabled
        ? computeSegmentBounds(
            data,
            xScale,
            xAccessor,
            hover.tooltipData,
            hover.selection,
            span
          )
        : INACTIVE_SEGMENT,
    [enabled, data, xScale, xAccessor, span]
  );

  const isActive = useChartHoverSelector(
    (hover) => resolveBounds(hover).isActive
  );

  const xSpring = useSpring(0, highlightSpring);
  const widthSpring = useSpring(0, highlightSpring);

  const wasActive = useRef(false);
  // Runs on every hover change (store subscription) and whenever the bounds
  // inputs change (data / scale / span), like the old per-render effect.
  useLayoutEffect(() => {
    if (!store) {
      return;
    }
    const drive = () => {
      const bounds = resolveBounds(store.getSnapshot());
      if (!bounds.isActive) {
        wasActive.current = false;
        return;
      }
      if (!wasActive.current || snap) {
        xSpring.jump(bounds.x);
        widthSpring.jump(bounds.width);
      }
      xSpring.set(bounds.x);
      widthSpring.set(bounds.width);
      wasActive.current = true;
    };
    drive();
    return store.subscribe(drive);
  }, [resolveBounds, snap, store, xSpring, widthSpring]);

  return { xSpring, widthSpring, isActive };
}

"use client";

import { animate, type Transition, useMotionValue } from "motion/react";
import { useEffect, useRef } from "react";
import { DEFAULT_CHART_ENTER_TRANSITION } from "./animation";

/** Drives 0→1 enter progress using the studio motion transition (spring or tween). */
export function useMountProgress(
  enterTransition: Transition | undefined,
  delaySeconds: number,
  replayKey: number | string
) {
  const progress = useMotionValue(0);
  const transitionRef = useRef(enterTransition);
  // Latest transition without restarting the enter tween on every new object
  // identity. Declared before the tween effect so it runs first.
  useEffect(() => {
    transitionRef.current = enterTransition;
  });

  // replayKey intentionally retriggers enter when motion settings change
  // biome-ignore lint/correctness/useExhaustiveDependencies: replayKey
  useEffect(() => {
    progress.set(0);
    const controls = animate(progress, 1, {
      ...(transitionRef.current ?? DEFAULT_CHART_ENTER_TRANSITION),
      delay: delaySeconds,
    });
    return () => controls.stop();
  }, [delaySeconds, replayKey, progress]);

  return progress;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";

export interface ScheduledTooltipControls<T> {
  tooltipData: T | null;
  setTooltipData: React.Dispatch<React.SetStateAction<T | null>>;
  scheduleTooltip: (tooltip: T, dedupeKey?: string) => void;
  clearTooltip: () => void;
  resetTooltipDedupe: () => void;
}

function defaultDedupeKey<T>(tooltip: T): string {
  if (
    typeof tooltip === "object" &&
    tooltip !== null &&
    "index" in tooltip &&
    typeof (tooltip as { index: unknown }).index === "number"
  ) {
    const { index, x, activeDataKey } = tooltip as {
      index: number;
      x?: number;
      activeDataKey?: string;
    };
    // Nearest-point hover: several series can share a row — key on the series too.
    const suffix = activeDataKey === undefined ? "" : `:${activeDataKey}`;
    if (typeof x === "number") {
      return `${index}:${Math.round(x)}${suffix}`;
    }
    return `${index}${suffix}`;
  }
  return JSON.stringify(tooltip);
}

/**
 * rAF-coalesced tooltip updates. Keeps the tooltip in React state, or in the
 * caller's store when `setExternal` is given (then `tooltipData` stays `null`
 * here — read it from the store).
 */
export function useScheduledTooltip<T>(
  setExternal?: React.Dispatch<React.SetStateAction<T | null>>
): ScheduledTooltipControls<T> {
  const [tooltipData, setLocalTooltipData] = useState<T | null>(null);
  const setTooltipData = setExternal ?? setLocalTooltipData;
  const lastKeyRef = useRef<string | null>(null);
  const pendingRef = useRef<T | null>(null);
  const rafRef = useRef<number | null>(null);
  const pendingKeyRef = useRef<string | null>(null);

  useEffect(() => {
    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  const commitTooltip = useCallback(
    (tooltip: T, dedupeKey: string) => {
      if (dedupeKey === lastKeyRef.current) {
        return;
      }
      lastKeyRef.current = dedupeKey;
      setTooltipData(tooltip);
    },
    [setTooltipData]
  );

  const scheduleTooltip = useCallback(
    (tooltip: T, dedupeKey?: string) => {
      const key = dedupeKey ?? defaultDedupeKey(tooltip);
      pendingRef.current = tooltip;
      pendingKeyRef.current = key;
      if (key === lastKeyRef.current) {
        return;
      }
      if (rafRef.current !== null) {
        return;
      }
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        const next = pendingRef.current;
        const nextKey = pendingKeyRef.current;
        if (next && nextKey) {
          // Commit inside this frame: a plain setState from rAF is
          // default-priority and would render after the frame paints,
          // showing the tooltip one frame late.
          flushSync(() => commitTooltip(next, nextKey));
        }
      });
    },
    [commitTooltip]
  );

  const clearTooltip = useCallback(() => {
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    pendingRef.current = null;
    pendingKeyRef.current = null;
    lastKeyRef.current = null;
    setTooltipData(null);
  }, [setTooltipData]);

  const resetTooltipDedupe = useCallback(() => {
    lastKeyRef.current = null;
  }, []);

  return {
    tooltipData,
    setTooltipData,
    scheduleTooltip,
    clearTooltip,
    resetTooltipDedupe,
  };
}

/** Pure label-reaction helpers for `XAxis` hover effects. */

/**
 * Label opacity while hovering: hidden under the date ticker (or when it shows
 * the same label), fading back in over `fadeBuffer` px beyond it.
 */
export function xAxisLabelOpacity(
  label: string,
  x: number,
  crosshairX: number | null,
  hoveredLabel: string | null,
  tickerHalfWidth: number
): number {
  if (crosshairX === null) {
    return 1;
  }
  const fadeBuffer = 20;
  const fadeRadius = tickerHalfWidth + fadeBuffer;
  const distance = Math.abs(x - crosshairX);
  if (distance < tickerHalfWidth) {
    return 0;
  }
  if (hoveredLabel && label === hoveredLabel) {
    return 0;
  }
  if (distance < fadeRadius) {
    return (distance - tickerHalfWidth) / fadeBuffer;
  }
  return 1;
}

/**
 * Highlight strength while hovering (`"highlight"` effect): `1` + `active`
 * for the hovered row's label, otherwise a linear falloff from `1` at the
 * crosshair to `0` at `radius` px. Rounded to whole percent so a pointer move
 * only re-renders labels whose color actually changes.
 */
export function xAxisLabelHighlight(
  label: string,
  x: number,
  crosshairX: number | null,
  hoveredLabel: string | null,
  radius: number
): { active: boolean; strength: number } {
  if (crosshairX === null) {
    return { active: false, strength: 0 };
  }
  if (hoveredLabel && label === hoveredLabel) {
    return { active: true, strength: 1 };
  }
  if (radius <= 0) {
    return { active: false, strength: 0 };
  }
  const distance = Math.abs(x - crosshairX);
  const strength = Math.max(0, 1 - distance / radius);
  return { active: false, strength: Math.round(strength * 100) / 100 };
}

/** CSS color for a highlight; `undefined` keeps the base label color. */
export function xAxisLabelColor(
  { active, strength }: ReturnType<typeof xAxisLabelHighlight>,
  activeColor: string,
  nearbyColor: string
): string | undefined {
  if (active) {
    return activeColor;
  }
  if (strength <= 0) {
    return undefined;
  }
  return `color-mix(in oklab, ${nearbyColor} ${Math.round(strength * 100)}%, var(--chart-label))`;
}

