interface XAxisLabelProps {
  label: string;
  x: number;
  /** Fades out near the crosshair; see {@link xAxisLabelOpacity}. */
  opacity: number;
  /** Highlight color near the crosshair; see {@link xAxisLabelHighlight}. */
