        style={{
          opacity,
          color,
          transition: "opacity 0.4s ease-in-out, color 0.2s ease-out",
        }}
      >
        {label}
      </span>
    </div>
  );
});

const MAX_GAP_LAYOUTS = 400;

function binomial(n: number, k: number): number {
  if (k < 0 || k > n) {
    return 0;
  }
  let result = 1;
  for (let i = 0; i < k; i++) {
    result = (result * (n - i)) / (i + 1);
  }
  return result;
}

/** All ways to split `span` into `parts` positive integer gaps. */
function composePositiveSum(sum: number, parts: number): number[][] {
  if (parts === 1) {
    return sum >= 1 ? [[sum]] : [];
  }

  const layouts: number[][] = [];
  for (let gap = 1; gap <= sum - (parts - 1); gap++) {
    for (const tail of composePositiveSum(sum - gap, parts - 1)) {
      layouts.push([gap, ...tail]);
    }
  }
  return layouts;
}

function gapsToIndices(gaps: number[]): number[] {
  const indices = [0];
  let position = 0;
  for (const gap of gaps) {
    position += gap;
    indices.push(position);
  }
  return indices;
}

function indicesForTickCount(length: number, tickCount: number): number[] {
  const span = length - 1;
  if (span <= 0) {
    return [0];
  }

  const rawIndices = Array.from({ length: tickCount }, (_, index) =>
    Math.round((index / (tickCount - 1)) * span)
  );

  const indices = [...new Set(rawIndices)].sort((a, b) => a - b);
  if (indices[0] !== 0) {
    indices.unshift(0);
  }
  if (indices.at(-1) !== span) {
    indices.push(span);
  }

  return [...new Set(indices)].sort((a, b) => a - b);
}

function allIndexLayouts(length: number, tickCount: number): number[][] {
  const span = length - 1;
  if (span <= 0) {
    return [[0]];
  }

  const gapCount = tickCount - 1;
  if (gapCount <= 0) {
    return [[0]];
  }

  const layoutCount = binomial(span - 1, gapCount - 1);
  if (layoutCount > MAX_GAP_LAYOUTS) {
    return [indicesForTickCount(length, tickCount)];
  }

  return composePositiveSum(span, gapCount).map(gapsToIndices);
}

function dedupeIndicesByLabel(
  indices: number[],
  data: Record<string, unknown>[],
  dateLabels: string[],
  xAccessor: (d: Record<string, unknown>) => Date
): number[] {
  const seenLabels = new Set<string>();
  const deduped: number[] = [];

  for (const index of indices) {
    const point = data[index];
    if (!point) {
      continue;
    }
    const label = dateLabels[index] ?? shortDateFmt.format(xAccessor(point));
    if (seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    deduped.push(index);
  }

  return deduped;
}

interface TickLayoutScore {
  score: number;
  symmetryPenalty: number;
  countDistance: number;
  /** 0 = smallest gap at end, 1 = at start, 2 = in the middle */
  edgePreference: number;
}

function indexGaps(indices: number[]): number[] {
  const gaps: number[] = [];
  for (let i = 1; i < indices.length; i++) {
    const current = indices[i];
    const previous = indices[i - 1];
    if (current == null || previous == null) {
      continue;
    }
    gaps.push(current - previous);
  }
  return gaps;
}

function smallestGapEdgePreference(indices: number[]): number {
  const gaps = indexGaps(indices);
  const smallestGap = Math.min(...gaps);
  const smallestGapIndex = gaps.indexOf(smallestGap);
  if (smallestGapIndex === gaps.length - 1) {
    return 0;
  }
  if (smallestGapIndex === 0) {
    return 1;
  }
  return 2;
}

function scoreTickLayout(
  indices: number[],
  resolveXPx: (index: number) => number,
  targetCount: number
): TickLayoutScore {
  if (indices.length < 2) {
    return {
      score: Number.POSITIVE_INFINITY,
      symmetryPenalty: Number.POSITIVE_INFINITY,
      countDistance: Number.POSITIVE_INFINITY,
      edgePreference: Number.POSITIVE_INFINITY,
    };
  }

  const pixelGaps: number[] = [];
  for (let i = 1; i < indices.length; i++) {
    const current = indices[i];
    const previous = indices[i - 1];
    if (current == null || previous == null) {
      continue;
    }
    pixelGaps.push(resolveXPx(current) - resolveXPx(previous));
  }

  const minGap = Math.min(...pixelGaps);
  const maxGap = Math.max(...pixelGaps);
  const meanGap =
    pixelGaps.reduce((sum, gap) => sum + gap, 0) / pixelGaps.length;
  const spreadRatio =
    meanGap > 0 ? (maxGap - minGap) / meanGap : maxGap - minGap;
  const countDistance = Math.abs(indices.length - targetCount);

  const gaps = indexGaps(indices);
  const smallestGap = Math.min(...gaps);
  const smallestGapIndex = gaps.indexOf(smallestGap);
  const interiorPenalty =
    smallestGapIndex > 0 && smallestGapIndex < gaps.length - 1 ? 0.08 : 0;

  const symmetryPenalty =
    gaps.reduce((penalty, gap, index) => {
      return penalty + Math.abs(gap - (gaps.at(-1 - index) ?? gap));
    }, 0) / gaps.length;

  return {
    score:
      spreadRatio +
      0.1 * countDistance +
      interiorPenalty +
      symmetryPenalty * 0.02,
    symmetryPenalty,
    countDistance,
    edgePreference: smallestGapEdgePreference(indices),
  };
}

function isBetterTickLayout(
  next: TickLayoutScore,
  best: TickLayoutScore,
  nextCountDistance: number,
  bestCountDistance: number
): boolean {
  if (next.score < best.score - 1e-6) {
    return true;
  }
  if (Math.abs(next.score - best.score) > 1e-6) {
    return false;
  }
  if (nextCountDistance < bestCountDistance) {
    return true;
  }
  if (nextCountDistance > bestCountDistance) {
    return false;
  }
  if (next.symmetryPenalty < best.symmetryPenalty - 1e-6) {
    return true;
  }
  if (next.symmetryPenalty > best.symmetryPenalty + 1e-6) {
    return false;
  }
  return next.edgePreference < best.edgePreference;
}

/**
 * Picks tick indices with the most even on-screen spacing. Tries
 * `targetCount ± 1` and evaluates every gap layout when feasible.
 */
export function selectEvenlySpacedIndices(
  length: number,
  targetCount: number,
  options?: {
    data?: Record<string, unknown>[];
    dateLabels?: string[];
    xAccessor?: (d: Record<string, unknown>) => Date;
    resolveXPx?: (index: number) => number;
  }
): number[] {
  if (length <= 0) {
    return [];
  }
  if (length === 1) {
    return [0];
  }
  if (length <= targetCount) {
    return Array.from({ length }, (_, index) => index);
  }

  const resolveXPx = options?.resolveXPx ?? ((index: number) => index);

  const minCount = Math.max(2, targetCount - 1);
  const maxCount = Math.min(length, targetCount + 1);

  let bestIndices = indicesForTickCount(length, targetCount);
  let bestScore = scoreTickLayout(bestIndices, resolveXPx, targetCount);
  let bestCountDistance = bestScore.countDistance;

  for (let tickCount = minCount; tickCount <= maxCount; tickCount++) {
    for (const rawIndices of allIndexLayouts(length, tickCount)) {
      const indices =
        options?.data && options.dateLabels && options.xAccessor
          ? dedupeIndicesByLabel(
              rawIndices,
              options.data,
              options.dateLabels,
              options.xAccessor
            )
          : rawIndices;

      if (indices.length < 2) {
        continue;
      }

      const layoutScore = scoreTickLayout(indices, resolveXPx, targetCount);
      const countDistance = Math.abs(indices.length - targetCount);

      if (
        isBetterTickLayout(
          layoutScore,
          bestScore,
          countDistance,
          bestCountDistance
        )
      ) {
        bestIndices = indices;
        bestScore = layoutScore;
        bestCountDistance = countDistance;
      }
    }
  }

  return bestIndices;
}

function buildDataAlignedTicks({
  data,
  dateLabels,
  marginLeft,
  targetTickCount,
  xAccessor,
  xScale,
}: {
  data: Record<string, unknown>[];
  dateLabels: string[];
  marginLeft: number;
  targetTickCount: number;
  xAccessor: (d: Record<string, unknown>) => Date;
  xScale: (date: Date) => number | undefined;
}): AxisTick[] {
  const seenLabels = new Set<string>();
  const ticks: AxisTick[] = [];

  const resolveXPx = (index: number) => {
    const point = data[index];
    if (!point) {
      return index;
    }
    return xScale(xAccessor(point)) ?? 0;
  };

  for (const index of selectEvenlySpacedIndices(data.length, targetTickCount, {
    data,
    dateLabels,
    resolveXPx,
    xAccessor,
  })) {
    const point = data[index];
    if (!point) {
      continue;
    }
    const date = xAccessor(point);
    const label = dateLabels[index] ?? shortDateFmt.format(date);
    if (seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    ticks.push({
      date,
      label,
      x: (xScale(date) ?? 0) + marginLeft,
    });
  }

  return ticks;
}

function buildDomainTicks({
  marginLeft,
  numTicks,
  xScale,
}: {
  marginLeft: number;
  numTicks: number;
  xScale: {
    domain: () => Date[];
    (date: Date): number | undefined;
  };
}): AxisTick[] {
  const domain = xScale.domain();
  const startDate = domain[0];
  const endDate = domain[1];

  if (!(startDate && endDate)) {
    return [];
  }

  const startTime = startDate.getTime();
  const endTime = endDate.getTime();
  const timeRange = endTime - startTime;
  const tickCount = Math.max(2, numTicks);
  const seenLabels = new Set<string>();
  const ticks: AxisTick[] = [];

  for (let i = 0; i < tickCount; i++) {
    const t = i / (tickCount - 1);
    const date = new Date(startTime + t * timeRange);
    const label = shortDateFmt.format(date);
    if (seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    ticks.push({
      date,
      label,
      x: (xScale(date) ?? 0) + marginLeft,
    });
  }

  return ticks;
}

function domainExtendsPastData(
  data: Record<string, unknown>[],
  xAccessor: (d: Record<string, unknown>) => Date,
  xScale: { domain: () => Date[] }
): boolean {
  if (data.length === 0) {
    return false;
  }
  const domainEnd = xScale.domain()[1];
  const lastPoint = data.at(-1);
  if (!(domainEnd && lastPoint)) {
    return false;
  }
  return domainEnd.getTime() > xAccessor(lastPoint).getTime();
}

/** Domain ticks for the projection tail when brush keeps data-aligned labels. */
function appendProjectionTailTicks(
  ticks: AxisTick[],
  data: Record<string, unknown>[],
  xAccessor: (d: Record<string, unknown>) => Date,
  xScale: {
    domain: () => Date[];
    (date: Date): number | undefined;
  },
  marginLeft: number,
  maxExtraTicks: number
): AxisTick[] {
  if (data.length === 0 || maxExtraTicks <= 0) {
    return ticks;
  }

  const lastPoint = data.at(-1);
  const domainEnd = xScale.domain()[1];
  if (!(lastPoint && domainEnd)) {
    return ticks;
  }

  const lastDate = xAccessor(lastPoint);
  const startTime = lastDate.getTime();
  const endTime = domainEnd.getTime();
  if (endTime <= startTime) {
    return ticks;
  }

  const seenLabels = new Set(ticks.map((tick) => tick.label));
  const extras: AxisTick[] = [];
  const extraCount = Math.min(maxExtraTicks, 3);

  for (let i = 1; i <= extraCount; i++) {
    const date = new Date(
      startTime + (i / (extraCount + 1)) * (endTime - startTime)
    );
    const label = shortDateFmt.format(date);
    if (seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    extras.push({
      date,
      label,
      x: (xScale(date) ?? 0) + marginLeft,
    });
  }

  const endLabel = shortDateFmt.format(domainEnd);
  if (!seenLabels.has(endLabel)) {
    extras.push({
      date: domainEnd,
      label: endLabel,
      x: (xScale(domainEnd) ?? 0) + marginLeft,
    });
  }

  if (extras.length === 0) {
    return ticks;
  }

  return [...ticks, ...extras].sort((a, b) => a.x - b.x);
}

export function XAxis(props: XAxisProps) {
  const { containerRef } = useChartStable();

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  return <XAxisInner {...props} container={container} />;
}

const XAxisInner = memo(function XAxisInner({
  numTicks = 5,
  tickerHalfWidth = 50,
  tickMode = "data",
  labels: labelsProp,
  hoverEffect = "auto",
  activeLabelColor = chartCssVars.indicatorColor,
  nearbyLabelColor,
  highlightRadius = 80,
  labelClassName,
  container,
}: XAxisProps & { container: HTMLDivElement }) {
  const {
    xScale,
    margin,
    data,
    xAccessor,
    dateLabels: contextDateLabels,
    xDomain,
    width,
  } = useChartStable();
  const tooltipData = useChartHoverSelector(selectTooltipData);
  const datePillPresent = useDatePillPresent(container);
  const autoEffect = datePillPresent ? "fade" : "highlight";
  const effect = hoverEffect === "auto" ? autoEffect : hoverEffect;
  const nearbyColor = nearbyLabelColor ?? activeLabelColor;
  const dateLabels = labelsProp ?? contextDateLabels;
  const resolvedNumTicks = useMemo(
    () => resolveResponsiveChartLabelCount(numTicks, width, 5),
    [numTicks, width]
  );

  const labelsToShow = useMemo(() => {
    const projectionExtendsScale =
      tickMode === "data" && domainExtendsPastData(data, xAccessor, xScale);

    if (tickMode === "domain") {
      return buildDomainTicks({
        marginLeft: margin.left,
        numTicks: resolvedNumTicks,
        xScale,
      });
    }

    // No brush: evenly spaced ticks across the full domain (data + projection).
    if (projectionExtendsScale && xDomain == null) {
      return buildDomainTicks({
        marginLeft: margin.left,
        numTicks: resolvedNumTicks,
        xScale,
      });
    }

    const dataTicks = buildDataAlignedTicks({
      data,
      dateLabels,
      marginLeft: margin.left,
      targetTickCount: resolvedNumTicks,
      xAccessor,
      xScale,
    });

    // Brush: keep data-aligned ticks, add labels only in the projection tail.
    if (projectionExtendsScale && xDomain != null) {
      return appendProjectionTailTicks(
        dataTicks,
        data,
        xAccessor,
        xScale,
        margin.left,
        Math.max(1, resolvedNumTicks - dataTicks.length + 1)
      );
    }

    return dataTicks;
  }, [
    tickMode,
    xDomain,
    data,
    dateLabels,
    xAccessor,
    xScale,
    margin.left,
    resolvedNumTicks,
  ]);

  const crosshairX =
    tooltipData && effect !== "none" ? tooltipData.x + margin.left : null;
  const hoveredLabel = tooltipData
    ? (dateLabels[tooltipData.index] ??
      shortDateFmt.format(xAccessor(tooltipData.point)))
    : null;

  return createPortal(
    <div className="pointer-events-none absolute inset-0">
      {labelsToShow.map((item) => (
        <XAxisLabel
          animatePosition={xDomain == null}
          className={labelClassName}
          color={
            effect === "highlight"
              ? xAxisLabelColor(
                  xAxisLabelHighlight(
                    item.label,
                    item.x,
                    crosshairX,
                    hoveredLabel,
                    highlightRadius
                  ),
                  activeLabelColor,
                  nearbyColor
                )
              : undefined
          }
          key={`${item.date.getTime()}-${item.x}`}
          label={item.label}
          opacity={
            effect === "fade"
              ? xAxisLabelOpacity(
                  item.label,
                  item.x,
                  crosshairX,
                  hoveredLabel,
                  tickerHalfWidth
                )
              : 1
          }
          x={item.x}
        />
      ))}
    </div>,
    container
  );
});

XAxis.displayName = "XAxis";

export default XAxis;

import { type ScaleLinear, scaleLinear } from "d3-scale";
import type { LineConfig } from "./chart-context";

/** Default axis id when `yAxisId` is omitted (Recharts-style `0` / primary left axis). */
export const DEFAULT_Y_AXIS_ID = "left";

export type YAxisOrientation = "left" | "right";

export function normalizeYAxisId(id?: string | number): string {
  if (id == null || id === "") {
    return DEFAULT_Y_AXIS_ID;
  }
  return String(id);
}

export function groupLinesByYAxisId(
  lines: LineConfig[]
): Map<string, LineConfig[]> {
  const groups = new Map<string, LineConfig[]>();
  for (const line of lines) {
    const axisId = normalizeYAxisId(line.yAxisId);
    const bucket = groups.get(axisId) ?? [];
    bucket.push(line);
    groups.set(axisId, bucket);
  }
  return groups;
}

type YScale = ScaleLinear<number, number>;

export function getPrimaryYScale(
  yScales: Record<string, YScale>,
  fallback: YScale
): YScale {
  const primary = yScales[DEFAULT_Y_AXIS_ID];
  if (primary) {
    return primary;
  }
  const first = Object.values(yScales)[0];
  return first ?? fallback;
}

export function buildYScalesForLines({
  lines,
  innerHeight,
  resolveDomain,
}: {
  lines: LineConfig[];
  /** Passed by callers; domain is resolved via `resolveDomain`. */
  data?: Record<string, unknown>[];
  innerHeight: number;
  resolveDomain: (dataKeys: string[]) => [number, number];
}): Record<string, YScale> {
  const groups = groupLinesByYAxisId(lines);
  const scales: Record<string, YScale> = {};

  for (const [axisId, axisLines] of groups) {
    const dataKeys = axisLines.map((line) => line.dataKey);
    const domain = resolveDomain(dataKeys);
    scales[axisId] = scaleLinear()
      .domain(domain)
      .nice()
      .range([innerHeight, 0]);
  }

  if (!scales[DEFAULT_Y_AXIS_ID]) {
    scales[DEFAULT_Y_AXIS_ID] = scaleLinear()
      .domain([0, 100])
      .nice()
      .range([innerHeight, 0]);
  }

  return scales;
}

/** Build y-scales from pre-computed (already nice'd) domain endpoints. */
export function buildYScalesFromDomains({
  lines,
  innerHeight,
  domainsByAxis,
}: {
  lines: LineConfig[];
  innerHeight: number;
  domainsByAxis: Record<string, [number, number]>;
}): Record<string, YScale> {
  const groups = groupLinesByYAxisId(lines);
  const scales: Record<string, YScale> = {};

  for (const [axisId] of groups) {
    const domain =
      domainsByAxis[axisId] ??
      domainsByAxis[DEFAULT_Y_AXIS_ID] ??
      ([0, 100] as [number, number]);
    scales[axisId] = scaleLinear().domain(domain).range([innerHeight, 0]);
  }

  if (!scales[DEFAULT_Y_AXIS_ID]) {
    scales[DEFAULT_Y_AXIS_ID] = scaleLinear()
      .domain(domainsByAxis[DEFAULT_Y_AXIS_ID] ?? [0, 100])
      .range([innerHeight, 0]);
  }

  return scales;
}

/** Single-axis charts (bar, scatter, candlestick, live line). */
export function wrapSingleYScale(yScale: YScale): Record<string, YScale> {
  return { [DEFAULT_Y_AXIS_ID]: yScale };
}

/** Default hint passed to `scale.ticks()` (d3 — approximate tick count). */
export const Y_AXIS_DEFAULT_TICK_COUNT = 5;

/** Minimum valid `numTicks` for `scale.ticks()` — values ≤ 0 yield no ticks. */
export const Y_AXIS_MIN_TICK_COUNT = 1;

/**
 * Upper bound for the tick count hint. D3 may return more "nice" ticks above ~10;
 * keeping the hint in a modest range avoids overcrowded axes.
 */
export const Y_AXIS_MAX_TICK_COUNT = 10;

/** Clamps a user `numTicks` value to a valid d3 tick-count hint. */
export function resolveYAxisTickCount(numTicks?: number): number {
  if (numTicks == null || !Number.isFinite(numTicks)) {
    return Y_AXIS_DEFAULT_TICK_COUNT;
  }
  const rounded = Math.round(numTicks);
  if (rounded < Y_AXIS_MIN_TICK_COUNT) {
    return Y_AXIS_MIN_TICK_COUNT;
  }
  if (rounded > Y_AXIS_MAX_TICK_COUNT) {
    return Y_AXIS_MAX_TICK_COUNT;
  }
  return rounded;
}

"use client";

import {
  AnimatePresence,
  m,
  useReducedMotion,
  type Variants,
} from "motion/react";
import { memo, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  useChartPortalContainer,
  useChartStable,
  useSettledYScale,
  useYScale,
} from "./chart-context";
import { crosshairTickOpacity, subscribeCrosshair } from "./crosshair-store";
import { resolveReferenceDataRange } from "./reference-area-geometry";
import type { YAxisOrientation } from "./y-axis-scales";
import { normalizeYAxisId } from "./y-axis-scales";
import {
  resolveYAxisTickCount,
  Y_AXIS_DEFAULT_TICK_COUNT,
} from "./y-axis-ticks";

/** Half the `ChartCrosshair` value pill height (h-6 + py-1). */
const CROSSHAIR_PILL_HALF_HEIGHT = 16;

/** Vertical drift (px) of labels fading in / out on a y-domain change. */
const Y_AXIS_LABEL_SHIFT_PX = 8;
const Y_AXIS_LABEL_EASE_OUT = [0.23, 1, 0.32, 1] as const;
const Y_AXIS_LABEL_ENTER_S = 0.4;
const Y_AXIS_LABEL_EXIT_S = 0.25;
const Y_AXIS_LABEL_CLIP_BLEED_PX = 12;
/** Delay between consecutive entering labels (cascade). */
const Y_AXIS_LABEL_STAGGER_S = 0.05;

/**
 * Direction labels travel while the y-domain tweens: `-1` (up) when the
 * domain shrinks — values grow apart and rise — `1` (down) when it grows.
 */
type LabelDrift = -1 | 1;

interface LabelMotion {
  drift: LabelDrift;
  reducedMotion: boolean;
}

const labelVariants: Variants = {
  hidden: ({ drift }: LabelMotion) => ({
    opacity: 0,
    y: -drift * Y_AXIS_LABEL_SHIFT_PX,
  }),
  visible: { opacity: 1, y: 0 },
  exit: ({ drift, reducedMotion }: LabelMotion) => ({
    opacity: 0,
    y: drift * Y_AXIS_LABEL_SHIFT_PX,
    transition: {
      duration: reducedMotion ? 0 : Y_AXIS_LABEL_EXIT_S,
      ease: Y_AXIS_LABEL_EASE_OUT,
    },
  }),
};

export interface YAxisProps {
  /** Scale group id (Recharts `yAxisId`). Default: `"left"`. */
  yAxisId?: string | number;
  /** Which side of the chart to render labels. Default: `"left"`. */
  orientation?: YAxisOrientation;
  /**
   * Approximate tick count hint for `scale.ticks()` (d3). Actual label count may differ.
   * Clamped to {@link Y_AXIS_MIN_TICK_COUNT}–{@link Y_AXIS_MAX_TICK_COUNT}. Default: 5.
   */
  numTicks?: number;
  /** Format large numbers (e.g. 1000 as "1k"). Default: true */
  formatLargeNumbers?: boolean;
  /** Custom formatter for tick labels (e.g. USD). Overrides formatLargeNumbers when set. */
  formatValue?: (value: number) => string;
}

function formatLabel(
  value: number,
  formatLargeNumbers: boolean,
  formatValue?: (value: number) => string
): string {
  if (formatValue) {
    return formatValue(value);
  }
  if (formatLargeNumbers && value >= 1000) {
    // One decimal so 1500 reads "1.5k", not a second "2k".
    return `${Number((value / 1000).toFixed(1))}k`;
  }
  return String(value);
}

function resolveTickLabelColor(
  tickY: number,
  axisId: string,
  yScale: ReturnType<typeof useYScale>,
  referenceAreas: ReturnType<typeof useChartStable>["referenceAreas"]
): string | undefined {
  for (const area of referenceAreas) {
    if (!area.axisLabelColor) {
      continue;
    }
    if (normalizeYAxisId(area.yAxisId) !== axisId) {
      continue;
    }
    const [low, high] = resolveReferenceDataRange(
      area.y1,
      area.y2,
      yScale.domain() as [number, number]
    );
    const topPixel = yScale(high) ?? 0;
    const bottomPixel = yScale(low) ?? 0;
    const bandTop = Math.min(topPixel, bottomPixel);
    const bandBottom = Math.max(topPixel, bottomPixel);
    if (tickY >= bandTop && tickY <= bandBottom) {
      return area.axisLabelColor;
    }
  }
  return undefined;
}

export function YAxis(props: YAxisProps) {
  const { containerRef } = useChartStable();

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  return <YAxisInner {...props} container={container} />;
}

const YAxisInner = memo(function YAxisInner({
  yAxisId,
  orientation = "left",
  numTicks = Y_AXIS_DEFAULT_TICK_COUNT,
  formatLargeNumbers = true,
  formatValue,
  container,
}: YAxisProps & { container: HTMLDivElement }) {
  const { margin, referenceAreas } = useChartStable();
  const yScale = useYScale(yAxisId);
  // Tick values come from the settled (target) domain so a y-domain tween
  // swaps one label set for the next once, instead of churning through every
  // intermediate tick set; positions still follow the live scale each frame.
  const settledYScale = useSettledYScale(yAxisId);
  const reducedMotion = useReducedMotion() ?? false;
  const isLeft = orientation === "left";
  const axisId = normalizeYAxisId(yAxisId);

  const [settledMin, settledMax] = settledYScale.domain() as [number, number];
  const settledSpan = settledMax - settledMin;
  const [prevSettledSpan, setPrevSettledSpan] = useState(settledSpan);
  const [drift, setDrift] = useState<LabelDrift>(-1);
  if (settledSpan !== prevSettledSpan) {
    setPrevSettledSpan(settledSpan);
    setDrift(settledSpan < prevSettledSpan ? -1 : 1);
  }

  const tickValues = useMemo(
    () => settledYScale.ticks(resolveYAxisTickCount(numTicks)),
    [settledYScale, numTicks]
  );

  const ticks = useMemo(() => {
    return tickValues.map((value) => {
      const y = (yScale(value) ?? 0) + margin.top;
      return {
        value,
        y,
        label: formatLabel(value, formatLargeNumbers, formatValue),
        labelColor: resolveTickLabelColor(
          y - margin.top,
          axisId,
          yScale,
          referenceAreas
        ),
      };
    });
  }, [
    tickValues,
    yScale,
    margin.top,
    formatLargeNumbers,
    formatValue,
    axisId,
    referenceAreas,
  ]);

  return createPortal(
    <div className="pointer-events-none absolute inset-0">
      <div
        className="absolute overflow-hidden"
        style={{
          // Clip labels tweening in from far off-scale, with room for a
          // half-height edge label when the chart margin is tight.
          top: -Y_AXIS_LABEL_CLIP_BLEED_PX,
          bottom: -Y_AXIS_LABEL_CLIP_BLEED_PX,
          ...(isLeft
            ? { left: 0, width: margin.left }
            : { right: 0, width: margin.right }),
        }}
      >
        <AnimatePresence
          custom={{ drift, reducedMotion } satisfies LabelMotion}
          initial={false}
        >
          {ticks.map((tick, index) => {
            // Cascade in the direction of travel: bottom-up while labels
            // rise, top-down while they fall.
            const cascadeIndex = drift < 0 ? index : ticks.length - 1 - index;
            return (
              <m.div
                animate="visible"
                className="absolute flex h-0 items-center"
                custom={{ drift, reducedMotion } satisfies LabelMotion}
                exit="exit"
                initial="hidden"
                key={tick.value}
                style={{
                  top: tick.y + Y_AXIS_LABEL_CLIP_BLEED_PX,
                  ...(isLeft
                    ? { right: 0, justifyContent: "flex-end", paddingRight: 8 }
                    : {
                        left: 0,
                        justifyContent: "flex-start",
                        paddingLeft: 8,
                      }),
                }}
                transition={
                  reducedMotion
                    ? { duration: 0 }
                    : {
                        delay: cascadeIndex * Y_AXIS_LABEL_STAGGER_S,
                        duration: Y_AXIS_LABEL_ENTER_S,
                        ease: Y_AXIS_LABEL_EASE_OUT,
                      }
                }
                variants={labelVariants}
              >
                <YAxisTickLabel
                  axisId={axisId}
                  color={tick.labelColor}
                  container={container}
                  label={tick.label}
                  plotY={tick.y - margin.top}
                />
              </m.div>
            );
          })}
        </AnimatePresence>
      </div>
    </div>,
    container
  );
});

YAxis.displayName = "YAxis";

/**
 * Tick label that fades under a `ChartCrosshair` value pill on the same axis.
 * The fade is written straight to the DOM from the crosshair's pointer
 * handler — no React render per pointer move.
 */
function YAxisTickLabel({
  label,
  color,
  container,
  axisId,
  plotY,
}: {
  label: string;
  color?: string;
  container: HTMLDivElement;
  axisId: string;
  plotY: number;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    let current = 1;
    return subscribeCrosshair(container, (state) => {
      const next = crosshairTickOpacity(
        state,
        axisId,
        plotY,
        CROSSHAIR_PILL_HALF_HEIGHT
      );
      if (next !== current && ref.current) {
        current = next;
        ref.current.style.opacity = String(next);
      }
    });
  }, [container, axisId, plotY]);
  return (
    <span
      className="whitespace-nowrap text-chart-label text-xs"
      ref={ref}
      style={{ color, transition: "opacity 0.4s ease-in-out" }}
    >
      {label}
    </span>
  );
}

import { scaleLinear } from "d3-scale";
import type { LineConfig } from "./chart-context";
import { type ChartPhase, Y_DOMAIN_TWEEN_SKIP_THRESHOLD } from "./chart-phase";
import { groupLinesByYAxisId, normalizeYAxisId } from "./y-axis-scales";

export type YDomain = [number, number];

/**
 * Per-axis y-domain override: a fixed `[min, max]`, or a function that
 * receives the auto domain (before `nice()`) and returns the one to use —
 * e.g. `([, max]) => [0, max * 3]` to push volume bars into the bottom third.
 */
export type YDomainOverride = YDomain | ((auto: YDomain) => YDomain);

export function applyYDomainOverride(
  auto: YDomain,
  override: YDomainOverride | undefined
): YDomain {
  if (!override) {
    return auto;
  }
  return typeof override === "function" ? override(auto) : override;
}

export interface NumericExtents {
  minValue: number;
  maxValue: number;
}

/** Min / max over every numeric `dataKeys` value. `{ 0, 100 }` when none are numeric. */
export function collectNumericExtents(
  data: Record<string, unknown>[],
  dataKeys: string[]
): NumericExtents {
  let minValue = Number.POSITIVE_INFINITY;
  let maxValue = Number.NEGATIVE_INFINITY;

  for (const d of data) {
    for (const key of dataKeys) {
      const value = d[key];
      if (typeof value === "number") {
        if (value < minValue) {
          minValue = value;
        }
        if (value > maxValue) {
          maxValue = value;
        }
      }
    }
  }

  if (minValue === Number.POSITIVE_INFINITY) {
    return { minValue: 0, maxValue: 100 };
  }

  return { minValue, maxValue };
}

/**
 * Line / area y-domain: zero-anchored while every value is >= 0, padded
 * min..max once any value is negative.
 */
export function resolveTimeSeriesYDomain(
  data: Record<string, unknown>[],
  dataKeys: string[],
  yScaleDomainMax: number | undefined
): YDomain {
  if (yScaleDomainMax != null && yScaleDomainMax > 0) {
    return [0, yScaleDomainMax * 1.1];
  }

  const { minValue, maxValue } = collectNumericExtents(data, dataKeys);

  if (minValue >= 0) {
    const top = maxValue <= 0 ? 100 : maxValue * 1.1;
    return [0, top];
  }

  const padding = (maxValue - minValue) * 0.05 || 1;
  return [minValue - padding, maxValue + padding];
}

/**
 * Floating y-domain (no zero anchor): padded min..max. For price-like series
 * such as candlesticks, where a zero baseline would flatten every candle.
 */
export function resolveFloatingYDomain(
  data: Record<string, unknown>[],
  dataKeys: string[]
): YDomain {
  const { minValue, maxValue } = collectNumericExtents(data, dataKeys);
  const padding = (maxValue - minValue) * 0.05 || 1;
  return [minValue - padding, maxValue + padding];
}

/**
 * Value extents for bar series. Stacked bars use the running totals (always
 * including the zero baseline) so the domain reaches every segment end;
 * grouped bars use the individual values.
 */
export function collectBarValueExtents(
  data: Record<string, unknown>[],
  dataKeys: string[],
  stacked: boolean
): NumericExtents {
  if (!stacked) {
    return collectNumericExtents(data, dataKeys);
  }
  let minValue = 0;
  let maxValue = 0;
  for (const d of data) {
    let sum = 0;
    for (const key of dataKeys) {
      const value = d[key];
      if (typeof value === "number") {
        sum += value;
        minValue = Math.min(minValue, sum);
        maxValue = Math.max(maxValue, sum);
      }
    }
  }
  return { minValue, maxValue };
}

/**
 * Bar value-axis domain. Bars grow from zero, so the domain always includes
 * 0: `[0, max * 1.1]` while every value is >= 0 (falls back to `[0, 110]`
 * when there is no positive value), and a padded min..max stretched to
 * include zero once any value is negative.
 */
export function resolveBarValueDomain({
  minValue,
  maxValue,
}: NumericExtents): YDomain {
  if (minValue >= 0) {
    return [0, (maxValue > 0 ? maxValue : 100) * 1.1];
  }

  const padding = (maxValue - minValue) * 0.05 || 1;
  return [Math.min(0, minValue - padding), Math.max(0, maxValue + padding)];
}

/** Apply d3 `nice()` to raw domain endpoints for stable grid ticks. */
export function niceYDomain(domain: YDomain): YDomain {
  const scale = scaleLinear().domain(domain).nice().range([0, 1]);
  const niceDomain = scale.domain();
  return [niceDomain[0] ?? domain[0], niceDomain[1] ?? domain[1]];
}

/**
 * Skip Y tween when both endpoints move less than the threshold relative to span.
 * When in doubt callers should tween — beauty wins over micro-optimization.
 */
export function shouldTweenYDomain(from: YDomain, to: YDomain): boolean {
  const span = Math.max(
    Math.abs(to[1] - to[0]),
    Math.abs(from[1] - from[0]),
    1
  );
  const deltaMin = Math.abs(to[0] - from[0]) / span;
  const deltaMax = Math.abs(to[1] - from[1]) / span;
  return (
    deltaMin >= Y_DOMAIN_TWEEN_SKIP_THRESHOLD ||
    deltaMax >= Y_DOMAIN_TWEEN_SKIP_THRESHOLD
  );
}

/** Phases where the chart shows loading chrome (shimmer, pulse, label). */
export function isLoadingChromePhase(phase: ChartPhase): boolean {
  return phase === "loading" || phase === "revealingLoading";
}

/** Phases where grid lines use loading stroke styling (muted / dashed chrome). */
export function isLoadingGridChromePhase(phase: ChartPhase): boolean {
  return (
    phase === "loading" || phase === "exiting" || phase === "gridTweenLoading"
  );
}

/** Phases where Y-domain tween runs after the series has exited. */
export function isYDomainTweenPhase(phase: ChartPhase): boolean {
  return phase === "gridTweenLoading" || phase === "gridTweenReady";
}

/** Phases where {@link ReferenceArea} bands are shown (fade in/out on transitions). */
export function isReferenceAreaVisiblePhase(phase: ChartPhase): boolean {
  return (
    phase === "ready" || phase === "revealing" || phase === "gridTweenReady"
  );
}

export function resolveAnimatedYDestinationDomains(
  chartPhase: ChartPhase,
  skeletonByAxis: Record<string, YDomain>,
  targetByAxis: Record<string, YDomain>
): Record<string, YDomain> {
  switch (chartPhase) {
    case "loading":
    case "exiting":
    case "gridTweenLoading":
      return skeletonByAxis;
    case "exitingReady":
    case "gridTweenReady":
    case "revealing":
    case "ready":
      return targetByAxis;
    default:
      return targetByAxis;
  }
}

export function computeYDomainsByAxis({
  lines,
  resolveDomain,
  extraKeysByAxis,
}: {
  lines: LineConfig[];
  /** Raw domain for one axis; `axisId` is normalised (`"left"` by default). */
  resolveDomain: (dataKeys: string[], axisId: string) => YDomain;
  /**
   * Additional value keys per axis that extend the domain without being
   * series (e.g. `<Band>` upper/lower keys). Axes with only extra keys still
   * get a domain.
   */
  extraKeysByAxis?: Record<string, string[]>;
}): Record<string, YDomain> {
  const keysByAxis = new Map<string, string[]>();
  for (const [axisId, axisLines] of groupLinesByYAxisId(lines)) {
    keysByAxis.set(
      normalizeYAxisId(axisId),
      axisLines.map((line) => line.dataKey)
    );
  }
  for (const [axisId, extraKeys] of Object.entries(extraKeysByAxis ?? {})) {
    const id = normalizeYAxisId(axisId);
    const keys = keysByAxis.get(id) ?? [];
    keysByAxis.set(id, [
      ...keys,
      ...extraKeys.filter((key) => !keys.includes(key)),
    ]);
  }

  const domains: Record<string, YDomain> = {};
  for (const [axisId, dataKeys] of keysByAxis) {
    domains[axisId] = niceYDomain(resolveDomain(dataKeys, axisId));
  }

  if (!domains.left) {
    domains.left = niceYDomain([0, 100]);
  }

  return domains;
}

/** Merge domain maps, normalizing axis ids to strings. */
export function mergeYDomainRecords(
  ...records: Record<string, YDomain>[]
): Record<string, YDomain> {
  const merged: Record<string, YDomain> = {};
  for (const record of records) {
    for (const [axisId, domain] of Object.entries(record)) {
      merged[normalizeYAxisId(axisId)] = domain;
    }
  }
  return merged;
}

export function domainsEqual(
  left: Record<string, YDomain>,
  right: Record<string, YDomain>
): boolean {
  const leftKeys = Object.keys(left);
  const rightKeys = Object.keys(right);
  if (leftKeys.length !== rightKeys.length) {
    return false;
  }

  for (const axisId of leftKeys) {
    const from = left[axisId];
    const to = right[axisId];
    if (!(from && to) || from[0] !== to[0] || from[1] !== to[1]) {
      return false;
    }
  }

  return true;
}

import { useDashboardReplay } from "../preview-animation";
import { AccessiblePlot } from "./accessible-plot";
import { RadarArea } from "./bklit/radar-area";
import { RadarAxis } from "./bklit/radar-axis";
import { RadarChart } from "./bklit/radar-chart";
import { RadarGrid } from "./bklit/radar-grid";
import { RadarLabels } from "./bklit/radar-labels";
import { ChartHeading, panel } from "./chart-controls";
import type { TrafficChannel } from "./data";

const indicators = [
  { key: "newVisitors", label: "新访客占比", color: "var(--chart-1)" },
  { key: "registrations", label: "注册转化率", color: "var(--chart-3)" },
] as const;
const number = new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 1 });

export function ChannelRadar({ channels, monthLabel }: { channels: TrafficChannel[]; monthLabel: string }) {
  const replay = useDashboardReplay();
  const ranked = channels.filter(channel => channel.visitors > 0)
    .toSorted((a, b) => b.visitors - a.visitors).slice(0, 5);
  const axes = ranked.map(channel => ({ key: channel.id, label: channel.name }));
  const series = indicators.map(({ key, label, color }) => ({
    label, color,
    values: Object.fromEntries(ranked.map(channel => [channel.id, 100 * channel[key] / channel.visitors])),
  }));

  return (
    <section id="dashboard-quality" aria-label="渠道质量分布" tabIndex={-1} className={`${panel} flex min-h-[318px] flex-col`}>
      <ChartHeading title="渠道质量分布" description="按独立访客数排名的前五个渠道" />
      <div className="mt-3 grid min-h-[196px] min-w-0 flex-1 place-items-center [container-type:size]">
        <div className="aspect-square w-[min(100cqw,100cqh)]">
          <AccessiblePlot label={`${monthLabel}各渠道的新访客占比和注册转化率`} values={axes.map(axis =>
            [axis.label, ...series.map(item => `${item.label} ${number.format(item.values[axis.key])}%`)].join("，")
          )}>
            <RadarChart key={`${monthLabel}-${replay}`} data={series} metrics={axes} margin={30}>
              <RadarGrid />
              <RadarAxis />
              <RadarLabels fontSize={10} offset={14} />
              {series.map((item, index) => <RadarArea key={item.label} index={index} />)}
            </RadarChart>
          </AccessiblePlot>
        </div>
      </div>
    </section>
  );
}

import { useMemo, useState, type ReactNode } from "react";
import { useDashboardReplay } from "../preview-animation";
import { ChartHeading, ChartLegendKey, chartLegendLayout, focusRing, panel } from "./chart-controls";
import { AccessiblePlot } from "./accessible-plot";
import { ChartBrush } from "./bklit/chart-brush";
import { ChartBrushLayout } from "./bklit/chart-brush-layout";
import { chartCssVars } from "./bklit/chart-context";
import { ChartLegendHoverProvider } from "./bklit/chart-legend-hover";
import { TooltipContent } from "./bklit/tooltip/tooltip-content";
import { Grid } from "./bklit/grid";
import { Line } from "./bklit/line";
import { LineChart } from "./bklit/line-chart";
import { ChartTooltip } from "./bklit/tooltip/chart-tooltip";
import { XAxis } from "./bklit/x-axis";
import { YAxis } from "./bklit/y-axis";
import { formatCount, reports, type ReportMonth } from "./data";

// Bklit's time-scale and brush both address a datum by Date. Equally spaced
// day slots keep our categorical channel labels, crosshair and brush aligned.
const day = 86_400_000;
const margin = { top: 22, right: 26, bottom: 34, left: 52 };
const amount = (value: unknown) => (typeof value === "number" ? `${formatCount(value)} 次` : "—");

export function ChannelVisitsChart({ month, action }: { month: ReportMonth; action?: ReactNode }) {
  const replay = useDashboardReplay();
  const [hovered, setHovered] = useState<number | null>(null);
  const { channels, label, previous } = reports[month];
  const data = useMemo(() => {
    const last = new Map(previous.channels.map((row) => [row.id, row.visits]));
    return channels.map((row, i) => ({
      date: new Date(i * day),
      name: row.name,
      current: row.visits,
      previous: last.get(row.id),
    }));
  }, [channels, previous]);
  const series = [
    { key: "current", label, color: chartCssVars.linePrimary },
    { key: "previous", label: previous.label, color: chartCssVars.lineSecondary },
  ] as const;
  const lines = series.map(({ key, color }) => <Line key={key} dataKey={key} stroke={color} />);
  return (
    <section
      className={`${panel} @container/visits flex flex-col`}
      id="dashboard-ranking"
      tabIndex={-1}
      aria-label="各渠道访问量"
    >
      <div className="flex items-start justify-between gap-3">
        <ChartHeading title="各渠道访问量" />
        {action}
      </div>
      <p className="mt-2 text-[11px] text-(--chart-foreground-muted)">访问次数（次）</p>
      <ChartLegendHoverProvider hoveredIndex={hovered} onHoverChange={setHovered}>
        <div className="mt-2 min-h-[225px] min-w-0 flex-1 @min-[600px]/visits:min-h-[260px]">
          <AccessiblePlot
            label="各渠道访问次数"
            values={data.map(
              (row) =>
                `${row.name}，${label} ${amount(row.current)}，${previous.label} ${amount(row.previous)}`,
            )}
          >
            <ChartBrushLayout
              data={data}
              enabled
              height={32}
              brushStrip={({ brushSelection, onBrushSelectionChange }) => (
                <div className="size-full" role="group" aria-label="渠道范围缩略轴">
                  <LineChart
                    data={data}
                    animationDuration={0}
                    aspectRatio="auto"
                    className="size-full"
                    margin={{ top: 5, right: margin.right, bottom: 5, left: margin.left }}
                  >
                    {series.map(({ key, color }) => (
                      <Line key={key} dataKey={key} stroke={color} strokeWidth={1.5} />
                    ))}
                    <ChartBrush
                      initialSelection={brushSelection}
                      onSelectionChange={onBrushSelectionChange}
                    />
                  </LineChart>
                </div>
              )}
            >
              {({ xDomain, xDomainSlotCount }) => {
                const labels = data
                  .filter(row => !xDomain || (row.date >= xDomain[0] && row.date <= xDomain[1]))
                  .map(row => row.name);
                return (
                  <LineChart
                    key={replay}
                    data={data}
                    aspectRatio="auto"
                    className="size-full"
                    margin={margin}
                    revealSignature={month}
                    xDomain={xDomain}
                    xDomainSlotCount={xDomainSlotCount}
                  >
                    <Grid horizontal />
                    {lines}
                    <XAxis numTicks={{ base: 3, sm: 6 }} labels={labels} />
                    <YAxis formatValue={formatCount} />
                    <ChartTooltip
                      dateLabels={labels}
                      datePillAnimation="static"
                      content={({ point }) => (
                        <TooltipContent
                          title={String(point.name)}
                          rows={series.map((line) => ({
                            label: line.label,
                            color: line.color,
                            value: amount(point[line.key]),
                          }))}
                        />
                      )}
                    />
                  </LineChart>
                );
              }}
            </ChartBrushLayout>
          </AccessiblePlot>
        </div>
        <div role="group" aria-label="统计月份图例" className={chartLegendLayout}>
          {series.map((line, index) => (
            <button
              key={line.key}
              type="button"
              className={`inline-flex cursor-pointer rounded-sm ${focusRing}`}
              onPointerEnter={() => setHovered(index)}
              onPointerLeave={() => setHovered(null)}
              onFocus={() => setHovered(index)}
              onBlur={() => setHovered(null)}
            >
              <ChartLegendKey label={line.label} color={line.color} />
            </button>
          ))}
        </div>
      </ChartLegendHoverProvider>
    </section>
  );
}

import { Select } from "@base-ui/react/select";
