/* Keep the Design Stack row identities and actions visible while metrics scroll. */
#dashboard-tools [role="grid"] {
  position: relative;
  isolation: isolate;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr);
  --stack-checkbox-width: 40px;
  --stack-tool-width: 112px;
  --stack-actions-width: 84px;
  --stack-scroll-shadow: rgb(0 0 0 / 10%);
}

.dark #dashboard-tools [role="grid"] { --stack-scroll-shadow: rgb(0 0 0 / 36%); }

#dashboard-tools [role="grid"]::before,
#dashboard-tools [role="grid"]::after {
  content: "";
  position: absolute;
  z-index: 2;
  inset-block: 0;
  width: 8px;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(to right, var(--stack-scroll-shadow), transparent);
  transition: opacity 150ms ease;
}

#dashboard-tools [role="grid"]::before { inset-inline-start: calc(var(--stack-checkbox-width) + var(--stack-tool-width)); }
#dashboard-tools [role="grid"]::after {
  inset-inline-end: calc(var(--stack-actions-width) + var(--stack-scrollbar-width, 0px));
  transform: scaleX(-1);
}
#dashboard-tools [role="grid"]:dir(rtl)::before { transform: scaleX(-1); }
#dashboard-tools [role="grid"]:dir(rtl)::after { transform: none; }
#dashboard-tools[data-overflow-start] [role="grid"]::before,
#dashboard-tools[data-overflow-end] [role="grid"]::after { opacity: 1; }

#dashboard-tools :is([data-slot="kalos-table-header"], [data-slot="kalos-table-scroll"]) {
  overscroll-behavior-x: none;
  scroll-padding-inline: calc(var(--stack-checkbox-width) + var(--stack-tool-width)) var(--stack-actions-width);
}

#dashboard-tools tr > :is(:first-child, :nth-child(2), :last-child):not(:only-child) {
  position: sticky;
  z-index: 1;
  background-color: var(--k-table-surface);
  background-image: linear-gradient(var(--stack-row-tint, transparent), var(--stack-row-tint, transparent));
}

#dashboard-tools tr > :first-child:not(:only-child) { inset-inline-start: 0; }
#dashboard-tools tr > :nth-child(2) { inset-inline-start: var(--stack-checkbox-width); }
#dashboard-tools tr > :last-child:not(:only-child) { inset-inline-end: 0; }

#dashboard-tools tbody tr:hover { --stack-row-tint: var(--k-table-hover); }
#dashboard-tools tbody tr[data-selected="true"],
#dashboard-tools td[data-range="true"] { --stack-row-tint: var(--k-table-selected); }

.dashboard-overview .text-chart-label { color: var(--chart-label); }

.dashboard-overview .bg-chart-tooltip-background { background-color: var(--chart-tooltip-background); }

.dashboard-overview .text-chart-tooltip-foreground { color: var(--chart-tooltip-foreground); }

.dashboard-overview .text-chart-tooltip-muted { color: var(--chart-tooltip-muted); }

