}

export function PriceChart({ month }: { month: ReportMonth }) {
  const replay = useDashboardReplay();
  const quotes = priceHistory[month];
  const labels = quotes.map(({ date }) => `${date.getUTCMonth() + 1}月 ${date.getUTCDate()}日`);

  return (
    <section id="dashboard-price" aria-label="价格走势" tabIndex={-1} className={`${panel} flex min-h-[318px] flex-col`}>
      <ChartHeading title="价格走势" />
      <div className="relative mt-4 min-h-[220px] flex-1">
        <div className="absolute inset-0">
          <AccessiblePlot label="每日开盘、最高、最低和收盘价" values={quotes.map((quote, index) =>
            [labels[index], ...fields.map(({ key, label }) => `${label} ${currency.format(quote[key])}`)].join("，")
          )}>
            <CandlestickChart key={replay} data={quotes} margin={margin} aspectRatio="auto" className="size-full" revealSignature={month}>
              <Candlestick positiveFill={upColor} negativeFill={downColor} fadedOpacity={0.25} />
              <ChartTooltip
                dateLabels={labels}
                showDots={false}
                indicatorColor={point => Number(point.close) >= Number(point.open) ? upColor : downColor}
                content={({ index }) => <PriceTooltip quote={quotes[index]} />}
              />
              <XAxis labels={labels} numTicks={{ base: 3, sm: 5 }} />
            </CandlestickChart>
          </AccessiblePlot>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useLayoutEffect, useRef, type ReactNode } from "react";
import type { ReportMonth } from "./data";
import "./stat-card-font.css";

const compact = new Intl.NumberFormat("en", { notation: "compact", maximumFractionDigits: 1 });
const countDuration = 720;
const percent = new Intl.NumberFormat("en", {
  style: "percent",
  signDisplay: "exceptZero",
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});

const cards = [
  { label: "营收额", "2026-07": { firstDay: 4226, latest: 4210 }, "2026-08": { firstDay: 4519, latest: 4587 } },
  { label: "曝光量", "2026-07": { firstDay: 1558, latest: 1751 }, "2026-08": { firstDay: 1926, latest: 1286 } },
  { label: "订单数", "2026-07": { firstDay: 99, latest: 132 }, "2026-08": { firstDay: 129, latest: 170 } },
  { label: "注册数", "2026-07": { firstDay: 52, latest: 85 }, "2026-08": { firstDay: 68, latest: 112 } },
];

function StatReading({ firstDay, latest }: { firstDay: number; latest: number }) {
  const output = useRef<HTMLSpanElement>(null);
  const current = useRef(0);
  const change = (latest - firstDay) / firstDay;

  // Activity reconnects layout effects when Data becomes visible again.
  useLayoutEffect(() => {
    current.current = 0;
  }, []);

  useLayoutEffect(() => {
    const element = output.current;
    if (!element) return;
    const from = current.current;
    const started = performance.now();
    let frame: number;

    const paint = (value: number) => {
      current.current = value;
      const text = compact.format(Math.round(value));
      if (element.textContent !== text) element.textContent = text;
    };

    function tick(now: number) {
      const progress = Math.min(1, Math.max(0, (now - started) / countDuration));
      paint(from + (latest - from) * (1 - (1 - progress) ** 3));
      if (progress < 1) frame = requestAnimationFrame(tick);
    }

    paint(from);
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [latest]);

  return (
    <div className="flex items-baseline justify-between gap-1 tabular-nums @min-[561px]/overview:gap-2">
      <span className="shrink-0 text-2xl leading-8 font-semibold">
        <span ref={output} aria-hidden="true">0</span>
        <span className="sr-only">{compact.format(latest)}</span>
      </span>
      <span className="flex min-w-0 flex-wrap items-baseline justify-end gap-x-1 text-xs leading-4 text-(--stat-muted)">
        <span className={change >= 0 ? "text-(--chart-positive)" : "text-(--chart-negative)"}>
          {percent.format(change)}
        </span>
        <span className="whitespace-nowrap">vs Day 1</span>
      </span>
    </div>
  );
}

export function StatCards(props: { month: ReportMonth } | { placeholder: ReactNode }) {
  return (
    <div className="grid min-w-0 grid-cols-2 gap-2 @min-[561px]/overview:gap-3 @min-[821px]/overview:grid-cols-4">
      {cards.map(card => (
        <section
          key={card.label}
          aria-label={card.label}
          className="dashboard-stat flex min-w-0 flex-col gap-2 rounded-xl border p-3 @min-[561px]/overview:px-4 @min-[561px]/overview:py-3.5"
        >
          <h2 className="text-xs leading-4 font-normal text-(--stat-muted)">{card.label}</h2>
          {"month" in props ? <StatReading {...card[props.month]} /> : props.placeholder}
        </section>
      ))}
    </div>
  );
}

import { useState } from "react";
import { ChartHeading, focusRing, panel } from "./chart-controls";
import { metrics, seriesColor, type TrafficChannel, type Metric } from "./data";
import { GroupedBars } from "./grouped-bars";

const comparisonMetrics = metrics
  .map((metric, index) => ({ ...metric, color: seriesColor(index) }))
  .filter((metric) => metric.key !== "newVisitors");

export function TrafficComparison({ channels }: { channels: TrafficChannel[] }) {
  const [shown, setShown] = useState<Metric[]>(comparisonMetrics.map((metric) => metric.key));
  const [hoveredMetric, setHoveredMetric] = useState<Metric | null>(null);
  const series = comparisonMetrics.filter((metric) => shown.includes(metric.key));
  function toggle(metric: Metric) {
    setShown((current) =>
      current.includes(metric) ? current.filter((value) => value !== metric) : [...current, metric],
    );
  }
  return (
    <section
      id="dashboard-comparison"
      tabIndex={-1}
      aria-label="渠道指标对比"
      className={`${panel} flex min-h-[431px] flex-col @min-[900px]/overview:min-h-0`}
    >
      <ChartHeading title="渠道指标对比" />
      <div className="mt-4 flex min-h-0 flex-1 flex-col">
        {channels.length === 0 ? (
          <p role="status" className="grid min-h-0 flex-1 place-items-center text-[13px] text-(--overview-muted)">
            暂无渠道数据
          </p>
        ) : (
          <GroupedBars channels={channels} series={series} hoveredMetric={hoveredMetric} />
        )}
        <div
          role="group"
          aria-label="图表系列"
          className="mt-5 flex shrink-0 flex-wrap items-center justify-center gap-2"
        >
          {comparisonMetrics.map((metric) => (
            <button
              key={metric.key}
              type="button"
              aria-pressed={shown.includes(metric.key)}
              disabled={shown.length === 1 && shown.includes(metric.key)}
              onClick={() => toggle(metric.key)}
              onPointerEnter={() => setHoveredMetric(metric.key)}
              onPointerLeave={() => setHoveredMetric(null)}
              onFocus={() => setHoveredMetric(metric.key)}
              onBlur={() => setHoveredMetric(null)}
              className={`${focusRing} inline-flex h-6 cursor-pointer items-center gap-2 rounded-md px-2 text-xs text-(--overview-muted) hover:bg-(--overview-soft) disabled:cursor-default aria-[pressed=false]:line-through aria-[pressed=false]:opacity-55`}
            >
              <span className="size-2 rounded-full" style={{ backgroundColor: metric.color }} />
              {metric.label}
            </button>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useId, useMemo, useState } from "react";
import { feature } from "topojson-client";
import type { GeometryCollection, Topology } from "topojson-specification";
import atlas from "world-atlas/countries-110m.json";
import { useDashboardReplay } from "../preview-animation";
import { DEFAULT_ANIMATION_DURATION_MS } from "./bklit/animation";
import { ChoroplethChart } from "./bklit/choropleth/choropleth-chart";
import { ChoroplethFeature } from "./bklit/choropleth/choropleth-feature";
import { ChoroplethMarker } from "./bklit/choropleth/choropleth-marker";
import { useChoroplethCamera, type ChoroplethPerspective } from "./bklit/choropleth/choropleth-camera";
import { ChoroplethTooltip } from "./bklit/choropleth/choropleth-tooltip";
import {
  type ChoroplethFeature as Region,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./bklit/choropleth/choropleth-context";
import { TooltipContent } from "./bklit/tooltip/tooltip-content";
import { ChartHeading, panel } from "./chart-controls";
import { formatCount, type ReportMonth } from "./data";
import names from "./world-region-names.json";

// The 1:110m geometry and Chinese names are derived from Natural Earth's
// public-domain Admin 0 dataset. World Atlas ships the TopoJSON locally.
const topology = atlas as unknown as Topology<{ countries: GeometryCollection<{ name: string }> }>;
const world = feature(topology, topology.objects.countries);
// Antarctica's polar extent lies outside the displayed Mercator map.
world.features = world.features.filter(region => String(region.id) !== "010");
const regionNames: Record<string, string> = names;
const regionId = (region: Region) => String(region.id ?? region.properties.name);
const regionName = (region: Region) => regionNames[regionId(region)] ?? region.properties.name ?? "";

// Example regional totals use the same monthly visit counts as the channel report.
// An absent country has no observations in this breakdown.
const regionalVisits: Record<ReportMonth, Record<string, number>> = {
  "2026-08": {
    "156": 42010, "840": 24160, "392": 12640, "276": 9120, "826": 7240,
    "124": 5560, "356": 5180, "250": 4350, "036": 3860, "076": 3120,
    "484": 2320, "410": 2180, "360": 1420, "710": 1280, "528": 1060,
    "724": 920, "752": 720, "682": 560, "032": 440, "578": 320,
  },
  "2026-07": {
    "156": 39490, "840": 22770, "392": 9460, "276": 8120, "826": 6750,
    "124": 4780, "356": 4160, "250": 1720, "036": 3580, "076": 3160,
    "484": 1760, "410": 2450, "360": 1810, "710": 1140, "528": 960,
    "724": 820, "752": 560, "682": 430, "032": 520, "578": 290,
  },
};
const camera: ChoroplethPerspective = { focus: { view: "auto", tilt: 24 } };
const cities: { label: string; coordinates: [number, number] }[] = [
  { label: "伦敦", coordinates: [-0.13, 51.51] },
  { label: "纽约", coordinates: [-74.01, 40.71] },
  { label: "东京", coordinates: [139.69, 35.69] },
  { label: "圣保罗", coordinates: [-46.63, -23.55] },
  { label: "悉尼", coordinates: [151.21, -33.87] },
];
const legend = [
  { below: 0, label: "暂无数据", color: "var(--chart-scale-01)" },
  { below: 1000, label: "<1千", color: "var(--chart-scale-02)" },
  { below: 5000, label: "1千–5千", color: "var(--chart-scale-03)" },
  { below: 10000, label: "5千–1万", color: "var(--chart-scale-04)" },
  { below: Infinity, label: "≥1万", color: "var(--chart-scale-05)" },
];
function colorFor(value?: number) {
  if (value === undefined) return legend[0].color;
  return legend.find(group => value < group.below)!.color;
}

function RegionReading({ region, visits }: { region: Region; visits: Record<string, number> }) {
  const value = visits[regionId(region)];
  return (
    <div role="tooltip">
      <TooltipContent title={regionName(region)} rows={[{
        label: "访问次数", color: colorFor(value),
        value: value === undefined ? "暂无数据" : `${formatCount(value)} 次`,
      }]} />
    </div>
  );
}

function KeyboardRegions({ visits }: { visits: Record<string, number> }) {
  const { features, containerRef } = useChoroplethStable();
  const { focusFeature, reset } = useChoroplethCamera();
  const { hoveredFeatureIndex, setHoveredFeatureIndex, tooltipData, setTooltipData, setMarkerTooltip } = useChoroplethInteraction();
  const instructions = useId();
  const [index, setIndex] = useState<number | null>(null);
  const order = useMemo(() => features.map((region, i) => ({
    i, count: visits[regionId(region)] ?? -1,
  })).sort((a, b) => b.count - a.count).map(region => region.i), [features, visits]);
  function select(position: number) {
    setIndex(position);
    setTooltipData(null);
    setHoveredFeatureIndex(order[position]);
  }
  function clear() {
    setIndex(null);
    setHoveredFeatureIndex(null);
    setTooltipData(null);
  }

  useEffect(() => {
    const container = containerRef.current;
    const dismiss = () => {
      setIndex(null);
      setHoveredFeatureIndex(null);
      setTooltipData(null);
      setMarkerTooltip?.(null);
    };
    // The official feature layer moves a hovered path to the front. Listen
    // on the stable host as well so replacing that path cannot strand its tip.
    const leave = (event: PointerEvent) => { if (event.pointerType === "mouse") dismiss(); };
    const leaveLand = (event: PointerEvent) => {
      if (event.pointerType === "mouse" && event.target instanceof Element && !event.target.closest("[data-region], [role=button]")) {
        dismiss();
      }
    };
    const outsideTap = (event: PointerEvent) => {
      if (event.pointerType !== "mouse" && !container?.contains(event.target as Node)) dismiss();
    };
    container?.addEventListener("pointerleave", leave);
    container?.addEventListener("pointermove", leaveLand);
    document.addEventListener("pointerdown", outsideTap);
    return () => {
      container?.removeEventListener("pointerleave", leave);
      container?.removeEventListener("pointermove", leaveLand);
      document.removeEventListener("pointerdown", outsideTap);
    };
  }, [containerRef, setHoveredFeatureIndex, setTooltipData, setMarkerTooltip]);

  const active = index === null ? undefined : features[order[index]];
  return (
    <div
      role="group" aria-label="按地区浏览访问次数"
      aria-describedby={instructions} tabIndex={0}
      className="pointer-events-none absolute inset-0 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-(--chart-1)"
      onFocus={() => select(0)} onBlur={clear}
      onKeyDown={event => {
        if (event.key === "Escape") {
          event.preventDefault();
          event.stopPropagation();
          clear();
          reset();
        } else if (event.key === "Enter" && index !== null) {
          event.preventDefault();
          focusFeature(order[index]);
        } else if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) {
          event.preventDefault();
          const next = event.key === "Home" ? 0 : event.key === "End" ? order.length - 1 :
            ((index ?? 0) + (event.key === "ArrowRight" ? 1 : -1) + order.length) % order.length;
          select(next);
        }
      }}
    >
      <span id={instructions} className="sr-only">左右方向键切换地区，Enter 缩放，Escape 返回。</span>
      <div aria-live="polite" aria-atomic="true" className="absolute top-2 left-2 rounded-xl border bg-popover text-popover-foreground shadow-md empty:hidden">
        {active && !tooltipData && hoveredFeatureIndex === order[index!] && <RegionReading region={active} visits={visits} />}
      </div>
    </div>
  );
}

export function TrafficMap({ month }: { month: ReportMonth }) {
  const replay = useDashboardReplay();
  const visits = regionalVisits[month];
  return (
    <section id="dashboard-geography" aria-label="访问地区分布" tabIndex={-1} className={`${panel} flex min-w-0 flex-col`}>
      <ChartHeading title="访问地区分布" />
      <div className="mt-2 flex flex-1 items-center @min-[900px]/overview:[container-type:size]">
        <ChoroplethChart
          data={world}
          revealSignature={String(replay)}
          animationDuration={DEFAULT_ANIMATION_DURATION_MS}
          aspectRatio="16 / 9"
          className="mx-auto @min-[900px]/overview:max-w-[calc(100cqh*16/9)]"
          clickToZoom
          perspective={camera}
        >
          <ChoroplethFeature getFeatureColor={region => colorFor(visits[regionId(region)])} stroke="var(--chart-background)" />
          {cities.map(city => <ChoroplethMarker key={city.label} {...city} zoomLabel={`缩放至${city.label}`} />)}
          <ChoroplethTooltip locationLabel="坐标" content={({ feature: region }) => <RegionReading region={region} visits={visits} />} />
          <KeyboardRegions visits={visits} />
        </ChoroplethChart>
      </div>
      <ul aria-label="各地区访问次数图例" className="mt-3 flex flex-wrap items-center justify-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
        <li className="font-medium">访问次数</li>
        {legend.map(item => <li key={item.label} className="inline-flex items-center gap-1.5 whitespace-nowrap">
          <span aria-hidden="true" className="size-2.5 rounded-[2px]" style={{ backgroundColor: item.color }} />
          {item.label}
        </li>)}
      </ul>
    </section>
  );
}

"use client";

import { useState } from "react";
import { useDashboardReplay } from "../preview-animation";
import { Legend } from "./bklit/legend/legend";
import { useLegend, useLegendItem } from "./bklit/legend/legend-context";
import { RingCenter } from "./bklit/ring-center";
import { RingChart } from "./bklit/ring-chart";
import { Ring } from "./bklit/ring";
import type { RingData } from "./bklit/ring-context";
import { ChartHeading, ChartLegendKey, chartLegendLayout, focusRing } from "./chart-controls";
import { formatCount, type TrafficChannel } from "./data";

const palette = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
];

function ChannelLegendItem({
  pinned,
  onPin,
}: {
  pinned: number | null;
  onPin: (index: number | null) => void;
}) {
  const { item, index, isHovered, isFaded, percentage } = useLegendItem();
  const { setHoveredIndex } = useLegend();
  const details = `${item.label}，${formatCount(item.value)} 位新访客 / ${formatCount(item.maxValue ?? 0)} 位独立访客`;
  return (
    <button
      type="button"
      aria-label={`${details}，占比 ${percentage.toFixed(1)}%`}
      aria-pressed={pinned === index}
      data-highlighted={isHovered || undefined}
      className={`inline-flex cursor-pointer rounded-sm transition-opacity ${focusRing} ${isFaded ? "opacity-45" : ""}`}
      onPointerEnter={() => setHoveredIndex(index)}
      onPointerLeave={() => setHoveredIndex(null)}
      onFocus={() => setHoveredIndex(index)}
      onBlur={() => setHoveredIndex(null)}
      onClick={() => onPin(pinned === index ? null : index)}
    >
      <ChartLegendKey label={item.label} color={item.color} />
    </button>
  );
}

function VisitorRings({
  items,
  monthLabel,
}: {
  items: (RingData & { color: string })[];
  monthLabel: string;
}) {
  const replay = useDashboardReplay();
  const [hovered, setHovered] = useState<number | null>(null);
  const [pinned, setPinned] = useState<number | null>(null);
  const selected = hovered ?? pinned;
  const newVisitors = items.reduce((sum, item) => sum + item.value, 0);
  const visitors = items.reduce((sum, item) => sum + item.maxValue, 0);
  return (
    <div className="flex min-w-0 flex-1 flex-col items-center">
      <figure
        role="img"
        aria-label={`${monthLabel}所示渠道共 ${formatCount(visitors)} 位独立访客，其中新访客 ${formatCount(newVisitors)} 人`}
        className="my-auto aspect-square w-full max-w-[174px] shrink-0"
      >
        <RingChart
          key={replay}
          data={items}
          padding={4}
          strokeWidth={11}
          ringGap={6}
          baseInnerRadius={51}
          hoveredIndex={selected}
          onHoverChange={setHovered}
        >
          {items.map((item, index) => (
            <Ring key={item.label} index={index} />
          ))}
          <RingCenter
            percentage
            defaultLabel="新访客占比"
            suffix="%"
            formatOptions={{ maximumFractionDigits: 1 }}
            valueClassName="text-[clamp(14px,28cqw,16px)] leading-none font-semibold tracking-tight tabular-nums text-foreground"
