        props.kind === "tabs" ? (
          <Tabs.Root
            value={value}
            onValueChange={(next) => {
              if (typeof next === "string") onChange(next);
            }}
          >
            <Tabs.List {...groupProps} activateOnFocus>
              {options.map((option) => (
                <Tabs.Tab
                  key={option.value}
                  value={option.value}
                  disabled={disabled || option.disabled}
                  {...optionProps(option)}
                >
                  {content(option)}
                </Tabs.Tab>
              ))}
            </Tabs.List>
          </Tabs.Root>
        ) : (
          <RadioGroup
            {...groupProps}
            value={value}
            onValueChange={onChange}
            disabled={disabled}
          >
            {options.map((option) => (
              <Radio.Root
                key={option.value}
                value={option.value}
                disabled={option.disabled}
                {...optionProps(option)}
              >
                {content(option)}
              </Radio.Root>
            ))}
          </RadioGroup>
        )
      }
    />
  );
}

